window.ExtraBibleBooks=window.ExtraBibleBooks||{};window.ExtraBibleBooks["EXO"]={"book":"EXO","editions":{"epo-londona":[[1,1,"Jen estas la nomoj de la filoj de Izrael, kiuj venis Egiptujon kun Jakob; ĉiu venis kun siaj domanoj:","Jen estas la nomoj de la filoj de Izrael, kiuj venis Egiptujon kun Jakob; ĉiu venis kun siaj domanoj:"],[1,2,"Ruben, Simeon, Levi, kaj Jehuda;","Ruben, Simeon, Levi, kaj Jehuda;"],[1,3,"Isaĥar, Zebulun, kaj Benjamen;","Isaĥar, Zebulun, kaj Benjamen;"],[1,4,"Dan kaj Naftali, Gad kaj Aŝer.","Dan kaj Naftali, Gad kaj Aŝer."],[1,5,"Kaj la nombro de ĉiuj animoj, kiuj eliris el la lumbo de Jakob, estis sepdek; kaj Jozef estis jam en Egiptujo.","Kaj la nombro de ĉiuj animoj, kiuj eliris el la lumbo de Jakob, estis sepdek; kaj Jozef estis jam en Egiptujo."],[1,6,"Kaj mortis Jozef kaj ĉiuj liaj fratoj kaj tiu tuta generacio.","Kaj mortis Jozef kaj ĉiuj liaj fratoj kaj tiu tuta generacio."],[1,7,"Kaj la Izraelidoj fruktis kaj diskreskis kaj multiĝis kaj treege fortiĝis, kaj la lando pleniĝis de ili.","Kaj la Izraelidoj fruktis kaj diskreskis kaj multiĝis kaj treege fortiĝis, kaj la lando pleniĝis de ili."],[1,8,"Aperis en Egiptujo nova reĝo, kiu ne konis Jozefon.","Aperis en Egiptujo nova reĝo, kiu ne konis Jozefon."],[1,9,"Kaj li diris al sia popolo: Jen la popolo de la Izraelidoj estas pli multenombra kaj pli forta ol ni;","Kaj li diris al sia popolo: Jen la popolo de la Izraelidoj estas pli multenombra kaj pli forta ol ni;"],[1,10,"ni uzu do ruzon kontraŭ ĝi, por ke ĝi ne multiĝu, ĉar se okazos milito, tiam ankaŭ tiu popolo aliĝos al niaj malamikoj kaj militos kontraŭ ni kaj foriros el la lando.","ni uzu do ruzon kontraŭ ĝi, por ke ĝi ne multiĝu, ĉar se okazos milito, tiam ankaŭ tiu popolo aliĝos al niaj malamikoj kaj militos kontraŭ ni kaj foriros el la lando."],[1,11,"Kaj oni metis super ilin laborestrojn, por premi ilin per malfacilaj laboroj. Kaj ili konstruis por Faraono provizejajn urbojn Pitom kaj Rameses.","Kaj oni metis super ilin laborestrojn, por premi ilin per malfacilaj laboroj. Kaj ili konstruis por Faraono provizejajn urbojn Pitom kaj Rameses."],[1,12,"Sed ju pli oni premis ilin, des pli ili multiĝis kaj kreskis; kaj la Izraelidoj fariĝis teruraĵo.","Sed ju pli oni premis ilin, des pli ili multiĝis kaj kreskis; kaj la Izraelidoj fariĝis teruraĵo."],[1,13,"Kaj la Egiptoj laborigis la Izraelidojn kruele.","Kaj la Egiptoj laborigis la Izraelidojn kruele."],[1,14,"Kaj ili maldolĉigis al ili la vivon per malfacila laboro super argilo kaj brikoj, kaj per ĉia laboro sur la kampo, per ĉiaj laboroj, kiujn ili kruele metis sur ilin.","Kaj ili maldolĉigis al ili la vivon per malfacila laboro super argilo kaj brikoj, kaj per ĉia laboro sur la kampo, per ĉiaj laboroj, kiujn ili kruele metis sur ilin."],[1,15,"Kaj la reĝo de Egiptujo parolis al la Hebreaj akuŝistinoj, el kiuj unu estis nomata Ŝifra kaj la dua estis nomata Pua.","Kaj la reĝo de Egiptujo parolis al la Hebreaj akuŝistinoj, el kiuj unu estis nomata Ŝifra kaj la dua estis nomata Pua."],[1,16,"Li diris: Kiam vi akuŝigos la Hebreinojn, rigardu la kuŝejon; se estas filo, mortigu lin, kaj se estas filino, lasu ŝin vivi.","Li diris: Kiam vi akuŝigos la Hebreinojn, rigardu la kuŝejon; se estas filo, mortigu lin, kaj se estas filino, lasu ŝin vivi."],[1,17,"Sed la akuŝistinoj timis Dion, kaj ili ne faris, kiel diris al ili la reĝo de Egiptujo; kaj ili lasis la vivon al la virseksaj infanoj.","Sed la akuŝistinoj timis Dion, kaj ili ne faris, kiel diris al ili la reĝo de Egiptujo; kaj ili lasis la vivon al la virseksaj infanoj."],[1,18,"Kaj la reĝo de Egiptujo alvokis la akuŝistinojn, kaj diris al ili: Kial vi tion faras kaj lasas la vivon al la virseksaj infanoj?","Kaj la reĝo de Egiptujo alvokis la akuŝistinojn, kaj diris al ili: Kial vi tion faras kaj lasas la vivon al la virseksaj infanoj?"],[1,19,"Tiam la akuŝistinoj diris al Faraono: Ne kiel la Egiptaj virinoj estas la Hebreinoj; ili estas viglaj: antaŭ ol venas al ili la akuŝistino, ili jam estas naskintaj.","Tiam la akuŝistinoj diris al Faraono: Ne kiel la Egiptaj virinoj estas la Hebreinoj; ili estas viglaj: antaŭ ol venas al ili la akuŝistino, ili jam estas naskintaj."],[1,20,"Kaj Dio faris bonon al la akuŝistinoj, kaj la popolo multiĝis kaj tre fortiĝis.","Kaj Dio faris bonon al la akuŝistinoj, kaj la popolo multiĝis kaj tre fortiĝis."],[1,21,"Kaj ĉar la akuŝistinoj timis Dion, Li konstruis al ili domojn.","Kaj ĉar la akuŝistinoj timis Dion, Li konstruis al ili domojn."],[1,22,"Kaj Faraono ordonis al sia tuta popolo, dirante: Ĉiun filon, kiu naskiĝis, ĵetu en la Riveron, kaj ĉiun filinon lasu viva.","Kaj Faraono ordonis al sia tuta popolo, dirante: Ĉiun filon, kiu naskiĝis, ĵetu en la Riveron, kaj ĉiun filinon lasu viva."],[2,1,"Kaj iris unu homo el la domo de Levi kaj prenis edzinon Leviidinon.","Kaj iris unu homo el la domo de Levi kaj prenis edzinon Leviidinon."],[2,2,"Kaj la virino gravediĝis, kaj naskis filon; kaj ŝi vidis, ke li estas bela, kaj ŝi kaŝis lin dum tri monatoj.","Kaj la virino gravediĝis, kaj naskis filon; kaj ŝi vidis, ke li estas bela, kaj ŝi kaŝis lin dum tri monatoj."],[2,3,"Sed ŝi ne povis plu kaŝi lin, tial ŝi prenis por li keston el kanoj kaj ĉirkaŭŝmiris ĝin per asfalto kaj peĉo, kaj metis tien la infanon kaj metis ĝin inter la kanojn sur la bordo de la Rivero.","Sed ŝi ne povis plu kaŝi lin, tial ŝi prenis por li keston el kanoj kaj ĉirkaŭŝmiris ĝin per asfalto kaj peĉo, kaj metis tien la infanon kaj metis ĝin inter la kanojn sur la bordo de la Rivero."],[2,4,"Kaj lia fratino stariĝis malproksime, por sciiĝi, kio fariĝos kun li.","Kaj lia fratino stariĝis malproksime, por sciiĝi, kio fariĝos kun li."],[2,5,"Kaj la filino de Faraono malsupreniris, por lavi sin en la Rivero, kaj ŝiaj servantinoj iradis sur la bordo de la Rivero. Ŝi ekvidis la keston meze de la kanoj, kaj ŝi sendis sian sklavinon, ke ŝi ĝin prenu.","Kaj la filino de Faraono malsupreniris, por lavi sin en la Rivero, kaj ŝiaj servantinoj iradis sur la bordo de la Rivero. Ŝi ekvidis la keston meze de la kanoj, kaj ŝi sendis sian sklavinon, ke ŝi ĝin prenu."],[2,6,"Ŝi malfermis, kaj ekvidis la infanon; ĝi estis knabeto, kiu ploris. Kaj ŝi kompatis lin, kaj diris: Ĝi estas el la Hebreaj infanoj.","Ŝi malfermis, kaj ekvidis la infanon; ĝi estis knabeto, kiu ploris. Kaj ŝi kompatis lin, kaj diris: Ĝi estas el la Hebreaj infanoj."],[2,7,"Tiam lia fratino diris al la filino de Faraono: Ĉu mi iru kaj voku al vi virinon nutrantinon el la Hebreinoj, ke ŝi nutru por vi la infanon?","Tiam lia fratino diris al la filino de Faraono: Ĉu mi iru kaj voku al vi virinon nutrantinon el la Hebreinoj, ke ŝi nutru por vi la infanon?"],[2,8,"Kaj la filino de Faraono diris al ŝi: Iru. Kaj la knabino iris kaj vokis la patrinon de la infano.","Kaj la filino de Faraono diris al ŝi: Iru. Kaj la knabino iris kaj vokis la patrinon de la infano."],[2,9,"Kaj la filino de Faraono diris al ŝi: Prenu ĉi tiun infanon kaj nutru ĝin por mi, kaj mi pagos al vi. Kaj la virino prenis la infanon kaj nutris ĝin.","Kaj la filino de Faraono diris al ŝi: Prenu ĉi tiun infanon kaj nutru ĝin por mi, kaj mi pagos al vi. Kaj la virino prenis la infanon kaj nutris ĝin."],[2,10,"Kiam la infano grandiĝis, ŝi alportis lin al la filino de Faraono, kaj li fariĝis filo por ŝi, kaj ŝi donis al li la nomon Moseo, dirante: El la akvo mi lin eltiris.","Kiam la infano grandiĝis, ŝi alportis lin al la filino de Faraono, kaj li fariĝis filo por ŝi, kaj ŝi donis al li la nomon Moseo, dirante: El la akvo mi lin eltiris."],[2,11,"En la tempo, kiam Moseo estis jam granda, li eliris al siaj fratoj kaj vidis iliajn malfacilajn laborojn; kaj li vidis, ke Egipto batas iun Hebreon el liaj fratoj.","En la tempo, kiam Moseo estis jam granda, li eliris al siaj fratoj kaj vidis iliajn malfacilajn laborojn; kaj li vidis, ke Egipto batas iun Hebreon el liaj fratoj."],[2,12,"Tiam li turnis sin unuflanken kaj aliflanken, kaj vidinte, ke estas neniu, mortigis la Egipton kaj kaŝis lin en la sablo.","Tiam li turnis sin unuflanken kaj aliflanken, kaj vidinte, ke estas neniu, mortigis la Egipton kaj kaŝis lin en la sablo."],[2,13,"Kaj li eliris en la sekvanta tago, kaj vidis, ke du Hebreoj malpacas. Kaj li diris al la ofendanto: Kial vi batas vian proksimulon?","Kaj li eliris en la sekvanta tago, kaj vidis, ke du Hebreoj malpacas. Kaj li diris al la ofendanto: Kial vi batas vian proksimulon?"],[2,14,"Kaj tiu diris: Kiu faris vin estro kaj juĝanto super ni? ĉu vi intencas mortigi min, kiel vi mortigis la Egipton? Tiam Moseo ektimis, kaj diris: Videble la afero fariĝis sciata.","Kaj tiu diris: Kiu faris vin estro kaj juĝanto super ni? ĉu vi intencas mortigi min, kiel vi mortigis la Egipton? Tiam Moseo ektimis, kaj diris: Videble la afero fariĝis sciata."],[2,15,"Kaj Faraono aŭdis pri tiu afero kaj deziris mortigi Moseon. Sed Moseo forkuris de Faraono kaj ekloĝis en la lando Midjana, kaj li loĝis apud puto.","Kaj Faraono aŭdis pri tiu afero kaj deziris mortigi Moseon. Sed Moseo forkuris de Faraono kaj ekloĝis en la lando Midjana, kaj li loĝis apud puto."],[2,16,"La pastro Midjana havis sep filinojn. Kaj ili venis kaj ĉerpis akvon kaj plenigis la trogojn, por trinkigi la ŝafojn de sia patro.","La pastro Midjana havis sep filinojn. Kaj ili venis kaj ĉerpis akvon kaj plenigis la trogojn, por trinkigi la ŝafojn de sia patro."],[2,17,"Sed venis la paŝtistoj kaj forpelis ilin. Tiam Moseo leviĝis kaj helpis ilin kaj trinkigis iliajn ŝafojn.","Sed venis la paŝtistoj kaj forpelis ilin. Tiam Moseo leviĝis kaj helpis ilin kaj trinkigis iliajn ŝafojn."],[2,18,"Kiam ili venis al sia patro Reuel, li diris: Kial vi tiel baldaŭ venis hodiaŭ?","Kiam ili venis al sia patro Reuel, li diris: Kial vi tiel baldaŭ venis hodiaŭ?"],[2,19,"Kaj ili diris: Iu Egipto savis nin el la manoj de la paŝtistoj, kaj li eĉ ĉerpis por ni kaj trinkigis la ŝafojn.","Kaj ili diris: Iu Egipto savis nin el la manoj de la paŝtistoj, kaj li eĉ ĉerpis por ni kaj trinkigis la ŝafojn."],[2,20,"Tiam li diris al siaj filinoj: Kie do li estas? kial vi forlasis tiun homon? voku lin, ke li manĝu panon.","Tiam li diris al siaj filinoj: Kie do li estas? kial vi forlasis tiun homon? voku lin, ke li manĝu panon."],[2,21,"Kaj Moseo konsentis loĝi ĉe tiu homo; kaj tiu donis sian filinon Cipora al Moseo.","Kaj Moseo konsentis loĝi ĉe tiu homo; kaj tiu donis sian filinon Cipora al Moseo."],[2,22,"Kaj ŝi naskis filon, kaj li donis al li la nomon Gerŝom, ĉar li diris: Fremdulo mi estis en lando fremda.","Kaj ŝi naskis filon, kaj li donis al li la nomon Gerŝom, ĉar li diris: Fremdulo mi estis en lando fremda."],[2,23,"Post longa tempo mortis la reĝo de Egiptujo. Kaj la Izraelidoj ĝemis pro la laboroj kaj kriis, kaj ilia kriado pro la laboroj venis supren al Dio.","Post longa tempo mortis la reĝo de Egiptujo. Kaj la Izraelidoj ĝemis pro la laboroj kaj kriis, kaj ilia kriado pro la laboroj venis supren al Dio."],[2,24,"Kaj Dio aŭdis ilian ĝemadon, kaj Dio rememoris Sian interligon kun Abraham, Isaak, kaj Jakob.","Kaj Dio aŭdis ilian ĝemadon, kaj Dio rememoris Sian interligon kun Abraham, Isaak, kaj Jakob."],[2,25,"Kaj Dio rigardis la Izraelidojn, kaj Dio rememoris ilin.","Kaj Dio rigardis la Izraelidojn, kaj Dio rememoris ilin."],[3,1,"Moseo paŝtis la ŝafojn de Jitro, sia bopatro, pastro Midjana. Kaj li forkondukis la ŝafojn en malproksiman parton de la dezerto kaj venis al la Dia monto Ĥoreb.","Moseo paŝtis la ŝafojn de Jitro, sia bopatro, pastro Midjana. Kaj li forkondukis la ŝafojn en malproksiman parton de la dezerto kaj venis al la Dia monto Ĥoreb."],[3,2,"Kaj aperis al li anĝelo de la Eternulo en flama fajro el la mezo de arbetaĵo. Kaj li vidis, ke jen la arbetaĵo brulas en la fajro, kaj tamen la arbetaĵo ne forbrulas.","Kaj aperis al li anĝelo de la Eternulo en flama fajro el la mezo de arbetaĵo. Kaj li vidis, ke jen la arbetaĵo brulas en la fajro, kaj tamen la arbetaĵo ne forbrulas."],[3,3,"Kaj Moseo diris: Mi iros kaj rigardos tiun grandan fenomenon, kial la arbetaĵo ne forbrulas.","Kaj Moseo diris: Mi iros kaj rigardos tiun grandan fenomenon, kial la arbetaĵo ne forbrulas."],[3,4,"La Eternulo vidis, ke li iras, por rigardi, kaj Dio vokis al li el la mezo de la arbetaĵo, kaj diris: Moseo, Moseo! Kaj tiu diris: Jen mi estas.","La Eternulo vidis, ke li iras, por rigardi, kaj Dio vokis al li el la mezo de la arbetaĵo, kaj diris: Moseo, Moseo! Kaj tiu diris: Jen mi estas."],[3,5,"Kaj Li diris: Ne alproksimiĝu ĉi tien; deprenu viajn ŝuojn de viaj piedoj, ĉar la loko, sur kiu vi staras, estas tero sankta.","Kaj Li diris: Ne alproksimiĝu ĉi tien; deprenu viajn ŝuojn de viaj piedoj, ĉar la loko, sur kiu vi staras, estas tero sankta."],[3,6,"Ankoraŭ Li diris: Mi estas la Dio de via patro, la Dio de Abraham, la Dio de Isaak, kaj la Dio de Jakob. Kaj Moseo kovris sian vizaĝon, ĉar li timis rigardi Dion.","Ankoraŭ Li diris: Mi estas la Dio de via patro, la Dio de Abraham, la Dio de Isaak, kaj la Dio de Jakob. Kaj Moseo kovris sian vizaĝon, ĉar li timis rigardi Dion."],[3,7,"Kaj la Eternulo diris: Mi vidis la mizeron de Mia popolo, kiu estas en Egiptujo, kaj Mi aŭdis ĝian kriadon kaŭze de ĝiaj premantoj; Mi scias ĝiajn suferojn.","Kaj la Eternulo diris: Mi vidis la mizeron de Mia popolo, kiu estas en Egiptujo, kaj Mi aŭdis ĝian kriadon kaŭze de ĝiaj premantoj; Mi scias ĝiajn suferojn."],[3,8,"Kaj Mi malsupreniris, por savi ĝin el la manoj de la Egiptoj kaj elirigi ĝin el tiu lando en landon bonan kaj vastan, en landon, en kiu fluas lakto kaj mielo, sur la lokon de la Kanaanidoj kaj la Ĥetidoj kaj la Amoridoj kaj la Perizidoj kaj la Ĥividoj kaj la Jebusidoj.","Kaj Mi malsupreniris, por savi ĝin el la manoj de la Egiptoj kaj elirigi ĝin el tiu lando en landon bonan kaj vastan, en landon, en kiu fluas lakto kaj mielo, sur la lokon de la Kanaanidoj kaj la Ĥetidoj kaj la Amoridoj kaj la Perizidoj kaj la Ĥividoj kaj la Jebusidoj."],[3,9,"Nun la krioj de la Izraelidoj venis al Mi; kaj Mi vidis la turmentojn, per kiuj la Egiptoj turmentas ilin.","Nun la krioj de la Izraelidoj venis al Mi; kaj Mi vidis la turmentojn, per kiuj la Egiptoj turmentas ilin."],[3,10,"Iru do, Mi sendos vin al Faraono, kaj elkonduku Mian popolon la Izraelidojn el Egiptujo.","Iru do, Mi sendos vin al Faraono, kaj elkonduku Mian popolon la Izraelidojn el Egiptujo."],[3,11,"Kaj Moseo diris al Dio: Kiu mi estas, ke mi iru al Faraono kaj mi elkonduku la Izraelidojn el Egiptujo?","Kaj Moseo diris al Dio: Kiu mi estas, ke mi iru al Faraono kaj mi elkonduku la Izraelidojn el Egiptujo?"],[3,12,"Kaj Li diris: Mi estos kun vi; kaj tio estu por vi signo, ke Mi vin sendis: kiam vi estos elkondukinta Mian popolon el Egiptujo, vi faros servon al Dio sur ĉi tiu monto.","Kaj Li diris: Mi estos kun vi; kaj tio estu por vi signo, ke Mi vin sendis: kiam vi estos elkondukinta Mian popolon el Egiptujo, vi faros servon al Dio sur ĉi tiu monto."],[3,13,"Kaj Moseo diris al Dio: Jen mi venos al la Izraelidoj, kaj diros al ili: La Dio de viaj patroj sendis min al vi; tiam ili diros al mi: Kia estas Lia nomo? Kion mi diru al ili?","Kaj Moseo diris al Dio: Jen mi venos al la Izraelidoj, kaj diros al ili: La Dio de viaj patroj sendis min al vi; tiam ili diros al mi: Kia estas Lia nomo? Kion mi diru al ili?"],[3,14,"Kaj Dio diris al Moseo: MI ESTAS, KIU ESTAS. Kaj Li diris: Tiel diru al la Izraelidoj: La Estanto sendis min al vi.","Kaj Dio diris al Moseo: MI ESTAS, KIU ESTAS. Kaj Li diris: Tiel diru al la Izraelidoj: La Estanto sendis min al vi."],[3,15,"Kaj plue Dio diris al Moseo: Tiel diru al la Izraelidoj: La Eternulo, la Dio de viaj patroj, la Dio de Abraham, la Dio de Isaak, kaj la Dio de Jakob, sendis min al vi. Tia estas Mia nomo por eterne, kaj tia estas memoraĵo pri Mi por ĉiuj generacioj.","Kaj plue Dio diris al Moseo: Tiel diru al la Izraelidoj: La Eternulo, la Dio de viaj patroj, la Dio de Abraham, la Dio de Isaak, kaj la Dio de Jakob, sendis min al vi. Tia estas Mia nomo por eterne, kaj tia estas memoraĵo pri Mi por ĉiuj generacioj."],[3,16,"Iru, kaj kunvenigu la ĉefojn de Izrael, kaj diru al ili: La Eternulo, la Dio de viaj patroj, aperis al mi, la Dio de Abraham, Isaak, kaj Jakob, kaj Li diris: Mi atentis vin, kaj tion, kio estas farita al vi en Egiptujo.","Iru, kaj kunvenigu la ĉefojn de Izrael, kaj diru al ili: La Eternulo, la Dio de viaj patroj, aperis al mi, la Dio de Abraham, Isaak, kaj Jakob, kaj Li diris: Mi atentis vin, kaj tion, kio estas farita al vi en Egiptujo."],[3,17,"Kaj Mi diris: Mi elirigos vin el la mizero de Egiptujo en la landon de la Kanaanidoj kaj la Ĥetidoj kaj la Amoridoj kaj la Perizidoj kaj la Ĥividoj kaj la Jebusidoj, en landon, en kiu fluas lakto kaj mielo.","Kaj Mi diris: Mi elirigos vin el la mizero de Egiptujo en la landon de la Kanaanidoj kaj la Ĥetidoj kaj la Amoridoj kaj la Perizidoj kaj la Ĥividoj kaj la Jebusidoj, en landon, en kiu fluas lakto kaj mielo."],[3,18,"Kaj ili aŭskultos vian voĉon, kaj vi venos, vi kaj la ĉefoj de Izrael, al la reĝo de Egiptujo, kaj vi diros al li: La Eternulo, la Dio de la Hebreoj, vokis nin; lasu do nin iri vojon de tri tagoj en la dezerton, por ke ni faru oferon al la Eternulo, nia Dio.","Kaj ili aŭskultos vian voĉon, kaj vi venos, vi kaj la ĉefoj de Izrael, al la reĝo de Egiptujo, kaj vi diros al li: La Eternulo, la Dio de la Hebreoj, vokis nin; lasu do nin iri vojon de tri tagoj en la dezerton, por ke ni faru oferon al la Eternulo, nia Dio."],[3,19,"Sed Mi scias, ke la reĝo de Egiptujo ne permesos al vi iri, se ne devigos lin forta mano.","Sed Mi scias, ke la reĝo de Egiptujo ne permesos al vi iri, se ne devigos lin forta mano."],[3,20,"Kaj Mi etendos Mian manon, kaj Mi batos Egiptujon per ĉiuj Miaj mirakloj, kiujn Mi faros meze de ĝi; kaj poste li lasos vin iri.","Kaj Mi etendos Mian manon, kaj Mi batos Egiptujon per ĉiuj Miaj mirakloj, kiujn Mi faros meze de ĝi; kaj poste li lasos vin iri."],[3,21,"Kaj Mi donos al tiu popolo favoron de la Egiptoj; kaj kiam vi iros, vi ne iros kun malplenaj manoj.","Kaj Mi donos al tiu popolo favoron de la Egiptoj; kaj kiam vi iros, vi ne iros kun malplenaj manoj."],[3,22,"Ĉiu virino petos de sia najbarino kaj de sia samdomanino vazojn arĝentajn kaj vazojn orajn kaj vestojn; kaj vi metos tion sur viajn filojn kaj sur viajn filinojn, kaj vi senhavigos la Egiptojn.","Ĉiu virino petos de sia najbarino kaj de sia samdomanino vazojn arĝentajn kaj vazojn orajn kaj vestojn; kaj vi metos tion sur viajn filojn kaj sur viajn filinojn, kaj vi senhavigos la Egiptojn."],[4,1,"Moseo respondis kaj diris: Sed se ili ne kredos al mi kaj ne aŭskultos mian voĉon, kaj se ili diros: Ne aperis al vi la Eternulo?","Moseo respondis kaj diris: Sed se ili ne kredos al mi kaj ne aŭskultos mian voĉon, kaj se ili diros: Ne aperis al vi la Eternulo?"],[4,2,"Kaj la Eternulo diris al li: Kion vi tie havas en via mano? Kaj li diris: Bastonon.","Kaj la Eternulo diris al li: Kion vi tie havas en via mano? Kaj li diris: Bastonon."],[4,3,"Kaj Li diris: Ĵetu ĝin sur la teron. Kaj li ĵetis ĝin sur la teron, kaj ĝi fariĝis serpento; kaj Moseo forkuris de ĝi.","Kaj Li diris: Ĵetu ĝin sur la teron. Kaj li ĵetis ĝin sur la teron, kaj ĝi fariĝis serpento; kaj Moseo forkuris de ĝi."],[4,4,"Sed la Eternulo diris al Moseo: Etendu vian manon, kaj kaptu ĝin je ĝia vosto (kaj li etendis sian manon kaj kaptis ĝin, kaj ĝi fariĝis bastono en lia mano),","Sed la Eternulo diris al Moseo: Etendu vian manon, kaj kaptu ĝin je ĝia vosto (kaj li etendis sian manon kaj kaptis ĝin, kaj ĝi fariĝis bastono en lia mano),"],[4,5,"por ke ili kredu, ke aperis al vi la Eternulo, la Dio de iliaj patroj, la Dio de Abraham, la Dio de Isaak, kaj la Dio de Jakob.","por ke ili kredu, ke aperis al vi la Eternulo, la Dio de iliaj patroj, la Dio de Abraham, la Dio de Isaak, kaj la Dio de Jakob."],[4,6,"Kaj la Eternulo diris al li plue: Metu vian manon en vian sinon. Kaj li metis sian manon en sian sinon; kaj kiam li elprenis ĝin, jen lia mano estis leprokovrita kvazaŭ neĝo.","Kaj la Eternulo diris al li plue: Metu vian manon en vian sinon. Kaj li metis sian manon en sian sinon; kaj kiam li elprenis ĝin, jen lia mano estis leprokovrita kvazaŭ neĝo."],[4,7,"Kaj Li diris: Remetu vian manon en vian sinon (kaj li remetis sian manon en sian sinon; kaj kiam li elprenis ĝin el sia sino, jen ĝi denove fariĝis kiel lia karno);","Kaj Li diris: Remetu vian manon en vian sinon (kaj li remetis sian manon en sian sinon; kaj kiam li elprenis ĝin el sia sino, jen ĝi denove fariĝis kiel lia karno);"],[4,8,"kaj se ili ne kredos al vi kaj ne aŭskultos la voĉon de la unua signo, ili kredos al la voĉo de la alia signo.","kaj se ili ne kredos al vi kaj ne aŭskultos la voĉon de la unua signo, ili kredos al la voĉo de la alia signo."],[4,9,"Kaj se ili ne kredos eĉ al ambaŭ tiuj signoj kaj ne aŭskultos vian voĉon, tiam prenu akvon el la Rivero kaj verŝu ĝin sur la sekan teron; kaj tiam la akvo, kiun vi prenis el la Rivero, fariĝos sango sur la seka tero.","Kaj se ili ne kredos eĉ al ambaŭ tiuj signoj kaj ne aŭskultos vian voĉon, tiam prenu akvon el la Rivero kaj verŝu ĝin sur la sekan teron; kaj tiam la akvo, kiun vi prenis el la Rivero, fariĝos sango sur la seka tero."],[4,10,"Kaj Moseo diris al la Eternulo: Ho, mia Sinjoro, mi ne estas elokventa, nek de hieraŭ, nek de antaŭhieraŭ, nek de tiu tempo, kiam Vi komencis paroli al Via sklavo; ĉar mi havas nelertan buŝon kaj nelertan langon.","Kaj Moseo diris al la Eternulo: Ho, mia Sinjoro, mi ne estas elokventa, nek de hieraŭ, nek de antaŭhieraŭ, nek de tiu tempo, kiam Vi komencis paroli al Via sklavo; ĉar mi havas nelertan buŝon kaj nelertan langon."],[4,11,"Kaj la Eternulo diris al li: Kiu faris buŝon al la homo? aŭ kiu faras muta aŭ surda aŭ vidanta aŭ blinda? ĉu ne Mi, la Eternulo?","Kaj la Eternulo diris al li: Kiu faris buŝon al la homo? aŭ kiu faras muta aŭ surda aŭ vidanta aŭ blinda? ĉu ne Mi, la Eternulo?"],[4,12,"Kaj nun iru, kaj Mi estos kun via buŝo, kaj Mi instruos vin, kion vi devas paroli.","Kaj nun iru, kaj Mi estos kun via buŝo, kaj Mi instruos vin, kion vi devas paroli."],[4,13,"Kaj li diris: Ho, mia Sinjoro, sendu iun alian.","Kaj li diris: Ho, mia Sinjoro, sendu iun alian."],[4,14,"Tiam ekflamis la kolero de la Eternulo kontraŭ Moseo, kaj Li diris: Mi scias ja, ke via frato Aaron, la Levido, estas elokventa; kaj jen li eĉ iras al vi renkonte, kaj kiam li vidos vin, li ekĝojos en sia koro.","Tiam ekflamis la kolero de la Eternulo kontraŭ Moseo, kaj Li diris: Mi scias ja, ke via frato Aaron, la Levido, estas elokventa; kaj jen li eĉ iras al vi renkonte, kaj kiam li vidos vin, li ekĝojos en sia koro."],[4,15,"Kaj vi parolos al li kaj metos la vortojn en lian buŝon; kaj Mi estos kun via buŝo kaj kun lia buŝo, kaj Mi instruos vin, kion vi devas fari.","Kaj vi parolos al li kaj metos la vortojn en lian buŝon; kaj Mi estos kun via buŝo kaj kun lia buŝo, kaj Mi instruos vin, kion vi devas fari."],[4,16,"Kaj li parolos por vi al la popolo; kaj li estos via buŝo, kaj vi estos por li anstataŭ Dio.","Kaj li parolos por vi al la popolo; kaj li estos via buŝo, kaj vi estos por li anstataŭ Dio."],[4,17,"Kaj ĉi tiun bastonon prenu en vian manon; per ĝi vi faros la signojn.","Kaj ĉi tiun bastonon prenu en vian manon; per ĝi vi faros la signojn."],[4,18,"Moseo iris kaj revenis al sia bopatro Jitro, kaj diris al li: Mi volas iri kaj reveni al miaj fratoj, kiuj estas en Egiptujo, kaj vidi, ĉu ili vivas ankoraŭ. Kaj Jitro diris al Moseo: Iru en paco.","Moseo iris kaj revenis al sia bopatro Jitro, kaj diris al li: Mi volas iri kaj reveni al miaj fratoj, kiuj estas en Egiptujo, kaj vidi, ĉu ili vivas ankoraŭ. Kaj Jitro diris al Moseo: Iru en paco."],[4,19,"Kaj la Eternulo diris al Moseo en Midjanujo: Iru, revenu Egiptujon; ĉar mortis ĉiuj homoj, kiuj volis vin mortigi.","Kaj la Eternulo diris al Moseo en Midjanujo: Iru, revenu Egiptujon; ĉar mortis ĉiuj homoj, kiuj volis vin mortigi."],[4,20,"Tiam Moseo prenis sian edzinon kaj siajn filojn kaj sidigis ilin sur azeno, kaj ekiris al la lando Egipta. Kaj Moseo prenis la bastonon de Dio en sian manon.","Tiam Moseo prenis sian edzinon kaj siajn filojn kaj sidigis ilin sur azeno, kaj ekiris al la lando Egipta. Kaj Moseo prenis la bastonon de Dio en sian manon."],[4,21,"Kaj la Eternulo diris al Moseo: Kiam vi revenos Egiptujon, tiam rigardu, ĉiujn miraklojn, kiujn Mi donis en vian manon, faru antaŭ Faraono. Sed Mi malmoligos lian koron, kaj li ne permesos al la popolo foriri.","Kaj la Eternulo diris al Moseo: Kiam vi revenos Egiptujon, tiam rigardu, ĉiujn miraklojn, kiujn Mi donis en vian manon, faru antaŭ Faraono. Sed Mi malmoligos lian koron, kaj li ne permesos al la popolo foriri."],[4,22,"Kaj vi diru al Faraono: Tiel diris la Eternulo: Mia filo unuenaskita estas Izrael;","Kaj vi diru al Faraono: Tiel diris la Eternulo: Mia filo unuenaskita estas Izrael;"],[4,23,"kaj Mi diras al vi: Permesu, ke Mia filo iru kaj faru al Mi servon; se vi ne permesos al li iri, tiam Mi mortigos vian unuenaskitan filon.","kaj Mi diras al vi: Permesu, ke Mia filo iru kaj faru al Mi servon; se vi ne permesos al li iri, tiam Mi mortigos vian unuenaskitan filon."],[4,24,"Sur la vojo, en la noktohaltejo, renkontis lin la Eternulo kaj volis mortigi lin;","Sur la vojo, en la noktohaltejo, renkontis lin la Eternulo kaj volis mortigi lin;"],[4,25,"sed Cipora prenis akran ŝtonon, kaj detranĉis la prepucion de sia filo kaj ektuŝis liajn piedojn, kaj diris: Sanga fianĉo vi estas por mi.","sed Cipora prenis akran ŝtonon, kaj detranĉis la prepucion de sia filo kaj ektuŝis liajn piedojn, kaj diris: Sanga fianĉo vi estas por mi."],[4,26,"Tiam Li forlasis lin. Kaj ŝi diris: Sanga fianĉo per la cirkumcido.","Tiam Li forlasis lin. Kaj ŝi diris: Sanga fianĉo per la cirkumcido."],[4,27,"Kaj la Eternulo diris al Aaron: Iru renkonte al Moseo en la dezerton. Kaj li iris kaj renkontis lin ĉe la monto de Dio, kaj kisis lin.","Kaj la Eternulo diris al Aaron: Iru renkonte al Moseo en la dezerton. Kaj li iris kaj renkontis lin ĉe la monto de Dio, kaj kisis lin."],[4,28,"Kaj Moseo diris al Aaron ĉiujn vortojn de la Eternulo, kiu sendis lin, kaj ĉiujn signojn, pri kiuj Li ordonis al li.","Kaj Moseo diris al Aaron ĉiujn vortojn de la Eternulo, kiu sendis lin, kaj ĉiujn signojn, pri kiuj Li ordonis al li."],[4,29,"Kaj iris Moseo kaj Aaron kaj kunvenigis ĉiujn ĉefojn de la Izraelidoj.","Kaj iris Moseo kaj Aaron kaj kunvenigis ĉiujn ĉefojn de la Izraelidoj."],[4,30,"Kaj Aaron diris ĉiujn vortojn, kiujn la Eternulo diris al Moseo, kaj li faris la signojn antaŭ la popolo.","Kaj Aaron diris ĉiujn vortojn, kiujn la Eternulo diris al Moseo, kaj li faris la signojn antaŭ la popolo."],[4,31,"Kaj la popolo kredis. Kaj ili aŭdis, ke la Eternulo rememoris la Izraelidojn kaj vidis ilian mizeron, kaj ili kliniĝis kaj faris adoron.","Kaj la popolo kredis. Kaj ili aŭdis, ke la Eternulo rememoris la Izraelidojn kaj vidis ilian mizeron, kaj ili kliniĝis kaj faris adoron."],[5,1,"Poste venis Moseo kaj Aaron, kaj diris al Faraono: Tiel diris la Eternulo, la Dio de Izrael: Permesu, ke Mia popolo iru kaj faru al Mi feston en la dezerto.","Poste venis Moseo kaj Aaron, kaj diris al Faraono: Tiel diris la Eternulo, la Dio de Izrael: Permesu, ke Mia popolo iru kaj faru al Mi feston en la dezerto."],[5,2,"Sed Faraono diris: Kiu estas la Eternulo, kies voĉon mi devas obei kaj lasi Izraelon iri? mi ne konas la Eternulon, kaj al Izrael mi ne permesos iri.","Sed Faraono diris: Kiu estas la Eternulo, kies voĉon mi devas obei kaj lasi Izraelon iri? mi ne konas la Eternulon, kaj al Izrael mi ne permesos iri."],[5,3,"Kaj ili diris: La Dio de la Hebreoj vokis nin; permesu, ke ni iru vojon de tri tagoj en la dezerton kaj ni alportu oferon al la Eternulo, nia Dio, por ke Li ne frapu nin per pesto aŭ glavo.","Kaj ili diris: La Dio de la Hebreoj vokis nin; permesu, ke ni iru vojon de tri tagoj en la dezerton kaj ni alportu oferon al la Eternulo, nia Dio, por ke Li ne frapu nin per pesto aŭ glavo."],[5,4,"Sed la reĝo de Egiptujo diris al ili: Kial vi, Moseo kaj Aaron, fortiras la popolon de ĝiaj laboroj? iru al viaj laboroj.","Sed la reĝo de Egiptujo diris al ili: Kial vi, Moseo kaj Aaron, fortiras la popolon de ĝiaj laboroj? iru al viaj laboroj."],[5,5,"Kaj Faraono diris: Jen multenombra estas nun la popolo de la lando, kaj vi volas liberigi ilin de iliaj laboroj!","Kaj Faraono diris: Jen multenombra estas nun la popolo de la lando, kaj vi volas liberigi ilin de iliaj laboroj!"],[5,6,"Kaj Faraono ordonis en tiu tago al la voktoj de la popolo kaj al ĝiaj kontrolistoj, dirante:","Kaj Faraono ordonis en tiu tago al la voktoj de la popolo kaj al ĝiaj kontrolistoj, dirante:"],[5,7,"Ne donu plu pajlon al la popolo por la farado de la brikoj, kiel ĝis nun; ili mem iru kaj kolektu al si pajlon.","Ne donu plu pajlon al la popolo por la farado de la brikoj, kiel ĝis nun; ili mem iru kaj kolektu al si pajlon."],[5,8,"Sed la nombron de la brikoj, kiun ili pretigas ĝis nun, postulu de ili, ne malgrandigu ĝin; ĉar ili vagas senlabore, tial ili krias: Ni iru kaj alportu oferon al nia Dio.","Sed la nombron de la brikoj, kiun ili pretigas ĝis nun, postulu de ili, ne malgrandigu ĝin; ĉar ili vagas senlabore, tial ili krias: Ni iru kaj alportu oferon al nia Dio."],[5,9,"Oni devas premi tiujn homojn per la laboro, por ke ili estu okupitaj de ĝi kaj ne atentu mensogajn vortojn.","Oni devas premi tiujn homojn per la laboro, por ke ili estu okupitaj de ĝi kaj ne atentu mensogajn vortojn."],[5,10,"Tiam eliris la voktoj de la popolo kaj ĝiaj kontrolistoj, kaj diris al la popolo: Tiel diras Faraono: Mi ne donos al vi pajlon;","Tiam eliris la voktoj de la popolo kaj ĝiaj kontrolistoj, kaj diris al la popolo: Tiel diras Faraono: Mi ne donos al vi pajlon;"],[5,11,"iru mem, prenu al vi pajlon, kie vi trovos; sed el via laboro nenio estos deprenata.","iru mem, prenu al vi pajlon, kie vi trovos; sed el via laboro nenio estos deprenata."],[5,12,"Tiam la popolo disiĝis en la tuta lando Egipta, por kolekti pecojn da pajlo.","Tiam la popolo disiĝis en la tuta lando Egipta, por kolekti pecojn da pajlo."],[5,13,"Kaj la voktoj insistadis, dirante: Pretigu vian ĉiutagan laboron, kiel tiam, kiam vi havis pajlon.","Kaj la voktoj insistadis, dirante: Pretigu vian ĉiutagan laboron, kiel tiam, kiam vi havis pajlon."],[5,14,"Kaj la kontrolistojn Izraelidojn, starigitajn super ili de la voktoj de Faraono, oni batadis, dirante: Kial vi ne pretigis vian ordonitan nombron da brikoj hieraŭ kaj hodiaŭ, kiel ĝis nun?","Kaj la kontrolistojn Izraelidojn, starigitajn super ili de la voktoj de Faraono, oni batadis, dirante: Kial vi ne pretigis vian ordonitan nombron da brikoj hieraŭ kaj hodiaŭ, kiel ĝis nun?"],[5,15,"La kontrolistoj Izraelidoj venis kaj kriis al Faraono, dirante: Kial vi agas tiel kun viaj sklavoj?","La kontrolistoj Izraelidoj venis kaj kriis al Faraono, dirante: Kial vi agas tiel kun viaj sklavoj?"],[5,16,"Pajlo ne estas donata al viaj sklavoj, kaj brikojn oni ordonas al ni fari; kaj nun viaj sklavoj estas batataj, kaj via popolo pekas.","Pajlo ne estas donata al viaj sklavoj, kaj brikojn oni ordonas al ni fari; kaj nun viaj sklavoj estas batataj, kaj via popolo pekas."],[5,17,"Sed li diris: Mallaboruloj vi estas, mallaboruloj, tial vi diras: Ni iru, ni alportu oferon al la Eternulo.","Sed li diris: Mallaboruloj vi estas, mallaboruloj, tial vi diras: Ni iru, ni alportu oferon al la Eternulo."],[5,18,"Kaj nun iru, laboru, kaj pajlon oni ne donos al vi, kaj la difinitan nombron da brikoj liveru.","Kaj nun iru, laboru, kaj pajlon oni ne donos al vi, kaj la difinitan nombron da brikoj liveru."],[5,19,"Kaj la kontrolistoj Izraelidoj vidis, ke estas al ili malbone, ĉar estas dirite: Ne malgrandigu la ĉiutagan nombron de viaj brikoj.","Kaj la kontrolistoj Izraelidoj vidis, ke estas al ili malbone, ĉar estas dirite: Ne malgrandigu la ĉiutagan nombron de viaj brikoj."],[5,20,"Ili renkontis Moseon kaj Aaronon, kiuj staris antaŭ ili, kiam ili eliris de Faraono.","Ili renkontis Moseon kaj Aaronon, kiuj staris antaŭ ili, kiam ili eliris de Faraono."],[5,21,"Kaj ili diris al tiuj: La Eternulo rigardu vin, kaj juĝu vin por tio, ke vi malbonodorigis nian odoron antaŭ Faraono kaj antaŭ liaj servantoj, kaj donis glavon en iliajn manojn, por mortigi nin.","Kaj ili diris al tiuj: La Eternulo rigardu vin, kaj juĝu vin por tio, ke vi malbonodorigis nian odoron antaŭ Faraono kaj antaŭ liaj servantoj, kaj donis glavon en iliajn manojn, por mortigi nin."],[5,22,"Tiam Moseo turnis sin al la Eternulo, kaj diris: Mia Sinjoro! kial Vi faris malbonon al tiu popolo? kial Vi sendis min?","Tiam Moseo turnis sin al la Eternulo, kaj diris: Mia Sinjoro! kial Vi faris malbonon al tiu popolo? kial Vi sendis min?"],[5,23,"De tiu tempo, kiam mi venis al Faraono, por paroli en Via nomo, li fariĝis pli malbona kontraŭ tiu popolo, kaj Vi ne savis Vian popolon.","De tiu tempo, kiam mi venis al Faraono, por paroli en Via nomo, li fariĝis pli malbona kontraŭ tiu popolo, kaj Vi ne savis Vian popolon."],[6,1,"Sed la Eternulo diris al Moseo: Nun vi vidos, kion Mi faros al Faraono; ĉar pro mano forta li foririgos ilin kaj pro mano forta li elpelos ilin el sia lando.","Sed la Eternulo diris al Moseo: Nun vi vidos, kion Mi faros al Faraono; ĉar pro mano forta li foririgos ilin kaj pro mano forta li elpelos ilin el sia lando."],[6,2,"Kaj Dio ekparolis al Moseo kaj diris al li: Mi estas la ETERNULO .","Kaj Dio ekparolis al Moseo kaj diris al li: Mi estas la ETERNULO ."],[6,3,"Mi aperis al Abraham, al Isaak, kaj al Jakob kiel Dio la Plejpotenca, sed Mian nomon ETERNULO Mi ne sciigis al ili.","Mi aperis al Abraham, al Isaak, kaj al Jakob kiel Dio la Plejpotenca, sed Mian nomon ETERNULO Mi ne sciigis al ili."],[6,4,"Mi starigis Mian interligon kun ili, ke Mi donos al ili la landon Kanaanan, la landon de ilia migrado, en kiu ili loĝis kiel fremduloj.","Mi starigis Mian interligon kun ili, ke Mi donos al ili la landon Kanaanan, la landon de ilia migrado, en kiu ili loĝis kiel fremduloj."],[6,5,"Kaj Mi aŭdis la ĝemadon de la Izraelidoj, kiujn la Egiptoj premas per laboroj, kaj Mi rememoris Mian interligon.","Kaj Mi aŭdis la ĝemadon de la Izraelidoj, kiujn la Egiptoj premas per laboroj, kaj Mi rememoris Mian interligon."],[6,6,"Tial diru al la Izraelidoj: Mi estas la Eternulo, kaj Mi elirigos vin el sub la jugo de Egiptujo, kaj Mi liberigos vin el ilia sklaveco, kaj Mi savos vin per etendita brako kaj grandaj juĝoj.","Tial diru al la Izraelidoj: Mi estas la Eternulo, kaj Mi elirigos vin el sub la jugo de Egiptujo, kaj Mi liberigos vin el ilia sklaveco, kaj Mi savos vin per etendita brako kaj grandaj juĝoj."],[6,7,"Kaj Mi prenos vin kiel Mian popolon, kaj Mi estos via Dio; kaj vi scios, ke Mi estas la Eternulo, via Dio, kiu elirigas vin el sub la jugo de Egiptujo.","Kaj Mi prenos vin kiel Mian popolon, kaj Mi estos via Dio; kaj vi scios, ke Mi estas la Eternulo, via Dio, kiu elirigas vin el sub la jugo de Egiptujo."],[6,8,"Kaj Mi venigos vin en la landon, pri kiu Mi, levinte Mian manon, promesis, ke Mi donos ĝin al Abraham, al Isaak, kaj al Jakob, kaj Mi donos ĝin al vi kiel posedaĵon, Mi, la Eternulo.","Kaj Mi venigos vin en la landon, pri kiu Mi, levinte Mian manon, promesis, ke Mi donos ĝin al Abraham, al Isaak, kaj al Jakob, kaj Mi donos ĝin al vi kiel posedaĵon, Mi, la Eternulo."],[6,9,"Moseo parolis tiel al la Izraelidoj; sed ili ne aŭskultis Moseon pro malforteco de spirito kaj pro la malfacilaj laboroj.","Moseo parolis tiel al la Izraelidoj; sed ili ne aŭskultis Moseon pro malforteco de spirito kaj pro la malfacilaj laboroj."],[6,10,"Kaj la Eternulo ekparolis al Moseo, dirante:","Kaj la Eternulo ekparolis al Moseo, dirante:"],[6,11,"Eniru, diru al Faraono, la reĝo de Egiptujo, ke li ellasu la Izraelidojn el sia lando.","Eniru, diru al Faraono, la reĝo de Egiptujo, ke li ellasu la Izraelidojn el sia lando."],[6,12,"Moseo ekparolis antaŭ la Eternulo, dirante: Jen la Izraelidoj ne aŭskultas min, kiel do min aŭskultos Faraono? kaj mi havas nelertajn lipojn.","Moseo ekparolis antaŭ la Eternulo, dirante: Jen la Izraelidoj ne aŭskultas min, kiel do min aŭskultos Faraono? kaj mi havas nelertajn lipojn."],[6,13,"Sed la Eternulo ekparolis al Moseo kaj al Aaron, kaj donis al ili ordonojn por la Izraelidoj, kaj por Faraono, reĝo de Egiptujo, por elirigi la Izraelidojn el la lando Egipta.","Sed la Eternulo ekparolis al Moseo kaj al Aaron, kaj donis al ili ordonojn por la Izraelidoj, kaj por Faraono, reĝo de Egiptujo, por elirigi la Izraelidojn el la lando Egipta."],[6,14,"Jen estas la ĉefoj de iliaj familioj: la filoj de Ruben, unuenaskito de Izrael: Ĥanoĥ kaj Palu, Ĥecron kaj Karmi. Tio estas la familioj de Ruben.","Jen estas la ĉefoj de iliaj familioj: la filoj de Ruben, unuenaskito de Izrael: Ĥanoĥ kaj Palu, Ĥecron kaj Karmi. Tio estas la familioj de Ruben."],[6,15,"Kaj la filoj de Simeon: Jemuel kaj Jamin kaj Ohad kaj Jaĥin kaj Coĥar, kaj Ŝaul, filo de Kanaanidino. Tio estas la familioj de Simeon.","Kaj la filoj de Simeon: Jemuel kaj Jamin kaj Ohad kaj Jaĥin kaj Coĥar, kaj Ŝaul, filo de Kanaanidino. Tio estas la familioj de Simeon."],[6,16,"Kaj jen estas la nomoj de la filoj de Levi laŭ ilia naskiĝo: Gerŝon kaj Kehat kaj Merari. La daŭro de la vivo de Levi estis cent tridek sep jaroj.","Kaj jen estas la nomoj de la filoj de Levi laŭ ilia naskiĝo: Gerŝon kaj Kehat kaj Merari. La daŭro de la vivo de Levi estis cent tridek sep jaroj."],[6,17,"La filoj de Gerŝon: Libni kaj Ŝimei, kun iliaj familioj.","La filoj de Gerŝon: Libni kaj Ŝimei, kun iliaj familioj."],[6,18,"Kaj la filoj de Kehat: Amram kaj Jichar kaj Ĥebron kaj Uziel. La daŭro de la vivo de Kehat estis cent tridek tri jaroj.","Kaj la filoj de Kehat: Amram kaj Jichar kaj Ĥebron kaj Uziel. La daŭro de la vivo de Kehat estis cent tridek tri jaroj."],[6,19,"Kaj la filoj de Merari: Maĥli kaj Muŝi. Tio estas la familioj de Levi laŭ ilia naskiĝo.","Kaj la filoj de Merari: Maĥli kaj Muŝi. Tio estas la familioj de Levi laŭ ilia naskiĝo."],[6,20,"Amram prenis al si sian onklinon Joĥebed kiel edzinon, kaj ŝi naskis al li Aaronon kaj Moseon. La daŭro de la vivo de Amram estis cent tridek sep jaroj.","Amram prenis al si sian onklinon Joĥebed kiel edzinon, kaj ŝi naskis al li Aaronon kaj Moseon. La daŭro de la vivo de Amram estis cent tridek sep jaroj."],[6,21,"Kaj la filoj de Jichar: Koraĥ kaj Nefeg kaj Ziĥri.","Kaj la filoj de Jichar: Koraĥ kaj Nefeg kaj Ziĥri."],[6,22,"Kaj la filoj de Uziel: Miŝael kaj Elcafan kaj Sitri.","Kaj la filoj de Uziel: Miŝael kaj Elcafan kaj Sitri."],[6,23,"Aaron prenis al si Eliŝeban, filinon de Aminadab kaj fratinon de Naĥŝon, kiel edzinon, kaj ŝi naskis al li Nadabon kaj Abihun, Eleazaron kaj Itamaron.","Aaron prenis al si Eliŝeban, filinon de Aminadab kaj fratinon de Naĥŝon, kiel edzinon, kaj ŝi naskis al li Nadabon kaj Abihun, Eleazaron kaj Itamaron."],[6,24,"Kaj la filoj de Koraĥ: Asir kaj Elkana kaj Abiasaf. Tio estas la familioj de la Koraĥidoj.","Kaj la filoj de Koraĥ: Asir kaj Elkana kaj Abiasaf. Tio estas la familioj de la Koraĥidoj."],[6,25,"Eleazar, la filo de Aaron, prenis al si edzinon el la filinoj de Putiel, kaj ŝi naskis al li Pineĥason. Tio estas la ĉefoj de la Leviidoj laŭ iliaj familioj.","Eleazar, la filo de Aaron, prenis al si edzinon el la filinoj de Putiel, kaj ŝi naskis al li Pineĥason. Tio estas la ĉefoj de la Leviidoj laŭ iliaj familioj."],[6,26,"Tio estas tiuj Aaron kaj Moseo, al kiuj la Eternulo diris: Elirigu la Izraelidojn el la lando Egipta laŭ iliaj taĉmentoj.","Tio estas tiuj Aaron kaj Moseo, al kiuj la Eternulo diris: Elirigu la Izraelidojn el la lando Egipta laŭ iliaj taĉmentoj."],[6,27,"Tio estas ili, kiuj parolis al Faraono, reĝo de Egiptujo, por elirigi la Izraelidojn el Egiptujo; tio estas Moseo kaj Aaron.","Tio estas ili, kiuj parolis al Faraono, reĝo de Egiptujo, por elirigi la Izraelidojn el Egiptujo; tio estas Moseo kaj Aaron."],[6,28,"En tiu tago, kiam la Eternulo parolis al Moseo en la lando Egipta,","En tiu tago, kiam la Eternulo parolis al Moseo en la lando Egipta,"],[6,29,"la Eternulo diris al Moseo jene: Mi estas la Eternulo. Diru al Faraono, reĝo de Egiptujo, ĉion, kion Mi diras al vi.","la Eternulo diris al Moseo jene: Mi estas la Eternulo. Diru al Faraono, reĝo de Egiptujo, ĉion, kion Mi diras al vi."],[6,30,"Kaj Moseo diris antaŭ la Eternulo: Jen mi havas nelertajn lipojn; kiel do Faraono min aŭskultos?","Kaj Moseo diris antaŭ la Eternulo: Jen mi havas nelertajn lipojn; kiel do Faraono min aŭskultos?"],[7,1,"Sed la Eternulo diris al Moseo: Vidu, mi faris vin dio por Faraono; kaj via frato Aaron estos via profeto.","Sed la Eternulo diris al Moseo: Vidu, mi faris vin dio por Faraono; kaj via frato Aaron estos via profeto."],[7,2,"Vi parolos ĉion, kion Mi ordonos al vi; kaj via frato Aaron parolos al Faraono, ke li ellasu la Izraelidojn el sia lando.","Vi parolos ĉion, kion Mi ordonos al vi; kaj via frato Aaron parolos al Faraono, ke li ellasu la Izraelidojn el sia lando."],[7,3,"Sed Mi malmoligos la koron de Faraono, kaj Mi multigos Miajn signojn kaj Miajn miraklojn en la lando Egipta.","Sed Mi malmoligos la koron de Faraono, kaj Mi multigos Miajn signojn kaj Miajn miraklojn en la lando Egipta."],[7,4,"Kaj Faraono vin ne aŭskultos, kaj Mi metos Mian manon sur Egiptujon, kaj Mi elirigos Mian militistaron, Mian popolon, la Izraelidojn, el la lando Egipta per grandaj juĝoj.","Kaj Faraono vin ne aŭskultos, kaj Mi metos Mian manon sur Egiptujon, kaj Mi elirigos Mian militistaron, Mian popolon, la Izraelidojn, el la lando Egipta per grandaj juĝoj."],[7,5,"Kaj la Egiptoj sciiĝos, ke Mi estas la Eternulo, kiam Mi etendos Mian manon super la Egiptojn kaj elirigos la Izraelidojn el inter ili.","Kaj la Egiptoj sciiĝos, ke Mi estas la Eternulo, kiam Mi etendos Mian manon super la Egiptojn kaj elirigos la Izraelidojn el inter ili."],[7,6,"Kaj Moseo kaj Aaron faris, kiel ordonis al ili la Eternulo; tiel ili faris.","Kaj Moseo kaj Aaron faris, kiel ordonis al ili la Eternulo; tiel ili faris."],[7,7,"Moseo havis la aĝon de okdek jaroj, kaj Aaron havis la aĝon de okdek tri jaroj, kiam ili parolis al Faraono.","Moseo havis la aĝon de okdek jaroj, kaj Aaron havis la aĝon de okdek tri jaroj, kiam ili parolis al Faraono."],[7,8,"Kaj la Eternulo ekparolis al Moseo kaj al Aaron, dirante:","Kaj la Eternulo ekparolis al Moseo kaj al Aaron, dirante:"],[7,9,"Se Faraono diros al vi, ke vi faru miraklon, tiam diru al Aaron: Prenu vian bastonon kaj ĵetu ĝin antaŭ Faraonon; ĝi fariĝos serpento.","Se Faraono diros al vi, ke vi faru miraklon, tiam diru al Aaron: Prenu vian bastonon kaj ĵetu ĝin antaŭ Faraonon; ĝi fariĝos serpento."],[7,10,"Moseo kaj Aaron venis al Faraono, kaj faris tiel, kiel ordonis la Eternulo. Aaron ĵetis sian bastonon antaŭ Faraonon kaj antaŭ liajn servantojn, kaj ĝi fariĝis serpento.","Moseo kaj Aaron venis al Faraono, kaj faris tiel, kiel ordonis la Eternulo. Aaron ĵetis sian bastonon antaŭ Faraonon kaj antaŭ liajn servantojn, kaj ĝi fariĝis serpento."],[7,11,"Tiam ankaŭ Faraono alvokis la saĝulojn kaj sorĉistojn; kaj ankaŭ ili, la Egiptaj sorĉistoj, per siaj sorĉoj faris tiel.","Tiam ankaŭ Faraono alvokis la saĝulojn kaj sorĉistojn; kaj ankaŭ ili, la Egiptaj sorĉistoj, per siaj sorĉoj faris tiel."],[7,12,"Ĉiu el ili ĵetis sian bastonon, kaj ili fariĝis serpentoj; sed la bastono de Aaron englutis iliajn bastonojn.","Ĉiu el ili ĵetis sian bastonon, kaj ili fariĝis serpentoj; sed la bastono de Aaron englutis iliajn bastonojn."],[7,13,"Kaj malmoliĝis la koro de Faraono, kaj li ne aŭskultis ilin, kiel diris la Eternulo.","Kaj malmoliĝis la koro de Faraono, kaj li ne aŭskultis ilin, kiel diris la Eternulo."],[7,14,"Tiam la Eternulo diris al Moseo: Obstina estas la koro de Faraono, li ne volas forliberigi la popolon.","Tiam la Eternulo diris al Moseo: Obstina estas la koro de Faraono, li ne volas forliberigi la popolon."],[7,15,"Iru al Faraono matene; li eliros al la akvo; stariĝu renkonte al li sur la bordo de la rivero, kaj la bastonon, kiu transformiĝis en serpenton, prenu en vian manon.","Iru al Faraono matene; li eliros al la akvo; stariĝu renkonte al li sur la bordo de la rivero, kaj la bastonon, kiu transformiĝis en serpenton, prenu en vian manon."],[7,16,"Kaj diru al li: La Eternulo, Dio de la Hebreoj, sendis min al vi, por diri: Permesu al Mia popolo iri kaj fari al Mi servon en la dezerto; sed jen vi ĝis nun ne obeis.","Kaj diru al li: La Eternulo, Dio de la Hebreoj, sendis min al vi, por diri: Permesu al Mia popolo iri kaj fari al Mi servon en la dezerto; sed jen vi ĝis nun ne obeis."],[7,17,"Tiel diris la Eternulo: Per tio vi sciiĝos, ke Mi estas la Eternulo: jen per la bastono, kiu estas en mia mano, mi frapos la akvon, kiu estas en la rivero, kaj ĝi transformiĝos en sangon.","Tiel diris la Eternulo: Per tio vi sciiĝos, ke Mi estas la Eternulo: jen per la bastono, kiu estas en mia mano, mi frapos la akvon, kiu estas en la rivero, kaj ĝi transformiĝos en sangon."],[7,18,"Kaj la fiŝoj, kiuj estas en la rivero, mortos, kaj la rivero malbonodoros, kaj la Egiptoj abomenos trinki akvon el la rivero.","Kaj la fiŝoj, kiuj estas en la rivero, mortos, kaj la rivero malbonodoros, kaj la Egiptoj abomenos trinki akvon el la rivero."],[7,19,"Kaj la Eternulo diris al Moseo: Diru al Aaron: Prenu vian bastonon, kaj etendu vian manon super la akvojn de la Egiptoj, super iliajn riverojn, super iliajn torentojn kaj super iliajn lagojn kaj super ĉian kolektiĝon de iliaj akvoj, kaj ili fariĝu sango; kaj estu sango en la tuta lando Egipta, en la vazoj lignaj kaj en la vazoj ŝtonaj.","Kaj la Eternulo diris al Moseo: Diru al Aaron: Prenu vian bastonon, kaj etendu vian manon super la akvojn de la Egiptoj, super iliajn riverojn, super iliajn torentojn kaj super iliajn lagojn kaj super ĉian kolektiĝon de iliaj akvoj, kaj ili fariĝu sango; kaj estu sango en la tuta lando Egipta, en la vazoj lignaj kaj en la vazoj ŝtonaj."],[7,20,"Kaj Moseo kaj Aaron faris tiel, kiel ordonis la Eternulo. Kaj li levis la bastonon, kaj frapis la akvon, kiu estis en la rivero, antaŭ la okuloj de Faraono kaj antaŭ la okuloj de liaj servantoj; kaj la tuta akvo, kiu estis en la rivero, transformiĝis en sangon.","Kaj Moseo kaj Aaron faris tiel, kiel ordonis la Eternulo. Kaj li levis la bastonon, kaj frapis la akvon, kiu estis en la rivero, antaŭ la okuloj de Faraono kaj antaŭ la okuloj de liaj servantoj; kaj la tuta akvo, kiu estis en la rivero, transformiĝis en sangon."],[7,21,"Kaj la fiŝoj, kiuj estis en la rivero, mortis, kaj la rivero fariĝis malbonodora, kaj la Egiptoj ne povis trinki akvon el la rivero; kaj estis sango en la tuta lando Egipta.","Kaj la fiŝoj, kiuj estis en la rivero, mortis, kaj la rivero fariĝis malbonodora, kaj la Egiptoj ne povis trinki akvon el la rivero; kaj estis sango en la tuta lando Egipta."],[7,22,"Sed tiel same faris la sorĉistoj de Egiptujo per siaj sorĉoj. Kaj malmoliĝis la koro de Faraono, kaj li ne aŭskultis ilin, kiel diris la Eternulo.","Sed tiel same faris la sorĉistoj de Egiptujo per siaj sorĉoj. Kaj malmoliĝis la koro de Faraono, kaj li ne aŭskultis ilin, kiel diris la Eternulo."],[7,23,"Kaj Faraono turniĝis kaj eniris en sian domon, kaj lia koro ne atentis eĉ tion.","Kaj Faraono turniĝis kaj eniris en sian domon, kaj lia koro ne atentis eĉ tion."],[7,24,"Kaj ĉiuj Egiptoj ekfosis ĉirkaŭ la rivero pro akvo por trinki, ĉar ili ne povis trinki la akvon el la rivero.","Kaj ĉiuj Egiptoj ekfosis ĉirkaŭ la rivero pro akvo por trinki, ĉar ili ne povis trinki la akvon el la rivero."],[7,25,"Pasis sep tagoj, post kiam la Eternulo frapis la riveron.","Pasis sep tagoj, post kiam la Eternulo frapis la riveron."],[8,1,"Kaj la Eternulo diris al Moseo: Iru al Faraono, kaj diru al li: Tiel diris la Eternulo: Permesu al Mia popolo iri, por ke ĝi faru servon al Mi.","Kaj la Eternulo diris al Moseo: Iru al Faraono, kaj diru al li: Tiel diris la Eternulo: Permesu al Mia popolo iri, por ke ĝi faru servon al Mi."],[8,2,"Kaj se vi ne volos permesi tion, jen Mi frapos vian tutan regionon per ranoj;","Kaj se vi ne volos permesi tion, jen Mi frapos vian tutan regionon per ranoj;"],[8,3,"kaj eksvarmos la rivero per ranoj, kaj ili elrampos kaj venos en vian domon kaj en vian dormoĉambron kaj sur vian liton kaj en la domojn de viaj servantoj kaj de via popolo kaj en viajn fornojn kaj en viajn pastujojn;","kaj eksvarmos la rivero per ranoj, kaj ili elrampos kaj venos en vian domon kaj en vian dormoĉambron kaj sur vian liton kaj en la domojn de viaj servantoj kaj de via popolo kaj en viajn fornojn kaj en viajn pastujojn;"],[8,4,"kaj sur vin kaj sur vian popolon kaj sur ĉiujn viajn servantojn rampos la ranoj.","kaj sur vin kaj sur vian popolon kaj sur ĉiujn viajn servantojn rampos la ranoj."],[8,5,"Kaj la Eternulo diris al Moseo: Diru al Aaron: Etendu vian manon kun via bastono super la riverojn, super la torentojn, kaj super la lagojn, kaj elirigu la ranojn sur la landon Egiptan.","Kaj la Eternulo diris al Moseo: Diru al Aaron: Etendu vian manon kun via bastono super la riverojn, super la torentojn, kaj super la lagojn, kaj elirigu la ranojn sur la landon Egiptan."],[8,6,"Kaj Aaron etendis sian manon super la akvojn de Egiptujo, kaj la ranoj eliris kaj kovris la landon Egiptan.","Kaj Aaron etendis sian manon super la akvojn de Egiptujo, kaj la ranoj eliris kaj kovris la landon Egiptan."],[8,7,"Tion saman faris la sorĉistoj per siaj sorĉoj, kaj ili elirigis la ranojn sur la landon Egiptan.","Tion saman faris la sorĉistoj per siaj sorĉoj, kaj ili elirigis la ranojn sur la landon Egiptan."],[8,8,"Tiam Faraono alvokis Moseon kaj Aaronon, kaj diris: Preĝu al la Eternulo, ke Li forigu la ranojn for de mi kaj de mia popolo; tiam mi forliberigos la popolon, ke ĝi alportu oferon al la Eternulo.","Tiam Faraono alvokis Moseon kaj Aaronon, kaj diris: Preĝu al la Eternulo, ke Li forigu la ranojn for de mi kaj de mia popolo; tiam mi forliberigos la popolon, ke ĝi alportu oferon al la Eternulo."],[8,9,"Kaj Moseo diris al Faraono: Ordonu al mi, por kiu tempo mi devas preĝi pro vi kaj pro viaj servantoj kaj pro via popolo, ke malaperu la ranoj for de vi kaj el viaj domoj kaj nur en la rivero ili restu.","Kaj Moseo diris al Faraono: Ordonu al mi, por kiu tempo mi devas preĝi pro vi kaj pro viaj servantoj kaj pro via popolo, ke malaperu la ranoj for de vi kaj el viaj domoj kaj nur en la rivero ili restu."],[8,10,"Tiu diris: Por morgaŭ. Kaj li diris: Ĝi estu, kiel vi diris, por ke vi sciu, ke ekzistas neniu tia, kiel la Eternulo, nia Dio.","Tiu diris: Por morgaŭ. Kaj li diris: Ĝi estu, kiel vi diris, por ke vi sciu, ke ekzistas neniu tia, kiel la Eternulo, nia Dio."],[8,11,"Kaj foriĝos la ranoj for de vi kaj de viaj domoj kaj de viaj servantoj kaj de via popolo; nur en la rivero ili restos.","Kaj foriĝos la ranoj for de vi kaj de viaj domoj kaj de viaj servantoj kaj de via popolo; nur en la rivero ili restos."],[8,12,"Moseo kaj Aaron eliris for de Faraono, kaj Moseo ekvokis al la Eternulo pri la ranoj, kiujn li venigis sur Faraonon.","Moseo kaj Aaron eliris for de Faraono, kaj Moseo ekvokis al la Eternulo pri la ranoj, kiujn li venigis sur Faraonon."],[8,13,"Kaj la Eternulo faris laŭ la vortoj de Moseo; kaj mortis la ranoj en la domoj, en la kortoj, kaj sur la kampoj.","Kaj la Eternulo faris laŭ la vortoj de Moseo; kaj mortis la ranoj en la domoj, en la kortoj, kaj sur la kampoj."],[8,14,"Kaj oni kunŝovelis ilin en multajn amasojn, kaj la lando malbonodoriĝis.","Kaj oni kunŝovelis ilin en multajn amasojn, kaj la lando malbonodoriĝis."],[8,15,"Sed kiam Faraono vidis, ke fariĝis faciliĝo, li malmoligis sian koron kaj ne aŭskultis ilin, kiel diris la Eternulo.","Sed kiam Faraono vidis, ke fariĝis faciliĝo, li malmoligis sian koron kaj ne aŭskultis ilin, kiel diris la Eternulo."],[8,16,"Tiam la Eternulo diris al Moseo: Diru al Aaron: Etendu vian bastonon, kaj frapu la polvon de la tero, kaj el ĝi fariĝos pikmuŝoj en la tuta lando Egipta.","Tiam la Eternulo diris al Moseo: Diru al Aaron: Etendu vian bastonon, kaj frapu la polvon de la tero, kaj el ĝi fariĝos pikmuŝoj en la tuta lando Egipta."],[8,17,"Ili faris tiel: Aaron etendis sian manon kun sia bastono kaj frapis la polvon de la tero, kaj aperis pikmuŝoj sur la homoj kaj la brutoj. La tuta polvo de la tero fariĝis pikmuŝoj en la tuta lando Egipta.","Ili faris tiel: Aaron etendis sian manon kun sia bastono kaj frapis la polvon de la tero, kaj aperis pikmuŝoj sur la homoj kaj la brutoj. La tuta polvo de la tero fariĝis pikmuŝoj en la tuta lando Egipta."],[8,18,"Tiel faris la sorĉistoj per siaj sorĉoj, por elirigi pikmuŝojn, sed ili ne povis. Kaj la pikmuŝoj estis sur la homoj kaj sur la brutoj.","Tiel faris la sorĉistoj per siaj sorĉoj, por elirigi pikmuŝojn, sed ili ne povis. Kaj la pikmuŝoj estis sur la homoj kaj sur la brutoj."],[8,19,"Tiam la sorĉistoj diris al Faraono: Ĝi estas fingro de Dio. Sed la koro de Faraono restis obstina, kaj li ne aŭskultis ilin, kiel diris la Eternulo.","Tiam la sorĉistoj diris al Faraono: Ĝi estas fingro de Dio. Sed la koro de Faraono restis obstina, kaj li ne aŭskultis ilin, kiel diris la Eternulo."],[8,20,"Kaj la Eternulo diris al Moseo: Leviĝu frue matene, kaj stariĝu antaŭ Faraono, kiam li iros al la akvo, kaj diru al li: Tiel diris la Eternulo: Forliberigu Mian popolon, ke ĝi faru servon al Mi.","Kaj la Eternulo diris al Moseo: Leviĝu frue matene, kaj stariĝu antaŭ Faraono, kiam li iros al la akvo, kaj diru al li: Tiel diris la Eternulo: Forliberigu Mian popolon, ke ĝi faru servon al Mi."],[8,21,"Ĉar se vi ne forliberigos Mian popolon, jen Mi venigos sur vin kaj sur viajn servantojn kaj sur vian popolon kaj en viajn domojn fiinsektojn; kaj pleniĝos de la fiinsektoj la domoj de la Egiptoj, kaj ankaŭ la tero, sur kiu ili estas.","Ĉar se vi ne forliberigos Mian popolon, jen Mi venigos sur vin kaj sur viajn servantojn kaj sur vian popolon kaj en viajn domojn fiinsektojn; kaj pleniĝos de la fiinsektoj la domoj de la Egiptoj, kaj ankaŭ la tero, sur kiu ili estas."],[8,22,"Kaj Mi distingos en tiu tago la teron de Goŝen, sur kiu troviĝas Mia popolo, ke tie ne estu fiinsektoj; por ke vi sciiĝu, ke Mi estas la Eternulo meze de la tero.","Kaj Mi distingos en tiu tago la teron de Goŝen, sur kiu troviĝas Mia popolo, ke tie ne estu fiinsektoj; por ke vi sciiĝu, ke Mi estas la Eternulo meze de la tero."],[8,23,"Kaj Mi faros apartigon inter Mia popolo kaj via popolo; morgaŭ okazos tiu signo.","Kaj Mi faros apartigon inter Mia popolo kaj via popolo; morgaŭ okazos tiu signo."],[8,24,"Kaj la Eternulo faris tiel, kaj aperis multego da fiinsektoj en la domo de Faraono kaj en la domoj de liaj servantoj kaj en la tuta lando Egipta; difektiĝis la tero kaŭze de la fiinsektoj.","Kaj la Eternulo faris tiel, kaj aperis multego da fiinsektoj en la domo de Faraono kaj en la domoj de liaj servantoj kaj en la tuta lando Egipta; difektiĝis la tero kaŭze de la fiinsektoj."],[8,25,"Tiam Faraono alvokis Moseon kaj Aaronon, kaj diris: Iru, alportu oferon al via Dio en la lando.","Tiam Faraono alvokis Moseon kaj Aaronon, kaj diris: Iru, alportu oferon al via Dio en la lando."],[8,26,"Sed Moseo diris: Ne estas oportune fari tiel; ĉar abomenindaĵo por la Egiptoj estus nia oferado al la Eternulo, nia Dio; se oferadon abomenindan por la Egiptoj ni faros antaŭ iliaj okuloj, ĉu ili tiam nin ne ŝtonmortigos?","Sed Moseo diris: Ne estas oportune fari tiel; ĉar abomenindaĵo por la Egiptoj estus nia oferado al la Eternulo, nia Dio; se oferadon abomenindan por la Egiptoj ni faros antaŭ iliaj okuloj, ĉu ili tiam nin ne ŝtonmortigos?"],[8,27,"Vojon de tri tagoj ni iros en la dezerton, kaj ni faros oferon al la Eternulo, nia Dio, kiel Li diros al ni.","Vojon de tri tagoj ni iros en la dezerton, kaj ni faros oferon al la Eternulo, nia Dio, kiel Li diros al ni."],[8,28,"Tiam Faraono diris: Mi forliberigos vin, kaj vi faros oferon al la Eternulo, via Dio, en la dezerto; nur ne foriru malproksime; preĝu pro mi.","Tiam Faraono diris: Mi forliberigos vin, kaj vi faros oferon al la Eternulo, via Dio, en la dezerto; nur ne foriru malproksime; preĝu pro mi."],[8,29,"Kaj Moseo diris: Jen mi foriras de vi, kaj mi preĝos al la Eternulo, ke foriĝu la fiinsektoj for de Faraono, de liaj servantoj, kaj de lia popolo morgaŭ; sed Faraono ne plu trompu, ne forliberigante la popolon, por fari oferon al la Eternulo.","Kaj Moseo diris: Jen mi foriras de vi, kaj mi preĝos al la Eternulo, ke foriĝu la fiinsektoj for de Faraono, de liaj servantoj, kaj de lia popolo morgaŭ; sed Faraono ne plu trompu, ne forliberigante la popolon, por fari oferon al la Eternulo."],[8,30,"Moseo eliris for de Faraono kaj preĝis al la Eternulo.","Moseo eliris for de Faraono kaj preĝis al la Eternulo."],[8,31,"Kaj la Eternulo faris, kiel diris Moseo, kaj forigis la fiinsektojn for de Faraono, de liaj servantoj, kaj de lia popolo; ne restis eĉ unu.","Kaj la Eternulo faris, kiel diris Moseo, kaj forigis la fiinsektojn for de Faraono, de liaj servantoj, kaj de lia popolo; ne restis eĉ unu."],[8,32,"Sed Faraono obstinigis sian koron ankaŭ ĉi tiun fojon, kaj ne forliberigis la popolon.","Sed Faraono obstinigis sian koron ankaŭ ĉi tiun fojon, kaj ne forliberigis la popolon."],[9,1,"Kaj la Eternulo diris al Moseo: Iru al Faraono, kaj diru al li: Tiel diris la Eternulo, Dio de la Hebreoj: Forliberigu Mian popolon, ke ĝi faru al Mi servon.","Kaj la Eternulo diris al Moseo: Iru al Faraono, kaj diru al li: Tiel diris la Eternulo, Dio de la Hebreoj: Forliberigu Mian popolon, ke ĝi faru al Mi servon."],[9,2,"Ĉar se vi ne volos forliberigi kaj vi plue ilin retenos,","Ĉar se vi ne volos forliberigi kaj vi plue ilin retenos,"],[9,3,"jen la mano de la Eternulo estos sur viaj brutoj, kiuj estas sur la kampo, sur la ĉevaloj, sur la azenoj, sur la kameloj, sur la bovoj, kaj sur la ŝafoj; estos sur ili tre forta pesto.","jen la mano de la Eternulo estos sur viaj brutoj, kiuj estas sur la kampo, sur la ĉevaloj, sur la azenoj, sur la kameloj, sur la bovoj, kaj sur la ŝafoj; estos sur ili tre forta pesto."],[9,4,"Kaj la Eternulo faros apartigon inter la brutoj de la Izraelidoj kaj la brutoj de la Egiptoj; kaj el ĉio, kio apartenas al la Izraelidoj, mortos nenio.","Kaj la Eternulo faros apartigon inter la brutoj de la Izraelidoj kaj la brutoj de la Egiptoj; kaj el ĉio, kio apartenas al la Izraelidoj, mortos nenio."],[9,5,"Kaj la Eternulo difinis tempon, dirante: Morgaŭ la Eternulo faros tiun aferon en la lando.","Kaj la Eternulo difinis tempon, dirante: Morgaŭ la Eternulo faros tiun aferon en la lando."],[9,6,"Kaj la Eternulo faris tion en la sekvanta tago, kaj mortis ĉiuj brutoj de la Egiptoj, sed el la brutoj de la Izraelidoj ne mortis eĉ unu.","Kaj la Eternulo faris tion en la sekvanta tago, kaj mortis ĉiuj brutoj de la Egiptoj, sed el la brutoj de la Izraelidoj ne mortis eĉ unu."],[9,7,"Faraono sendis, kaj oni vidis, ke el la brutoj de la Izraelidoj ne mortis eĉ unu. Sed la koro de Faraono estis obstina, kaj li ne forliberigis la popolon.","Faraono sendis, kaj oni vidis, ke el la brutoj de la Izraelidoj ne mortis eĉ unu. Sed la koro de Faraono estis obstina, kaj li ne forliberigis la popolon."],[9,8,"Tiam la Eternulo diris al Moseo kaj al Aaron: Prenu al vi plenmanojn da cindro el la forno, kaj Moseo ĵetu ĝin al la ĉielo antaŭ la okuloj de Faraono.","Tiam la Eternulo diris al Moseo kaj al Aaron: Prenu al vi plenmanojn da cindro el la forno, kaj Moseo ĵetu ĝin al la ĉielo antaŭ la okuloj de Faraono."],[9,9,"Kaj ĝi fariĝos polvo super la tuta lando Egipta, kaj sur la homoj kaj sur la bestoj fariĝos el ĝi brulumaj abscesoj en la tuta lando Egipta.","Kaj ĝi fariĝos polvo super la tuta lando Egipta, kaj sur la homoj kaj sur la bestoj fariĝos el ĝi brulumaj abscesoj en la tuta lando Egipta."],[9,10,"Kaj ili prenis cindron el la forno kaj stariĝis antaŭ Faraono, kaj Moseo ĵetis ĝin al la ĉielo, kaj aperis brulumaj abscesoj sur la homoj kaj sur la bestoj.","Kaj ili prenis cindron el la forno kaj stariĝis antaŭ Faraono, kaj Moseo ĵetis ĝin al la ĉielo, kaj aperis brulumaj abscesoj sur la homoj kaj sur la bestoj."],[9,11,"Kaj la sorĉistoj ne povis teni sin antaŭ Moseo pro la abscesoj, ĉar la abscesoj estis sur la sorĉistoj kaj sur ĉiuj Egiptoj.","Kaj la sorĉistoj ne povis teni sin antaŭ Moseo pro la abscesoj, ĉar la abscesoj estis sur la sorĉistoj kaj sur ĉiuj Egiptoj."],[9,12,"Sed la Eternulo obstinigis la koron de Faraono, kaj li ne aŭskultis ilin, kiel diris la Eternulo al Moseo.","Sed la Eternulo obstinigis la koron de Faraono, kaj li ne aŭskultis ilin, kiel diris la Eternulo al Moseo."],[9,13,"Tiam la Eternulo diris al Moseo: Leviĝu frue matene kaj stariĝu antaŭ Faraono, kaj diru al li: Tiel diris la Eternulo, Dio de la Hebreoj: Forliberigu Mian popolon, ke ĝi faru al Mi servon.","Tiam la Eternulo diris al Moseo: Leviĝu frue matene kaj stariĝu antaŭ Faraono, kaj diru al li: Tiel diris la Eternulo, Dio de la Hebreoj: Forliberigu Mian popolon, ke ĝi faru al Mi servon."],[9,14,"Ĉar ĉi tiun fojon Mi sendos ĉiujn Miajn frapojn en vian koron kaj sur viajn servantojn kaj sur vian popolon, por ke vi sciu, ke ne ekzistas simila al Mi sur la tuta tero.","Ĉar ĉi tiun fojon Mi sendos ĉiujn Miajn frapojn en vian koron kaj sur viajn servantojn kaj sur vian popolon, por ke vi sciu, ke ne ekzistas simila al Mi sur la tuta tero."],[9,15,"Ĉar nun Mi etendus Mian manon kaj batus vin kaj vian popolon per pesto, kaj vi malaperus de la tero;","Ĉar nun Mi etendus Mian manon kaj batus vin kaj vian popolon per pesto, kaj vi malaperus de la tero;"],[9,16,"sed nur por tio Mi vin konservis, ke Mi montru sur vi Mian forton, kaj por ke oni rakontu pri Mia nomo sur la tuta tero.","sed nur por tio Mi vin konservis, ke Mi montru sur vi Mian forton, kaj por ke oni rakontu pri Mia nomo sur la tuta tero."],[9,17,"Ankoraŭ vi retenas Mian popolon, kaj ne forliberigas ĝin.","Ankoraŭ vi retenas Mian popolon, kaj ne forliberigas ĝin."],[9,18,"Jen morgaŭ en ĉi tiu tempo Mi pluvigos tre grandan hajlon, tian, ke simila al ĝi ne estis en Egiptujo de post la tago de ĝia fondiĝo ĝis nun.","Jen morgaŭ en ĉi tiu tempo Mi pluvigos tre grandan hajlon, tian, ke simila al ĝi ne estis en Egiptujo de post la tago de ĝia fondiĝo ĝis nun."],[9,19,"Kaj nun sendu, kolektu viajn brutojn, kaj ĉion, kion vi havas sur la kampo; sur ĉiun homon kaj bruton, kiuj troviĝos sur la kampo kaj ne kolektiĝos en la domon, falos la hajlo, kaj ili mortos.","Kaj nun sendu, kolektu viajn brutojn, kaj ĉion, kion vi havas sur la kampo; sur ĉiun homon kaj bruton, kiuj troviĝos sur la kampo kaj ne kolektiĝos en la domon, falos la hajlo, kaj ili mortos."],[9,20,"Kiu el la servantoj de Faraono timis la vorton de la Eternulo, tiu rapide envenigis siajn sklavojn kaj brutojn en la domojn;","Kiu el la servantoj de Faraono timis la vorton de la Eternulo, tiu rapide envenigis siajn sklavojn kaj brutojn en la domojn;"],[9,21,"sed kiu ne atentis la vorton de la Eternulo, tiu lasis siajn sklavojn kaj siajn brutojn sur la kampo.","sed kiu ne atentis la vorton de la Eternulo, tiu lasis siajn sklavojn kaj siajn brutojn sur la kampo."],[9,22,"Kaj la Eternulo diris al Moseo: Etendu vian manon al la ĉielo, kaj venos hajlo en la tuta lando Egipta, sur la homojn kaj sur la brutojn kaj sur ĉiujn herbojn de la kampo en la lando Egipta.","Kaj la Eternulo diris al Moseo: Etendu vian manon al la ĉielo, kaj venos hajlo en la tuta lando Egipta, sur la homojn kaj sur la brutojn kaj sur ĉiujn herbojn de la kampo en la lando Egipta."],[9,23,"Kaj Moseo etendis sian bastonon al la ĉielo; kaj la Eternulo aperigis tondrojn kaj hajlon, kaj fajro iris sur la teron, kaj la Eternulo pluvigis hajlon sur la landon Egiptan.","Kaj Moseo etendis sian bastonon al la ĉielo; kaj la Eternulo aperigis tondrojn kaj hajlon, kaj fajro iris sur la teron, kaj la Eternulo pluvigis hajlon sur la landon Egiptan."],[9,24,"Kaj estis hajlo, kaj fajro ekflamadis meze de la hajlo, en tiel forta grado, ke io simila neniam estis en la tuta lando Egipta de post la tempo, kiam en ĝi aperis popolo.","Kaj estis hajlo, kaj fajro ekflamadis meze de la hajlo, en tiel forta grado, ke io simila neniam estis en la tuta lando Egipta de post la tempo, kiam en ĝi aperis popolo."],[9,25,"Kaj la hajlo batdifektis en la tuta lando Egipta ĉion, kio estis sur la kampo; homojn kaj brutojn kaj ĉiun herbon de la kampo batdifektis la hajlo, kaj ĉiujn arbojn de la kampo ĝi rompis.","Kaj la hajlo batdifektis en la tuta lando Egipta ĉion, kio estis sur la kampo; homojn kaj brutojn kaj ĉiun herbon de la kampo batdifektis la hajlo, kaj ĉiujn arbojn de la kampo ĝi rompis."],[9,26,"Nur en la lando Goŝen, kie estis la Izraelidoj, ne estis hajlo.","Nur en la lando Goŝen, kie estis la Izraelidoj, ne estis hajlo."],[9,27,"Tiam Faraono sendis, kaj alvokis Moseon kaj Aaronon, kaj diris al ili: Mi pekis la nunan fojon; la Eternulo estas la pravulo, mi kaj mia popolo estas la malpravuloj.","Tiam Faraono sendis, kaj alvokis Moseon kaj Aaronon, kaj diris al ili: Mi pekis la nunan fojon; la Eternulo estas la pravulo, mi kaj mia popolo estas la malpravuloj."],[9,28,"Preĝu al la Eternulo, ke ĉesiĝu la tondroj de Dio kaj la hajlo; tiam mi forliberigos vin, kaj vi ne plu restos.","Preĝu al la Eternulo, ke ĉesiĝu la tondroj de Dio kaj la hajlo; tiam mi forliberigos vin, kaj vi ne plu restos."],[9,29,"Kaj Moseo diris al li: Kiam mi eliros el la urbo, mi etendos miajn manojn al la Eternulo; la tondroj ĉesiĝos kaj la hajlo ne plu estos, por ke vi sciiĝu, ke al la Eternulo apartenas la tero.","Kaj Moseo diris al li: Kiam mi eliros el la urbo, mi etendos miajn manojn al la Eternulo; la tondroj ĉesiĝos kaj la hajlo ne plu estos, por ke vi sciiĝu, ke al la Eternulo apartenas la tero."],[9,30,"Sed mi scias, ke vi kaj viaj servantoj ankoraŭ ne timas Dion, la Eternulon.","Sed mi scias, ke vi kaj viaj servantoj ankoraŭ ne timas Dion, la Eternulon."],[9,31,"La lino kaj la hordeo estis batdifektitaj, ĉar la hordeo havis spikojn kaj la lino havis burĝonojn;","La lino kaj la hordeo estis batdifektitaj, ĉar la hordeo havis spikojn kaj la lino havis burĝonojn;"],[9,32,"sed la tritiko kaj la spelto ne estis batdifektitaj, ĉar ili estis malfrusezonaj.","sed la tritiko kaj la spelto ne estis batdifektitaj, ĉar ili estis malfrusezonaj."],[9,33,"Moseo eliris de Faraono el la urbo kaj etendis siajn manojn al la Eternulo; tiam ĉesiĝis la tondroj kaj la hajlo, kaj pluvo ne plu verŝiĝis sur la teron.","Moseo eliris de Faraono el la urbo kaj etendis siajn manojn al la Eternulo; tiam ĉesiĝis la tondroj kaj la hajlo, kaj pluvo ne plu verŝiĝis sur la teron."],[9,34,"Kiam Faraono vidis, ke ĉesiĝis la pluvo kaj la hajlo kaj la tondroj, tiam li plue pekis kaj obstinigis sian koron, li kaj liaj servantoj.","Kiam Faraono vidis, ke ĉesiĝis la pluvo kaj la hajlo kaj la tondroj, tiam li plue pekis kaj obstinigis sian koron, li kaj liaj servantoj."],[9,35,"La koro de Faraono restis obstina, kaj li ne forliberigis la Izraelidojn, kiel diris la Eternulo per Moseo.","La koro de Faraono restis obstina, kaj li ne forliberigis la Izraelidojn, kiel diris la Eternulo per Moseo."],[10,1,"Kaj la Eternulo diris al Moseo: Iru al Faraono, ĉar Mi obstinigis lian koron kaj la korojn de liaj servantoj, por ke Mi faru ĉi tiujn Miajn signojn inter ili;","Kaj la Eternulo diris al Moseo: Iru al Faraono, ĉar Mi obstinigis lian koron kaj la korojn de liaj servantoj, por ke Mi faru ĉi tiujn Miajn signojn inter ili;"],[10,2,"kaj por ke vi rakontu al via filo kaj al via nepo, kion Mi plenumis sur la Egiptoj, kaj pri Miaj signoj, kiujn Mi faris inter ili; kaj por ke vi sciu, ke Mi estas la Eternulo.","kaj por ke vi rakontu al via filo kaj al via nepo, kion Mi plenumis sur la Egiptoj, kaj pri Miaj signoj, kiujn Mi faris inter ili; kaj por ke vi sciu, ke Mi estas la Eternulo."],[10,3,"Moseo kaj Aaron venis al Faraono, kaj diris al li: Tiel diris la Eternulo, Dio de la Hebreoj: Ĝis kiam vi rifuzos humiliĝi antaŭ Mi? forliberigu Mian popolon, ke ĝi faru al Mi servon.","Moseo kaj Aaron venis al Faraono, kaj diris al li: Tiel diris la Eternulo, Dio de la Hebreoj: Ĝis kiam vi rifuzos humiliĝi antaŭ Mi? forliberigu Mian popolon, ke ĝi faru al Mi servon."],[10,4,"Ĉar se vi rifuzos forliberigi Mian popolon, jen Mi venigos morgaŭ akridojn en vian regionon;","Ĉar se vi rifuzos forliberigi Mian popolon, jen Mi venigos morgaŭ akridojn en vian regionon;"],[10,5,"kaj ili kovros la supraĵon de la tero tiel, ke oni ne povos vidi la teron; kaj ili formanĝos ĉion, kio restis ĉe vi savita kontraŭ la hajlo, kaj ili ĉirkaŭmanĝos ĉiujn arbojn, kiuj kreskas ĉe vi sur la kampo;","kaj ili kovros la supraĵon de la tero tiel, ke oni ne povos vidi la teron; kaj ili formanĝos ĉion, kio restis ĉe vi savita kontraŭ la hajlo, kaj ili ĉirkaŭmanĝos ĉiujn arbojn, kiuj kreskas ĉe vi sur la kampo;"],[10,6,"kaj ili plenigos viajn domojn kaj la domojn de ĉiuj viaj servantoj kaj la domojn de ĉiuj Egiptoj tiel, kiel ne vidis viaj patroj kaj viaj prapatroj de post la tago, kiam ili aperis sur la tero ĝis la nuna tago. Kaj li turniĝis kaj eliris for de Faraono.","kaj ili plenigos viajn domojn kaj la domojn de ĉiuj viaj servantoj kaj la domojn de ĉiuj Egiptoj tiel, kiel ne vidis viaj patroj kaj viaj prapatroj de post la tago, kiam ili aperis sur la tero ĝis la nuna tago. Kaj li turniĝis kaj eliris for de Faraono."],[10,7,"Tiam la servantoj de Faraono diris al li: Ĝis kiam tiu homo estos por ni suferilo? forliberigu tiujn homojn, por ke ili faru servon al la Eternulo, ilia Dio; ĉu vi ankoraŭ ne vidas, ke Egiptujo pereas?","Tiam la servantoj de Faraono diris al li: Ĝis kiam tiu homo estos por ni suferilo? forliberigu tiujn homojn, por ke ili faru servon al la Eternulo, ilia Dio; ĉu vi ankoraŭ ne vidas, ke Egiptujo pereas?"],[10,8,"Kaj oni revenigis denove Moseon kaj Aaronon al Faraono, kaj ĉi tiu diris al ili: Iru, faru servon al la Eternulo, via Dio; sed kiuj estas la irontoj?","Kaj oni revenigis denove Moseon kaj Aaronon al Faraono, kaj ĉi tiu diris al ili: Iru, faru servon al la Eternulo, via Dio; sed kiuj estas la irontoj?"],[10,9,"Tiam Moseo diris: Kun niaj junuloj kaj maljunuloj ni iros, kun niaj filoj kaj niaj filinoj, kun niaj ŝafoj kaj niaj bovoj ni iros, ĉar ni havas feston de la Eternulo.","Tiam Moseo diris: Kun niaj junuloj kaj maljunuloj ni iros, kun niaj filoj kaj niaj filinoj, kun niaj ŝafoj kaj niaj bovoj ni iros, ĉar ni havas feston de la Eternulo."],[10,10,"Kaj li diris al ili: Tiel la Eternulo estu kun vi, se mi forliberigos vin kaj viajn infanojn! ĉu vi ne havas ian malbonan intencon?","Kaj li diris al ili: Tiel la Eternulo estu kun vi, se mi forliberigos vin kaj viajn infanojn! ĉu vi ne havas ian malbonan intencon?"],[10,11,"Ne; iru nur la viroj kaj faru servon al la Eternulo, ĉar tion vi petas. Kaj oni elpelis ilin for de Faraono.","Ne; iru nur la viroj kaj faru servon al la Eternulo, ĉar tion vi petas. Kaj oni elpelis ilin for de Faraono."],[10,12,"Tiam la Eternulo diris al Moseo: Etendu vian manon super la landon Egiptan pro la akridoj, ke ili venu sur la landon Egiptan, kaj formanĝu ĉiujn herbojn de la tero, ĉion, kion restigis la hajlo.","Tiam la Eternulo diris al Moseo: Etendu vian manon super la landon Egiptan pro la akridoj, ke ili venu sur la landon Egiptan, kaj formanĝu ĉiujn herbojn de la tero, ĉion, kion restigis la hajlo."],[10,13,"Kaj Moseo etendis sian bastonon super la landon Egiptan, kaj la Eternulo direktis orientan venton sur la landon dum tiu tuta tago kaj dum la tuta nokto. Kiam fariĝis mateno, la orienta vento alportis la akridojn.","Kaj Moseo etendis sian bastonon super la landon Egiptan, kaj la Eternulo direktis orientan venton sur la landon dum tiu tuta tago kaj dum la tuta nokto. Kiam fariĝis mateno, la orienta vento alportis la akridojn."],[10,14,"Kaj la akridoj venis sur la tutan landon Egiptan kaj sidiĝis en la tuta Egipta regiono en tre granda amaso; antaŭ ili neniam estis akridaro simila al ili, kaj poste neniam estos tia.","Kaj la akridoj venis sur la tutan landon Egiptan kaj sidiĝis en la tuta Egipta regiono en tre granda amaso; antaŭ ili neniam estis akridaro simila al ili, kaj poste neniam estos tia."],[10,15,"Kaj ili kovris la tutan supraĵon de la tero, kaj la tero fariĝis malluma; kaj ili formanĝis la tutan herbon de la kampo, kaj ĉiujn arbajn fruktojn, kiujn restigis la hajlo; kaj restis nenia verdaĵo sur la arboj aŭ inter la herboj de la kampo en la tuta lando Egipta.","Kaj ili kovris la tutan supraĵon de la tero, kaj la tero fariĝis malluma; kaj ili formanĝis la tutan herbon de la kampo, kaj ĉiujn arbajn fruktojn, kiujn restigis la hajlo; kaj restis nenia verdaĵo sur la arboj aŭ inter la herboj de la kampo en la tuta lando Egipta."],[10,16,"Tiam Faraono rapide alvokis Moseon kaj Aaronon, kaj diris: Mi pekis antaŭ la Eternulo, via Dio, kaj antaŭ vi.","Tiam Faraono rapide alvokis Moseon kaj Aaronon, kaj diris: Mi pekis antaŭ la Eternulo, via Dio, kaj antaŭ vi."],[10,17,"Sed nun pardonu mian pekon nur ĉi tiun fojon, kaj preĝu al la Eternulo, via Dio, ke Li forigu de mi nur ĉi tiun morton.","Sed nun pardonu mian pekon nur ĉi tiun fojon, kaj preĝu al la Eternulo, via Dio, ke Li forigu de mi nur ĉi tiun morton."],[10,18,"Kaj li eliris for de Faraono kaj preĝis al la Eternulo.","Kaj li eliris for de Faraono kaj preĝis al la Eternulo."],[10,19,"Kaj la Eternulo venigis de la kontraŭa flanko venton okcidentan tre fortan, kaj ĝi levis la akridojn kaj ĵetis ilin en la Ruĝan Maron; ne restis eĉ unu akrido en la tuta Egipta regiono.","Kaj la Eternulo venigis de la kontraŭa flanko venton okcidentan tre fortan, kaj ĝi levis la akridojn kaj ĵetis ilin en la Ruĝan Maron; ne restis eĉ unu akrido en la tuta Egipta regiono."],[10,20,"Sed la Eternulo obstinigis la koron de Faraono, kaj li ne forliberigis la Izraelidojn.","Sed la Eternulo obstinigis la koron de Faraono, kaj li ne forliberigis la Izraelidojn."],[10,21,"Tiam la Eternulo diris al Moseo: Etendu vian manon al la ĉielo, kaj fariĝos mallumo en la lando Egipta, palpebla mallumo.","Tiam la Eternulo diris al Moseo: Etendu vian manon al la ĉielo, kaj fariĝos mallumo en la lando Egipta, palpebla mallumo."],[10,22,"Kaj Moseo etendis sian manon al la ĉielo, kaj fariĝis densa mallumo en la tuta lando Egipta dum tri tagoj.","Kaj Moseo etendis sian manon al la ĉielo, kaj fariĝis densa mallumo en la tuta lando Egipta dum tri tagoj."],[10,23,"Oni ne vidis unu alian, kaj neniu leviĝis de sia loko dum tri tagoj; sed ĉiuj Izraelidoj havis lumon en siaj loĝejoj.","Oni ne vidis unu alian, kaj neniu leviĝis de sia loko dum tri tagoj; sed ĉiuj Izraelidoj havis lumon en siaj loĝejoj."],[10,24,"Tiam Faraono alvokis Moseon, kaj diris: Iru, faru servon al la Eternulo; nur viaj ŝafoj kaj viaj bovoj restu; ankaŭ viaj infanoj iru kun vi.","Tiam Faraono alvokis Moseon, kaj diris: Iru, faru servon al la Eternulo; nur viaj ŝafoj kaj viaj bovoj restu; ankaŭ viaj infanoj iru kun vi."],[10,25,"Sed Moseo diris: Vi devas ankaŭ doni en niajn manojn oferojn kaj bruloferojn, kiujn ni alportos al la Eternulo, nia Dio.","Sed Moseo diris: Vi devas ankaŭ doni en niajn manojn oferojn kaj bruloferojn, kiujn ni alportos al la Eternulo, nia Dio."],[10,26,"Ankaŭ niaj brutoj iros kun ni, ne restos eĉ unu hufo; ĉar el ili ni prenos, por fari servon al la Eternulo, nia Dio; kaj ni ne scias, per kio ni devas servi al la Eternulo, ĝis ni venos tien.","Ankaŭ niaj brutoj iros kun ni, ne restos eĉ unu hufo; ĉar el ili ni prenos, por fari servon al la Eternulo, nia Dio; kaj ni ne scias, per kio ni devas servi al la Eternulo, ĝis ni venos tien."],[10,27,"Kaj la Eternulo obstinigis la koron de Faraono, kaj li ne volis forliberigi ilin.","Kaj la Eternulo obstinigis la koron de Faraono, kaj li ne volis forliberigi ilin."],[10,28,"Kaj Faraono diris al li: Iru for de mi! gardu vin, ke vi ne venu plu antaŭ mian vizaĝon; ĉar en la tago, en kiu vi venos antaŭ mian vizaĝon, vi mortos.","Kaj Faraono diris al li: Iru for de mi! gardu vin, ke vi ne venu plu antaŭ mian vizaĝon; ĉar en la tago, en kiu vi venos antaŭ mian vizaĝon, vi mortos."],[10,29,"Tiam Moseo diris: Tiel vi diris; mi ne venos do plu antaŭ vian vizaĝon.","Tiam Moseo diris: Tiel vi diris; mi ne venos do plu antaŭ vian vizaĝon."],[11,1,"Kaj la Eternulo diris al Moseo: Ankoraŭ unu punon Mi venigos sur Faraonon kaj sur Egiptujon; post tio li forliberigos vin el ĉi tie; kaj forliberigante, li tute elpelos vin el ĉi tie.","Kaj la Eternulo diris al Moseo: Ankoraŭ unu punon Mi venigos sur Faraonon kaj sur Egiptujon; post tio li forliberigos vin el ĉi tie; kaj forliberigante, li tute elpelos vin el ĉi tie."],[11,2,"Diru nun al la popolo, ke ili petu ĉiu viro de sia proksimulo kaj ĉiu virino de sia proksimulino vazojn arĝentajn kaj vazojn orajn.","Diru nun al la popolo, ke ili petu ĉiu viro de sia proksimulo kaj ĉiu virino de sia proksimulino vazojn arĝentajn kaj vazojn orajn."],[11,3,"Kaj la Eternulo donis al la popolo favoron ĉe la Egiptoj; kaj ankaŭ Moseo estis tre granda homo en la lando Egipta, en la okuloj de la servantoj de Faraono kaj en la okuloj de la popolo.","Kaj la Eternulo donis al la popolo favoron ĉe la Egiptoj; kaj ankaŭ Moseo estis tre granda homo en la lando Egipta, en la okuloj de la servantoj de Faraono kaj en la okuloj de la popolo."],[11,4,"Kaj Moseo diris: Tiel diris la Eternulo: En la mezo de la nokto Mi iros internen de Egiptujo.","Kaj Moseo diris: Tiel diris la Eternulo: En la mezo de la nokto Mi iros internen de Egiptujo."],[11,5,"Kaj mortos ĉiu unuenaskito en la lando Egipta, de la unuenaskito de Faraono, kiu sidas sur sia trono, ĝis la unuenaskito de la sklavino, kiu sidas malantaŭ la muelejo; kaj ĉiu unuenaskito el la brutoj.","Kaj mortos ĉiu unuenaskito en la lando Egipta, de la unuenaskito de Faraono, kiu sidas sur sia trono, ĝis la unuenaskito de la sklavino, kiu sidas malantaŭ la muelejo; kaj ĉiu unuenaskito el la brutoj."],[11,6,"Kaj estos granda kriado en la tuta lando Egipta, tia, ke simila al ĝi neniam estis kaj neniam plu estos.","Kaj estos granda kriado en la tuta lando Egipta, tia, ke simila al ĝi neniam estis kaj neniam plu estos."],[11,7,"Sed ĉe ĉiuj Izraelidoj ne movos hundo sian langon, nek kontraŭ homon, nek kontraŭ bruton; por ke vi sciu, kiel la Eternulo faras apartigon inter la Egiptoj kaj la Izraelidoj.","Sed ĉe ĉiuj Izraelidoj ne movos hundo sian langon, nek kontraŭ homon, nek kontraŭ bruton; por ke vi sciu, kiel la Eternulo faras apartigon inter la Egiptoj kaj la Izraelidoj."],[11,8,"Kaj venos ĉiuj viaj sklavoj al mi kaj terĵetiĝos antaŭ mi, dirante: Eliru vi kaj la tuta popolo, kiu vin sekvas. Post tio mi eliros. Kaj li eliris for de Faraono kun granda kolero.","Kaj venos ĉiuj viaj sklavoj al mi kaj terĵetiĝos antaŭ mi, dirante: Eliru vi kaj la tuta popolo, kiu vin sekvas. Post tio mi eliros. Kaj li eliris for de Faraono kun granda kolero."],[11,9,"Kaj la Eternulo diris al Moseo: Faraono vin ne aŭskultos; por ke multiĝu Miaj mirakloj en la lando Egipta.","Kaj la Eternulo diris al Moseo: Faraono vin ne aŭskultos; por ke multiĝu Miaj mirakloj en la lando Egipta."],[11,10,"Kaj Moseo kaj Aaron faris ĉiujn tiujn miraklojn antaŭ Faraono; sed la Eternulo obstinigis la koron de Faraono, kaj li ne forliberigis la Izraelidojn el sia lando.","Kaj Moseo kaj Aaron faris ĉiujn tiujn miraklojn antaŭ Faraono; sed la Eternulo obstinigis la koron de Faraono, kaj li ne forliberigis la Izraelidojn el sia lando."],[12,1,"Kaj la Eternulo ekparolis al Moseo kaj al Aaron en la lando Egipta, dirante:","Kaj la Eternulo ekparolis al Moseo kaj al Aaron en la lando Egipta, dirante:"],[12,2,"Ĉi tiu monato estu por vi komenco de la monatoj; la unua ĝi estu por vi inter la monatoj de la jaro.","Ĉi tiu monato estu por vi komenco de la monatoj; la unua ĝi estu por vi inter la monatoj de la jaro."],[12,3,"Diru al la tuta komunumo de Izrael: En la deka tago de ĉi tiu monato prenu al si ŝafidon ĉiu patro de familio, po unu ŝafido por domo.","Diru al la tuta komunumo de Izrael: En la deka tago de ĉi tiu monato prenu al si ŝafidon ĉiu patro de familio, po unu ŝafido por domo."],[12,4,"Kaj se en la domo estas tro malmulte da personoj por tuta ŝafido, tiam li prenu kune kun sia najbaro plej proksima al lia domo; laŭ la nombro de la animoj, laŭ la kvanto de manĝado de ĉiu, ili kalkulu sin por la ŝafido.","Kaj se en la domo estas tro malmulte da personoj por tuta ŝafido, tiam li prenu kune kun sia najbaro plej proksima al lia domo; laŭ la nombro de la animoj, laŭ la kvanto de manĝado de ĉiu, ili kalkulu sin por la ŝafido."],[12,5,"La ŝafido estu sendifekta, virseksa, havanta la aĝon de unu jaro; el la ŝafoj aŭ el la kaproj vi povas preni.","La ŝafido estu sendifekta, virseksa, havanta la aĝon de unu jaro; el la ŝafoj aŭ el la kaproj vi povas preni."],[12,6,"Konservu ĝin ĝis la dek-kvara tago de ĉi tiu monato; kaj la tuta komunumo de Izrael buĉu ĝin en la komenco de vespero.","Konservu ĝin ĝis la dek-kvara tago de ĉi tiu monato; kaj la tuta komunumo de Izrael buĉu ĝin en la komenco de vespero."],[12,7,"Kaj ili prenu iom el la sango, kaj ŝmiru sur ambaŭ fostoj kaj sur la supra sojlo de la domoj, en kiuj ili ĝin manĝos.","Kaj ili prenu iom el la sango, kaj ŝmiru sur ambaŭ fostoj kaj sur la supra sojlo de la domoj, en kiuj ili ĝin manĝos."],[12,8,"Kaj ili manĝu la viandon en tiu nokto, rostitan sur fajro; kaj macojn kun maldolĉaj herboj ili manĝu.","Kaj ili manĝu la viandon en tiu nokto, rostitan sur fajro; kaj macojn kun maldolĉaj herboj ili manĝu."],[12,9,"Ne manĝu ĝin duonkrudan, nek kuiritan en akvo, sed nur rostitan sur fajro kun ĝiaj kapo, kruroj, kaj internaĵoj.","Ne manĝu ĝin duonkrudan, nek kuiritan en akvo, sed nur rostitan sur fajro kun ĝiaj kapo, kruroj, kaj internaĵoj."],[12,10,"Ne restigu iom el ĝi ĝis la mateno; kio restos el ĝi ĝis la mateno, tion bruligu per fajro.","Ne restigu iom el ĝi ĝis la mateno; kio restos el ĝi ĝis la mateno, tion bruligu per fajro."],[12,11,"Kaj tiele manĝu ĝin; via lumbo estu zonita, viaj ŝuoj sur viaj piedoj, kaj via bastono en via mano; kaj manĝu ĝin rapidante; ĝi estas Pasko de la Eternulo.","Kaj tiele manĝu ĝin; via lumbo estu zonita, viaj ŝuoj sur viaj piedoj, kaj via bastono en via mano; kaj manĝu ĝin rapidante; ĝi estas Pasko de la Eternulo."],[12,12,"Kaj Mi trairos la landon Egiptan en tiu nokto, kaj Mi batos ĉiun unuenaskiton en la lando Egipta, de la homoj ĝis la brutoj; kaj super ĉiuj dioj de Egiptujo Mi faros juĝon, Mi, la Eternulo.","Kaj Mi trairos la landon Egiptan en tiu nokto, kaj Mi batos ĉiun unuenaskiton en la lando Egipta, de la homoj ĝis la brutoj; kaj super ĉiuj dioj de Egiptujo Mi faros juĝon, Mi, la Eternulo."],[12,13,"Kaj la sango ĉe vi estos signo sur la domoj, en kiuj vi troviĝas; kiam Mi vidos la sangon, Mi pasos preter vi, kaj ne estos inter vi la eksterma puno, kiam Mi batos la landon Egiptan.","Kaj la sango ĉe vi estos signo sur la domoj, en kiuj vi troviĝas; kiam Mi vidos la sangon, Mi pasos preter vi, kaj ne estos inter vi la eksterma puno, kiam Mi batos la landon Egiptan."],[12,14,"Kaj tiu tago estu por vi memoraĵo; kaj festu ĝin kiel feston de la Eternulo en viaj generacioj, kiel leĝon por eterne festu ĝin.","Kaj tiu tago estu por vi memoraĵo; kaj festu ĝin kiel feston de la Eternulo en viaj generacioj, kiel leĝon por eterne festu ĝin."],[12,15,"Dum sep tagoj manĝu macojn; en la unua tago forigu la fermentaĵon el viaj domoj; ĉiu kiu manĝos fermentaĵon de la unua tago ĝis la sepa tago, ties animo estos ekstermita el Izrael.","Dum sep tagoj manĝu macojn; en la unua tago forigu la fermentaĵon el viaj domoj; ĉiu kiu manĝos fermentaĵon de la unua tago ĝis la sepa tago, ties animo estos ekstermita el Izrael."],[12,16,"Kaj en la unua tago faru al vi sanktan kunvenon, kaj en la sepa tago faru al vi sanktan kunvenon; nenia laboro estu farata en tiuj tagoj; nur kio estas necesa por manĝi por ĉiu, nur tio sola povas esti farata de vi.","Kaj en la unua tago faru al vi sanktan kunvenon, kaj en la sepa tago faru al vi sanktan kunvenon; nenia laboro estu farata en tiuj tagoj; nur kio estas necesa por manĝi por ĉiu, nur tio sola povas esti farata de vi."],[12,17,"Kaj observu la ordonon pri la macoj, ĉar ĝuste en tiu tago Mi elkondukis viajn taĉmentojn el la lando Egipta; kaj observu tiun tagon en viaj generacioj kiel leĝon eternan.","Kaj observu la ordonon pri la macoj, ĉar ĝuste en tiu tago Mi elkondukis viajn taĉmentojn el la lando Egipta; kaj observu tiun tagon en viaj generacioj kiel leĝon eternan."],[12,18,"De post la vespero de la dek-kvara tago de la unua monato manĝu macojn ĝis la vespero de la dudek-unua tago de la monato.","De post la vespero de la dek-kvara tago de la unua monato manĝu macojn ĝis la vespero de la dudek-unua tago de la monato."],[12,19,"Dum sep tagoj fermentaĵo ne troviĝu en viaj domoj; ĉar kiu manĝos fermentaĵon, ties animo ekstermiĝos el la komunumo de Izrael, ĉu li estas fremdulo, aŭ ĉu li estas indiĝeno de la lando.","Dum sep tagoj fermentaĵo ne troviĝu en viaj domoj; ĉar kiu manĝos fermentaĵon, ties animo ekstermiĝos el la komunumo de Izrael, ĉu li estas fremdulo, aŭ ĉu li estas indiĝeno de la lando."],[12,20,"Nenion fermentintan manĝu; en ĉiuj viaj loĝlokoj manĝu macojn.","Nenion fermentintan manĝu; en ĉiuj viaj loĝlokoj manĝu macojn."],[12,21,"Moseo alvokis ĉiujn ĉefojn de Izrael, kaj diris al ili: Elektu kaj prenu al vi ŝafidojn laŭ viaj familioj, kaj buĉu la Paskon.","Moseo alvokis ĉiujn ĉefojn de Izrael, kaj diris al ili: Elektu kaj prenu al vi ŝafidojn laŭ viaj familioj, kaj buĉu la Paskon."],[12,22,"Kaj prenu faskon da hisopo, kaj trempu ĝin en la sango, kiu estos en la pelvo, kaj tuŝu la supran sojlon kaj ambaŭ fostojn per la sango, kiu estos en la pelvo; kaj neniu el vi eliru el la pordo de sia domo ĝis la mateno.","Kaj prenu faskon da hisopo, kaj trempu ĝin en la sango, kiu estos en la pelvo, kaj tuŝu la supran sojlon kaj ambaŭ fostojn per la sango, kiu estos en la pelvo; kaj neniu el vi eliru el la pordo de sia domo ĝis la mateno."],[12,23,"Kaj la Eternulo trairos, por puni la Egiptojn; kiam Li vidos la sangon sur la supra sojlo kaj ambaŭ fostoj, tiam la Eternulo preterpasos la pordon kaj ne permesos al la ekstermanto veni en viajn domojn por puni.","Kaj la Eternulo trairos, por puni la Egiptojn; kiam Li vidos la sangon sur la supra sojlo kaj ambaŭ fostoj, tiam la Eternulo preterpasos la pordon kaj ne permesos al la ekstermanto veni en viajn domojn por puni."],[12,24,"Kaj observu ĉi tion kiel leĝon por vi kaj por viaj filoj eterne.","Kaj observu ĉi tion kiel leĝon por vi kaj por viaj filoj eterne."],[12,25,"Kaj kiam vi venos en la landon, kiun la Eternulo donos al vi, kiel Li diris, observu ĉi tiun servon.","Kaj kiam vi venos en la landon, kiun la Eternulo donos al vi, kiel Li diris, observu ĉi tiun servon."],[12,26,"Kaj kiam diros al vi viaj filoj: Kion signifas ĉi tiu via servo?","Kaj kiam diros al vi viaj filoj: Kion signifas ĉi tiu via servo?"],[12,27,"tiam diru: Ĝi estas ofero de Pasko al la Eternulo, kiu preterpasis la domojn de la Izraelidoj en Egiptujo, kiam Li punis la Egiptojn, sed niajn domojn savis. Kaj la popolo kliniĝis kaj faris adoron.","tiam diru: Ĝi estas ofero de Pasko al la Eternulo, kiu preterpasis la domojn de la Izraelidoj en Egiptujo, kiam Li punis la Egiptojn, sed niajn domojn savis. Kaj la popolo kliniĝis kaj faris adoron."],[12,28,"Kaj la Izraelidoj iris, kaj faris, kiel ordonis la Eternulo al Moseo kaj Aaron; tiel ili faris.","Kaj la Izraelidoj iris, kaj faris, kiel ordonis la Eternulo al Moseo kaj Aaron; tiel ili faris."],[12,29,"Kiam venis la noktomezo, la Eternulo batis ĉiujn unuenaskitojn en la lando Egipta, de la unuenaskito de Faraono, sidanta sur sia trono, ĝis la unuenaskito de malliberulo, sidanta en malliberejo; kaj ĉiujn unuenaskitojn el la brutoj.","Kiam venis la noktomezo, la Eternulo batis ĉiujn unuenaskitojn en la lando Egipta, de la unuenaskito de Faraono, sidanta sur sia trono, ĝis la unuenaskito de malliberulo, sidanta en malliberejo; kaj ĉiujn unuenaskitojn el la brutoj."],[12,30,"Tiam Faraono leviĝis en la nokto, li kaj ĉiuj liaj servantoj kaj ĉiuj Egiptoj; kaj fariĝis granda kriado en Egiptujo; ĉar ne estis domo, en kiu ne estis mortinto.","Tiam Faraono leviĝis en la nokto, li kaj ĉiuj liaj servantoj kaj ĉiuj Egiptoj; kaj fariĝis granda kriado en Egiptujo; ĉar ne estis domo, en kiu ne estis mortinto."],[12,31,"Kaj li alvokis Moseon kaj Aaronon en la nokto, kaj diris: Leviĝu, foriru el inter mia popolo, vi kaj la Izraelidoj; kaj iru, faru servon al la Eternulo, kiel vi diris.","Kaj li alvokis Moseon kaj Aaronon en la nokto, kaj diris: Leviĝu, foriru el inter mia popolo, vi kaj la Izraelidoj; kaj iru, faru servon al la Eternulo, kiel vi diris."],[12,32,"Ankaŭ viajn ŝafojn kaj viajn bovojn prenu, kiel vi diris, kaj iru; kaj benu ankaŭ min.","Ankaŭ viajn ŝafojn kaj viajn bovojn prenu, kiel vi diris, kaj iru; kaj benu ankaŭ min."],[12,33,"Kaj la Egiptoj urĝis sur la popolon, por pli rapide elirigi ilin el la lando; ĉar ili diris: Ni ĉiuj mortos.","Kaj la Egiptoj urĝis sur la popolon, por pli rapide elirigi ilin el la lando; ĉar ili diris: Ni ĉiuj mortos."],[12,34,"Kaj la popolo forportis sian paston, antaŭ ol ĝi fermentis; iliaj pastujoj, ligitaj en iliaj vestoj, estis sur iliaj ŝultroj.","Kaj la popolo forportis sian paston, antaŭ ol ĝi fermentis; iliaj pastujoj, ligitaj en iliaj vestoj, estis sur iliaj ŝultroj."],[12,35,"Kaj la Izraelidoj faris, kiel diris Moseo; kaj ili petis de la Egiptoj vazojn arĝentajn kaj vazojn orajn kaj vestojn.","Kaj la Izraelidoj faris, kiel diris Moseo; kaj ili petis de la Egiptoj vazojn arĝentajn kaj vazojn orajn kaj vestojn."],[12,36,"Kaj la Eternulo favorigis al la popolo la Egiptojn, kaj ĉi tiuj pruntedonis al ili; kaj ili multe prenis de la Egiptoj.","Kaj la Eternulo favorigis al la popolo la Egiptojn, kaj ĉi tiuj pruntedonis al ili; kaj ili multe prenis de la Egiptoj."],[12,37,"Kaj la Izraelidoj ekiris el Rameses al Sukot, en la nombro de ĉirkaŭ sescent mil piedirantaj viroj, krom la infanoj.","Kaj la Izraelidoj ekiris el Rameses al Sukot, en la nombro de ĉirkaŭ sescent mil piedirantaj viroj, krom la infanoj."],[12,38,"Kaj ankaŭ granda amaso da diversgentaj homoj eliris kun ili, kaj da ŝafoj kaj bovoj tre granda brutaro.","Kaj ankaŭ granda amaso da diversgentaj homoj eliris kun ili, kaj da ŝafoj kaj bovoj tre granda brutaro."],[12,39,"Kaj el la pasto, kiun ili elportis el Egiptujo, ili bakis macajn platpanojn, ĉar ĝi ankoraŭ ne fermentis; ĉar ili estis elpelitaj el Egiptujo kaj ne povis prokrasti, kaj ili eĉ ne pretigis al si manĝaĵon.","Kaj el la pasto, kiun ili elportis el Egiptujo, ili bakis macajn platpanojn, ĉar ĝi ankoraŭ ne fermentis; ĉar ili estis elpelitaj el Egiptujo kaj ne povis prokrasti, kaj ili eĉ ne pretigis al si manĝaĵon."],[12,40,"La daŭro de la tempo, kiun la Izraelidoj loĝis en Egiptujo, estis kvarcent tridek jaroj.","La daŭro de la tempo, kiun la Izraelidoj loĝis en Egiptujo, estis kvarcent tridek jaroj."],[12,41,"Kiam finiĝis kvarcent tridek jaroj, ĝuste en la sama tago, ĉiuj taĉmentoj de la Eternulo eliris el la lando Egipta.","Kiam finiĝis kvarcent tridek jaroj, ĝuste en la sama tago, ĉiuj taĉmentoj de la Eternulo eliris el la lando Egipta."],[12,42,"Ĝi estas nokto dediĉata al la Eternulo, ĉar Li elkondukis ilin el la lando Egipta; ĝi estas tiu nokto, kiu estas dediĉata al la Eternulo de ĉiuj Izraelidoj en iliaj generacioj.","Ĝi estas nokto dediĉata al la Eternulo, ĉar Li elkondukis ilin el la lando Egipta; ĝi estas tiu nokto, kiu estas dediĉata al la Eternulo de ĉiuj Izraelidoj en iliaj generacioj."],[12,43,"Kaj la Eternulo diris al Moseo kaj Aaron: Ĉi tio estas la leĝo pri la Pasko: neniu fremdulo manĝu ĝin.","Kaj la Eternulo diris al Moseo kaj Aaron: Ĉi tio estas la leĝo pri la Pasko: neniu fremdulo manĝu ĝin."],[12,44,"Sed ĉiu sklavo, kiun iu aĉetis per mono, se vi cirkumcidis lin, tiam li povas manĝi ĝin.","Sed ĉiu sklavo, kiun iu aĉetis per mono, se vi cirkumcidis lin, tiam li povas manĝi ĝin."],[12,45,"Pasloĝanto kaj dungito ne manĝu ĝin.","Pasloĝanto kaj dungito ne manĝu ĝin."],[12,46,"En unu domo ĝi estu manĝata; ne elportu el la domo iom el la viando eksteren, kaj oston en ĝi ne rompu.","En unu domo ĝi estu manĝata; ne elportu el la domo iom el la viando eksteren, kaj oston en ĝi ne rompu."],[12,47,"La tuta komunumo de Izrael faru ĝin.","La tuta komunumo de Izrael faru ĝin."],[12,48,"Kaj se enloĝiĝos ĉe vi aligentulo kaj li volos fari Paskon al la Eternulo, tiam cirkumcidu ĉe li ĉiujn virseksulojn, kaj tiam li povas prepari sin, por fari ĝin, kaj li estos kiel indiĝeno de la lando; sed neniu ne cirkumcidita manĝu ĝin.","Kaj se enloĝiĝos ĉe vi aligentulo kaj li volos fari Paskon al la Eternulo, tiam cirkumcidu ĉe li ĉiujn virseksulojn, kaj tiam li povas prepari sin, por fari ĝin, kaj li estos kiel indiĝeno de la lando; sed neniu ne cirkumcidita manĝu ĝin."],[12,49,"La sama leĝo estu por la indiĝeno, kaj por la aligentulo, kiu enloĝiĝis inter vi.","La sama leĝo estu por la indiĝeno, kaj por la aligentulo, kiu enloĝiĝis inter vi."],[12,50,"Kaj ĉiuj Izraelidoj faris, kiel ordonis la Eternulo al Moseo kaj al Aaron; tiel ili faris.","Kaj ĉiuj Izraelidoj faris, kiel ordonis la Eternulo al Moseo kaj al Aaron; tiel ili faris."],[12,51,"En tiu sama tago la Eternulo elkondukis la Izraelidojn el la lando Egipta laŭ iliaj taĉmentoj.","En tiu sama tago la Eternulo elkondukis la Izraelidojn el la lando Egipta laŭ iliaj taĉmentoj."],[13,1,"Kaj la Eternulo ekparolis al Moseo, dirante:","Kaj la Eternulo ekparolis al Moseo, dirante:"],[13,2,"Dediĉu al Mi ĉiun unuenaskiton, kiu malfermas ĉiun uteron inter la Izraelidoj, el la homo kaj el la brutoj: al Mi li apartenas.","Dediĉu al Mi ĉiun unuenaskiton, kiu malfermas ĉiun uteron inter la Izraelidoj, el la homo kaj el la brutoj: al Mi li apartenas."],[13,3,"Kaj Moseo diris al la popolo: Memoru ĉi tiun tagon, en kiu vi eliris el Egiptujo, el la domo de sklaveco; ĉar per forta mano la Eternulo elkondukis vin el tie; kaj ne manĝu fermentaĵon.","Kaj Moseo diris al la popolo: Memoru ĉi tiun tagon, en kiu vi eliris el Egiptujo, el la domo de sklaveco; ĉar per forta mano la Eternulo elkondukis vin el tie; kaj ne manĝu fermentaĵon."],[13,4,"Hodiaŭ vi eliras, en la monato Abib.","Hodiaŭ vi eliras, en la monato Abib."],[13,5,"Kaj kiam la Eternulo venigos vin en la landon de la Kanaanidoj kaj la Ĥetidoj kaj la Amoridoj kaj la Ĥividoj kaj la Jebusidoj, pri kiu Li ĵuris al viaj patroj, ke Li donos al vi, en la landon, en kiu fluas lakto kaj mielo, tiam servu ĉi tiun servon en ĉi tiu monato.","Kaj kiam la Eternulo venigos vin en la landon de la Kanaanidoj kaj la Ĥetidoj kaj la Amoridoj kaj la Ĥividoj kaj la Jebusidoj, pri kiu Li ĵuris al viaj patroj, ke Li donos al vi, en la landon, en kiu fluas lakto kaj mielo, tiam servu ĉi tiun servon en ĉi tiu monato."],[13,6,"Dum sep tagoj manĝu macojn, kaj en la sepa tago estu festo de la Eternulo.","Dum sep tagoj manĝu macojn, kaj en la sepa tago estu festo de la Eternulo."],[13,7,"Macoj estu manĝataj dum la sep tagoj, kaj ne vidiĝu ĉe vi fermentaĵo kaj ne vidiĝu ĉe vi fermentinta pasto, en la tuta regiono, kiu apartenas al vi.","Macoj estu manĝataj dum la sep tagoj, kaj ne vidiĝu ĉe vi fermentaĵo kaj ne vidiĝu ĉe vi fermentinta pasto, en la tuta regiono, kiu apartenas al vi."],[13,8,"Kaj sciigu al via filo en tiu tago, dirante: Ĝi estas pro tio, kion la Eternulo faris al mi ĉe mia elirado el Egiptujo.","Kaj sciigu al via filo en tiu tago, dirante: Ĝi estas pro tio, kion la Eternulo faris al mi ĉe mia elirado el Egiptujo."],[13,9,"Kaj tio estu ĉe vi kiel signo sur via mano kaj kiel memorigaĵo inter viaj okuloj, por ke la instruo de la Eternulo estu en via buŝo; ĉar per forta mano la Eternulo elkondukis vin el Egiptujo.","Kaj tio estu ĉe vi kiel signo sur via mano kaj kiel memorigaĵo inter viaj okuloj, por ke la instruo de la Eternulo estu en via buŝo; ĉar per forta mano la Eternulo elkondukis vin el Egiptujo."],[13,10,"Plenumu ĉi tiun leĝon en ĝia tempo en ĉiu jaro.","Plenumu ĉi tiun leĝon en ĝia tempo en ĉiu jaro."],[13,11,"Kaj kiam la Eternulo venigos vin en la landon de la Kanaanidoj, kiel Li ĵuris al vi kaj al viaj patroj, kaj donos ĝin al vi,","Kaj kiam la Eternulo venigos vin en la landon de la Kanaanidoj, kiel Li ĵuris al vi kaj al viaj patroj, kaj donos ĝin al vi,"],[13,12,"tiam transdonadu ĉiun utermalferminton al la Eternulo, kaj ĉiun unuenaskiton el la brutoj, virseksulon, al la Eternulo.","tiam transdonadu ĉiun utermalferminton al la Eternulo, kaj ĉiun unuenaskiton el la brutoj, virseksulon, al la Eternulo."],[13,13,"Kaj ĉiun unuenaskiton el la azenoj elaĉetu per ŝafido; kaj se vi ne elaĉetos, tiam rompu al ĝi la kolon; kaj ĉiun homan unuenaskiton inter viaj filoj elaĉetu.","Kaj ĉiun unuenaskiton el la azenoj elaĉetu per ŝafido; kaj se vi ne elaĉetos, tiam rompu al ĝi la kolon; kaj ĉiun homan unuenaskiton inter viaj filoj elaĉetu."],[13,14,"Kaj kiam via filo morgaŭ vin demandos, dirante: Kio tio estas? tiam diru al li: Per forta mano la Eternulo elkondukis nin el Egiptujo, el la domo de sklaveco;","Kaj kiam via filo morgaŭ vin demandos, dirante: Kio tio estas? tiam diru al li: Per forta mano la Eternulo elkondukis nin el Egiptujo, el la domo de sklaveco;"],[13,15,"kaj kiam Faraono obstine rifuzis forliberigi nin, tiam la Eternulo mortigis ĉiun unuenaskiton en la lando Egipta, de la unuenaskito de homo ĝis la unuenaskito de bruto; tial mi oferas al la Eternulo ĉiun utermalfermintan virseksulon, kaj ĉiun unuenaskiton el miaj filoj mi elaĉetas.","kaj kiam Faraono obstine rifuzis forliberigi nin, tiam la Eternulo mortigis ĉiun unuenaskiton en la lando Egipta, de la unuenaskito de homo ĝis la unuenaskito de bruto; tial mi oferas al la Eternulo ĉiun utermalfermintan virseksulon, kaj ĉiun unuenaskiton el miaj filoj mi elaĉetas."],[13,16,"Kaj tio estu kiel signo sur via mano kaj kiel memorigaĵo inter viaj okuloj; ĉar per forta mano la Eternulo elkondukis nin el Egiptujo.","Kaj tio estu kiel signo sur via mano kaj kiel memorigaĵo inter viaj okuloj; ĉar per forta mano la Eternulo elkondukis nin el Egiptujo."],[13,17,"Kiam Faraono forliberigis la popolon, Dio ne irigis ilin per la vojo de la lando Filiŝta, kiu estis proksima; ĉar Dio diris: Eble la popolo pentos, kiam ĝi ekvidos militon, kaj ĝi reiros Egiptujon.","Kiam Faraono forliberigis la popolon, Dio ne irigis ilin per la vojo de la lando Filiŝta, kiu estis proksima; ĉar Dio diris: Eble la popolo pentos, kiam ĝi ekvidos militon, kaj ĝi reiros Egiptujon."],[13,18,"Kaj Dio kondukis la popolon ĉirkaŭire, per la vojo tra la dezerto, al la Ruĝa Maro. Kaj armitaj la Izraelidoj eliris el la lando Egipta.","Kaj Dio kondukis la popolon ĉirkaŭire, per la vojo tra la dezerto, al la Ruĝa Maro. Kaj armitaj la Izraelidoj eliris el la lando Egipta."],[13,19,"Kaj Moseo prenis kun si la ostojn de Jozef, ĉar tiu ĵurigis la Izraelidojn, dirante: Kiam Dio rememoros vin, tiam elportu miajn ostojn el ĉi tie kun vi.","Kaj Moseo prenis kun si la ostojn de Jozef, ĉar tiu ĵurigis la Izraelidojn, dirante: Kiam Dio rememoros vin, tiam elportu miajn ostojn el ĉi tie kun vi."],[13,20,"Kaj ili elmoviĝis el Sukot, kaj starigis sian tendaron en Etam, en la fino de la dezerto.","Kaj ili elmoviĝis el Sukot, kaj starigis sian tendaron en Etam, en la fino de la dezerto."],[13,21,"Kaj la Eternulo iradis antaŭ ili dum la tago en nuba kolono, por konduki ilin laŭ la ĝusta vojo, kaj dum la nokto en kolono fajra, por lumi al ili, ke ili povu iri tage kaj nokte.","Kaj la Eternulo iradis antaŭ ili dum la tago en nuba kolono, por konduki ilin laŭ la ĝusta vojo, kaj dum la nokto en kolono fajra, por lumi al ili, ke ili povu iri tage kaj nokte."],[13,22,"Ne foriĝadis de antaŭ la popolo la nuba kolono dum la tago nek la fajra kolono dum la nokto.","Ne foriĝadis de antaŭ la popolo la nuba kolono dum la tago nek la fajra kolono dum la nokto."],[14,1,"Kaj la Eternulo ekparolis al Moseo, dirante:","Kaj la Eternulo ekparolis al Moseo, dirante:"],[14,2,"Diru al la Izraelidoj, ke ili iru returne, kaj starigu sian tendaron antaŭ Pi-Haĥirot, inter Migdol kaj la maro, apud Baal-Cefon; tie ili stariĝu tendare super la maro.","Diru al la Izraelidoj, ke ili iru returne, kaj starigu sian tendaron antaŭ Pi-Haĥirot, inter Migdol kaj la maro, apud Baal-Cefon; tie ili stariĝu tendare super la maro."],[14,3,"Faraono diros pri la Izraelidoj: Ili perdis la vojon en la lando, la dezerto ilin ŝlosis.","Faraono diros pri la Izraelidoj: Ili perdis la vojon en la lando, la dezerto ilin ŝlosis."],[14,4,"Kaj Mi obstinigos la koron de Faraono, kaj li kuros post ili; kaj Mi gloriĝos per Faraono kaj per lia tuta militistaro, kaj la Egiptoj sciiĝos, ke Mi estas la Eternulo. Kaj ili faris tiel.","Kaj Mi obstinigos la koron de Faraono, kaj li kuros post ili; kaj Mi gloriĝos per Faraono kaj per lia tuta militistaro, kaj la Egiptoj sciiĝos, ke Mi estas la Eternulo. Kaj ili faris tiel."],[14,5,"Kiam oni diris al la reĝo de Egiptujo, ke la popolo forkuris, tiam la koro de Faraono kaj de liaj servantoj turniĝis kontraŭ la popolon, kaj ili diris: Kion ni faris, forliberiginte la Izraelidojn de servado al ni?","Kiam oni diris al la reĝo de Egiptujo, ke la popolo forkuris, tiam la koro de Faraono kaj de liaj servantoj turniĝis kontraŭ la popolon, kaj ili diris: Kion ni faris, forliberiginte la Izraelidojn de servado al ni?"],[14,6,"Kaj li jungis sian ĉaron kaj prenis kun si sian popolon.","Kaj li jungis sian ĉaron kaj prenis kun si sian popolon."],[14,7,"Kaj li prenis sescent plej bonajn ĉarojn kaj ĉiujn ĉarojn de Egiptujo kaj la ĉefojn de la tuta militistaro.","Kaj li prenis sescent plej bonajn ĉarojn kaj ĉiujn ĉarojn de Egiptujo kaj la ĉefojn de la tuta militistaro."],[14,8,"Kaj la Eternulo obstinigis la koron de Faraono, la reĝo de Egiptujo, kaj li postkuris la Izraelidojn; sed la Izraelidojn elirigis mano alta.","Kaj la Eternulo obstinigis la koron de Faraono, la reĝo de Egiptujo, kaj li postkuris la Izraelidojn; sed la Izraelidojn elirigis mano alta."],[14,9,"La Egiptoj postkuris ilin, kaj ĉiuj ĉevaloj kaj ĉaroj de Faraono kaj liaj rajdantoj kaj lia militistaro atingis ilin, kiam ili staris tendare super la maro, apud Pi-Haĥirot antaŭ Baal-Cefon.","La Egiptoj postkuris ilin, kaj ĉiuj ĉevaloj kaj ĉaroj de Faraono kaj liaj rajdantoj kaj lia militistaro atingis ilin, kiam ili staris tendare super la maro, apud Pi-Haĥirot antaŭ Baal-Cefon."],[14,10,"Kiam Faraono alproksimiĝis, tiam la Izraelidoj levis siajn okulojn, kaj ekvidis, ke jen la Egiptoj iras post ili; kaj ili tre ektimis, kaj la Izraelidoj ekkriis al la Eternulo.","Kiam Faraono alproksimiĝis, tiam la Izraelidoj levis siajn okulojn, kaj ekvidis, ke jen la Egiptoj iras post ili; kaj ili tre ektimis, kaj la Izraelidoj ekkriis al la Eternulo."],[14,11,"Kaj ili diris al Moseo: Ĉu ne ekzistis tomboj en Egiptujo, ke vi prenis nin, por morti en la dezerto? kion vi faris al ni, elkondukinte nin el Egiptujo?","Kaj ili diris al Moseo: Ĉu ne ekzistis tomboj en Egiptujo, ke vi prenis nin, por morti en la dezerto? kion vi faris al ni, elkondukinte nin el Egiptujo?"],[14,12,"Tion ni diris ja al vi en Egiptujo: Lasu nin, kaj ni servu la Egiptojn; ĉar pli bone estus por ni servi la Egiptojn, ol morti en la dezerto.","Tion ni diris ja al vi en Egiptujo: Lasu nin, kaj ni servu la Egiptojn; ĉar pli bone estus por ni servi la Egiptojn, ol morti en la dezerto."],[14,13,"Tiam Moseo diris al la popolo: Ne timu; staru, kaj vidu la savon de la Eternulo, kiun Li faros al vi hodiaŭ; ĉar la Egiptojn, kiujn vi vidas hodiaŭ, vi eterne neniam plu vidos.","Tiam Moseo diris al la popolo: Ne timu; staru, kaj vidu la savon de la Eternulo, kiun Li faros al vi hodiaŭ; ĉar la Egiptojn, kiujn vi vidas hodiaŭ, vi eterne neniam plu vidos."],[14,14,"La Eternulo militos por vi, kaj vi silentu.","La Eternulo militos por vi, kaj vi silentu."],[14,15,"Kaj la Eternulo diris al Moseo: Kion vi krias al Mi? diru al la Izraelidoj, ke ili ekiru.","Kaj la Eternulo diris al Moseo: Kion vi krias al Mi? diru al la Izraelidoj, ke ili ekiru."],[14,16,"Kaj vi levu vian bastonon kaj etendu vian manon super la maron kaj disfendu ĝin, por ke la Izraelidoj iru tra la mezo de la maro sur seka tero.","Kaj vi levu vian bastonon kaj etendu vian manon super la maron kaj disfendu ĝin, por ke la Izraelidoj iru tra la mezo de la maro sur seka tero."],[14,17,"Kaj jen, Mi obstinigos la korojn de la Egiptoj, kaj ili iros post vi; kaj Mi gloriĝos per Faraono kaj per lia tuta militistaro, per liaj ĉaroj kaj liaj rajdantoj.","Kaj jen, Mi obstinigos la korojn de la Egiptoj, kaj ili iros post vi; kaj Mi gloriĝos per Faraono kaj per lia tuta militistaro, per liaj ĉaroj kaj liaj rajdantoj."],[14,18,"Kaj la Egiptoj sciiĝos, ke Mi estas la Eternulo, kiam Mi gloriĝos per Faraono, per liaj ĉaroj kaj liaj rajdantoj.","Kaj la Egiptoj sciiĝos, ke Mi estas la Eternulo, kiam Mi gloriĝos per Faraono, per liaj ĉaroj kaj liaj rajdantoj."],[14,19,"Kaj la Dia anĝelo, kiu iradis antaŭ la tendaro de la Izraelidoj, formoviĝis kaj ekiris post ili; kaj la nuba kolono formoviĝis de antaŭ ili kaj stariĝis post ili;","Kaj la Dia anĝelo, kiu iradis antaŭ la tendaro de la Izraelidoj, formoviĝis kaj ekiris post ili; kaj la nuba kolono formoviĝis de antaŭ ili kaj stariĝis post ili;"],[14,20,"kaj ĝi aperis inter la tendaro de la Egiptoj kaj la tendaro de la Izraelidoj, kaj ĝi estis nubo malluma, kaj lumis dum la nokto tiamaniere, ke unuj al la aliaj ne povis alproksimiĝi dum la tuta nokto.","kaj ĝi aperis inter la tendaro de la Egiptoj kaj la tendaro de la Izraelidoj, kaj ĝi estis nubo malluma, kaj lumis dum la nokto tiamaniere, ke unuj al la aliaj ne povis alproksimiĝi dum la tuta nokto."],[14,21,"Kaj Moseo etendis sian manon super la maron; kaj la Eternulo pelis la maron per forta orienta vento dum la tuta nokto kaj faris la maron seka tero; kaj la akvo disfendiĝis.","Kaj Moseo etendis sian manon super la maron; kaj la Eternulo pelis la maron per forta orienta vento dum la tuta nokto kaj faris la maron seka tero; kaj la akvo disfendiĝis."],[14,22,"Kaj la Izraelidoj ekiris tra la mezo de la maro sur seka tero, kaj la akvo estis por ili muro dekstre kaj maldekstre.","Kaj la Izraelidoj ekiris tra la mezo de la maro sur seka tero, kaj la akvo estis por ili muro dekstre kaj maldekstre."],[14,23,"Kaj la Egiptoj postkuris kaj venis post ili, ĉiuj ĉevaloj de Faraono, liaj ĉaroj kaj liaj rajdantoj, en la mezon de la maro.","Kaj la Egiptoj postkuris kaj venis post ili, ĉiuj ĉevaloj de Faraono, liaj ĉaroj kaj liaj rajdantoj, en la mezon de la maro."],[14,24,"Kiam venis la matena gardotempo, la Eternulo ekrigardis la tendaron de la Egiptoj el la fajra kaj nuba kolono, kaj Li tumultigis la tendaron de la Egiptoj.","Kiam venis la matena gardotempo, la Eternulo ekrigardis la tendaron de la Egiptoj el la fajra kaj nuba kolono, kaj Li tumultigis la tendaron de la Egiptoj."],[14,25,"Kaj Li depuŝis la radojn de iliaj ĉaroj kaj malrapidigis ilian iradon. Tiam la Egiptoj diris: Ni forkuru for de la Izraelidoj, ĉar la Eternulo militas por ili kontraŭ la Egiptoj.","Kaj Li depuŝis la radojn de iliaj ĉaroj kaj malrapidigis ilian iradon. Tiam la Egiptoj diris: Ni forkuru for de la Izraelidoj, ĉar la Eternulo militas por ili kontraŭ la Egiptoj."],[14,26,"Kaj la Eternulo diris al Moseo: Etendu vian manon super la maron, por ke la akvo revenu sur la Egiptojn, sur iliajn ĉarojn kaj iliajn rajdantojn.","Kaj la Eternulo diris al Moseo: Etendu vian manon super la maron, por ke la akvo revenu sur la Egiptojn, sur iliajn ĉarojn kaj iliajn rajdantojn."],[14,27,"Kaj Moseo etendis sian manon super la maron, kaj la maro revenis en la komenco de la mateno, sur sian lokon, kaj la Egiptoj kuris renkonte al ĝi. Kaj la Eternulo ĵetis la Egiptojn en la mezon de la maro.","Kaj Moseo etendis sian manon super la maron, kaj la maro revenis en la komenco de la mateno, sur sian lokon, kaj la Egiptoj kuris renkonte al ĝi. Kaj la Eternulo ĵetis la Egiptojn en la mezon de la maro."],[14,28,"Kaj la akvo revenis, kaj kovris la ĉarojn kaj la rajdantojn de la tuta militistaro de Faraono, kiu venis post ili en la maron; ne restis el ili eĉ unu.","Kaj la akvo revenis, kaj kovris la ĉarojn kaj la rajdantojn de la tuta militistaro de Faraono, kiu venis post ili en la maron; ne restis el ili eĉ unu."],[14,29,"Sed la Izraelidoj iris sur seka tero tra la mezo de la maro, kaj la akvo estis por ili muro dekstre kaj maldekstre.","Sed la Izraelidoj iris sur seka tero tra la mezo de la maro, kaj la akvo estis por ili muro dekstre kaj maldekstre."],[14,30,"Kaj la Eternulo savis en tiu tago la Izraelidojn el la mano de la Egiptoj; kaj la Izraelidoj vidis la Egiptojn mortintaj sur la bordo de la maro.","Kaj la Eternulo savis en tiu tago la Izraelidojn el la mano de la Egiptoj; kaj la Izraelidoj vidis la Egiptojn mortintaj sur la bordo de la maro."],[14,31,"Kaj la Izraelidoj vidis la grandan manon, kiun la Eternulo aperigis sur la Egiptoj, kaj la popolo ektimis la Eternulon kaj ekkredis al la Eternulo kaj al Lia sklavo Moseo.","Kaj la Izraelidoj vidis la grandan manon, kiun la Eternulo aperigis sur la Egiptoj, kaj la popolo ektimis la Eternulon kaj ekkredis al la Eternulo kaj al Lia sklavo Moseo."],[15,1,"Tiam Moseo kaj la Izraelidoj kantis ĉi tiun kanton al la Eternulo, kaj parolis jene: Mi kantos al la Eternulo, ĉar Li alte leviĝis; Ĉevalon kaj ĝian rajdanton Li ĵetis en la maron.","Tiam Moseo kaj la Izraelidoj kantis ĉi tiun kanton al la Eternulo, kaj parolis jene: Mi kantos al la Eternulo, ĉar Li alte leviĝis; Ĉevalon kaj ĝian rajdanton Li ĵetis en la maron."],[15,2,"Mia forto kaj glorkanto estas la Eternulo, Kaj Li estis por mi savo. Li estas mia Dio, kaj mi Lin gloros, La Dio de mia patro, kaj mi Lin altigos.","Mia forto kaj glorkanto estas la Eternulo, Kaj Li estis por mi savo. Li estas mia Dio, kaj mi Lin gloros, La Dio de mia patro, kaj mi Lin altigos."],[15,3,"La Eternulo estas viro de milito, Eternulo estas Lia nomo.","La Eternulo estas viro de milito, Eternulo estas Lia nomo."],[15,4,"La ĉarojn de Faraono kaj lian militistaron Li ĵetis en la maron; Kaj liaj elektitaj militestroj dronis en la Ruĝa Maro.","La ĉarojn de Faraono kaj lian militistaron Li ĵetis en la maron; Kaj liaj elektitaj militestroj dronis en la Ruĝa Maro."],[15,5,"Abismoj ilin kovris; Ili falis en la profundojn kiel ŝtono.","Abismoj ilin kovris; Ili falis en la profundojn kiel ŝtono."],[15,6,"Via dekstra mano, ho Eternulo, estas glora per forto, Via dekstra mano, ho Eternulo, disbatas malamikon.","Via dekstra mano, ho Eternulo, estas glora per forto, Via dekstra mano, ho Eternulo, disbatas malamikon."],[15,7,"Per Via granda majesto Vi frakasas Viajn kontraŭulojn; Vi sendas Vian koleron, kaj ĝi forbruligas ilin kiel pajlon.","Per Via granda majesto Vi frakasas Viajn kontraŭulojn; Vi sendas Vian koleron, kaj ĝi forbruligas ilin kiel pajlon."],[15,8,"De Via kolera blovo montiĝis akvo, Amasigite stariĝis fluaĵo, Densiĝis abismoj en la mezo de la maro.","De Via kolera blovo montiĝis akvo, Amasigite stariĝis fluaĵo, Densiĝis abismoj en la mezo de la maro."],[15,9,"La malamiko diris: Mi persekutos, Mi atingos, mi dividos militakiron; Satiĝos de ili mia animo; Mi eltiros mian glavon, ekstermos ilin mia mano.","La malamiko diris: Mi persekutos, Mi atingos, mi dividos militakiron; Satiĝos de ili mia animo; Mi eltiros mian glavon, ekstermos ilin mia mano."],[15,10,"Vi blovis per Via spirito, kaj ilin kovris la maro; Kiel plumbo ili iris al fundo en la akvo potenca.","Vi blovis per Via spirito, kaj ilin kovris la maro; Kiel plumbo ili iris al fundo en la akvo potenca."],[15,11,"Kiu estas kiel Vi inter la dioj, ho Eternulo? Kiu estas kiel Vi, majesta en sankteco, Timinda kaj laŭdinda, faranta miraklojn?","Kiu estas kiel Vi inter la dioj, ho Eternulo? Kiu estas kiel Vi, majesta en sankteco, Timinda kaj laŭdinda, faranta miraklojn?"],[15,12,"Vi etendis Vian dekstran manon, Kaj ilin englutis la tero.","Vi etendis Vian dekstran manon, Kaj ilin englutis la tero."],[15,13,"Vi kondukis kun Via favorkoreco tiun popolon, kiun Vi liberigis; Vi kondukis ĝin per Via forto al Via sankta loĝejo.","Vi kondukis kun Via favorkoreco tiun popolon, kiun Vi liberigis; Vi kondukis ĝin per Via forto al Via sankta loĝejo."],[15,14,"Aŭdis popoloj kaj ektremis; Teruro atakis la loĝantojn de Filiŝtujo.","Aŭdis popoloj kaj ektremis; Teruro atakis la loĝantojn de Filiŝtujo."],[15,15,"Tiam ektimis la ĉefoj de Edom; La potenculojn de Moab atakis tremo; Perdis la kuraĝon ĉiuj loĝantoj de Kanaan.","Tiam ektimis la ĉefoj de Edom; La potenculojn de Moab atakis tremo; Perdis la kuraĝon ĉiuj loĝantoj de Kanaan."],[15,16,"Falas sur ilin timo kaj teruro pro la grandeco de Via brako; Ili mutiĝas kiel ŝtono, ĝis pasas Via popolo, ho Eternulo, Ĝis pasas la popolo, kiun Vi akiris.","Falas sur ilin timo kaj teruro pro la grandeco de Via brako; Ili mutiĝas kiel ŝtono, ĝis pasas Via popolo, ho Eternulo, Ĝis pasas la popolo, kiun Vi akiris."],[15,17,"Vi venigos ilin, kaj plantos ilin Sur la monto de Via heredo, Sur la loko, ho Eternulo, kiun Vi faris Via sidejo, En la sanktejo, ho Sinjoro, kiun pretigis Viaj manoj.","Vi venigos ilin, kaj plantos ilin Sur la monto de Via heredo, Sur la loko, ho Eternulo, kiun Vi faris Via sidejo, En la sanktejo, ho Sinjoro, kiun pretigis Viaj manoj."],[15,18,"La Eternulo reĝos ĉiam kaj eterne.","La Eternulo reĝos ĉiam kaj eterne."],[15,19,"Ĉar la ĉevaloj de Faraono kun liaj ĉaroj kaj rajdantoj eniĝis en la maron, kaj la Eternulo turnis sur ilin la akvon de la maro; sed la Izraelidoj iris sur seka tero tra la mezo de la maro.","Ĉar la ĉevaloj de Faraono kun liaj ĉaroj kaj rajdantoj eniĝis en la maron, kaj la Eternulo turnis sur ilin la akvon de la maro; sed la Izraelidoj iris sur seka tero tra la mezo de la maro."],[15,20,"Mirjam, la profetino, fratino de Aaron, prenis tamburinon en sian manon, kaj ĉiuj virinoj eliris post ŝi kun tamburinoj kaj dancante.","Mirjam, la profetino, fratino de Aaron, prenis tamburinon en sian manon, kaj ĉiuj virinoj eliris post ŝi kun tamburinoj kaj dancante."],[15,21,"Kaj Mirjam antaŭkantis al ili: Kantu al la Eternulo, ĉar Li alte leviĝis; Ĉevalon kaj ĝian rajdanton Li ĵetis en la maron.","Kaj Mirjam antaŭkantis al ili: Kantu al la Eternulo, ĉar Li alte leviĝis; Ĉevalon kaj ĝian rajdanton Li ĵetis en la maron."],[15,22,"Moseo ekkondukis la Izraelidojn for de la Ruĝa Maro, kaj ili eliris al la dezerto Ŝur; ili iris dum tri tagoj tra la dezerto kaj ne trovis akvon.","Moseo ekkondukis la Izraelidojn for de la Ruĝa Maro, kaj ili eliris al la dezerto Ŝur; ili iris dum tri tagoj tra la dezerto kaj ne trovis akvon."],[15,23,"Ili venis al Mara, sed ili ne povis trinki la akvon en Mara, ĉar ĝi estis maldolĉa; tial oni donis al la loko la nomon Mara.","Ili venis al Mara, sed ili ne povis trinki la akvon en Mara, ĉar ĝi estis maldolĉa; tial oni donis al la loko la nomon Mara."],[15,24,"Kaj la popolo ekmurmuris kontraŭ Moseo, dirante: Kiam ni trinkos?","Kaj la popolo ekmurmuris kontraŭ Moseo, dirante: Kiam ni trinkos?"],[15,25,"Tiam li kriis al la Eternulo, kaj la Eternulo montris al li arbon, kaj li ĵetis ĝin en la akvon, kaj la akvo fariĝis dolĉa. Tie Li donis al ili leĝon kaj juĝon, kaj tie Li ilin elprovis.","Tiam li kriis al la Eternulo, kaj la Eternulo montris al li arbon, kaj li ĵetis ĝin en la akvon, kaj la akvo fariĝis dolĉa. Tie Li donis al ili leĝon kaj juĝon, kaj tie Li ilin elprovis."],[15,26,"Kaj Li diris: Se vi aŭskultados la voĉon de la Eternulo, via Dio, kaj farados tion, kio plaĉas al Li, kaj vi atentados Liajn ordonojn kaj observados ĉiujn Liajn leĝojn, tiam Mi venigos sur vin neniun el tiuj malsanoj, kiujn Mi venigis sur la Egiptojn; ĉar Mi estas la Eternulo, via saniganto.","Kaj Li diris: Se vi aŭskultados la voĉon de la Eternulo, via Dio, kaj farados tion, kio plaĉas al Li, kaj vi atentados Liajn ordonojn kaj observados ĉiujn Liajn leĝojn, tiam Mi venigos sur vin neniun el tiuj malsanoj, kiujn Mi venigis sur la Egiptojn; ĉar Mi estas la Eternulo, via saniganto."],[15,27,"Kaj ili venis al Elim; tie estis dek du fontoj de akvo, kaj sepdek daktilpalmoj. Kaj ili starigis tie sian tendaron ĉe la akvo.","Kaj ili venis al Elim; tie estis dek du fontoj de akvo, kaj sepdek daktilpalmoj. Kaj ili starigis tie sian tendaron ĉe la akvo."],[16,1,"Ili elmoviĝis el Elim, kaj la tuta komunumo de la Izraelidoj venis en la dezerton Sin, kiu troviĝas inter Elim kaj Sinaj, en la dek-kvina tago de la dua monato, post sia eliro el la lando Egipta.","Ili elmoviĝis el Elim, kaj la tuta komunumo de la Izraelidoj venis en la dezerton Sin, kiu troviĝas inter Elim kaj Sinaj, en la dek-kvina tago de la dua monato, post sia eliro el la lando Egipta."],[16,2,"Kaj la tuta komunumo de la Izraelidoj ekmurmuris kontraŭ Moseo kaj Aaron en la dezerto.","Kaj la tuta komunumo de la Izraelidoj ekmurmuris kontraŭ Moseo kaj Aaron en la dezerto."],[16,3,"Kaj la Izraelidoj diris al ili: Ho, ni dezirus morti per la mano de la Eternulo en la lando Egipta, sidante super la potoj kun viando, manĝante panon ĝissate! vi elkondukis nin en ĉi tiun dezerton, por mortigi ĉi tiun tutan komunumon per malsato.","Kaj la Izraelidoj diris al ili: Ho, ni dezirus morti per la mano de la Eternulo en la lando Egipta, sidante super la potoj kun viando, manĝante panon ĝissate! vi elkondukis nin en ĉi tiun dezerton, por mortigi ĉi tiun tutan komunumon per malsato."],[16,4,"Tiam la Eternulo diris al Moseo: Jen Mi pluvigos por vi panon el la ĉielo; kaj la popolo eliru kaj kolektu ĉiutage tiom, kiom ĝi bezonas por la tago, por ke Mi esploru ĝin, ĉu ĝi sekvos Mian leĝon aŭ ne.","Tiam la Eternulo diris al Moseo: Jen Mi pluvigos por vi panon el la ĉielo; kaj la popolo eliru kaj kolektu ĉiutage tiom, kiom ĝi bezonas por la tago, por ke Mi esploru ĝin, ĉu ĝi sekvos Mian leĝon aŭ ne."],[16,5,"Sed en la sesa tago ili preparu tion, kion ili devas enporti, kaj tiam estos duobla porcio kompare kun tio, kion ili kolektas ĉiutage.","Sed en la sesa tago ili preparu tion, kion ili devas enporti, kaj tiam estos duobla porcio kompare kun tio, kion ili kolektas ĉiutage."],[16,6,"Kaj Moseo kaj Aaron diris al ĉiuj Izraelidoj: Vespere vi sciiĝos, ke la Eternulo elkondukis vin el la lando Egipta.","Kaj Moseo kaj Aaron diris al ĉiuj Izraelidoj: Vespere vi sciiĝos, ke la Eternulo elkondukis vin el la lando Egipta."],[16,7,"Kaj matene vi vidos la gloron de la Eternulo; ĉar Li aŭdis vian murmuradon kontraŭ la Eternulo. Sed kio estas ni, ke vi murmuras kontraŭ ni?","Kaj matene vi vidos la gloron de la Eternulo; ĉar Li aŭdis vian murmuradon kontraŭ la Eternulo. Sed kio estas ni, ke vi murmuras kontraŭ ni?"],[16,8,"Kaj Moseo diris: La Eternulo donos al vi vespere viandon por manĝi kaj matene panon por satiĝi; ĉar la Eternulo aŭdis vian murmuradon, kiun vi murmuris kontraŭ Li. Sed ni, kio ni estas? ne kontraŭ ni estas via murmurado, sed kontraŭ la Eternulo.","Kaj Moseo diris: La Eternulo donos al vi vespere viandon por manĝi kaj matene panon por satiĝi; ĉar la Eternulo aŭdis vian murmuradon, kiun vi murmuris kontraŭ Li. Sed ni, kio ni estas? ne kontraŭ ni estas via murmurado, sed kontraŭ la Eternulo."],[16,9,"Kaj Moseo diris al Aaron: Diru al la tuta komunumo de la Izraelidoj: Alproksimiĝu antaŭ la Eternulon, ĉar Li aŭdis vian murmuradon.","Kaj Moseo diris al Aaron: Diru al la tuta komunumo de la Izraelidoj: Alproksimiĝu antaŭ la Eternulon, ĉar Li aŭdis vian murmuradon."],[16,10,"Kaj dum Aaron estis parolanta al la tuta komunumo de la Izraelidoj, ili turniĝis al la dezerto, kaj jen la gloro de la Eternulo aperis en nubo.","Kaj dum Aaron estis parolanta al la tuta komunumo de la Izraelidoj, ili turniĝis al la dezerto, kaj jen la gloro de la Eternulo aperis en nubo."],[16,11,"Kaj la Eternulo parolis al Moseo, dirante:","Kaj la Eternulo parolis al Moseo, dirante:"],[16,12,"Mi aŭdis la murmuradon de la Izraelidoj; diru al ili jenon: En la komenco de la vespero vi manĝos viandon, kaj matene vi satiĝos per pano, kaj vi sciiĝos, ke Mi estas la Eternulo, via Dio.","Mi aŭdis la murmuradon de la Izraelidoj; diru al ili jenon: En la komenco de la vespero vi manĝos viandon, kaj matene vi satiĝos per pano, kaj vi sciiĝos, ke Mi estas la Eternulo, via Dio."],[16,13,"Kiam venis la vespero, alflugis koturnoj kaj kovris la tendaron, kaj matene estis tavolo da roso ĉirkaŭ la tendaro.","Kiam venis la vespero, alflugis koturnoj kaj kovris la tendaron, kaj matene estis tavolo da roso ĉirkaŭ la tendaro."],[16,14,"Kiam la tavolo da roso forleviĝis, tiam montriĝis, ke sur la supraĵo de la dezerto kuŝas io delikata, senŝela, delikata kiel prujno sur la tero.","Kiam la tavolo da roso forleviĝis, tiam montriĝis, ke sur la supraĵo de la dezerto kuŝas io delikata, senŝela, delikata kiel prujno sur la tero."],[16,15,"Kiam la Izraelidoj ekvidis, ili diris unuj al la aliaj: Kio ĝi estas? ĉar ili ne sciis, kio ĝi estas. Kaj Moseo diris al ili: Ĝi estas la pano, kiun la Eternulo donis al vi por manĝi.","Kiam la Izraelidoj ekvidis, ili diris unuj al la aliaj: Kio ĝi estas? ĉar ili ne sciis, kio ĝi estas. Kaj Moseo diris al ili: Ĝi estas la pano, kiun la Eternulo donis al vi por manĝi."],[16,16,"Jen estas tio, kion ordonis la Eternulo: Kolektu ĝin ĉiu en tia kvanto, kiom li bezonas por manĝi; prenu po unu omero por ĉiu kapo, laŭ la nombro de viaj animoj, kiujn ĉiu havas en sia tendo.","Jen estas tio, kion ordonis la Eternulo: Kolektu ĝin ĉiu en tia kvanto, kiom li bezonas por manĝi; prenu po unu omero por ĉiu kapo, laŭ la nombro de viaj animoj, kiujn ĉiu havas en sia tendo."],[16,17,"Kaj tiel faris la Izraelidoj, kaj ili kolektis, unu pli, alia malpli.","Kaj tiel faris la Izraelidoj, kaj ili kolektis, unu pli, alia malpli."],[16,18,"Kaj oni mezuris per omero; kaj kiu kolektis pli, ne havis superflue, kaj kiu kolektis malpli, ne havis mankon; ĉiu kolektis tiom, kiom li povis manĝi.","Kaj oni mezuris per omero; kaj kiu kolektis pli, ne havis superflue, kaj kiu kolektis malpli, ne havis mankon; ĉiu kolektis tiom, kiom li povis manĝi."],[16,19,"Kaj Moseo diris al ili: Neniu restigu iom el ĝi ĝis la mateno.","Kaj Moseo diris al ili: Neniu restigu iom el ĝi ĝis la mateno."],[16,20,"Sed ili ne obeis Moseon, kaj kelkaj restigis iom el ĝi ĝis la mateno; kaj aperis en ĝi vermoj, kaj ĝi malbonodoriĝis; kaj Moseo ekkoleris ilin.","Sed ili ne obeis Moseon, kaj kelkaj restigis iom el ĝi ĝis la mateno; kaj aperis en ĝi vermoj, kaj ĝi malbonodoriĝis; kaj Moseo ekkoleris ilin."],[16,21,"Ili kolektadis ĝin ĉiumatene, ĉiu tiom, kiom li bezonis por manĝi; kaj kiam la suno fariĝis pli varma, tio fandiĝadis.","Ili kolektadis ĝin ĉiumatene, ĉiu tiom, kiom li bezonis por manĝi; kaj kiam la suno fariĝis pli varma, tio fandiĝadis."],[16,22,"Kiam venis la sesa tago, ili kolektis duoble da pano, po du omeroj por ĉiu; kaj ĉiuj ĉefoj de la komunumo venis kaj diris tion al Moseo.","Kiam venis la sesa tago, ili kolektis duoble da pano, po du omeroj por ĉiu; kaj ĉiuj ĉefoj de la komunumo venis kaj diris tion al Moseo."],[16,23,"Kaj li diris al ili: Jen estas, kion diris la Eternulo: ripozo de sankta sabato de la Eternulo estas morgaŭ; kion vi estas bakontaj, baku, kaj kion vi estas kuirontaj, kuiru; sed ĉion superfluan formetu, por ke ĝi estu konservata ĝis la mateno.","Kaj li diris al ili: Jen estas, kion diris la Eternulo: ripozo de sankta sabato de la Eternulo estas morgaŭ; kion vi estas bakontaj, baku, kaj kion vi estas kuirontaj, kuiru; sed ĉion superfluan formetu, por ke ĝi estu konservata ĝis la mateno."],[16,24,"Kaj ili formetis ĝin ĝis la mateno, kiel ordonis Moseo, kaj ĝi ne malbonodoriĝis, kaj vermoj ne aperis en ĝi.","Kaj ili formetis ĝin ĝis la mateno, kiel ordonis Moseo, kaj ĝi ne malbonodoriĝis, kaj vermoj ne aperis en ĝi."],[16,25,"Kaj Moseo diris: Manĝu ĝin hodiaŭ, ĉar hodiaŭ estas sabato de la Eternulo; hodiaŭ vi ne trovos ĝin sur la kampo.","Kaj Moseo diris: Manĝu ĝin hodiaŭ, ĉar hodiaŭ estas sabato de la Eternulo; hodiaŭ vi ne trovos ĝin sur la kampo."],[16,26,"Dum ses tagoj kolektu ĝin, sed la sepa tago estas sabato, en tiu tago ĝi ne troviĝos.","Dum ses tagoj kolektu ĝin, sed la sepa tago estas sabato, en tiu tago ĝi ne troviĝos."],[16,27,"En la sepa tago eliris kelkaj el la popolo, por kolekti, sed ili ne trovis.","En la sepa tago eliris kelkaj el la popolo, por kolekti, sed ili ne trovis."],[16,28,"Kaj la Eternulo diris al Moseo: Ĝis kiam vi rifuzos observi Miajn ordonojn kaj Mian instruon?","Kaj la Eternulo diris al Moseo: Ĝis kiam vi rifuzos observi Miajn ordonojn kaj Mian instruon?"],[16,29,"Rigardu, la Eternulo donis al vi la sabaton, tial Li donas al vi en la sesa tago panon por du tagoj; restu ĉiu hejme, neniu eliru for de sia loko en la sepa tago.","Rigardu, la Eternulo donis al vi la sabaton, tial Li donas al vi en la sesa tago panon por du tagoj; restu ĉiu hejme, neniu eliru for de sia loko en la sepa tago."],[16,30,"Kaj la popolo ripozis en la sepa tago.","Kaj la popolo ripozis en la sepa tago."],[16,31,"Kaj la domo de Izrael donis al ĝi la nomon manao; ĝi estis kiel la semo de koriandro, blanka, kaj ĝia gusto estis kiel blankpaneto kun mielo.","Kaj la domo de Izrael donis al ĝi la nomon manao; ĝi estis kiel la semo de koriandro, blanka, kaj ĝia gusto estis kiel blankpaneto kun mielo."],[16,32,"Kaj Moseo diris: Jen estas tio, kion ordonis la Eternulo: Plenigu per ĝi omeron, ke ĝi estu konservata en viaj generacioj, por ke oni vidu la panon, kiun Mi manĝigis al vi en la dezerto, kiam Mi elkondukis vin el la lando Egipta.","Kaj Moseo diris: Jen estas tio, kion ordonis la Eternulo: Plenigu per ĝi omeron, ke ĝi estu konservata en viaj generacioj, por ke oni vidu la panon, kiun Mi manĝigis al vi en la dezerto, kiam Mi elkondukis vin el la lando Egipta."],[16,33,"Kaj Moseo diris al Aaron: Prenu unu vazon kaj enmetu tien plenan omeron da manao kaj starigu ĝin antaŭ la Eternulo, por ke ĝi estu konservata en viaj generacioj.","Kaj Moseo diris al Aaron: Prenu unu vazon kaj enmetu tien plenan omeron da manao kaj starigu ĝin antaŭ la Eternulo, por ke ĝi estu konservata en viaj generacioj."],[16,34,"Kiel la Eternulo ordonis al Moseo, Aaron starigis ĝin antaŭ la Atesto, por konserviĝi.","Kiel la Eternulo ordonis al Moseo, Aaron starigis ĝin antaŭ la Atesto, por konserviĝi."],[16,35,"Kaj la Izraelidoj manĝis la manaon dum kvardek jaroj, ĝis ili venis en landon loĝeblan; la manaon ili manĝis, ĝis ili venis al la limo de la lando Kanaana.","Kaj la Izraelidoj manĝis la manaon dum kvardek jaroj, ĝis ili venis en landon loĝeblan; la manaon ili manĝis, ĝis ili venis al la limo de la lando Kanaana."],[16,36,"Kaj omero estas dekono de efo.","Kaj omero estas dekono de efo."],[17,1,"La tuta komunumo de la Izraelidoj elmoviĝis el la dezerto Sin laŭ siaj tagvojoj, kiel ordonis la Eternulo; kaj ili starigis sian tendaron en Refidim, kaj la popolo ne havis akvon por trinki.","La tuta komunumo de la Izraelidoj elmoviĝis el la dezerto Sin laŭ siaj tagvojoj, kiel ordonis la Eternulo; kaj ili starigis sian tendaron en Refidim, kaj la popolo ne havis akvon por trinki."],[17,2,"Kaj la popolo malpacis kontraŭ Moseo, kaj ili diris: Donu al ni akvon por trinki. Kaj Moseo diris al ili: Kial vi malpacas kontraŭ mi? kial vi provas la Eternulon?","Kaj la popolo malpacis kontraŭ Moseo, kaj ili diris: Donu al ni akvon por trinki. Kaj Moseo diris al ili: Kial vi malpacas kontraŭ mi? kial vi provas la Eternulon?"],[17,3,"Sed la popolo tie suferis pro manko de akvo, kaj la popolo murmuris kontraŭ Moseo, kaj diris: Kial vi elkondukis nin el Egiptujo, por mortigi nin kaj niajn infanojn kaj niajn brutojn per soifo?","Sed la popolo tie suferis pro manko de akvo, kaj la popolo murmuris kontraŭ Moseo, kaj diris: Kial vi elkondukis nin el Egiptujo, por mortigi nin kaj niajn infanojn kaj niajn brutojn per soifo?"],[17,4,"Tiam Moseo kriis al la Eternulo, dirante: Kion mi faros kun ĉi tiu popolo? baldaŭ povas okazi, ke ili min ŝtonmortigos.","Tiam Moseo kriis al la Eternulo, dirante: Kion mi faros kun ĉi tiu popolo? baldaŭ povas okazi, ke ili min ŝtonmortigos."],[17,5,"Kaj la Eternulo diris al Moseo: Preteriru antaŭ la popolo, kaj prenu kun vi kelkajn el la ĉefoj de Izrael, kaj vian bastonon, per kiu vi frapis la riveron, prenu en vian manon, kaj iru.","Kaj la Eternulo diris al Moseo: Preteriru antaŭ la popolo, kaj prenu kun vi kelkajn el la ĉefoj de Izrael, kaj vian bastonon, per kiu vi frapis la riveron, prenu en vian manon, kaj iru."],[17,6,"Jen Mi staros antaŭ vi tie super roko sur Ĥoreb; kaj vi frapos la rokon, kaj eliros el ĝi akvo, kaj la popolo trinkos. Kaj Moseo faris tiel antaŭ la okuloj de la ĉefoj de Izrael.","Jen Mi staros antaŭ vi tie super roko sur Ĥoreb; kaj vi frapos la rokon, kaj eliros el ĝi akvo, kaj la popolo trinkos. Kaj Moseo faris tiel antaŭ la okuloj de la ĉefoj de Izrael."],[17,7,"Kaj li donis al tiu loko la nomon Masa kaj Meriba, pro la malpaco de la Izraelidoj, kaj pro tio, ke ili provis la Eternulon, dirante: Ĉu la Eternulo estas inter ni, aŭ ne?","Kaj li donis al tiu loko la nomon Masa kaj Meriba, pro la malpaco de la Izraelidoj, kaj pro tio, ke ili provis la Eternulon, dirante: Ĉu la Eternulo estas inter ni, aŭ ne?"],[17,8,"Venis la Amalekidoj, kaj ekmilitis kontraŭ la Izraelidoj en Refidim.","Venis la Amalekidoj, kaj ekmilitis kontraŭ la Izraelidoj en Refidim."],[17,9,"Tiam Moseo diris al Josuo: Elektu al ni virojn, kaj eliru, batalu kontraŭ la Amalekidoj. Morgaŭ mi staros sur supro de monteto, kaj la Dian bastonon mi havos en mia mano.","Tiam Moseo diris al Josuo: Elektu al ni virojn, kaj eliru, batalu kontraŭ la Amalekidoj. Morgaŭ mi staros sur supro de monteto, kaj la Dian bastonon mi havos en mia mano."],[17,10,"Kaj Josuo faris, kiel diris al li Moseo, kaj batalis kontraŭ la Amalekidoj; kaj Moseo, Aaron, kaj Ĥur supreniris sur la supron de la monteto.","Kaj Josuo faris, kiel diris al li Moseo, kaj batalis kontraŭ la Amalekidoj; kaj Moseo, Aaron, kaj Ĥur supreniris sur la supron de la monteto."],[17,11,"Kaj ĉiufoje, kiam Moseo levis sian manon, venkis Izrael; kaj kiam li mallevis sian manon, venkis Amalek.","Kaj ĉiufoje, kiam Moseo levis sian manon, venkis Izrael; kaj kiam li mallevis sian manon, venkis Amalek."],[17,12,"Sed la manoj de Moseo estis pezaj; tial ili prenis ŝtonon kaj metis ĝin sub lin, kaj li sidiĝis sur ĝi; kaj Aaron kaj Ĥur subtenis liajn manojn, unu de unu flanko, la dua de la dua flanko; kaj liaj manoj estis en ĝusta teniĝo ĝis la subiro de la suno.","Sed la manoj de Moseo estis pezaj; tial ili prenis ŝtonon kaj metis ĝin sub lin, kaj li sidiĝis sur ĝi; kaj Aaron kaj Ĥur subtenis liajn manojn, unu de unu flanko, la dua de la dua flanko; kaj liaj manoj estis en ĝusta teniĝo ĝis la subiro de la suno."],[17,13,"Kaj Josuo senfortigis Amalekon kaj lian popolon per la glavo.","Kaj Josuo senfortigis Amalekon kaj lian popolon per la glavo."],[17,14,"Kaj la Eternulo diris al Moseo: Skribu ĉi tion por memoro en libron kaj enmetu ĉi tion en la orelojn de Josuo, ke Mi ekstermos la memoron pri Amalek sub la ĉielo.","Kaj la Eternulo diris al Moseo: Skribu ĉi tion por memoro en libron kaj enmetu ĉi tion en la orelojn de Josuo, ke Mi ekstermos la memoron pri Amalek sub la ĉielo."],[17,15,"Moseo konstruis altaron, kaj donis al ĝi la nomon: La Eternulo mia Standardo.","Moseo konstruis altaron, kaj donis al ĝi la nomon: La Eternulo mia Standardo."],[17,16,"Ĉar li diris: Estas promesite per la altaro de la Eternulo, ke la Eternulo militos kontraŭ Amalek de generacio al generacio.","Ĉar li diris: Estas promesite per la altaro de la Eternulo, ke la Eternulo militos kontraŭ Amalek de generacio al generacio."],[18,1,"Jitro, la Midjana pastro, la bopatro de Moseo, aŭdis ĉion, kion la Eternulo faris al Moseo kaj al Sia popolo Izrael, ke la Eternulo elkondukis Izraelon el Egiptujo.","Jitro, la Midjana pastro, la bopatro de Moseo, aŭdis ĉion, kion la Eternulo faris al Moseo kaj al Sia popolo Izrael, ke la Eternulo elkondukis Izraelon el Egiptujo."],[18,2,"Kaj Jitro, la bopatro de Moseo, prenis Ciporan, la edzinon de Moseo, kiun tiu forlasis;","Kaj Jitro, la bopatro de Moseo, prenis Ciporan, la edzinon de Moseo, kiun tiu forlasis;"],[18,3,"kaj ŝiajn du filojn, el kiuj unu havis la nomon Gerŝom; ĉar la patro diris: Mi estis fremdulo en fremda lando;","kaj ŝiajn du filojn, el kiuj unu havis la nomon Gerŝom; ĉar la patro diris: Mi estis fremdulo en fremda lando;"],[18,4,"kaj la dua havis la nomon Eliezer, ĉar tiu diris: La Dio de mia patro helpis min, kaj savis min kontraŭ la glavo de Faraono.","kaj la dua havis la nomon Eliezer, ĉar tiu diris: La Dio de mia patro helpis min, kaj savis min kontraŭ la glavo de Faraono."],[18,5,"Kaj Jitro, la bopatro de Moseo, kun liaj filoj kaj lia edzino venis al Moseo en la dezerton, kie li staris tendare ĉe la monto de Dio.","Kaj Jitro, la bopatro de Moseo, kun liaj filoj kaj lia edzino venis al Moseo en la dezerton, kie li staris tendare ĉe la monto de Dio."],[18,6,"Kaj li dirigis al Moseo: Mi, via bopatro Jitro, venas al vi, kaj ankaŭ via edzino kaj ŝiaj du filoj kun ŝi.","Kaj li dirigis al Moseo: Mi, via bopatro Jitro, venas al vi, kaj ankaŭ via edzino kaj ŝiaj du filoj kun ŝi."],[18,7,"Tiam Moseo eliris renkonte al sia bopatro kaj profunde salutis lin kaj kisis lin, kaj ili demandis sin reciproke pri la farto kaj eniris en la tendon.","Tiam Moseo eliris renkonte al sia bopatro kaj profunde salutis lin kaj kisis lin, kaj ili demandis sin reciproke pri la farto kaj eniris en la tendon."],[18,8,"Kaj Moseo rakontis al sia bopatro ĉion, kion la Eternulo faris al Faraono kaj al la Egiptoj pro Izrael, kaj ĉiujn malfacilaĵojn, kiuj trafis ilin dum la vojo kaj el kiuj la Eternulo ilin savis.","Kaj Moseo rakontis al sia bopatro ĉion, kion la Eternulo faris al Faraono kaj al la Egiptoj pro Izrael, kaj ĉiujn malfacilaĵojn, kiuj trafis ilin dum la vojo kaj el kiuj la Eternulo ilin savis."],[18,9,"Jitro ĝojis je la tuta bono, kiun la Eternulo faris al Izrael, savinte lin el la mano de la Egiptoj.","Jitro ĝojis je la tuta bono, kiun la Eternulo faris al Izrael, savinte lin el la mano de la Egiptoj."],[18,10,"Kaj Jitro diris: Benata estu la Eternulo, kiu savis vin el la manoj de la Egiptoj kaj el la mano de Faraono, kaj kiu savis la popolon el sub la mano de la Egiptoj.","Kaj Jitro diris: Benata estu la Eternulo, kiu savis vin el la manoj de la Egiptoj kaj el la mano de Faraono, kaj kiu savis la popolon el sub la mano de la Egiptoj."],[18,11,"Nun mi scias, ke la Eternulo estas pli granda ol ĉiuj dioj; ĝi estas pro tio, ke tiuj malbonintencis kontraŭ ili.","Nun mi scias, ke la Eternulo estas pli granda ol ĉiuj dioj; ĝi estas pro tio, ke tiuj malbonintencis kontraŭ ili."],[18,12,"Kaj Jitro, la bopatro de Moseo, alportis al Dio bruloferon kaj buĉoferojn; kaj Aaron kaj ĉiuj ĉefoj de Izrael venis, por manĝi panon kun la bopatro de Moseo antaŭ Dio.","Kaj Jitro, la bopatro de Moseo, alportis al Dio bruloferon kaj buĉoferojn; kaj Aaron kaj ĉiuj ĉefoj de Izrael venis, por manĝi panon kun la bopatro de Moseo antaŭ Dio."],[18,13,"La sekvantan tagon Moseo sidiĝis, por juĝi la popolon; kaj la popolo staris antaŭ Moseo de la mateno ĝis la vespero.","La sekvantan tagon Moseo sidiĝis, por juĝi la popolon; kaj la popolo staris antaŭ Moseo de la mateno ĝis la vespero."],[18,14,"Kaj la bopatro de Moseo vidis ĉion, kion li faras por la popolo, kaj diris: Kio estas tio, kion vi faras al la popolo? kial vi sola sidas kaj la tuta popolo staras antaŭ vi de mateno ĝis vespero?","Kaj la bopatro de Moseo vidis ĉion, kion li faras por la popolo, kaj diris: Kio estas tio, kion vi faras al la popolo? kial vi sola sidas kaj la tuta popolo staras antaŭ vi de mateno ĝis vespero?"],[18,15,"Tiam Moseo diris al sia bopatro: La popolo venas al mi, por demandi Dion.","Tiam Moseo diris al sia bopatro: La popolo venas al mi, por demandi Dion."],[18,16,"Kiam fariĝas inter ili ia afero, ili venas al mi; kaj mi juĝas inter unu kaj alia, kaj mi sciigas la leĝojn de Dio kaj Liajn instruojn.","Kiam fariĝas inter ili ia afero, ili venas al mi; kaj mi juĝas inter unu kaj alia, kaj mi sciigas la leĝojn de Dio kaj Liajn instruojn."],[18,17,"Sed la bopatro de Moseo diris al li: Ne bona estas la afero, kiun vi faras.","Sed la bopatro de Moseo diris al li: Ne bona estas la afero, kiun vi faras."],[18,18,"Senfortiĝos vi kaj ĉi tiu popolo, kiu estas kun vi; ĉar la afero estas tro malfacila por vi; vi ne povas plenumi ĝin sola.","Senfortiĝos vi kaj ĉi tiu popolo, kiu estas kun vi; ĉar la afero estas tro malfacila por vi; vi ne povas plenumi ĝin sola."],[18,19,"Aŭskultu mian voĉon, mi donos al vi konsilon, kaj Dio estos kun vi. Vi estu por la popolo perulo antaŭ Dio, kaj prezentu la aferojn al Dio.","Aŭskultu mian voĉon, mi donos al vi konsilon, kaj Dio estos kun vi. Vi estu por la popolo perulo antaŭ Dio, kaj prezentu la aferojn al Dio."],[18,20,"Instruu al ili la leĝojn kaj instruojn, kaj montru al ili la vojon, kiun ili devas iri, kaj la farojn, kiujn ili devas fari.","Instruu al ili la leĝojn kaj instruojn, kaj montru al ili la vojon, kiun ili devas iri, kaj la farojn, kiujn ili devas fari."],[18,21,"Kaj vi elserĉu inter la tuta popolo homojn bravajn, timantajn Dion, homojn veramajn, neprofitamajn; kaj starigu ilin super la popolo kiel milestrojn, centestrojn, kvindekestrojn, kaj dekestrojn.","Kaj vi elserĉu inter la tuta popolo homojn bravajn, timantajn Dion, homojn veramajn, neprofitamajn; kaj starigu ilin super la popolo kiel milestrojn, centestrojn, kvindekestrojn, kaj dekestrojn."],[18,22,"Kaj ili juĝadu la popolon en ĉiu tempo; ĉiun grandan aferon ili venigu al vi, sed ĉiun malgrandan aferon juĝu ili; tiel fariĝos pli facile al vi, kaj ili portos kun vi.","Kaj ili juĝadu la popolon en ĉiu tempo; ĉiun grandan aferon ili venigu al vi, sed ĉiun malgrandan aferon juĝu ili; tiel fariĝos pli facile al vi, kaj ili portos kun vi."],[18,23,"Se vi tion faros kaj Dio al vi ordonos, tiam vi povos resti forta, kaj ankaŭ ĉi tiu tuta popolo venos al sia loko en paco.","Se vi tion faros kaj Dio al vi ordonos, tiam vi povos resti forta, kaj ankaŭ ĉi tiu tuta popolo venos al sia loko en paco."],[18,24,"Moseo obeis la voĉon de sia bopatro, kaj faris ĉion, kion tiu diris.","Moseo obeis la voĉon de sia bopatro, kaj faris ĉion, kion tiu diris."],[18,25,"Kaj Moseo elektis bravajn homojn inter la tuta Izrael, kaj faris ilin estroj super la popolo, milestroj, centestroj, kvindekestroj, kaj dekestroj.","Kaj Moseo elektis bravajn homojn inter la tuta Izrael, kaj faris ilin estroj super la popolo, milestroj, centestroj, kvindekestroj, kaj dekestroj."],[18,26,"Kaj ili juĝadis la popolon en ĉiu tempo; malfacilan aferon ili venigadis al Moseo, kaj ĉiun aferon malgrandan juĝadis ili.","Kaj ili juĝadis la popolon en ĉiu tempo; malfacilan aferon ili venigadis al Moseo, kaj ĉiun aferon malgrandan juĝadis ili."],[18,27,"Kaj Moseo lasis sian bopatron foriri, kaj tiu iris en sian landon.","Kaj Moseo lasis sian bopatron foriri, kaj tiu iris en sian landon."],[19,1,"En la tria monato post la eliro de la Izraelidoj el la lando Egipta, en tiu tago ili venis en la dezerton Sinaj.","En la tria monato post la eliro de la Izraelidoj el la lando Egipta, en tiu tago ili venis en la dezerton Sinaj."],[19,2,"Ili eliris el Refidim, kaj venis en la dezerton Sinaj kaj starigis sian tendaron en la dezerto; kaj Izrael stariĝis tie tendare antaŭ la monto.","Ili eliris el Refidim, kaj venis en la dezerton Sinaj kaj starigis sian tendaron en la dezerto; kaj Izrael stariĝis tie tendare antaŭ la monto."],[19,3,"Kaj Moseo supreniris al Dio; kaj la Eternulo vokis al li de la monto, dirante: Tiel diru al la domo de Jakob kaj sciigu al la filoj de Izrael:","Kaj Moseo supreniris al Dio; kaj la Eternulo vokis al li de la monto, dirante: Tiel diru al la domo de Jakob kaj sciigu al la filoj de Izrael:"],[19,4,"Vi vidis, kion Mi faris al la Egiptoj kaj kiel Mi portis vin sur aglaj flugiloj kaj venigis vin al Mi.","Vi vidis, kion Mi faris al la Egiptoj kaj kiel Mi portis vin sur aglaj flugiloj kaj venigis vin al Mi."],[19,5,"Kaj nun se vi obeos Mian voĉon kaj observos Mian interligon, vi estos Mia amata propraĵo inter ĉiuj popoloj, ĉar al Mi apartenas la tuta tero.","Kaj nun se vi obeos Mian voĉon kaj observos Mian interligon, vi estos Mia amata propraĵo inter ĉiuj popoloj, ĉar al Mi apartenas la tuta tero."],[19,6,"Kaj vi estos por Mi regno de pastroj kaj popolo sankta. Tio estas la vortoj, kiujn vi diru al la Izraelidoj.","Kaj vi estos por Mi regno de pastroj kaj popolo sankta. Tio estas la vortoj, kiujn vi diru al la Izraelidoj."],[19,7,"Moseo venis, kaj alvokis la ĉefojn de la popolo, kaj prezentis al ili ĉiujn tiujn vortojn, pri kiuj la Eternulo ordonis al li.","Moseo venis, kaj alvokis la ĉefojn de la popolo, kaj prezentis al ili ĉiujn tiujn vortojn, pri kiuj la Eternulo ordonis al li."],[19,8,"Kaj la tuta popolo respondis kune kaj diris: Ĉion, kion la Eternulo diris, ni faros. Kaj Moseo raportis la vortojn de la popolo al la Eternulo.","Kaj la tuta popolo respondis kune kaj diris: Ĉion, kion la Eternulo diris, ni faros. Kaj Moseo raportis la vortojn de la popolo al la Eternulo."],[19,9,"Kaj la Eternulo diris al Moseo: Jen Mi venos al vi en densa nubo, por ke la popolo aŭdu, kiam Mi parolos kun vi, kaj por ke ili kredu al vi eterne. Kaj Moseo sciigis la vortojn de la popolo al la Eternulo.","Kaj la Eternulo diris al Moseo: Jen Mi venos al vi en densa nubo, por ke la popolo aŭdu, kiam Mi parolos kun vi, kaj por ke ili kredu al vi eterne. Kaj Moseo sciigis la vortojn de la popolo al la Eternulo."],[19,10,"Kaj la Eternulo diris al Moseo: Iru al la popolo kaj sanktigu ĝin hodiaŭ kaj morgaŭ, kaj ili lavu siajn vestojn.","Kaj la Eternulo diris al Moseo: Iru al la popolo kaj sanktigu ĝin hodiaŭ kaj morgaŭ, kaj ili lavu siajn vestojn."],[19,11,"Kaj ili estu pretaj por la tria tago, ĉar en la tria tago la Eternulo malsupreniros antaŭ la okuloj de la tuta popolo sur la monton Sinaj.","Kaj ili estu pretaj por la tria tago, ĉar en la tria tago la Eternulo malsupreniros antaŭ la okuloj de la tuta popolo sur la monton Sinaj."],[19,12,"Kaj difinu limon por la popolo ĉirkaŭe, dirante: Gardu vin, ke vi ne supreniru sur la monton nek tuŝu ĝian bazon; ĉiu, kiu tuŝos la monton, estu mortigita.","Kaj difinu limon por la popolo ĉirkaŭe, dirante: Gardu vin, ke vi ne supreniru sur la monton nek tuŝu ĝian bazon; ĉiu, kiu tuŝos la monton, estu mortigita."],[19,13,"Mano lin ne tuŝu, sed per ŝtonoj li estu mortigita, aŭ li estu pafmortigita; ĉu tio estos bruto, ĉu tio estos homo, li ne vivu. Kiam eksonos longa trumpetado, tiam ili povas supreniri sur la monton.","Mano lin ne tuŝu, sed per ŝtonoj li estu mortigita, aŭ li estu pafmortigita; ĉu tio estos bruto, ĉu tio estos homo, li ne vivu. Kiam eksonos longa trumpetado, tiam ili povas supreniri sur la monton."],[19,14,"Kaj Moseo malsupreniris de la monto al la popolo kaj sanktigis la popolon, kaj ili lavis siajn vestojn.","Kaj Moseo malsupreniris de la monto al la popolo kaj sanktigis la popolon, kaj ili lavis siajn vestojn."],[19,15,"Kaj li diris al la popolo: Estu pretaj por la tria tago; ne alproksimiĝu al virino.","Kaj li diris al la popolo: Estu pretaj por la tria tago; ne alproksimiĝu al virino."],[19,16,"En la tria tago, tuj matene, komenciĝis tondroj kaj fulmoj, kaj densa nubo estis super la monto, kaj aŭdiĝis tre forta sonado de korno; kaj ektremis la tuta popolo, kiu estis en la tendaro.","En la tria tago, tuj matene, komenciĝis tondroj kaj fulmoj, kaj densa nubo estis super la monto, kaj aŭdiĝis tre forta sonado de korno; kaj ektremis la tuta popolo, kiu estis en la tendaro."],[19,17,"Kaj Moseo elirigis la popolon el la tendaro renkonte al Dio, kaj ili stariĝis antaŭ la bazo de la monto.","Kaj Moseo elirigis la popolon el la tendaro renkonte al Dio, kaj ili stariĝis antaŭ la bazo de la monto."],[19,18,"Kaj la monto Sinaj tuta fumiĝis kaŭze de tio, ke la Eternulo malsupreniris sur ĝin en fajro; kaj ĝia fumo leviĝadis kiel fumo el forno, kaj la tuta monto forte tremis.","Kaj la monto Sinaj tuta fumiĝis kaŭze de tio, ke la Eternulo malsupreniris sur ĝin en fajro; kaj ĝia fumo leviĝadis kiel fumo el forno, kaj la tuta monto forte tremis."],[19,19,"Kaj la sonado de la korno fariĝadis ĉiam pli kaj pli forta; Moseo paroladis, kaj Dio respondadis al li per voĉo.","Kaj la sonado de la korno fariĝadis ĉiam pli kaj pli forta; Moseo paroladis, kaj Dio respondadis al li per voĉo."],[19,20,"Kaj la Eternulo malsupreniris sur la monton Sinaj, sur la supron de la monto; kaj la Eternulo vokis Moseon sur la supron de la monto, kaj Moseo supreniris.","Kaj la Eternulo malsupreniris sur la monton Sinaj, sur la supron de la monto; kaj la Eternulo vokis Moseon sur la supron de la monto, kaj Moseo supreniris."],[19,21,"Kaj la Eternulo diris al Moseo: Iru malsupren, avertu la popolon, ke ili ne translimiĝu perforte al la Eternulo, por vidi, ĉar tiam multaj el ili falus.","Kaj la Eternulo diris al Moseo: Iru malsupren, avertu la popolon, ke ili ne translimiĝu perforte al la Eternulo, por vidi, ĉar tiam multaj el ili falus."],[19,22,"Eĉ la pastroj, kiuj alproksimiĝos al la Eternulo, sanktigu sin, por ke la Eternulo ne frakasu ilin.","Eĉ la pastroj, kiuj alproksimiĝos al la Eternulo, sanktigu sin, por ke la Eternulo ne frakasu ilin."],[19,23,"Kaj Moseo diris al la Eternulo: La popolo ne povas supreniri sur la monton Sinaj, ĉar Vi avertis nin, dirante: Faru limon ĉirkaŭ la monto, kaj sanktigu ĝin.","Kaj Moseo diris al la Eternulo: La popolo ne povas supreniri sur la monton Sinaj, ĉar Vi avertis nin, dirante: Faru limon ĉirkaŭ la monto, kaj sanktigu ĝin."],[19,24,"Sed la Eternulo diris al li: Iru malsupren, poste supreniru vi kaj Aaron kun vi; sed la pastroj kaj la popolo ne penu perforte supreniri al la Eternulo, por ke Li ne frakasu ilin.","Sed la Eternulo diris al li: Iru malsupren, poste supreniru vi kaj Aaron kun vi; sed la pastroj kaj la popolo ne penu perforte supreniri al la Eternulo, por ke Li ne frakasu ilin."],[19,25,"Kaj Moseo malsupreniris al la popolo kaj diris tion al ili.","Kaj Moseo malsupreniris al la popolo kaj diris tion al ili."],[20,1,"Kaj Dio diris ĉiujn sekvantajn vortojn:","Kaj Dio diris ĉiujn sekvantajn vortojn:"],[20,2,"Mi estas la Eternulo, via Dio, kiu elkondukis vin el la lando Egipta, el la domo de sklaveco.","Mi estas la Eternulo, via Dio, kiu elkondukis vin el la lando Egipta, el la domo de sklaveco."],[20,3,"Ne ekzistu ĉe vi aliaj dioj antaŭ Mi.","Ne ekzistu ĉe vi aliaj dioj antaŭ Mi."],[20,4,"Ne faru al vi idolon, nek bildon de io, kio estas en la ĉielo supre aŭ sur la tero malsupre aŭ en la akvo sub la tero;","Ne faru al vi idolon, nek bildon de io, kio estas en la ĉielo supre aŭ sur la tero malsupre aŭ en la akvo sub la tero;"],[20,5,"ne kliniĝu antaŭ ili kaj ne servu ilin; ĉar Mi, la Eternulo, via Dio, estas Dio severa, kiu la malbonagon de la patroj punas sur la idoj en la tria kaj kvara generacioj ĉe Miaj malamantoj,","ne kliniĝu antaŭ ili kaj ne servu ilin; ĉar Mi, la Eternulo, via Dio, estas Dio severa, kiu la malbonagon de la patroj punas sur la idoj en la tria kaj kvara generacioj ĉe Miaj malamantoj,"],[20,6,"kaj kiu faras favorkoraĵon por miloj al Miaj amantoj kaj al la plenumantoj de Miaj ordonoj.","kaj kiu faras favorkoraĵon por miloj al Miaj amantoj kaj al la plenumantoj de Miaj ordonoj."],[20,7,"Ne malbonuzu la nomon de la Eternulo, via Dio; ĉar la Eternulo ne lasos senpuna tiun, kiu malbonuzas Lian nomon.","Ne malbonuzu la nomon de la Eternulo, via Dio; ĉar la Eternulo ne lasos senpuna tiun, kiu malbonuzas Lian nomon."],[20,8,"Memoru pri la tago sabata, ke vi tenu ĝin sankta.","Memoru pri la tago sabata, ke vi tenu ĝin sankta."],[20,9,"Dum ses tagoj laboru kaj faru ĉiujn viajn aferojn;","Dum ses tagoj laboru kaj faru ĉiujn viajn aferojn;"],[20,10,"sed la sepa tago estas sabato de la Eternulo, via Dio; faru nenian laboron, nek vi, nek via filo, nek via filino, nek via sklavo, nek via sklavino, nek via bruto, nek via fremdulo, kiu estas inter viaj pordegoj;","sed la sepa tago estas sabato de la Eternulo, via Dio; faru nenian laboron, nek vi, nek via filo, nek via filino, nek via sklavo, nek via sklavino, nek via bruto, nek via fremdulo, kiu estas inter viaj pordegoj;"],[20,11,"ĉar dum ses tagoj la Eternulo kreis la ĉielon kaj la teron, la maron, kaj ĉion, kio estas en ili, sed en la sepa tago Li ripozis. Tial la Eternulo benis la tagon sabatan kaj sanktigis ĝin.","ĉar dum ses tagoj la Eternulo kreis la ĉielon kaj la teron, la maron, kaj ĉion, kio estas en ili, sed en la sepa tago Li ripozis. Tial la Eternulo benis la tagon sabatan kaj sanktigis ĝin."],[20,12,"Respektu vian patron kaj vian patrinon, por ke longe daŭru via vivo sur la tero, kiun la Eternulo, via Dio, donas al vi.","Respektu vian patron kaj vian patrinon, por ke longe daŭru via vivo sur la tero, kiun la Eternulo, via Dio, donas al vi."],[20,13,"Ne mortigu.","Ne mortigu."],[20,14,"Ne adultu.","Ne adultu."],[20,15,"Ne ŝtelu.","Ne ŝtelu."],[20,16,"Ne parolu kontraŭ via proksimulo malveran ateston.","Ne parolu kontraŭ via proksimulo malveran ateston."],[20,17,"Ne deziru la domon de via proksimulo; ne deziru la edzinon de via proksimulo, nek lian sklavon, nek lian sklavinon, nek lian bovon, nek lian azenon, nek ion, kio apartenas al via proksimulo.","Ne deziru la domon de via proksimulo; ne deziru la edzinon de via proksimulo, nek lian sklavon, nek lian sklavinon, nek lian bovon, nek lian azenon, nek ion, kio apartenas al via proksimulo."],[20,18,"Kaj la tuta popolo vidis la tondrojn kaj la fulmojn kaj la sonadon de la korno kaj la fumiĝadon de la monto; kaj la popolo vidis, kaj retiriĝis kun teruro kaj stariĝis malproksime.","Kaj la tuta popolo vidis la tondrojn kaj la fulmojn kaj la sonadon de la korno kaj la fumiĝadon de la monto; kaj la popolo vidis, kaj retiriĝis kun teruro kaj stariĝis malproksime."],[20,19,"Kaj ili diris al Moseo: Parolu vi kun ni, kaj ni aŭskultos, sed Dio ne parolu kun ni, por ke ni ne mortu.","Kaj ili diris al Moseo: Parolu vi kun ni, kaj ni aŭskultos, sed Dio ne parolu kun ni, por ke ni ne mortu."],[20,20,"Kaj Moseo diris al la popolo: Ne timu; ĉar por vin elprovi venis Dio, kaj por ke la timo antaŭ Li estu antaŭ via vizaĝo, por ke vi ne peku.","Kaj Moseo diris al la popolo: Ne timu; ĉar por vin elprovi venis Dio, kaj por ke la timo antaŭ Li estu antaŭ via vizaĝo, por ke vi ne peku."],[20,21,"Kaj la popolo staris malproksime; sed Moseo alproksimiĝis al la mallumo, kie estis Dio.","Kaj la popolo staris malproksime; sed Moseo alproksimiĝis al la mallumo, kie estis Dio."],[20,22,"Kaj la Eternulo diris al Moseo: Tiel diru al la Izraelidoj: Vi vidis, kiel Mi parolis kun vi el la ĉielo.","Kaj la Eternulo diris al Moseo: Tiel diru al la Izraelidoj: Vi vidis, kiel Mi parolis kun vi el la ĉielo."],[20,23,"Ne faru antaŭ Mi diojn arĝentajn, kaj diojn orajn ne faru al vi.","Ne faru antaŭ Mi diojn arĝentajn, kaj diojn orajn ne faru al vi."],[20,24,"Altaron el tero faru al Mi, kaj oferu sur ĝi viajn bruloferojn kaj pacoferojn, viajn ŝafojn kaj viajn bovojn; sur ĉiu loko, kie Mi memorigos Mian nomon, Mi venos al vi kaj benos vin.","Altaron el tero faru al Mi, kaj oferu sur ĝi viajn bruloferojn kaj pacoferojn, viajn ŝafojn kaj viajn bovojn; sur ĉiu loko, kie Mi memorigos Mian nomon, Mi venos al vi kaj benos vin."],[20,25,"Kaj se vi faros al Mi altaron el ŝtonoj, ne konstruu ĝin el ŝtonoj hakitaj; ĉar se vi levos sur ĝin vian hakilon, vi ĝin malsanktigos.","Kaj se vi faros al Mi altaron el ŝtonoj, ne konstruu ĝin el ŝtonoj hakitaj; ĉar se vi levos sur ĝin vian hakilon, vi ĝin malsanktigos."],[20,26,"Kaj ne supreniru per ŝtupoj al Mia altaro, por ke ne malkovriĝu via nudeco antaŭ ĝi.","Kaj ne supreniru per ŝtupoj al Mia altaro, por ke ne malkovriĝu via nudeco antaŭ ĝi."],[21,1,"Kaj jen estas la juĝoj, kiujn vi proponos al ili:","Kaj jen estas la juĝoj, kiujn vi proponos al ili:"],[21,2,"Se vi aĉetos sklavon Hebreon, li servu dum ses jaroj; sed en la sepa li eliru libera senpage.","Se vi aĉetos sklavon Hebreon, li servu dum ses jaroj; sed en la sepa li eliru libera senpage."],[21,3,"Se li venis sola, li eliru sola; se li estas edzigita, tiam lia edzino eliru kune kun li.","Se li venis sola, li eliru sola; se li estas edzigita, tiam lia edzino eliru kune kun li."],[21,4,"Se lia sinjoro donis al li edzinon kaj ŝi naskis al li filojn aŭ filinojn, tiam la edzino kaj ŝiaj infanoj restu ĉe sia sinjoro, kaj li eliru sola.","Se lia sinjoro donis al li edzinon kaj ŝi naskis al li filojn aŭ filinojn, tiam la edzino kaj ŝiaj infanoj restu ĉe sia sinjoro, kaj li eliru sola."],[21,5,"Sed se la sklavo diros: Mi amas mian sinjoron, mian edzinon, kaj miajn infanojn, mi ne volas liberiĝi;","Sed se la sklavo diros: Mi amas mian sinjoron, mian edzinon, kaj miajn infanojn, mi ne volas liberiĝi;"],[21,6,"tiam lia sinjoro alkonduku lin antaŭ la potenculojn kaj starigu lin apud la pordo aŭ apud la fosto, kaj lia sinjoro trapiku lian orelon per aleno, kaj li estu lia sklavo por ĉiam.","tiam lia sinjoro alkonduku lin antaŭ la potenculojn kaj starigu lin apud la pordo aŭ apud la fosto, kaj lia sinjoro trapiku lian orelon per aleno, kaj li estu lia sklavo por ĉiam."],[21,7,"Kaj se iu vendos sian filinon kiel sklavinon, ŝi ne eliru kiel eliras la sklavoj.","Kaj se iu vendos sian filinon kiel sklavinon, ŝi ne eliru kiel eliras la sklavoj."],[21,8,"Se ŝi ne plaĉas al sia sinjoro, al kiu ŝi estis fordonita, tiam li donu al ŝi la eblon elaĉetiĝi; al fremda popolo ŝin vendi li ne havas la rajton, ĉar li kondutis ne honeste kontraŭ ŝi.","Se ŝi ne plaĉas al sia sinjoro, al kiu ŝi estis fordonita, tiam li donu al ŝi la eblon elaĉetiĝi; al fremda popolo ŝin vendi li ne havas la rajton, ĉar li kondutis ne honeste kontraŭ ŝi."],[21,9,"Se iu transdonos ŝin al sia filo, li agu kun ŝi laŭ la rajto de filinoj.","Se iu transdonos ŝin al sia filo, li agu kun ŝi laŭ la rajto de filinoj."],[21,10,"Se li prenos por li alian edzinon, tiam nutraĵo, vestoj, kaj edzina vivo ne devas esti rifuzataj al ŝi.","Se li prenos por li alian edzinon, tiam nutraĵo, vestoj, kaj edzina vivo ne devas esti rifuzataj al ŝi."],[21,11,"Kaj se tiujn tri aferojn li ne faros por ŝi, tiam ŝi eliru senpage, sen elaĉeto.","Kaj se tiujn tri aferojn li ne faros por ŝi, tiam ŝi eliru senpage, sen elaĉeto."],[21,12,"Se iu batos homon kaj tiu mortos, li estu mortigita.","Se iu batos homon kaj tiu mortos, li estu mortigita."],[21,13,"Sed se li ne agis malbonintence, nur Dio puŝis tiun sub lian manon, Mi difinas al vi lokon, kien li povas forkuri.","Sed se li ne agis malbonintence, nur Dio puŝis tiun sub lian manon, Mi difinas al vi lokon, kien li povas forkuri."],[21,14,"Sed se iu intence mortigis sian proksimulon per ruzo, tiam eĉ de Mia altaro forprenu lin, ke li mortu.","Sed se iu intence mortigis sian proksimulon per ruzo, tiam eĉ de Mia altaro forprenu lin, ke li mortu."],[21,15,"Kiu batas sian patron aŭ sian patrinon, tiu devas esti mortigita.","Kiu batas sian patron aŭ sian patrinon, tiu devas esti mortigita."],[21,16,"Kaj se iu ŝtelas homon por vendi lin, aŭ oni trovas tiun en lia mano, li devas esti mortigita.","Kaj se iu ŝtelas homon por vendi lin, aŭ oni trovas tiun en lia mano, li devas esti mortigita."],[21,17,"Kiu malbenas sian patron aŭ sian patrinon, tiu devas esti mortigita.","Kiu malbenas sian patron aŭ sian patrinon, tiu devas esti mortigita."],[21,18,"Se homoj kverelos, kaj unu batos la alian per ŝtono aŭ per pugno kaj tiu ne mortos, sed devos kuŝi en lito:","Se homoj kverelos, kaj unu batos la alian per ŝtono aŭ per pugno kaj tiu ne mortos, sed devos kuŝi en lito:"],[21,19,"se li leviĝos kaj irados ekstere per apogilo, tiam la batinto estu senkulpa; li nur kompensu al li lian malliberigitecon kaj zorgu pri lia kuracado.","se li leviĝos kaj irados ekstere per apogilo, tiam la batinto estu senkulpa; li nur kompensu al li lian malliberigitecon kaj zorgu pri lia kuracado."],[21,20,"Se iu batos sian sklavon aŭ sian sklavinon per bastono, kaj tiu mortos sub lia mano, tiam oni devas lin puni;","Se iu batos sian sklavon aŭ sian sklavinon per bastono, kaj tiu mortos sub lia mano, tiam oni devas lin puni;"],[21,21,"sed se tiu restos viva dum unu aŭ du tagoj, tiam oni ne devas lin puni; ĉar tio estas lia mono.","sed se tiu restos viva dum unu aŭ du tagoj, tiam oni ne devas lin puni; ĉar tio estas lia mono."],[21,22,"Se viroj kverelos kaj frapos gravedan virinon, kaj ŝi abortos, sed ne fariĝos malfeliĉo, tiam oni punu lin per monpuno, kian metos sur lin la edzo de la virino, kaj li pagu ĝin laŭ decido de juĝantoj.","Se viroj kverelos kaj frapos gravedan virinon, kaj ŝi abortos, sed ne fariĝos malfeliĉo, tiam oni punu lin per monpuno, kian metos sur lin la edzo de la virino, kaj li pagu ĝin laŭ decido de juĝantoj."],[21,23,"Sed se fariĝos malfeliĉo, tiam donu animon pro animo,","Sed se fariĝos malfeliĉo, tiam donu animon pro animo,"],[21,24,"okulon pro okulo, denton pro dento, manon pro mano, piedon pro piedo,","okulon pro okulo, denton pro dento, manon pro mano, piedon pro piedo,"],[21,25,"bruldifekton pro bruldifekto, vundon pro vundo, kontuzon pro kontuzo.","bruldifekton pro bruldifekto, vundon pro vundo, kontuzon pro kontuzo."],[21,26,"Kaj se iu batos okulon de sia sklavo aŭ de sia sklavino kaj difektos ĝin, tiam li forliberigu tiun kompense pro la okulo.","Kaj se iu batos okulon de sia sklavo aŭ de sia sklavino kaj difektos ĝin, tiam li forliberigu tiun kompense pro la okulo."],[21,27,"Kaj se li elbatos denton de sia sklavo aŭ denton de sia sklavino, li forliberigu tiun kompense pro la dento.","Kaj se li elbatos denton de sia sklavo aŭ denton de sia sklavino, li forliberigu tiun kompense pro la dento."],[21,28,"Se bovo kornobatos viron aŭ virinon kaj tiu mortos, tiam oni ŝtonmortigu la bovon kaj ĝia viando ne estu manĝata, sed la mastro de la bovo restu senkulpa.","Se bovo kornobatos viron aŭ virinon kaj tiu mortos, tiam oni ŝtonmortigu la bovon kaj ĝia viando ne estu manĝata, sed la mastro de la bovo restu senkulpa."],[21,29,"Sed se la bovo estis kornobatema antaŭe kaj oni tion sciigis al ĝia mastro kaj li ĝin ne gardis kaj ĝi mortigis viron aŭ virinon, tiam la bovon oni ŝtonmortigu kaj ĝian mastron oni mortigu.","Sed se la bovo estis kornobatema antaŭe kaj oni tion sciigis al ĝia mastro kaj li ĝin ne gardis kaj ĝi mortigis viron aŭ virinon, tiam la bovon oni ŝtonmortigu kaj ĝian mastron oni mortigu."],[21,30,"Se oni metos sur lin elaĉeton, tiam li donu pro sia animo tian elaĉetan sumon, kia estos metita sur lin.","Se oni metos sur lin elaĉeton, tiam li donu pro sia animo tian elaĉetan sumon, kia estos metita sur lin."],[21,31,"Se filo aŭ filino estos kornobatita, oni agu kun li en la sama maniero.","Se filo aŭ filino estos kornobatita, oni agu kun li en la sama maniero."],[21,32,"Se iun sklavon aŭ sklavinon kornobatos la bovo, tiam tridek sikloj da mono devas esti pagitaj al ties mastro kaj la bovo devas esti ŝtonmortigita.","Se iun sklavon aŭ sklavinon kornobatos la bovo, tiam tridek sikloj da mono devas esti pagitaj al ties mastro kaj la bovo devas esti ŝtonmortigita."],[21,33,"Se iu malfermos kavon, aŭ elfosos kavon, kaj ne kovros ĝin, kaj falos tien bovo aŭ azeno,","Se iu malfermos kavon, aŭ elfosos kavon, kaj ne kovros ĝin, kaj falos tien bovo aŭ azeno,"],[21,34,"tiam la mastro de la kavo devas kompensi per mono al ĝia mastro, kaj la kadavro apartenu al li.","tiam la mastro de la kavo devas kompensi per mono al ĝia mastro, kaj la kadavro apartenu al li."],[21,35,"Se la bovo de iu homo kornobatos bovon de lia proksimulo tiel, ke ĝi mortos, tiam ili vendu la vivan bovon kaj dividu inter si egalparte la monon pro ĝi, kaj ankaŭ la kadavron ili dividu.","Se la bovo de iu homo kornobatos bovon de lia proksimulo tiel, ke ĝi mortos, tiam ili vendu la vivan bovon kaj dividu inter si egalparte la monon pro ĝi, kaj ankaŭ la kadavron ili dividu."],[21,36,"Sed se oni sciis, ke la bovo estis kornobatema antaŭe, kaj ĝia mastro ĝin ne gardis, tiam ili pagu bovon pro la bovo, kaj la kadavro apartenu al li.","Sed se oni sciis, ke la bovo estis kornobatema antaŭe, kaj ĝia mastro ĝin ne gardis, tiam ili pagu bovon pro la bovo, kaj la kadavro apartenu al li."],[22,1,"Se iu ŝtelos bovon aŭ ŝafon kaj buĉos ĝin aŭ vendos ĝin, tiam li pagu kvin bovojn pro la bovo kaj kvar ŝafojn pro la ŝafo.","Se iu ŝtelos bovon aŭ ŝafon kaj buĉos ĝin aŭ vendos ĝin, tiam li pagu kvin bovojn pro la bovo kaj kvar ŝafojn pro la ŝafo."],[22,2,"Se iu trovos ŝtelanton ĉe subfosado kaj batos lin kaj tiu mortos, tiam oni ne juĝu lin pro la sango.","Se iu trovos ŝtelanton ĉe subfosado kaj batos lin kaj tiu mortos, tiam oni ne juĝu lin pro la sango."],[22,3,"Sed se lumis super li la suno, tiam oni juĝu lin pro la sango. La ŝtelinto pagu kompenson; se li ne havas, tiam oni lin vendu pro lia ŝtelo.","Sed se lumis super li la suno, tiam oni juĝu lin pro la sango. La ŝtelinto pagu kompenson; se li ne havas, tiam oni lin vendu pro lia ŝtelo."],[22,4,"Se la ŝtelitaĵo, ĉu ĝi estas bovo, ĉu azeno, ĉu ŝafo, estos trovita en liaj manoj viva, tiam li kompensu duoble.","Se la ŝtelitaĵo, ĉu ĝi estas bovo, ĉu azeno, ĉu ŝafo, estos trovita en liaj manoj viva, tiam li kompensu duoble."],[22,5,"Se iu difektos kampon aŭ vinberejon, lasante sian bruton, ke ĝi difektu kampon de aliulo, tiam li devas pagi per plejbonaĵo el sia kampo kaj per plejbonaĵo el sia vinberejo.","Se iu difektos kampon aŭ vinberejon, lasante sian bruton, ke ĝi difektu kampon de aliulo, tiam li devas pagi per plejbonaĵo el sia kampo kaj per plejbonaĵo el sia vinberejo."],[22,6,"Se eliros fajro kaj trafos dornojn kaj ekstermos garbojn aŭ starantan grenon aŭ kampon, tiam tiu kompensu, kiu kaŭzis la brulon.","Se eliros fajro kaj trafos dornojn kaj ekstermos garbojn aŭ starantan grenon aŭ kampon, tiam tiu kompensu, kiu kaŭzis la brulon."],[22,7,"Se iu donos al sia proksimulo monon aŭ uzataĵojn, por konservi, kaj ili estos ŝtelitaj el la domo de tiu homo, tiam, se la ŝtelinto estos trovita, li kompensu duoble.","Se iu donos al sia proksimulo monon aŭ uzataĵojn, por konservi, kaj ili estos ŝtelitaj el la domo de tiu homo, tiam, se la ŝtelinto estos trovita, li kompensu duoble."],[22,8,"Se la ŝtelinto ne estos trovita, tiam la mastro de la domo venu al la potenculoj, kaj ĵuru, ke li ne etendis sian manon sur la apartenaĵon de sia proksimulo.","Se la ŝtelinto ne estos trovita, tiam la mastro de la domo venu al la potenculoj, kaj ĵuru, ke li ne etendis sian manon sur la apartenaĵon de sia proksimulo."],[22,9,"Pri ĉiu maljustaĵo, ĉu ĝi estos pri bovo, ĉu pri azeno, ĉu pri ŝafo, ĉu pri vesto, pri ĉiu perditaĵo, pri kiu iu diros, ke ĝi estas lia, la afero de ambaŭ devas esti prezentita al la potenculoj; kiun la potenculoj trovos kulpa, tiu kompensu duoble al sia proksimulo.","Pri ĉiu maljustaĵo, ĉu ĝi estos pri bovo, ĉu pri azeno, ĉu pri ŝafo, ĉu pri vesto, pri ĉiu perditaĵo, pri kiu iu diros, ke ĝi estas lia, la afero de ambaŭ devas esti prezentita al la potenculoj; kiun la potenculoj trovos kulpa, tiu kompensu duoble al sia proksimulo."],[22,10,"Se iu donos al sia proksimulo azenon aŭ bovon aŭ ŝafon aŭ alian bruton, por konservi, kaj ĝi mortos aŭ estos difektita aŭ forkaptita, kaj neniu tion vidos,","Se iu donos al sia proksimulo azenon aŭ bovon aŭ ŝafon aŭ alian bruton, por konservi, kaj ĝi mortos aŭ estos difektita aŭ forkaptita, kaj neniu tion vidos,"],[22,11,"tiam ĵuro antaŭ la Eternulo estu inter ili, ke li ne etendis sian manon sur la apartenaĵon de sia proksimulo, kaj ĝia mastro ĝin prenos kaj li ne kompensos.","tiam ĵuro antaŭ la Eternulo estu inter ili, ke li ne etendis sian manon sur la apartenaĵon de sia proksimulo, kaj ĝia mastro ĝin prenos kaj li ne kompensos."],[22,12,"Sed se oni ĝin ŝtelos de li, tiam li devas kompensi al ĝia mastro.","Sed se oni ĝin ŝtelos de li, tiam li devas kompensi al ĝia mastro."],[22,13,"Se ĝi estos disŝirita, li prezentu ateston, kaj la disŝiritaĵon li ne kompensos.","Se ĝi estos disŝirita, li prezentu ateston, kaj la disŝiritaĵon li ne kompensos."],[22,14,"Se iu ĝin prenos prunte de sia proksimulo, kaj ĝi estos difektita aŭ mortos dum foresto de sia mastro, tiam li devas kompensi.","Se iu ĝin prenos prunte de sia proksimulo, kaj ĝi estos difektita aŭ mortos dum foresto de sia mastro, tiam li devas kompensi."],[22,15,"Se ĝia mastro estis apud ĝi, tiam li ne devas kompensi. Se ĝi estis dungita, li perdis sian dungomonon.","Se ĝia mastro estis apud ĝi, tiam li ne devas kompensi. Se ĝi estis dungita, li perdis sian dungomonon."],[22,16,"Se iu forlogos virgulinon, kiu ne estas fianĉinigita, kaj kuŝos kun ŝi, tiam li donu al ŝi doton kaj prenu ŝin al si kiel edzinon.","Se iu forlogos virgulinon, kiu ne estas fianĉinigita, kaj kuŝos kun ŝi, tiam li donu al ŝi doton kaj prenu ŝin al si kiel edzinon."],[22,17,"Se ŝia patro ne volos doni ŝin al li, tiam li pagu tiom da mono, kiom virgulinoj ordinare ricevas dote.","Se ŝia patro ne volos doni ŝin al li, tiam li pagu tiom da mono, kiom virgulinoj ordinare ricevas dote."],[22,18,"Sorĉistinon ne lasu vivi.","Sorĉistinon ne lasu vivi."],[22,19,"Ĉiu, kiu kuŝis kun bruto, estu mortigita.","Ĉiu, kiu kuŝis kun bruto, estu mortigita."],[22,20,"Kiu alportas oferojn al dioj, krom al la Eternulo sole, tiu estu ekstermita.","Kiu alportas oferojn al dioj, krom al la Eternulo sole, tiu estu ekstermita."],[22,21,"Fremdulon ne ofendu, nek premu lin; ĉar fremduloj vi estis en la lando Egipta.","Fremdulon ne ofendu, nek premu lin; ĉar fremduloj vi estis en la lando Egipta."],[22,22,"Vidvinon kaj orfon ne premu.","Vidvinon kaj orfon ne premu."],[22,23,"Se vi ilin premos kaj ili krios al Mi, tiam Mi aŭdos ilian krion;","Se vi ilin premos kaj ili krios al Mi, tiam Mi aŭdos ilian krion;"],[22,24,"kaj ekflamos Mia kolero, kaj Mi mortigos vin per glavo, kaj viaj edzinoj estos vidvinoj kaj viaj infanoj estos orfoj.","kaj ekflamos Mia kolero, kaj Mi mortigos vin per glavo, kaj viaj edzinoj estos vidvinoj kaj viaj infanoj estos orfoj."],[22,25,"Se vi pruntedonos monon al iu el Mia popolo, al iu malriĉulo apud vi, ne estu por li premanto, ne metu sur lin procentojn.","Se vi pruntedonos monon al iu el Mia popolo, al iu malriĉulo apud vi, ne estu por li premanto, ne metu sur lin procentojn."],[22,26,"Se vi prenos de via proksimulo veston kiel garantiaĵon, tiam antaŭ la subiro de la suno redonu ĝin al li;","Se vi prenos de via proksimulo veston kiel garantiaĵon, tiam antaŭ la subiro de la suno redonu ĝin al li;"],[22,27,"ĉar ĝi estas lia sola kovro, ĝi estas la vesto por lia korpo; en kio li dormos? kaj kiam li krios al Mi, Mi aŭdos, ĉar Mi estas favorkora.","ĉar ĝi estas lia sola kovro, ĝi estas la vesto por lia korpo; en kio li dormos? kaj kiam li krios al Mi, Mi aŭdos, ĉar Mi estas favorkora."],[22,28,"Potenculojn ne malbenu, kaj estron de via popolo ne insultu.","Potenculojn ne malbenu, kaj estron de via popolo ne insultu."],[22,29,"Vian abundon kaj sukon ne retenu; la unuenaskiton el viaj filoj vi devas doni al Mi.","Vian abundon kaj sukon ne retenu; la unuenaskiton el viaj filoj vi devas doni al Mi."],[22,30,"Tiel same agu kun via bovo kaj via ŝafo; sep tagojn ĝi restu kun sia patrino, en la oka tago donu ĝin al Mi.","Tiel same agu kun via bovo kaj via ŝafo; sep tagojn ĝi restu kun sia patrino, en la oka tago donu ĝin al Mi."],[22,31,"Estu por Mi sanktaj homoj; kaj viandon, disŝiritan sur la kampo, ne manĝu; al hundo ĵetu ĝin.","Estu por Mi sanktaj homoj; kaj viandon, disŝiritan sur la kampo, ne manĝu; al hundo ĵetu ĝin."],[23,1,"Ne disvastigu malveran famon; ne kunigu vian manon kun malvirtulo, por esti atestanto de malbonago.","Ne disvastigu malveran famon; ne kunigu vian manon kun malvirtulo, por esti atestanto de malbonago."],[23,2,"Ne sekvu la amason por malbonaĵoj; kaj en juĝo ne kliniĝu al la opinio de la plimulto, por dekliniĝi de la vero.","Ne sekvu la amason por malbonaĵoj; kaj en juĝo ne kliniĝu al la opinio de la plimulto, por dekliniĝi de la vero."],[23,3,"Ankaŭ malriĉulon ne favoru en lia juĝa afero.","Ankaŭ malriĉulon ne favoru en lia juĝa afero."],[23,4,"Se vi renkontos bovon de via malamiko aŭ lian azenon erarvagantan, rekonduku ĝin al li.","Se vi renkontos bovon de via malamiko aŭ lian azenon erarvagantan, rekonduku ĝin al li."],[23,5,"Se vi vidos, ke azeno de via malamiko falis sub sia ŝarĝo, ne forlasu ĝin, sed alportu helpon kune kun li.","Se vi vidos, ke azeno de via malamiko falis sub sia ŝarĝo, ne forlasu ĝin, sed alportu helpon kune kun li."],[23,6,"Ne forklinu la rajton de via malriĉulo en lia juĝa afero.","Ne forklinu la rajton de via malriĉulo en lia juĝa afero."],[23,7,"De mensogaĵo malproksimiĝu, kaj senkulpulon kaj virtulon ne mortigu; ĉar Mi ne pravigos maljustulon.","De mensogaĵo malproksimiĝu, kaj senkulpulon kaj virtulon ne mortigu; ĉar Mi ne pravigos maljustulon."],[23,8,"Donacojn ne akceptu; ĉar donacoj blindigas vidantojn kaj malĝustigas la aferojn de virtuloj.","Donacojn ne akceptu; ĉar donacoj blindigas vidantojn kaj malĝustigas la aferojn de virtuloj."],[23,9,"Fremdulon ne premu; vi konas ja la animon de fremdulo, ĉar fremduloj vi estis en la lando Egipta.","Fremdulon ne premu; vi konas ja la animon de fremdulo, ĉar fremduloj vi estis en la lando Egipta."],[23,10,"Dum ses jaroj prisemu vian teron kaj rikoltu ĝiajn produktaĵojn;","Dum ses jaroj prisemu vian teron kaj rikoltu ĝiajn produktaĵojn;"],[23,11,"sed en la sepa jaro ripozigu ĝin kaj ne tuŝu ĝin, por ke manĝu la malriĉuloj el via popolo, kaj la restaĵon manĝu la bestoj de la kampo. Tiel same agu kun via vinberejo kaj kun via olivarbejo.","sed en la sepa jaro ripozigu ĝin kaj ne tuŝu ĝin, por ke manĝu la malriĉuloj el via popolo, kaj la restaĵon manĝu la bestoj de la kampo. Tiel same agu kun via vinberejo kaj kun via olivarbejo."],[23,12,"Dum ses tagoj faru viajn laborojn, kaj en la sepa tago festu, por ke ripozu via bovo kaj via azeno kaj por ke refreŝiĝu la filo de via sklavino kaj la fremdulo.","Dum ses tagoj faru viajn laborojn, kaj en la sepa tago festu, por ke ripozu via bovo kaj via azeno kaj por ke refreŝiĝu la filo de via sklavino kaj la fremdulo."],[23,13,"Kaj ĉion, kion Mi diris al vi, observu; kaj la nomon de aliaj dioj ne citu, ĝi ne estu aŭdata el via buŝo.","Kaj ĉion, kion Mi diris al vi, observu; kaj la nomon de aliaj dioj ne citu, ĝi ne estu aŭdata el via buŝo."],[23,14,"Tri fojojn festu al Mi dum la jaro.","Tri fojojn festu al Mi dum la jaro."],[23,15,"La feston de la macoj observu; dum sep tagoj manĝu macojn, kiel Mi ordonis al vi, en la difinita tempo en la monato Abib (ĉar en tiu tempo vi eliris el Egiptujo); kaj oni ne aperu antaŭ Mi kun malplenaj manoj;","La feston de la macoj observu; dum sep tagoj manĝu macojn, kiel Mi ordonis al vi, en la difinita tempo en la monato Abib (ĉar en tiu tempo vi eliris el Egiptujo); kaj oni ne aperu antaŭ Mi kun malplenaj manoj;"],[23,16,"ankaŭ la feston de la rikolto de la unuaj fruktoj de via laboro, de tio, kion vi semos sur la kampo; kaj la feston de kolekto en la fino de la jaro, kiam vi kolektos viajn laborfruktojn el la kampo.","ankaŭ la feston de la rikolto de la unuaj fruktoj de via laboro, de tio, kion vi semos sur la kampo; kaj la feston de kolekto en la fino de la jaro, kiam vi kolektos viajn laborfruktojn el la kampo."],[23,17,"Tri fojojn ĉiujare aperu ĉiuj viaj virseksuloj antaŭ la Sinjoro, la Eternulo.","Tri fojojn ĉiujare aperu ĉiuj viaj virseksuloj antaŭ la Sinjoro, la Eternulo."],[23,18,"Ne verŝu sur fermentaĵon la sangon de Mia ofero; kaj la graso de Mia festofero ne restu ĝis mateno.","Ne verŝu sur fermentaĵon la sangon de Mia ofero; kaj la graso de Mia festofero ne restu ĝis mateno."],[23,19,"La komencaĵon de la unuaj fruktoj de via tero alportu en la domon de la Eternulo, via Dio. Ne kuiru kapridon en la lakto de ĝia patrino.","La komencaĵon de la unuaj fruktoj de via tero alportu en la domon de la Eternulo, via Dio. Ne kuiru kapridon en la lakto de ĝia patrino."],[23,20,"Jen Mi sendas anĝelon antaŭ vi, por gardi vin sur la vojo, kaj por venigi vin al la loko, kiun Mi pretigis.","Jen Mi sendas anĝelon antaŭ vi, por gardi vin sur la vojo, kaj por venigi vin al la loko, kiun Mi pretigis."],[23,21,"Gardu vin antaŭ lia vizaĝo kaj aŭskultu lian voĉon; ne incitu lin, ĉar li ne pardonos vian pekon; ĉar Mia nomo estas en li.","Gardu vin antaŭ lia vizaĝo kaj aŭskultu lian voĉon; ne incitu lin, ĉar li ne pardonos vian pekon; ĉar Mia nomo estas en li."],[23,22,"Sed se vi aŭskultos lian voĉon, kaj faros ĉion, kion Mi diros, tiam Mi malamikos kontraŭ viaj malamikoj kaj premos viajn premantojn.","Sed se vi aŭskultos lian voĉon, kaj faros ĉion, kion Mi diros, tiam Mi malamikos kontraŭ viaj malamikoj kaj premos viajn premantojn."],[23,23,"Kiam Mia anĝelo iros antaŭ vi, kaj Mi venigos vin al la Amoridoj, la Ĥetidoj, la Perizidoj, la Kanaanidoj, la Ĥividoj, kaj la Jebusidoj, kaj Mi ilin ekstermos:","Kiam Mia anĝelo iros antaŭ vi, kaj Mi venigos vin al la Amoridoj, la Ĥetidoj, la Perizidoj, la Kanaanidoj, la Ĥividoj, kaj la Jebusidoj, kaj Mi ilin ekstermos:"],[23,24,"ne adoru iliajn diojn kaj ne servu ilin, kaj ne agu kiel ili agas, sed frakasu ilin kaj detruu iliajn statuojn.","ne adoru iliajn diojn kaj ne servu ilin, kaj ne agu kiel ili agas, sed frakasu ilin kaj detruu iliajn statuojn."],[23,25,"Kaj servu la Eternulon, vian Dion, kaj Li benos vian panon kaj vian akvon; kaj Mi forigos malsanon el via mezo.","Kaj servu la Eternulon, vian Dion, kaj Li benos vian panon kaj vian akvon; kaj Mi forigos malsanon el via mezo."],[23,26,"Ne estos seninfana nek sennaska en via lando; la nombron de viaj tagoj Mi faros plena.","Ne estos seninfana nek sennaska en via lando; la nombron de viaj tagoj Mi faros plena."],[23,27,"Mian teruron Mi sendos antaŭ vi, kaj Mi konfuzos ĉiun popolon, al kiu vi venos, kaj ĉiujn viajn malamikojn Mi turnos al vi dorse.","Mian teruron Mi sendos antaŭ vi, kaj Mi konfuzos ĉiun popolon, al kiu vi venos, kaj ĉiujn viajn malamikojn Mi turnos al vi dorse."],[23,28,"Kaj Mi sendos krabrojn antaŭ vi, kaj ili forpelos la Ĥividojn kaj la Kanaanidojn kaj la Ĥetidojn de antaŭ vi.","Kaj Mi sendos krabrojn antaŭ vi, kaj ili forpelos la Ĥividojn kaj la Kanaanidojn kaj la Ĥetidojn de antaŭ vi."],[23,29,"Mi ne forpelos ilin de antaŭ vi en unu jaro, por ke la tero ne fariĝu senhoma kaj por ke ne multiĝu kontraŭ vi la bestoj de la kampo.","Mi ne forpelos ilin de antaŭ vi en unu jaro, por ke la tero ne fariĝu senhoma kaj por ke ne multiĝu kontraŭ vi la bestoj de la kampo."],[23,30,"Iom post iom Mi forpelos ilin de antaŭ vi, ĝis vi multiĝos kaj posedos la landon.","Iom post iom Mi forpelos ilin de antaŭ vi, ĝis vi multiĝos kaj posedos la landon."],[23,31,"Kaj Mi faros viajn limojn de la Ruĝa Maro ĝis la Maro Filiŝta, kaj de la dezerto ĝis la Rivero; ĉar Mi transdonos en viajn manojn la loĝantojn de la lando, kaj vi forpelos ilin de antaŭ vi.","Kaj Mi faros viajn limojn de la Ruĝa Maro ĝis la Maro Filiŝta, kaj de la dezerto ĝis la Rivero; ĉar Mi transdonos en viajn manojn la loĝantojn de la lando, kaj vi forpelos ilin de antaŭ vi."],[23,32,"Ne faru interligon kun ili nek kun iliaj dioj.","Ne faru interligon kun ili nek kun iliaj dioj."],[23,33,"Ili ne loĝu en via lando, por ke ili ne pekigu vin kontraŭ Mi; se vi servos iliajn diojn, tio fariĝos kaptilo por vi.","Ili ne loĝu en via lando, por ke ili ne pekigu vin kontraŭ Mi; se vi servos iliajn diojn, tio fariĝos kaptilo por vi."],[24,1,"Kaj al Moseo Li diris: Supreniru al la Eternulo, vi kaj Aaron, Nadab kaj Abihu, kaj sepdek el la ĉefoj de Izrael, kaj faru adoron de malproksime.","Kaj al Moseo Li diris: Supreniru al la Eternulo, vi kaj Aaron, Nadab kaj Abihu, kaj sepdek el la ĉefoj de Izrael, kaj faru adoron de malproksime."],[24,2,"Kaj Moseo sola alproksimiĝu al la Eternulo; sed ili ne alproksimiĝu, kaj la popolo ne supreniru kun li.","Kaj Moseo sola alproksimiĝu al la Eternulo; sed ili ne alproksimiĝu, kaj la popolo ne supreniru kun li."],[24,3,"Kaj Moseo venis kaj rakontis al la popolo ĉiujn vortojn de la Eternulo kaj ĉiujn leĝojn. Kaj la tuta popolo respondis per unu voĉo, kaj ili diris: Ĉion, kion diris la Eternulo, ni faros.","Kaj Moseo venis kaj rakontis al la popolo ĉiujn vortojn de la Eternulo kaj ĉiujn leĝojn. Kaj la tuta popolo respondis per unu voĉo, kaj ili diris: Ĉion, kion diris la Eternulo, ni faros."],[24,4,"Kaj Moseo skribis ĉiujn vortojn de la Eternulo, kaj li leviĝis frue matene kaj konstruis altaron sub la monto kaj dek du kolonojn laŭ la dek du triboj de Izrael.","Kaj Moseo skribis ĉiujn vortojn de la Eternulo, kaj li leviĝis frue matene kaj konstruis altaron sub la monto kaj dek du kolonojn laŭ la dek du triboj de Izrael."],[24,5,"Kaj li sendis junulojn el la Izraelidoj, kaj ili alportis bruloferojn kaj buĉis pacoferojn al la Eternulo, bovidojn.","Kaj li sendis junulojn el la Izraelidoj, kaj ili alportis bruloferojn kaj buĉis pacoferojn al la Eternulo, bovidojn."],[24,6,"Moseo prenis duonon de la sango kaj enverŝis en pelvojn, kaj duonon de la sango li ŝprucigis sur la altaron.","Moseo prenis duonon de la sango kaj enverŝis en pelvojn, kaj duonon de la sango li ŝprucigis sur la altaron."],[24,7,"Kaj li prenis la libron de la interligo kaj laŭtlegis ĝin al la popolo, kaj ili diris: Ĉion, kion diris la Eternulo, ni faros kaj obeos.","Kaj li prenis la libron de la interligo kaj laŭtlegis ĝin al la popolo, kaj ili diris: Ĉion, kion diris la Eternulo, ni faros kaj obeos."],[24,8,"Kaj Moseo prenis la sangon kaj ŝprucigis sur la popolon, kaj diris: Jen estas sango de la interligo, kiun la Eternulo faris kun vi pri ĉiuj tiuj vortoj.","Kaj Moseo prenis la sangon kaj ŝprucigis sur la popolon, kaj diris: Jen estas sango de la interligo, kiun la Eternulo faris kun vi pri ĉiuj tiuj vortoj."],[24,9,"Kaj supreniris Moseo kaj Aaron, Nadab kaj Abihu, kaj sepdek el la ĉefoj de Izrael.","Kaj supreniris Moseo kaj Aaron, Nadab kaj Abihu, kaj sepdek el la ĉefoj de Izrael."],[24,10,"Kaj ili vidis la Dion de Izrael; kaj sub Liaj piedoj estis io, kiel faritaĵo el brilanta safiro, kaj kiel la ĉielo mem, kiam ĝi estas klara.","Kaj ili vidis la Dion de Izrael; kaj sub Liaj piedoj estis io, kiel faritaĵo el brilanta safiro, kaj kiel la ĉielo mem, kiam ĝi estas klara."],[24,11,"Li ne etendis Sian manon kontraŭ la ĉefojn de Izrael; kaj ili vidis Dion, kaj manĝis kaj trinkis.","Li ne etendis Sian manon kontraŭ la ĉefojn de Izrael; kaj ili vidis Dion, kaj manĝis kaj trinkis."],[24,12,"Kaj la Eternulo diris al Moseo: Supreniru al Mi sur la monton kaj estu tie; kaj Mi donos al vi ŝtonajn tabelojn, kaj la instruon kaj ordonojn, kiujn Mi skribis, por instrui ilin.","Kaj la Eternulo diris al Moseo: Supreniru al Mi sur la monton kaj estu tie; kaj Mi donos al vi ŝtonajn tabelojn, kaj la instruon kaj ordonojn, kiujn Mi skribis, por instrui ilin."],[24,13,"Kaj leviĝis Moseo kaj lia servanto Josuo, kaj Moseo supreniris sur la monton de Dio.","Kaj leviĝis Moseo kaj lia servanto Josuo, kaj Moseo supreniris sur la monton de Dio."],[24,14,"Kaj al la ĉefoj li diris: Restu ĉi tie, ĝis ni revenos al vi; kaj jen Aaron kaj Ĥur estas kun vi; kiu havas ian aferon, tiu venu al ili.","Kaj al la ĉefoj li diris: Restu ĉi tie, ĝis ni revenos al vi; kaj jen Aaron kaj Ĥur estas kun vi; kiu havas ian aferon, tiu venu al ili."],[24,15,"Kaj Moseo supreniris sur la monton, kaj nubo kovris la monton.","Kaj Moseo supreniris sur la monton, kaj nubo kovris la monton."],[24,16,"Kaj la majesto de la Eternulo loĝis sur la monto Sinaj, kaj la nubo ĝin kovris dum ses tagoj; kaj Li vokis Moseon en la sepa tago el interne de la nubo.","Kaj la majesto de la Eternulo loĝis sur la monto Sinaj, kaj la nubo ĝin kovris dum ses tagoj; kaj Li vokis Moseon en la sepa tago el interne de la nubo."],[24,17,"Kaj la aspekto de la majesto de la Eternulo estis kiel fajro flamanta sur la supro de la monto antaŭ la okuloj de la Izraelidoj.","Kaj la aspekto de la majesto de la Eternulo estis kiel fajro flamanta sur la supro de la monto antaŭ la okuloj de la Izraelidoj."],[24,18,"Kaj Moseo eniris en la mezon de la nubo, kaj supreniris sur la monton; kaj Moseo estis sur la monto dum kvardek tagoj kaj kvardek noktoj.","Kaj Moseo eniris en la mezon de la nubo, kaj supreniris sur la monton; kaj Moseo estis sur la monto dum kvardek tagoj kaj kvardek noktoj."],[25,1,"Kaj la Eternulo ekparolis al Moseo, dirante:","Kaj la Eternulo ekparolis al Moseo, dirante:"],[25,2,"Diru al la Izraelidoj, ke ili alportu por Mi oferdonon; de ĉiu homo, kies koro deziros doni, prenu la oferdonon por Mi.","Diru al la Izraelidoj, ke ili alportu por Mi oferdonon; de ĉiu homo, kies koro deziros doni, prenu la oferdonon por Mi."],[25,3,"Kaj jen estas la oferdono, kiun vi prenos de ili: oro kaj arĝento kaj kupro,","Kaj jen estas la oferdono, kiun vi prenos de ili: oro kaj arĝento kaj kupro,"],[25,4,"kaj blua teksaĵo kaj purpura kaj ruĝa, kaj bisino kaj kapra lano,","kaj blua teksaĵo kaj purpura kaj ruĝa, kaj bisino kaj kapra lano,"],[25,5,"kaj virŝafaj feloj ruĝe kolorigitaj kaj antilopaj feloj, kaj akacia ligno,","kaj virŝafaj feloj ruĝe kolorigitaj kaj antilopaj feloj, kaj akacia ligno,"],[25,6,"oleo por lumigado, aromaĵoj por la sankta oleo kaj por la bonodoraj incensoj,","oleo por lumigado, aromaĵoj por la sankta oleo kaj por la bonodoraj incensoj,"],[25,7,"ŝtonoj oniksaj kaj ŝtonoj enkadrigeblaj por la efodo kaj por la surbrustaĵo.","ŝtonoj oniksaj kaj ŝtonoj enkadrigeblaj por la efodo kaj por la surbrustaĵo."],[25,8,"Kaj ili faru por Mi sanktejon, por ke Mi loĝu inter ili.","Kaj ili faru por Mi sanktejon, por ke Mi loĝu inter ili."],[25,9,"Laŭ ĉio, kiel Mi montros al vi la bildon de la Loĝejo kaj la bildon de ĉiuj ĝiaj objektoj, tiel faru.","Laŭ ĉio, kiel Mi montros al vi la bildon de la Loĝejo kaj la bildon de ĉiuj ĝiaj objektoj, tiel faru."],[25,10,"Kaj ili faru keston el akacia ligno; du ulnoj kaj duono estu ĝia longo, kaj unu ulno kaj duono ĝia larĝo, kaj unu ulno kaj duono ĝia alto.","Kaj ili faru keston el akacia ligno; du ulnoj kaj duono estu ĝia longo, kaj unu ulno kaj duono ĝia larĝo, kaj unu ulno kaj duono ĝia alto."],[25,11,"Kaj tegu ĝin per pura oro, interne kaj ekstere tegu ĝin, kaj faru sur ĝi oran kronon ĉirkaŭe.","Kaj tegu ĝin per pura oro, interne kaj ekstere tegu ĝin, kaj faru sur ĝi oran kronon ĉirkaŭe."],[25,12,"Kaj fandu por ĝi kvar orajn ringojn, kaj alfortikigu ilin sur ĝiaj kvar anguloj: du ringojn sur unu ĝia flanko kaj du ringojn sur ĝia alia flanko.","Kaj fandu por ĝi kvar orajn ringojn, kaj alfortikigu ilin sur ĝiaj kvar anguloj: du ringojn sur unu ĝia flanko kaj du ringojn sur ĝia alia flanko."],[25,13,"Kaj faru stangojn el akacia ligno kaj tegu ilin per oro.","Kaj faru stangojn el akacia ligno kaj tegu ilin per oro."],[25,14,"Kaj metu la stangojn en la ringojn sur la flankoj de la kesto, por porti la keston per ili.","Kaj metu la stangojn en la ringojn sur la flankoj de la kesto, por porti la keston per ili."],[25,15,"En la ringoj de la kesto devas esti la stangoj; ili ne estu prenataj for de ĝi.","En la ringoj de la kesto devas esti la stangoj; ili ne estu prenataj for de ĝi."],[25,16,"Kaj en la keston enmetu la Ateston, kiun Mi donos al vi.","Kaj en la keston enmetu la Ateston, kiun Mi donos al vi."],[25,17,"Kaj faru fermoplaton el pura oro; du ulnoj kaj duono estu ĝia longo, kaj unu ulno kaj duono ĝia larĝo.","Kaj faru fermoplaton el pura oro; du ulnoj kaj duono estu ĝia longo, kaj unu ulno kaj duono ĝia larĝo."],[25,18,"Kaj faru du kerubojn el oro; per forĝa laboro faru ilin ĉe la du randoj de la fermoplato.","Kaj faru du kerubojn el oro; per forĝa laboro faru ilin ĉe la du randoj de la fermoplato."],[25,19,"Faru unu kerubon ĉe unu flanko kaj unu kerubon ĉe la alia flanko; elstarantaj el la fermoplato faru la kerubojn, sur ĝiaj du flankoj.","Faru unu kerubon ĉe unu flanko kaj unu kerubon ĉe la alia flanko; elstarantaj el la fermoplato faru la kerubojn, sur ĝiaj du flankoj."],[25,20,"Kaj la keruboj estu etendantaj siajn flugilojn supren, kovrante per siaj flugiloj la fermoplaton, kaj iliaj vizaĝoj estu unu kontraŭ la alia; al la fermoplato estu turnitaj la vizaĝoj de la keruboj.","Kaj la keruboj estu etendantaj siajn flugilojn supren, kovrante per siaj flugiloj la fermoplaton, kaj iliaj vizaĝoj estu unu kontraŭ la alia; al la fermoplato estu turnitaj la vizaĝoj de la keruboj."],[25,21,"Kaj metu la fermoplaton sur la keston supre, kaj en la keston metu la ateston, kiun Mi donos al vi.","Kaj metu la fermoplaton sur la keston supre, kaj en la keston metu la ateston, kiun Mi donos al vi."],[25,22,"Kaj Mi aperados al vi tie, kaj Mi parolados kun vi super la fermoplato, el inter la du keruboj, kiuj estos super la kesto de atesto, pri ĉio, kion Mi ordonos al vi por la Izraelidoj.","Kaj Mi aperados al vi tie, kaj Mi parolados kun vi super la fermoplato, el inter la du keruboj, kiuj estos super la kesto de atesto, pri ĉio, kion Mi ordonos al vi por la Izraelidoj."],[25,23,"Kaj faru tablon el akacia ligno; du ulnoj estu ĝia longo, kaj unu ulno ĝia larĝo, kaj unu ulno kaj duono ĝia alto.","Kaj faru tablon el akacia ligno; du ulnoj estu ĝia longo, kaj unu ulno ĝia larĝo, kaj unu ulno kaj duono ĝia alto."],[25,24,"Kaj tegu ĝin per pura oro, kaj faru al ĝi oran kronon ĉirkaŭe.","Kaj tegu ĝin per pura oro, kaj faru al ĝi oran kronon ĉirkaŭe."],[25,25,"Kaj faru ĉirkaŭ ĝi manlarĝan listelon, kaj faru oran kronon ĉirkaŭ la listelo.","Kaj faru ĉirkaŭ ĝi manlarĝan listelon, kaj faru oran kronon ĉirkaŭ la listelo."],[25,26,"Kaj faru por ĝi kvar orajn ringojn, kaj alfortikigu la ringojn en la kvar anguloj, ĉe ĝiaj kvar piedoj.","Kaj faru por ĝi kvar orajn ringojn, kaj alfortikigu la ringojn en la kvar anguloj, ĉe ĝiaj kvar piedoj."],[25,27,"Apud la listelo estu la ringoj, kiel ingoj por stangoj, por porti la tablon.","Apud la listelo estu la ringoj, kiel ingoj por stangoj, por porti la tablon."],[25,28,"Kaj faru la stangojn el akacia ligno, kaj tegu ilin per oro, ke per ili oni portu la tablon.","Kaj faru la stangojn el akacia ligno, kaj tegu ilin per oro, ke per ili oni portu la tablon."],[25,29,"Kaj faru ĝiajn pladojn kaj ĝiajn kulerojn, kaj ĝiajn kalikojn kaj ĝiajn kruĉojn, per kiuj oni verŝos; el pura oro faru ilin.","Kaj faru ĝiajn pladojn kaj ĝiajn kulerojn, kaj ĝiajn kalikojn kaj ĝiajn kruĉojn, per kiuj oni verŝos; el pura oro faru ilin."],[25,30,"Kaj metu sur la tablon panon de propono antaŭ Mi ĉiam.","Kaj metu sur la tablon panon de propono antaŭ Mi ĉiam."],[25,31,"Kaj faru kandelabron el pura oro, per forĝa laboro estu farita la kandelabro; ĝia trunko kaj ĝiaj branĉoj, ĝiaj kalikoj, ĝiaj kapetoj, kaj ĝiaj floroj elstaru el ĝi.","Kaj faru kandelabron el pura oro, per forĝa laboro estu farita la kandelabro; ĝia trunko kaj ĝiaj branĉoj, ĝiaj kalikoj, ĝiaj kapetoj, kaj ĝiaj floroj elstaru el ĝi."],[25,32,"Kaj ses branĉoj devas elstari el ĝiaj flankoj: tri branĉoj de la kandelabro el unu flanko, kaj tri branĉoj de la kandelabro el la alia flanko;","Kaj ses branĉoj devas elstari el ĝiaj flankoj: tri branĉoj de la kandelabro el unu flanko, kaj tri branĉoj de la kandelabro el la alia flanko;"],[25,33,"tri migdalformaj kalikoj, kapeto, kaj floro, sur unu branĉo, kaj tri migdalformaj kalikoj, kapeto, kaj floro, sur la alia branĉo; tiel sur la ses branĉoj, kiuj elstaras el la kandelabro.","tri migdalformaj kalikoj, kapeto, kaj floro, sur unu branĉo, kaj tri migdalformaj kalikoj, kapeto, kaj floro, sur la alia branĉo; tiel sur la ses branĉoj, kiuj elstaras el la kandelabro."],[25,34,"Kaj sur la kandelabro estu kvar migdalformaj kalikoj kun kapetoj kaj floroj.","Kaj sur la kandelabro estu kvar migdalformaj kalikoj kun kapetoj kaj floroj."],[25,35,"Kaj kapeto sub unu paro da branĉoj, kapeto sub la dua paro da branĉoj, kaj kapeto sub la tria paro da branĉoj; tiel por la ses branĉoj, kiuj elstaras el la kandelabro.","Kaj kapeto sub unu paro da branĉoj, kapeto sub la dua paro da branĉoj, kaj kapeto sub la tria paro da branĉoj; tiel por la ses branĉoj, kiuj elstaras el la kandelabro."],[25,36,"La kapetoj kaj branĉoj devas elstari el ĝi; ĉio devas esti unu forĝita tutaĵo el pura oro.","La kapetoj kaj branĉoj devas elstari el ĝi; ĉio devas esti unu forĝita tutaĵo el pura oro."],[25,37,"Kaj faru por ĝi sep lucernojn; kaj starigu sur ĝi ĝiajn lucernojn, ke ili lumu sur ĝian antaŭan flankon.","Kaj faru por ĝi sep lucernojn; kaj starigu sur ĝi ĝiajn lucernojn, ke ili lumu sur ĝian antaŭan flankon."],[25,38,"Kaj ĝiaj preniloj kaj cindrujoj estu el pura oro.","Kaj ĝiaj preniloj kaj cindrujoj estu el pura oro."],[25,39,"El kikaro da pura oro oni faru ĝin kaj ĉiujn tiujn apartenaĵojn.","El kikaro da pura oro oni faru ĝin kaj ĉiujn tiujn apartenaĵojn."],[25,40,"Kaj rigardu kaj faru laŭ ilia modelo, kiu estis montrita al vi sur la monto.","Kaj rigardu kaj faru laŭ ilia modelo, kiu estis montrita al vi sur la monto."],[26,1,"La tabernaklon faru el dek tapiŝoj el tordita bisino, kaj el blua, purpura, kaj ruĝa teksaĵo; kerubojn artiste laboritajn faru sur ili.","La tabernaklon faru el dek tapiŝoj el tordita bisino, kaj el blua, purpura, kaj ruĝa teksaĵo; kerubojn artiste laboritajn faru sur ili."],[26,2,"La longo de ĉiu tapiŝo estu dudek ok ulnoj, kaj la larĝo de ĉiu tapiŝo estu kvar ulnoj; unu mezuro estu por ĉiuj tapiŝoj.","La longo de ĉiu tapiŝo estu dudek ok ulnoj, kaj la larĝo de ĉiu tapiŝo estu kvar ulnoj; unu mezuro estu por ĉiuj tapiŝoj."],[26,3,"Kvin tapiŝoj estu kunigitaj unu kun la alia, kaj la kvin ceteraj tapiŝoj estu ankaŭ kunigitaj unu kun la alia.","Kvin tapiŝoj estu kunigitaj unu kun la alia, kaj la kvin ceteraj tapiŝoj estu ankaŭ kunigitaj unu kun la alia."],[26,4,"Kaj faru maŝojn el blua teksaĵo sur la rando de unu tapiŝo, sur la rando de la kuniĝo, kaj tiel same faru sur la rando de la ekstrema tapiŝo, sur la dua rando de kuniĝo.","Kaj faru maŝojn el blua teksaĵo sur la rando de unu tapiŝo, sur la rando de la kuniĝo, kaj tiel same faru sur la rando de la ekstrema tapiŝo, sur la dua rando de kuniĝo."],[26,5,"Kvindek maŝojn faru sur unu tapiŝo, kaj kvindek maŝojn faru sur la rando de tiu tapiŝo, sur kiu estas la dua flanko de la kuniĝo; la maŝoj devas esti reciproke aranĝitaj unu kontraŭ alia.","Kvindek maŝojn faru sur unu tapiŝo, kaj kvindek maŝojn faru sur la rando de tiu tapiŝo, sur kiu estas la dua flanko de la kuniĝo; la maŝoj devas esti reciproke aranĝitaj unu kontraŭ alia."],[26,6,"Kaj faru kvindek orajn hoketojn, kaj kunigu la tapiŝojn unu kun la alia per la hoketoj, por ke la tabernaklo fariĝu unu tutaĵo.","Kaj faru kvindek orajn hoketojn, kaj kunigu la tapiŝojn unu kun la alia per la hoketoj, por ke la tabernaklo fariĝu unu tutaĵo."],[26,7,"Kaj faru tapiŝojn el kapra lano kiel kovron super la tabernaklo; dek unu tiajn tapiŝojn faru.","Kaj faru tapiŝojn el kapra lano kiel kovron super la tabernaklo; dek unu tiajn tapiŝojn faru."],[26,8,"La longo de ĉiu tapiŝo estu tridek ulnoj, kaj la larĝo de ĉiu tapiŝo estu kvar ulnoj; unu mezuro estu por la dek unu tapiŝoj.","La longo de ĉiu tapiŝo estu tridek ulnoj, kaj la larĝo de ĉiu tapiŝo estu kvar ulnoj; unu mezuro estu por la dek unu tapiŝoj."],[26,9,"Kaj kunigu kvin tapiŝojn aparte kaj ses tapiŝojn aparte, kaj la sesan tapiŝon faldu duige antaŭ la tabernaklo.","Kaj kunigu kvin tapiŝojn aparte kaj ses tapiŝojn aparte, kaj la sesan tapiŝon faldu duige antaŭ la tabernaklo."],[26,10,"Kaj faru kvindek maŝojn sur la rando de la ekstrema tapiŝo, sur la rando de la kuniĝo, kaj kvindek maŝojn sur la rando de la dua kuniĝa tapiŝo.","Kaj faru kvindek maŝojn sur la rando de la ekstrema tapiŝo, sur la rando de la kuniĝo, kaj kvindek maŝojn sur la rando de la dua kuniĝa tapiŝo."],[26,11,"Kaj faru kvindek kuprajn hoketojn, kaj metu la hoketojn en la maŝojn, por ke vi kunigu la tendon kaj ĝi estu unu tutaĵo.","Kaj faru kvindek kuprajn hoketojn, kaj metu la hoketojn en la maŝojn, por ke vi kunigu la tendon kaj ĝi estu unu tutaĵo."],[26,12,"Kaj el la superflua pendanta parto de la tapiŝoj de la kovro, duono de la superflua tapiŝa parto superpendu super la malantaŭa flanko de la tabernaklo.","Kaj el la superflua pendanta parto de la tapiŝoj de la kovro, duono de la superflua tapiŝa parto superpendu super la malantaŭa flanko de la tabernaklo."],[26,13,"Kaj po unu ulno ĉiuflanke el la superflua longo de la tapiŝoj superpendu super ambaŭ flankoj de la tabernaklo, por kovri ĝin.","Kaj po unu ulno ĉiuflanke el la superflua longo de la tapiŝoj superpendu super ambaŭ flankoj de la tabernaklo, por kovri ĝin."],[26,14,"Kaj faru kovron por la tendo el ruĝaj virŝafaj feloj kaj ankoraŭ kovron el antilopaj feloj supre.","Kaj faru kovron por la tendo el ruĝaj virŝafaj feloj kaj ankoraŭ kovron el antilopaj feloj supre."],[26,15,"Kaj faru starantajn tabulojn por la tabernaklo el akacia ligno.","Kaj faru starantajn tabulojn por la tabernaklo el akacia ligno."],[26,16,"Dek ulnoj estu la longo de ĉiu tabulo, kaj unu ulno kaj duono la larĝo de ĉiu tabulo.","Dek ulnoj estu la longo de ĉiu tabulo, kaj unu ulno kaj duono la larĝo de ĉiu tabulo."],[26,17,"Du pivotoj estu ĉe ĉiu tabulo, alĝustigitaj unu al la alia; tiel faru ĉe ĉiuj tabuloj de la tabernaklo.","Du pivotoj estu ĉe ĉiu tabulo, alĝustigitaj unu al la alia; tiel faru ĉe ĉiuj tabuloj de la tabernaklo."],[26,18,"Kaj faru la tabulojn por la tabernaklo: dudek tabuloj staru sur la flanko suda.","Kaj faru la tabulojn por la tabernaklo: dudek tabuloj staru sur la flanko suda."],[26,19,"Kaj kvardek arĝentajn bazojn faru sub la dudek tabuloj: du bazojn sub ĉiu tabulo, por ĝiaj du pivotoj.","Kaj kvardek arĝentajn bazojn faru sub la dudek tabuloj: du bazojn sub ĉiu tabulo, por ĝiaj du pivotoj."],[26,20,"Kaj sur la dua flanko de la tabernaklo, sur la flanko norda, estu dudek tabuloj,","Kaj sur la dua flanko de la tabernaklo, sur la flanko norda, estu dudek tabuloj,"],[26,21,"kaj kvardek arĝentaj bazoj por ili, po du bazoj sub ĉiu tabulo.","kaj kvardek arĝentaj bazoj por ili, po du bazoj sub ĉiu tabulo."],[26,22,"Kaj sur la malantaŭa flanko de la tabernaklo, okcidente, faru ses tabulojn.","Kaj sur la malantaŭa flanko de la tabernaklo, okcidente, faru ses tabulojn."],[26,23,"Kaj du tabulojn faru en la anguloj de la tabernaklo sur la malantaŭa flanko.","Kaj du tabulojn faru en la anguloj de la tabernaklo sur la malantaŭa flanko."],[26,24,"Ili estu kunigitaj malsupre kaj kunigitaj supre per unu ringo; tiel ĝi estu kun ili ambaŭ; por ambaŭ anguloj ili estu.","Ili estu kunigitaj malsupre kaj kunigitaj supre per unu ringo; tiel ĝi estu kun ili ambaŭ; por ambaŭ anguloj ili estu."],[26,25,"Tiel estu ok tabuloj, kaj ĉe ili dek ses arĝentaj bazoj, po du bazoj sub ĉiu tabulo.","Tiel estu ok tabuloj, kaj ĉe ili dek ses arĝentaj bazoj, po du bazoj sub ĉiu tabulo."],[26,26,"Kaj faru riglilojn el akacia ligno, kvin por la tabuloj de unu flanko de la tabernaklo,","Kaj faru riglilojn el akacia ligno, kvin por la tabuloj de unu flanko de la tabernaklo,"],[26,27,"kaj kvin riglilojn por la tabuloj de la dua flanko de la tabernaklo, kaj kvin riglilojn por la tabuloj de la malantaŭa flanko de la tabernaklo, okcidente.","kaj kvin riglilojn por la tabuloj de la dua flanko de la tabernaklo, kaj kvin riglilojn por la tabuloj de la malantaŭa flanko de la tabernaklo, okcidente."],[26,28,"Kaj la meza riglilo meze de la tabuloj ŝoviĝu de unu fino ĝis la alia.","Kaj la meza riglilo meze de la tabuloj ŝoviĝu de unu fino ĝis la alia."],[26,29,"Kaj la tabulojn tegu per oro, kaj iliajn ringojn, ingojn por la rigliloj, faru el oro, kaj la riglilojn tegu per oro.","Kaj la tabulojn tegu per oro, kaj iliajn ringojn, ingojn por la rigliloj, faru el oro, kaj la riglilojn tegu per oro."],[26,30,"Starigu la tabernaklon laŭ ĝia modelo, kiu estis montrita al vi sur la monto.","Starigu la tabernaklon laŭ ĝia modelo, kiu estis montrita al vi sur la monto."],[26,31,"Kaj faru kurtenon el blua, purpura, kaj ruĝa teksaĵo, kaj el tordita bisino; artiste laboritaj keruboj estu faritaj sur ĝi.","Kaj faru kurtenon el blua, purpura, kaj ruĝa teksaĵo, kaj el tordita bisino; artiste laboritaj keruboj estu faritaj sur ĝi."],[26,32,"Kaj pendigu ĝin sur kvar akaciaj kolonoj, tegitaj per oro kaj havantaj orajn hokojn kaj arĝentajn bazojn.","Kaj pendigu ĝin sur kvar akaciaj kolonoj, tegitaj per oro kaj havantaj orajn hokojn kaj arĝentajn bazojn."],[26,33,"Kaj pendigu la kurtenon sub la hokoj, kaj enportu tien internen de la kurteno la keston de atesto; kaj la kurteno faru por vi apartigon inter la sanktejo kaj la plejsanktejo.","Kaj pendigu la kurtenon sub la hokoj, kaj enportu tien internen de la kurteno la keston de atesto; kaj la kurteno faru por vi apartigon inter la sanktejo kaj la plejsanktejo."],[26,34,"Kaj metu la fermoplaton sur la keston de atesto en la plejsanktejo.","Kaj metu la fermoplaton sur la keston de atesto en la plejsanktejo."],[26,35,"Kaj starigu la tablon ekster la kurteno, kaj la kandelabron kontraŭ la tablo, en la suda parto de la tabernaklo; la tablon starigu en la norda parto.","Kaj starigu la tablon ekster la kurteno, kaj la kandelabron kontraŭ la tablo, en la suda parto de la tabernaklo; la tablon starigu en la norda parto."],[26,36,"Kaj faru kovrotukon por la pordo de la tabernaklo, el blua, purpura, kaj ruĝa teksaĵo, kaj el tordita bisino, kun brodaĵoj;","Kaj faru kovrotukon por la pordo de la tabernaklo, el blua, purpura, kaj ruĝa teksaĵo, kaj el tordita bisino, kun brodaĵoj;"],[26,37,"kaj faru por la kovrotuko kvin kolonojn el akacia ligno, kaj tegu ilin per oro, kaj iliaj hoketoj estu el oro; kaj fandu por ili kvin kuprajn bazojn.","kaj faru por la kovrotuko kvin kolonojn el akacia ligno, kaj tegu ilin per oro, kaj iliaj hoketoj estu el oro; kaj fandu por ili kvin kuprajn bazojn."],[27,1,"Kaj faru la altaron el akacia ligno, havantan la longon de kvin ulnoj kaj la larĝon de kvin ulnoj; kvarangula estu la altaro; kaj ĝia alto estu tri ulnoj.","Kaj faru la altaron el akacia ligno, havantan la longon de kvin ulnoj kaj la larĝon de kvin ulnoj; kvarangula estu la altaro; kaj ĝia alto estu tri ulnoj."],[27,2,"Kaj faru ĝiajn kornojn sur ĝiaj kvar anguloj; el ĝi elstaru ĝiaj kornoj; kaj tegu ĝin per kupro.","Kaj faru ĝiajn kornojn sur ĝiaj kvar anguloj; el ĝi elstaru ĝiaj kornoj; kaj tegu ĝin per kupro."],[27,3,"Kaj faru por ĝi potojn por ĝia cindro kaj ŝovelilojn kaj kalikojn kaj forkojn kaj karbujojn; ĉiujn ĝiajn vazojn faru el kupro.","Kaj faru por ĝi potojn por ĝia cindro kaj ŝovelilojn kaj kalikojn kaj forkojn kaj karbujojn; ĉiujn ĝiajn vazojn faru el kupro."],[27,4,"Kaj faru por ĝi kradon en formo de kupra reto, kaj faru sur la reto kvar kuprajn ringojn sur ĝiaj kvar anguloj.","Kaj faru por ĝi kradon en formo de kupra reto, kaj faru sur la reto kvar kuprajn ringojn sur ĝiaj kvar anguloj."],[27,5,"Kaj metu ĝin sub la kornicon de la altaro, malsupren, tiel, ke la reto atingu ĝis la mezo de la altaro.","Kaj metu ĝin sub la kornicon de la altaro, malsupren, tiel, ke la reto atingu ĝis la mezo de la altaro."],[27,6,"Kaj faru stangojn por la altaro, stangojn el akacia ligno, kaj tegu ilin per kupro.","Kaj faru stangojn por la altaro, stangojn el akacia ligno, kaj tegu ilin per kupro."],[27,7,"Kaj metu ĝiajn stangojn en ringojn, tiel, ke la stangoj estu ĉe ambaŭ flankoj de la altaro, kiam oni ĝin portos.","Kaj metu ĝiajn stangojn en ringojn, tiel, ke la stangoj estu ĉe ambaŭ flankoj de la altaro, kiam oni ĝin portos."],[27,8,"Interne malplena faru ĝin el tabuloj; kiel estis montrite al vi sur la monto, tiel oni faru.","Interne malplena faru ĝin el tabuloj; kiel estis montrite al vi sur la monto, tiel oni faru."],[27,9,"Kaj faru korton por la tabernaklo; sur la flanko suda estu kurtenoj por la korto, el tordita bisino; unu flanko havu la longon de cent ulnoj;","Kaj faru korton por la tabernaklo; sur la flanko suda estu kurtenoj por la korto, el tordita bisino; unu flanko havu la longon de cent ulnoj;"],[27,10,"kaj ĝiaj dudek kolonoj kaj iliaj dudek bazoj estu el kupro; la hokoj de la kolonoj kaj iliaj ligiloj estu el arĝento.","kaj ĝiaj dudek kolonoj kaj iliaj dudek bazoj estu el kupro; la hokoj de la kolonoj kaj iliaj ligiloj estu el arĝento."],[27,11,"Tiel same ankaŭ sur la norda flanko laŭlonge estu kurtenoj, havantaj la longon de cent ulnoj; kaj dudek kolonoj, kaj por ili dudek bazoj el kupro; la hokoj de la kolonoj kaj iliaj ligiloj estu el arĝento.","Tiel same ankaŭ sur la norda flanko laŭlonge estu kurtenoj, havantaj la longon de cent ulnoj; kaj dudek kolonoj, kaj por ili dudek bazoj el kupro; la hokoj de la kolonoj kaj iliaj ligiloj estu el arĝento."],[27,12,"Sed laŭlarĝe de la korto, sur la flanko okcidenta, estu kurtenoj, havantaj la longon de kvindek ulnoj; dek kolonoj, kaj por ili dek bazoj.","Sed laŭlarĝe de la korto, sur la flanko okcidenta, estu kurtenoj, havantaj la longon de kvindek ulnoj; dek kolonoj, kaj por ili dek bazoj."],[27,13,"Kaj laŭlarĝe de la korto, sur la flanko orienta, estu kurtenoj, havantaj la longon de kvindek ulnoj.","Kaj laŭlarĝe de la korto, sur la flanko orienta, estu kurtenoj, havantaj la longon de kvindek ulnoj."],[27,14,"Kaj kurtenoj, havantaj la longon de dek kvin ulnoj, estu por unu latero; ankaŭ tri kolonoj, kaj por ili tri bazoj.","Kaj kurtenoj, havantaj la longon de dek kvin ulnoj, estu por unu latero; ankaŭ tri kolonoj, kaj por ili tri bazoj."],[27,15,"Kaj por la dua latero estu kurtenoj, havantaj la longon de dek kvin ulnoj; ankaŭ tri kolonoj, kaj por ili tri bazoj.","Kaj por la dua latero estu kurtenoj, havantaj la longon de dek kvin ulnoj; ankaŭ tri kolonoj, kaj por ili tri bazoj."],[27,16,"Kaj por la pordego de la korto estu kovrotuko, havanta la longon de dudek ulnoj, el blua, purpura, kaj ruĝa teksaĵo, kaj el tordita bisino, kun brodaĵoj; kvar kolonoj, kaj por ili kvar bazoj.","Kaj por la pordego de la korto estu kovrotuko, havanta la longon de dudek ulnoj, el blua, purpura, kaj ruĝa teksaĵo, kaj el tordita bisino, kun brodaĵoj; kvar kolonoj, kaj por ili kvar bazoj."],[27,17,"Ĉiuj kolonoj ĉirkaŭ la korto havu ligilojn el arĝento, hokojn el arĝento, kaj bazojn el kupro.","Ĉiuj kolonoj ĉirkaŭ la korto havu ligilojn el arĝento, hokojn el arĝento, kaj bazojn el kupro."],[27,18,"La longo de la korto estu cent ulnoj, la larĝo ĉie kvindek, kaj la alto kvin ulnoj; ĉio estu farita el tordita bisino, kaj la bazoj estu el kupro.","La longo de la korto estu cent ulnoj, la larĝo ĉie kvindek, kaj la alto kvin ulnoj; ĉio estu farita el tordita bisino, kaj la bazoj estu el kupro."],[27,19,"Ĉiuj vazoj de la tabernaklo, por ĉiuj servoj, kaj ĉiuj ĝiaj najloj kaj ĉiuj najloj de la korto, estu el kupro.","Ĉiuj vazoj de la tabernaklo, por ĉiuj servoj, kaj ĉiuj ĝiaj najloj kaj ĉiuj najloj de la korto, estu el kupro."],[27,20,"Kaj vi ordonu al la Izraelidoj, ke ili alportu al vi oleon olivan, puran, pistitan, por lumigado, por ke lucerno brulu ĉiam.","Kaj vi ordonu al la Izraelidoj, ke ili alportu al vi oleon olivan, puran, pistitan, por lumigado, por ke lucerno brulu ĉiam."],[27,21,"En la tabernaklo de kunveno, ekstere de la kurteno, kiu pendas antaŭ la atesto, aranĝadu ĝin Aaron kaj liaj filoj de vespero ĝis mateno antaŭ la Eternulo. Tio estu eterna leĝo en la generacioj de la Izraelidoj.","En la tabernaklo de kunveno, ekstere de la kurteno, kiu pendas antaŭ la atesto, aranĝadu ĝin Aaron kaj liaj filoj de vespero ĝis mateno antaŭ la Eternulo. Tio estu eterna leĝo en la generacioj de la Izraelidoj."],[28,1,"Kaj vi alproksimigu al vi vian fraton Aaron kaj liajn filojn kun li el inter la Izraelidoj, por ke li estu Mia pastro: Aaron, kaj Nadab, Abihu, Eleazar, kaj Itamar, la filoj de Aaron.","Kaj vi alproksimigu al vi vian fraton Aaron kaj liajn filojn kun li el inter la Izraelidoj, por ke li estu Mia pastro: Aaron, kaj Nadab, Abihu, Eleazar, kaj Itamar, la filoj de Aaron."],[28,2,"Kaj faru sanktajn vestojn por via frato Aaron, por honoro kaj ornamo.","Kaj faru sanktajn vestojn por via frato Aaron, por honoro kaj ornamo."],[28,3,"Kaj diru al ĉiuj, kiuj havas saĝan koron kaj kiujn Mi plenigis per spirito de saĝo, ke ili faru por Aaron vestojn, por sanktigi lin, ke li estu Mia pastro.","Kaj diru al ĉiuj, kiuj havas saĝan koron kaj kiujn Mi plenigis per spirito de saĝo, ke ili faru por Aaron vestojn, por sanktigi lin, ke li estu Mia pastro."],[28,4,"Kaj jen estas la vestoj, kiujn ili devas fari: surbrustaĵo, efodo, tuniko, ĥitono teksita, cidaro, kaj zono. Kaj ili faru sanktajn vestojn por via frato Aaron kaj por liaj filoj, ke li estu Mia pastro.","Kaj jen estas la vestoj, kiujn ili devas fari: surbrustaĵo, efodo, tuniko, ĥitono teksita, cidaro, kaj zono. Kaj ili faru sanktajn vestojn por via frato Aaron kaj por liaj filoj, ke li estu Mia pastro."],[28,5,"Kaj ili prenu oron, kaj bluan, purpuran, kaj ruĝan teksaĵon, kaj bisinon.","Kaj ili prenu oron, kaj bluan, purpuran, kaj ruĝan teksaĵon, kaj bisinon."],[28,6,"Kaj ili faru la efodon el oro, el blua, purpura, kaj ruĝa teksaĵo, kaj el tordita bisino, en artista maniero.","Kaj ili faru la efodon el oro, el blua, purpura, kaj ruĝa teksaĵo, kaj el tordita bisino, en artista maniero."],[28,7,"Du surŝultraĵojn kunigantajn ĝi havu sur siaj du finoj, por ke ĝi estu ligita.","Du surŝultraĵojn kunigantajn ĝi havu sur siaj du finoj, por ke ĝi estu ligita."],[28,8,"Kaj la ĉirkaŭliganta zono sur ĝi estu la sama laboraĵo, kiel ĝia kontinuaĵo, el oro, el blua, purpura, kaj ruĝa teksaĵo, kaj el tordita bisino.","Kaj la ĉirkaŭliganta zono sur ĝi estu la sama laboraĵo, kiel ĝia kontinuaĵo, el oro, el blua, purpura, kaj ruĝa teksaĵo, kaj el tordita bisino."],[28,9,"Kaj prenu du oniksajn ŝtonojn, kaj gravuru sur ili la nomojn de la filoj de Izrael:","Kaj prenu du oniksajn ŝtonojn, kaj gravuru sur ili la nomojn de la filoj de Izrael:"],[28,10,"ses el iliaj nomoj sur unu ŝtono kaj la ses ceterajn nomojn sur la dua ŝtono, laŭ la ordo de ilia naskiĝo.","ses el iliaj nomoj sur unu ŝtono kaj la ses ceterajn nomojn sur la dua ŝtono, laŭ la ordo de ilia naskiĝo."],[28,11,"Per laboro de gravuristoj, kiel sigelila gravurado, gravurigu sur la du ŝtonoj la nomojn de la filoj de Izrael; faru ilin ĉirkaŭataj per kadretoj el oro.","Per laboro de gravuristoj, kiel sigelila gravurado, gravurigu sur la du ŝtonoj la nomojn de la filoj de Izrael; faru ilin ĉirkaŭataj per kadretoj el oro."],[28,12,"Kaj metu la du ŝtonojn sur la surŝultraĵojn de la efodo, kiel ŝtonojn de memoro pri la filoj de Izrael; kaj Aaron portu iliajn nomojn antaŭ la Eternulo sur siaj du surŝultraĵoj por memoro.","Kaj metu la du ŝtonojn sur la surŝultraĵojn de la efodo, kiel ŝtonojn de memoro pri la filoj de Izrael; kaj Aaron portu iliajn nomojn antaŭ la Eternulo sur siaj du surŝultraĵoj por memoro."],[28,13,"Kaj faru kadretojn el oro;","Kaj faru kadretojn el oro;"],[28,14,"kaj du ĉenetojn el pura oro; faru ilin kuniĝantaj per siaj finoj, plektitaj; kaj alfortikigu la plektitajn ĉenetojn al la kadretoj.","kaj du ĉenetojn el pura oro; faru ilin kuniĝantaj per siaj finoj, plektitaj; kaj alfortikigu la plektitajn ĉenetojn al la kadretoj."],[28,15,"Kaj faru juĝan surbrustaĵon per artista laboro; simile al la laboro de la efodo faru ĝin; el oro, el blua, purpura, kaj ruĝa teksaĵo, kaj el tordita bisino faru ĝin.","Kaj faru juĝan surbrustaĵon per artista laboro; simile al la laboro de la efodo faru ĝin; el oro, el blua, purpura, kaj ruĝa teksaĵo, kaj el tordita bisino faru ĝin."],[28,16,"Kvarangula ĝi estu kaj duobla; manstreĉo estu ĝia longo, kaj manstreĉo ĝia larĝo.","Kvarangula ĝi estu kaj duobla; manstreĉo estu ĝia longo, kaj manstreĉo ĝia larĝo."],[28,17,"Kaj enmetu en ĝin enmetaĵon el ŝtonoj en kvar vicoj. La ŝtonoj de vico: rubeno, topazo, kaj smeraldo estu la unua vico;","Kaj enmetu en ĝin enmetaĵon el ŝtonoj en kvar vicoj. La ŝtonoj de vico: rubeno, topazo, kaj smeraldo estu la unua vico;"],[28,18,"kaj la dua vico: hiacinto, safiro, kaj jaspiso;","kaj la dua vico: hiacinto, safiro, kaj jaspiso;"],[28,19,"kaj la tria vico: ligurio, agato, kaj ametisto;","kaj la tria vico: ligurio, agato, kaj ametisto;"],[28,20,"kaj la kvara vico: krizolito, kaj onikso, kaj berilo. En oraj kadretoj ili estu laŭ siaj vicoj.","kaj la kvara vico: krizolito, kaj onikso, kaj berilo. En oraj kadretoj ili estu laŭ siaj vicoj."],[28,21,"Kaj la ŝtonoj estu laŭ la nomoj de la filoj de Izrael; dek du, laŭ iliaj nomoj, gravuritaj sigelile, ĉiu kun sia nomo, por la dek du triboj.","Kaj la ŝtonoj estu laŭ la nomoj de la filoj de Izrael; dek du, laŭ iliaj nomoj, gravuritaj sigelile, ĉiu kun sia nomo, por la dek du triboj."],[28,22,"Kaj faru al la surbrustaĵo plektitajn ĉenetojn, kuniĝantajn per siaj finoj, el pura oro.","Kaj faru al la surbrustaĵo plektitajn ĉenetojn, kuniĝantajn per siaj finoj, el pura oro."],[28,23,"Kaj faru por la surbrustaĵo du orajn ringojn, kaj alfortikigu la du ringojn al la du finoj de la surbrustaĵo.","Kaj faru por la surbrustaĵo du orajn ringojn, kaj alfortikigu la du ringojn al la du finoj de la surbrustaĵo."],[28,24,"Kaj metu la du orajn plektitajn ĉenetojn en la du ringojn ĉe la finoj de la surbrustaĵo.","Kaj metu la du orajn plektitajn ĉenetojn en la du ringojn ĉe la finoj de la surbrustaĵo."],[28,25,"Kaj la du finojn de la du plektitaj ĉenetoj enfortikigu en la du kadretojn, kaj alfortikigu ilin al la surŝultraĵoj de la efodo sur la antaŭa flanko.","Kaj la du finojn de la du plektitaj ĉenetoj enfortikigu en la du kadretojn, kaj alfortikigu ilin al la surŝultraĵoj de la efodo sur la antaŭa flanko."],[28,26,"Kaj faru du orajn ringojn, kaj alfortikigu ilin al la du aliaj finoj de la surbrustaĵo, sur interna ĝia rando, direktita al la efodo.","Kaj faru du orajn ringojn, kaj alfortikigu ilin al la du aliaj finoj de la surbrustaĵo, sur interna ĝia rando, direktita al la efodo."],[28,27,"Kaj faru du orajn ringojn, kaj alfortikigu ilin al la du surŝultraĵoj de la efodo malsupre, sur la antaŭa flanko, ĉe ĝia kuniĝo, super la zono de la efodo.","Kaj faru du orajn ringojn, kaj alfortikigu ilin al la du surŝultraĵoj de la efodo malsupre, sur la antaŭa flanko, ĉe ĝia kuniĝo, super la zono de la efodo."],[28,28,"Kaj oni alligu la surbrustaĵon per ĝiaj ringoj al la ringoj de la efodo per laĉo el blua ŝtofo, por ke ĝi estu super la zono de la efodo kaj por ke la surbrustaĵo ne forŝoviĝu de sur la efodo.","Kaj oni alligu la surbrustaĵon per ĝiaj ringoj al la ringoj de la efodo per laĉo el blua ŝtofo, por ke ĝi estu super la zono de la efodo kaj por ke la surbrustaĵo ne forŝoviĝu de sur la efodo."],[28,29,"Kaj Aaron portu la nomojn de la filoj de Izrael sur la juĝa surbrustaĵo sur sia koro, kiam li eniros en la sanktejon, por ĉiama memoro antaŭ la Eternulo.","Kaj Aaron portu la nomojn de la filoj de Izrael sur la juĝa surbrustaĵo sur sia koro, kiam li eniros en la sanktejon, por ĉiama memoro antaŭ la Eternulo."],[28,30,"Kaj metu sur la juĝan surbrustaĵon la signojn de lumo kaj la signojn de justo, por ke ili estu sur la koro de Aaron, kiam li eniros antaŭ la Eternulon; kaj Aaron ĉiam portu la juĝon de la filoj de Izrael sur sia koro antaŭ la Eternulo.","Kaj metu sur la juĝan surbrustaĵon la signojn de lumo kaj la signojn de justo, por ke ili estu sur la koro de Aaron, kiam li eniros antaŭ la Eternulon; kaj Aaron ĉiam portu la juĝon de la filoj de Izrael sur sia koro antaŭ la Eternulo."],[28,31,"Kaj faru la tunikon de la efodo tutan el blua teksaĵo.","Kaj faru la tunikon de la efodo tutan el blua teksaĵo."],[28,32,"La aperturo por la kapo estu en ĝia mezo; ĉirkaŭ la aperturo estu teksita bordero, kiel ĉe aperturo de ŝildo, por ke ĝi ne disŝiriĝu.","La aperturo por la kapo estu en ĝia mezo; ĉirkaŭ la aperturo estu teksita bordero, kiel ĉe aperturo de ŝildo, por ke ĝi ne disŝiriĝu."],[28,33,"Sur ĝia malsupra rando faru granatojn el blua, purpura, kaj ruĝa teksaĵo, ĉirkaŭe sur ĝia malsupra rando, kaj inter ili ĉirkaŭe orajn tintilojn.","Sur ĝia malsupra rando faru granatojn el blua, purpura, kaj ruĝa teksaĵo, ĉirkaŭe sur ĝia malsupra rando, kaj inter ili ĉirkaŭe orajn tintilojn."],[28,34,"Ora tintilo kaj granato, ora tintilo kaj granato estu ĉirkaŭe sur la malsupra rando de la tuniko.","Ora tintilo kaj granato, ora tintilo kaj granato estu ĉirkaŭe sur la malsupra rando de la tuniko."],[28,35,"Ĝi estu sur Aaron dum lia servado; por ke oni aŭdu sonon de li, kiam li eniros en la sanktejon antaŭ la Eternulon kaj kiam li eliros, kaj por ke li ne mortu.","Ĝi estu sur Aaron dum lia servado; por ke oni aŭdu sonon de li, kiam li eniros en la sanktejon antaŭ la Eternulon kaj kiam li eliros, kaj por ke li ne mortu."],[28,36,"Kaj faru tabuleton el pura oro, kaj gravuru sur ĝi en sigelila maniero: SANKTA AL LA ETERNULO .","Kaj faru tabuleton el pura oro, kaj gravuru sur ĝi en sigelila maniero: SANKTA AL LA ETERNULO ."],[28,37,"Kaj alfortikigu ĝin per laĉo el blua ŝtofo, ke ĝi estu sur la cidaro; sur la antaŭa flanko de la cidaro ĝi devas esti.","Kaj alfortikigu ĝin per laĉo el blua ŝtofo, ke ĝi estu sur la cidaro; sur la antaŭa flanko de la cidaro ĝi devas esti."],[28,38,"Ĝi estu sur la frunto de Aaron; kaj Aaron portados la pekon kontraŭ la sanktaĵoj, kiujn sanktigos la Izraelidoj en ĉiuj siaj sanktaj donoj; kaj ĝi estos sur lia frunto ĉiam, por ke la Eternulo ilin favoru.","Ĝi estu sur la frunto de Aaron; kaj Aaron portados la pekon kontraŭ la sanktaĵoj, kiujn sanktigos la Izraelidoj en ĉiuj siaj sanktaj donoj; kaj ĝi estos sur lia frunto ĉiam, por ke la Eternulo ilin favoru."],[28,39,"Kaj teksu la ĥitonon el bisino, kaj faru la cidaron el bisino, kaj faru broditan zonon.","Kaj teksu la ĥitonon el bisino, kaj faru la cidaron el bisino, kaj faru broditan zonon."],[28,40,"Kaj por la filoj de Aaron faru ĥitonojn, kaj faru por ili zonojn, kaj mitrojn faru por ili, por honoro kaj ornamo.","Kaj por la filoj de Aaron faru ĥitonojn, kaj faru por ili zonojn, kaj mitrojn faru por ili, por honoro kaj ornamo."],[28,41,"Kaj vestu per ili vian fraton Aaron kaj liajn filojn kune kun li; kaj sanktoleu ilin kaj konsekru ilin kaj sanktigu ilin, por ke ili estu pastroj al Mi.","Kaj vestu per ili vian fraton Aaron kaj liajn filojn kune kun li; kaj sanktoleu ilin kaj konsekru ilin kaj sanktigu ilin, por ke ili estu pastroj al Mi."],[28,42,"Kaj faru por ili linajn pantalonojn, por kovri la nudecon de ilia karno; de la lumbo ĝis la femuroj ili estu.","Kaj faru por ili linajn pantalonojn, por kovri la nudecon de ilia karno; de la lumbo ĝis la femuroj ili estu."],[28,43,"Kaj ili estu sur Aaron kaj sur liaj filoj, kiam ili eniros en la tabernaklon de kunveno, aŭ kiam ili alproksimiĝos al la altaro, por servi en la sanktejo; por ke ili ne faru pekon kaj ne mortu. Eterna leĝo ĝi estu por li kaj por lia idaro post li.","Kaj ili estu sur Aaron kaj sur liaj filoj, kiam ili eniros en la tabernaklon de kunveno, aŭ kiam ili alproksimiĝos al la altaro, por servi en la sanktejo; por ke ili ne faru pekon kaj ne mortu. Eterna leĝo ĝi estu por li kaj por lia idaro post li."],[29,1,"Kaj jen estas tio, kion vi devas fari al ili, por sanktigi ilin, ke ili estu pastroj al Mi: prenu unu virbovidon kaj du virŝafojn sendifektajn;","Kaj jen estas tio, kion vi devas fari al ili, por sanktigi ilin, ke ili estu pastroj al Mi: prenu unu virbovidon kaj du virŝafojn sendifektajn;"],[29,2,"kaj macan panon, kaj macajn kukojn, miksitajn kun oleo, kaj macajn flanojn, ŝmiritajn per oleo; el delikata tritika faruno faru ilin.","kaj macan panon, kaj macajn kukojn, miksitajn kun oleo, kaj macajn flanojn, ŝmiritajn per oleo; el delikata tritika faruno faru ilin."],[29,3,"Kaj metu ilin en unu korbon, kaj venigu ilin en la korbo, kaj ankaŭ la bovidon kaj la du virŝafojn.","Kaj metu ilin en unu korbon, kaj venigu ilin en la korbo, kaj ankaŭ la bovidon kaj la du virŝafojn."],[29,4,"Kaj Aaronon kaj liajn filojn alvenigu al la pordo de la tabernaklo de kunveno, kaj lavu ilin per akvo.","Kaj Aaronon kaj liajn filojn alvenigu al la pordo de la tabernaklo de kunveno, kaj lavu ilin per akvo."],[29,5,"Kaj prenu la vestojn, kaj metu sur Aaronon la ĥitonon kaj la tunikon de la efodo kaj la efodon kaj la surbrustaĵon, kaj zonu lin per la zono de la efodo.","Kaj prenu la vestojn, kaj metu sur Aaronon la ĥitonon kaj la tunikon de la efodo kaj la efodon kaj la surbrustaĵon, kaj zonu lin per la zono de la efodo."],[29,6,"Kaj metu la cidaron sur lian kapon, kaj metu la sanktan kronon sur la cidaron.","Kaj metu la cidaron sur lian kapon, kaj metu la sanktan kronon sur la cidaron."],[29,7,"Kaj prenu la oleon de sanktoleado, kaj verŝu sur lian kapon kaj sanktoleu lin.","Kaj prenu la oleon de sanktoleado, kaj verŝu sur lian kapon kaj sanktoleu lin."],[29,8,"Kaj liajn filojn alvenigu, kaj vestu ilin per la ĥitonoj.","Kaj liajn filojn alvenigu, kaj vestu ilin per la ĥitonoj."],[29,9,"Kaj zonu ilin per zono, Aaronon kaj liajn filojn, kaj alligu sur ili mitrojn, por ke al ili apartenu la pastreco laŭ eterna leĝo; kaj konsekru Aaronon kaj liajn filojn.","Kaj zonu ilin per zono, Aaronon kaj liajn filojn, kaj alligu sur ili mitrojn, por ke al ili apartenu la pastreco laŭ eterna leĝo; kaj konsekru Aaronon kaj liajn filojn."],[29,10,"Kaj alvenigu la bovidon antaŭ la tabernaklon de kunveno, kaj Aaron kaj liaj filoj metu siajn manojn sur la kapon de la bovido.","Kaj alvenigu la bovidon antaŭ la tabernaklon de kunveno, kaj Aaron kaj liaj filoj metu siajn manojn sur la kapon de la bovido."],[29,11,"Kaj buĉu la bovidon antaŭ la Eternulo, ĉe la pordo de la tabernaklo de kunveno.","Kaj buĉu la bovidon antaŭ la Eternulo, ĉe la pordo de la tabernaklo de kunveno."],[29,12,"Kaj prenu iom el la sango de la bovido kaj metu per viaj fingroj sur la kornojn de la altaro, kaj la tutan ceteran sangon elverŝu ĉe la bazo de la altaro.","Kaj prenu iom el la sango de la bovido kaj metu per viaj fingroj sur la kornojn de la altaro, kaj la tutan ceteran sangon elverŝu ĉe la bazo de la altaro."],[29,13,"Kaj prenu la tutan sebon, kiu kovras la internaĵon, kaj la reton de la hepato, kaj la du renojn, kaj la sebon, kiu estas sur ili, kaj incense bruligu ilin sur la altaro.","Kaj prenu la tutan sebon, kiu kovras la internaĵon, kaj la reton de la hepato, kaj la du renojn, kaj la sebon, kiu estas sur ili, kaj incense bruligu ilin sur la altaro."],[29,14,"Kaj la karnon de la bovido kaj ĝian felon kaj ĝian malpuraĵon forbruligu per fajro ekster la tendaro; ĝi estas pekofero.","Kaj la karnon de la bovido kaj ĝian felon kaj ĝian malpuraĵon forbruligu per fajro ekster la tendaro; ĝi estas pekofero."],[29,15,"Kaj unu virŝafon prenu, kaj Aaron kaj liaj filoj metu siajn manojn sur la kapon de la virŝafo.","Kaj unu virŝafon prenu, kaj Aaron kaj liaj filoj metu siajn manojn sur la kapon de la virŝafo."],[29,16,"Kaj buĉu la virŝafon, kaj prenu ĝian sangon kaj aspergu la altaron ĉirkaŭe.","Kaj buĉu la virŝafon, kaj prenu ĝian sangon kaj aspergu la altaron ĉirkaŭe."],[29,17,"Kaj la virŝafon dishaku en partojn, kaj lavu ĝian internaĵon kaj ĝiajn krurojn, kaj metu ilin sur ĝiajn partojn kaj sur ĝian kapon.","Kaj la virŝafon dishaku en partojn, kaj lavu ĝian internaĵon kaj ĝiajn krurojn, kaj metu ilin sur ĝiajn partojn kaj sur ĝian kapon."],[29,18,"Kaj forbruligu la tutan virŝafon sur la altaro; ĝi estas brulofero por la Eternulo; agrabla odoraĵo, fajrofero por la Eternulo ĝi estas.","Kaj forbruligu la tutan virŝafon sur la altaro; ĝi estas brulofero por la Eternulo; agrabla odoraĵo, fajrofero por la Eternulo ĝi estas."],[29,19,"Kaj prenu la duan virŝafon, kaj Aaron kaj liaj filoj metu siajn manojn sur la kapon de la virŝafo.","Kaj prenu la duan virŝafon, kaj Aaron kaj liaj filoj metu siajn manojn sur la kapon de la virŝafo."],[29,20,"Kaj buĉu la virŝafon, kaj prenu iom el ĝia sango kaj metu sur la malsupran randon de la dekstra orelo de Aaron kaj sur la malsupran randon de la dekstra orelo de liaj filoj kaj sur la dikan fingron de ilia dekstra mano kaj sur la dikan fingron de ilia dekstra piedo; kaj aspergu per la sango la altaron ĉirkaŭe.","Kaj buĉu la virŝafon, kaj prenu iom el ĝia sango kaj metu sur la malsupran randon de la dekstra orelo de Aaron kaj sur la malsupran randon de la dekstra orelo de liaj filoj kaj sur la dikan fingron de ilia dekstra mano kaj sur la dikan fingron de ilia dekstra piedo; kaj aspergu per la sango la altaron ĉirkaŭe."],[29,21,"Kaj prenu el la sango, kiu estos sur la altaro, kaj sanktan oleon, kaj aspergu Aaronon kaj liajn vestojn kaj liajn filojn kaj la vestojn de liaj filoj kune kun li; kaj sanktiĝos li kaj liaj vestoj kaj liaj filoj kaj la vestoj de liaj filoj kune kun li.","Kaj prenu el la sango, kiu estos sur la altaro, kaj sanktan oleon, kaj aspergu Aaronon kaj liajn vestojn kaj liajn filojn kaj la vestojn de liaj filoj kune kun li; kaj sanktiĝos li kaj liaj vestoj kaj liaj filoj kaj la vestoj de liaj filoj kune kun li."],[29,22,"Kaj prenu de la virŝafo la sebon kaj la voston, kaj la sebon, kiu kovras la internaĵon, kaj la reton de la hepato, kaj la du renojn, kaj la sebon, kiu estas sur ili, kaj la dekstran femuron, ĉar tio estas virŝafo de konsekrado;","Kaj prenu de la virŝafo la sebon kaj la voston, kaj la sebon, kiu kovras la internaĵon, kaj la reton de la hepato, kaj la du renojn, kaj la sebon, kiu estas sur ili, kaj la dekstran femuron, ĉar tio estas virŝafo de konsekrado;"],[29,23,"kaj unu bulon da pano kaj unu kukon kun oleo kaj unu flanon, el la korbo kun macoj, kiu staras antaŭ la Eternulo;","kaj unu bulon da pano kaj unu kukon kun oleo kaj unu flanon, el la korbo kun macoj, kiu staras antaŭ la Eternulo;"],[29,24,"kaj metu ĉion sur la manojn de Aaron kaj sur la manojn de liaj filoj, kaj skuu tion kiel skuoferon antaŭ la Eternulo.","kaj metu ĉion sur la manojn de Aaron kaj sur la manojn de liaj filoj, kaj skuu tion kiel skuoferon antaŭ la Eternulo."],[29,25,"Kaj prenu tion el iliaj manoj, kaj forbruligu ĝin sur la altaro kune kun la brulofero, kiel agrablan odoraĵon antaŭ la Eternulo; ĝi estas fajrofero por la Eternulo.","Kaj prenu tion el iliaj manoj, kaj forbruligu ĝin sur la altaro kune kun la brulofero, kiel agrablan odoraĵon antaŭ la Eternulo; ĝi estas fajrofero por la Eternulo."],[29,26,"Kaj prenu la brustaĵon de la virŝafo de konsekrado de Aaron, kaj skuu ĝin kiel skuoferon antaŭ la Eternulo; kaj tio estos via parto.","Kaj prenu la brustaĵon de la virŝafo de konsekrado de Aaron, kaj skuu ĝin kiel skuoferon antaŭ la Eternulo; kaj tio estos via parto."],[29,27,"Kaj sanktigu la brustaĵon de skuado kaj la femuron de levado, kiuj estis skuitaj kaj levitaj el la virŝafo de konsekrado de Aaron kaj de liaj filoj;","Kaj sanktigu la brustaĵon de skuado kaj la femuron de levado, kiuj estis skuitaj kaj levitaj el la virŝafo de konsekrado de Aaron kaj de liaj filoj;"],[29,28,"kaj tio estu por Aaron kaj por liaj filoj porĉiama destinitaĵo de la Izraelidoj; ĉar ĝi estas levofero, kaj levofero ĝi estu de la Izraelidoj, el iliaj pacoferoj ilia levofero al la Eternulo.","kaj tio estu por Aaron kaj por liaj filoj porĉiama destinitaĵo de la Izraelidoj; ĉar ĝi estas levofero, kaj levofero ĝi estu de la Izraelidoj, el iliaj pacoferoj ilia levofero al la Eternulo."],[29,29,"Kaj la sanktaj vestoj de Aaron estu por liaj filoj post li, por ke ili estu sanktoleataj en ili kaj por ke ili estu konsekrataj en ili.","Kaj la sanktaj vestoj de Aaron estu por liaj filoj post li, por ke ili estu sanktoleataj en ili kaj por ke ili estu konsekrataj en ili."],[29,30,"Dum sep tagoj portu ilin sur si tiu el liaj filoj, kiu estos pastro anstataŭ li, kaj kiu venos en la tabernaklon de kunveno, por servi en la sanktejo.","Dum sep tagoj portu ilin sur si tiu el liaj filoj, kiu estos pastro anstataŭ li, kaj kiu venos en la tabernaklon de kunveno, por servi en la sanktejo."],[29,31,"Kaj la virŝafon de konsekrado prenu, kaj kuiru ĝian viandon sur sankta loko.","Kaj la virŝafon de konsekrado prenu, kaj kuiru ĝian viandon sur sankta loko."],[29,32,"Kaj Aaron kaj liaj filoj manĝu la viandon de la virŝafo, kaj la panon, kiu estas en la korbo, ĉe la pordo de la tabernaklo de kunveno.","Kaj Aaron kaj liaj filoj manĝu la viandon de la virŝafo, kaj la panon, kiu estas en la korbo, ĉe la pordo de la tabernaklo de kunveno."],[29,33,"Kaj ili tion manĝu, ĉar per tio ili puriĝis, por ke ili estu konsekritaj kaj por ke ili estu sanktigitaj. Laiko tion ne manĝu, ĉar tio estas sankta.","Kaj ili tion manĝu, ĉar per tio ili puriĝis, por ke ili estu konsekritaj kaj por ke ili estu sanktigitaj. Laiko tion ne manĝu, ĉar tio estas sankta."],[29,34,"Se el la viando de konsekrado kaj el la pano restos iom ĝis la mateno, tiam forbruligu la restaĵon per fajro; ĝi ne estu manĝata, ĉar ĝi estas sankta.","Se el la viando de konsekrado kaj el la pano restos iom ĝis la mateno, tiam forbruligu la restaĵon per fajro; ĝi ne estu manĝata, ĉar ĝi estas sankta."],[29,35,"Kaj agu kun Aaron kaj kun liaj filoj tiel, kiel Mi ĉion ordonis al vi; dum sep tagoj konsekru ilin.","Kaj agu kun Aaron kaj kun liaj filoj tiel, kiel Mi ĉion ordonis al vi; dum sep tagoj konsekru ilin."],[29,36,"Kaj propekan bovidon oferu ĉiutage por senpekiĝo; kaj senpekigu la altaron, oferante sur ĝi, kaj oleu ĝin, por ĝin sanktigi.","Kaj propekan bovidon oferu ĉiutage por senpekiĝo; kaj senpekigu la altaron, oferante sur ĝi, kaj oleu ĝin, por ĝin sanktigi."],[29,37,"Dum sep tagoj senpekigu la altaron kaj sanktigu ĝin; kaj la altaro fariĝu plejsanktaĵo; ĉio, kio ektuŝos la altaron, fariĝos sankta.","Dum sep tagoj senpekigu la altaron kaj sanktigu ĝin; kaj la altaro fariĝu plejsanktaĵo; ĉio, kio ektuŝos la altaron, fariĝos sankta."],[29,38,"Jen tio, kion vi metos sur la altaron: du jaraĝajn ŝafidojn ĉiutage, ĉiam;","Jen tio, kion vi metos sur la altaron: du jaraĝajn ŝafidojn ĉiutage, ĉiam;"],[29,39,"unu ŝafidon oferu matene, kaj la duan ŝafidon oferu ĉirkaŭ la vespero;","unu ŝafidon oferu matene, kaj la duan ŝafidon oferu ĉirkaŭ la vespero;"],[29,40,"kaj por unu ŝafido dekonon de efo da delikata faruno, miksita kun kvarono de hino da elpistita oleo, kaj kvaronon de hino da vino por verŝoferi.","kaj por unu ŝafido dekonon de efo da delikata faruno, miksita kun kvarono de hino da elpistita oleo, kaj kvaronon de hino da vino por verŝoferi."],[29,41,"La duan ŝafidon oferu ĉirkaŭ la vespero; faru kun ĝi kiel kun la matena donofero kaj verŝofero, ke ĝi estu agrabla odoraĵo, fajrofero por la Eternulo,","La duan ŝafidon oferu ĉirkaŭ la vespero; faru kun ĝi kiel kun la matena donofero kaj verŝofero, ke ĝi estu agrabla odoraĵo, fajrofero por la Eternulo,"],[29,42,"ĉiama brulofero en viaj generacioj ĉe la pordo de la tabernaklo de kunveno antaŭ la Eternulo, kie Mi aperados antaŭ vi, por paroli tie kun vi.","ĉiama brulofero en viaj generacioj ĉe la pordo de la tabernaklo de kunveno antaŭ la Eternulo, kie Mi aperados antaŭ vi, por paroli tie kun vi."],[29,43,"Kaj Mi aperados tie antaŭ la Izraelidoj, kaj la loko sanktiĝos per Mia gloro.","Kaj Mi aperados tie antaŭ la Izraelidoj, kaj la loko sanktiĝos per Mia gloro."],[29,44,"Kaj Mi sanktigos la tabernaklon de kunveno kaj la altaron; kaj Aaronon kaj liajn filojn Mi sanktigos, por ke ili estu Miaj pastroj.","Kaj Mi sanktigos la tabernaklon de kunveno kaj la altaron; kaj Aaronon kaj liajn filojn Mi sanktigos, por ke ili estu Miaj pastroj."],[29,45,"Kaj Mi loĝos inter la Izraelidoj, kaj Mi estos por ili Dio.","Kaj Mi loĝos inter la Izraelidoj, kaj Mi estos por ili Dio."],[29,46,"Kaj ili sciu, ke Mi estas la Eternulo, ilia Dio, kiu elirigis ilin el la lando Egipta, por ke Mi loĝu inter ili, Mi, la Eternulo, ilia Dio.","Kaj ili sciu, ke Mi estas la Eternulo, ilia Dio, kiu elirigis ilin el la lando Egipta, por ke Mi loĝu inter ili, Mi, la Eternulo, ilia Dio."],[30,1,"Kaj faru altaron, por fumigi incenson; el akacia ligno faru ĝin.","Kaj faru altaron, por fumigi incenson; el akacia ligno faru ĝin."],[30,2,"Unu ulno estu ĝia longo, kaj unu ulno ĝia larĝo; ĝi estu kvarangula; kaj du ulnoj estu ĝia alto; kornoj elstaru el ĝi.","Unu ulno estu ĝia longo, kaj unu ulno ĝia larĝo; ĝi estu kvarangula; kaj du ulnoj estu ĝia alto; kornoj elstaru el ĝi."],[30,3,"Kaj tegu ĝin per pura oro, ĝian supran platon kaj ĝiajn flankojn ĉirkaŭe kaj ĝiajn kornojn; kaj faru al ĝi oran kronon ĉirkaŭe.","Kaj tegu ĝin per pura oro, ĝian supran platon kaj ĝiajn flankojn ĉirkaŭe kaj ĝiajn kornojn; kaj faru al ĝi oran kronon ĉirkaŭe."],[30,4,"Kaj du orajn ringojn faru al ĝi sub ĝia krono, sur ĝiaj du lateroj; sur du flankoj faru ilin; kaj ili estu ingoj por stangoj, per kiuj oni portu ĝin.","Kaj du orajn ringojn faru al ĝi sub ĝia krono, sur ĝiaj du lateroj; sur du flankoj faru ilin; kaj ili estu ingoj por stangoj, per kiuj oni portu ĝin."],[30,5,"Kaj faru la stangojn el akacia ligno, kaj tegu ilin per oro.","Kaj faru la stangojn el akacia ligno, kaj tegu ilin per oro."],[30,6,"Kaj starigu ĝin antaŭ la kurteno, kiu estas antaŭ la kesto de atesto, kontraŭ la fermoplato de la kesto de atesto, kie Mi aperados al vi.","Kaj starigu ĝin antaŭ la kurteno, kiu estas antaŭ la kesto de atesto, kontraŭ la fermoplato de la kesto de atesto, kie Mi aperados al vi."],[30,7,"Kaj Aaron incensadu sur ĝi aroman incenson; ĉiumatene, kiam li ordigos la lucernojn, li incensu.","Kaj Aaron incensadu sur ĝi aroman incenson; ĉiumatene, kiam li ordigos la lucernojn, li incensu."],[30,8,"Kaj kiam Aaron ekbruligos la lucernojn ĉirkaŭ vespero, li incensu; ĝi estu ĉiama incensado antaŭ la Eternulo en viaj generacioj.","Kaj kiam Aaron ekbruligos la lucernojn ĉirkaŭ vespero, li incensu; ĝi estu ĉiama incensado antaŭ la Eternulo en viaj generacioj."],[30,9,"Ne alportu sur ĝi incenson alian, nek bruloferon nek donoferon, kaj verŝoferon ne verŝu sur ĝin.","Ne alportu sur ĝi incenson alian, nek bruloferon nek donoferon, kaj verŝoferon ne verŝu sur ĝin."],[30,10,"Kaj ĉiopardonan oferon Aaron alportos sur ĝiaj kornoj unu fojon en la jaro; el la sango de la ĉiopardona pekofero unu fojon en jaro li alportu sur ĝi ĉiopardonan oferon en viaj generacioj; tio estos plej granda sanktaĵo antaŭ la Eternulo.","Kaj ĉiopardonan oferon Aaron alportos sur ĝiaj kornoj unu fojon en la jaro; el la sango de la ĉiopardona pekofero unu fojon en jaro li alportu sur ĝi ĉiopardonan oferon en viaj generacioj; tio estos plej granda sanktaĵo antaŭ la Eternulo."],[30,11,"Kaj la Eternulo ekparolis al Moseo, dirante:","Kaj la Eternulo ekparolis al Moseo, dirante:"],[30,12,"Kiam vi kalkulos la kapojn de la Izraelidoj, tiam ĉiu donu liberigan pagon por sia animo al la Eternulo, kiam ili estos kalkulataj; kaj tiam ne estos inter ili epidemio dum la kalkulado.","Kiam vi kalkulos la kapojn de la Izraelidoj, tiam ĉiu donu liberigan pagon por sia animo al la Eternulo, kiam ili estos kalkulataj; kaj tiam ne estos inter ili epidemio dum la kalkulado."],[30,13,"Jen kion devas doni ĉiu, kiu pasas la kalkulon: duonon de siklo laŭ la grandeco de la sankta siklo (siklo enhavas dudek gerojn); duono de siklo estu oferdono por la Eternulo.","Jen kion devas doni ĉiu, kiu pasas la kalkulon: duonon de siklo laŭ la grandeco de la sankta siklo (siklo enhavas dudek gerojn); duono de siklo estu oferdono por la Eternulo."],[30,14,"Ĉiu, kiu pasas la kalkulon, de la aĝo de dudek jaroj kaj pli, devas doni la oferdonon al la Eternulo.","Ĉiu, kiu pasas la kalkulon, de la aĝo de dudek jaroj kaj pli, devas doni la oferdonon al la Eternulo."],[30,15,"La riĉulo ne donu pli kaj la malriĉulo ne donu malpli ol duonon de siklo, donante la oferdonon por la Eternulo, por liberigi viajn animojn.","La riĉulo ne donu pli kaj la malriĉulo ne donu malpli ol duonon de siklo, donante la oferdonon por la Eternulo, por liberigi viajn animojn."],[30,16,"Kaj prenu la monon de la liberigo de la Izraelidoj kaj uzu ĝin por la servado en la tabernaklo de kunveno, kaj tio estos por la Izraelidoj kiel memorigaĵo antaŭ la Eternulo, por liberigi viajn animojn.","Kaj prenu la monon de la liberigo de la Izraelidoj kaj uzu ĝin por la servado en la tabernaklo de kunveno, kaj tio estos por la Izraelidoj kiel memorigaĵo antaŭ la Eternulo, por liberigi viajn animojn."],[30,17,"Kaj la Eternulo ekparolis al Moseo, dirante:","Kaj la Eternulo ekparolis al Moseo, dirante:"],[30,18,"Faru kupran lavujon kun kupra piedestalo, por lavado; kaj starigu ĝin inter la tabernaklo de kunveno kaj la altaro, kaj enverŝu tien akvon.","Faru kupran lavujon kun kupra piedestalo, por lavado; kaj starigu ĝin inter la tabernaklo de kunveno kaj la altaro, kaj enverŝu tien akvon."],[30,19,"Kaj Aaron kaj liaj filoj lavu per ĝi siajn manojn kaj piedojn:","Kaj Aaron kaj liaj filoj lavu per ĝi siajn manojn kaj piedojn:"],[30,20,"kiam ili iros en la tabernaklon de kunveno, ili lavu sin per akvo, por ke ili ne mortu; aŭ kiam ili alproksimiĝos al la altaro, por servi, por incensi fajroferon al la Eternulo,","kiam ili iros en la tabernaklon de kunveno, ili lavu sin per akvo, por ke ili ne mortu; aŭ kiam ili alproksimiĝos al la altaro, por servi, por incensi fajroferon al la Eternulo,"],[30,21,"ili lavu siajn manojn kaj piedojn, por ke ili ne mortu; kaj tio estu por ili leĝo eterna, por li kaj por lia idaro en iliaj generacioj.","ili lavu siajn manojn kaj piedojn, por ke ili ne mortu; kaj tio estu por ili leĝo eterna, por li kaj por lia idaro en iliaj generacioj."],[30,22,"Plue la Eternulo ekparolis al Moseo, dirante:","Plue la Eternulo ekparolis al Moseo, dirante:"],[30,23,"Prenu al vi plej bonajn aromaĵojn: da bonodora mirho kvincent siklojn, kaj da aroma cinamo duonon de tio, ducent kvindek, kaj da aroma kano ducent kvindek,","Prenu al vi plej bonajn aromaĵojn: da bonodora mirho kvincent siklojn, kaj da aroma cinamo duonon de tio, ducent kvindek, kaj da aroma kano ducent kvindek,"],[30,24,"kaj da kasio kvincent siklojn laŭ la mezuro de la sankta siklo, kaj da olivoleo unu hinon.","kaj da kasio kvincent siklojn laŭ la mezuro de la sankta siklo, kaj da olivoleo unu hinon."],[30,25,"Kaj faru el tio oleon por sanktoleado, kunmetitan ŝmiraĵon laŭ la arto de la ŝmiraĵisto; ĝi estu oleo por sanktoleado.","Kaj faru el tio oleon por sanktoleado, kunmetitan ŝmiraĵon laŭ la arto de la ŝmiraĵisto; ĝi estu oleo por sanktoleado."],[30,26,"Kaj sanktoleu per ĝi la tabernaklon de kunveno kaj la keston de atesto,","Kaj sanktoleu per ĝi la tabernaklon de kunveno kaj la keston de atesto,"],[30,27,"kaj la tablon kaj ĉiujn ĝiajn apartenaĵojn, kaj la kandelabron kaj ĝiajn apartenaĵojn, kaj la altaron de incensado,","kaj la tablon kaj ĉiujn ĝiajn apartenaĵojn, kaj la kandelabron kaj ĝiajn apartenaĵojn, kaj la altaron de incensado,"],[30,28,"kaj la altaron de bruloferoj kaj ĉiujn ĝiajn apartenaĵojn, kaj la lavujon kaj ĝian piedestalon.","kaj la altaron de bruloferoj kaj ĉiujn ĝiajn apartenaĵojn, kaj la lavujon kaj ĝian piedestalon."],[30,29,"Kaj sanktigu ilin, ke ili fariĝu plejsanktaĵo; ĉiu, kiu ektuŝos ilin, sanktiĝos.","Kaj sanktigu ilin, ke ili fariĝu plejsanktaĵo; ĉiu, kiu ektuŝos ilin, sanktiĝos."],[30,30,"Kaj Aaronon kaj liajn filojn sanktoleu, kaj sanktigu ilin, ke ili estu Miaj pastroj.","Kaj Aaronon kaj liajn filojn sanktoleu, kaj sanktigu ilin, ke ili estu Miaj pastroj."],[30,31,"Kaj al la Izraelidoj diru jene: Tio estu por Mi oleo de sanktoleado en viaj generacioj.","Kaj al la Izraelidoj diru jene: Tio estu por Mi oleo de sanktoleado en viaj generacioj."],[30,32,"Sur homan karnon ĝi ne estu verŝata, kaj laŭ ĝia konsisto ne faru ion similan; ĝi estas sankta, ĝi estu sankta por vi.","Sur homan karnon ĝi ne estu verŝata, kaj laŭ ĝia konsisto ne faru ion similan; ĝi estas sankta, ĝi estu sankta por vi."],[30,33,"Se iu konsistigos ion similan kaj ŝmiros per ĝi laikon, li ekstermiĝu el sia popolo.","Se iu konsistigos ion similan kaj ŝmiros per ĝi laikon, li ekstermiĝu el sia popolo."],[30,34,"Kaj la Eternulo diris al Moseo: Prenu al vi aromaĵon: balzamon kaj stakton kaj galbanon bonodoran kaj puran olibanon, po egalaj partoj el ĉio;","Kaj la Eternulo diris al Moseo: Prenu al vi aromaĵon: balzamon kaj stakton kaj galbanon bonodoran kaj puran olibanon, po egalaj partoj el ĉio;"],[30,35,"kaj faru el tio incensaĵon kunmetitan laŭ la arto de la ŝmiraĵisto, bone frotmiksitan, puran, sanktan.","kaj faru el tio incensaĵon kunmetitan laŭ la arto de la ŝmiraĵisto, bone frotmiksitan, puran, sanktan."],[30,36,"Kaj pistu el tio subtilan pulvoron, kaj metu iom el ĝi antaŭ la keston de atesto en la tabernaklo de kunveno, kie Mi aperados al vi; plejsanktaĵo ĝi estu por vi.","Kaj pistu el tio subtilan pulvoron, kaj metu iom el ĝi antaŭ la keston de atesto en la tabernaklo de kunveno, kie Mi aperados al vi; plejsanktaĵo ĝi estu por vi."],[30,37,"Kaj laŭ la incensaĵo, kiun vi faros, ne faru al vi alian similan; sankta ĝi estu al vi por la Eternulo.","Kaj laŭ la incensaĵo, kiun vi faros, ne faru al vi alian similan; sankta ĝi estu al vi por la Eternulo."],[30,38,"Se iu faros ion similan, por odorigi per ĝi, li ekstermiĝos el sia popolo.","Se iu faros ion similan, por odorigi per ĝi, li ekstermiĝos el sia popolo."],[31,1,"Kaj la Eternulo ekparolis al Moseo, dirante:","Kaj la Eternulo ekparolis al Moseo, dirante:"],[31,2,"Jen, Mi vokis per la nomo Becalelon, filon de Uri, filo de Ĥur, el la tribo de Jehuda;","Jen, Mi vokis per la nomo Becalelon, filon de Uri, filo de Ĥur, el la tribo de Jehuda;"],[31,3,"kaj Mi plenigis lin per Dia spirito, per saĝo kaj prudento kaj scio kaj ĉia arto,","kaj Mi plenigis lin per Dia spirito, per saĝo kaj prudento kaj scio kaj ĉia arto,"],[31,4,"por pripensi ideojn, por labori el oro kaj el arĝento kaj el kupro,","por pripensi ideojn, por labori el oro kaj el arĝento kaj el kupro,"],[31,5,"kaj por ĉizi ŝtonojn por enkadrigo, kaj por ĉizi lignon, por fari ĉian laboron.","kaj por ĉizi ŝtonojn por enkadrigo, kaj por ĉizi lignon, por fari ĉian laboron."],[31,6,"Kaj jen Mi donis al li kiel helpanton Oholiabon, filon de Aĥisamaĥ, el la tribo de Dan; kaj en la koron de ĉiu kompetentulo Mi enmetis saĝon, por ke ili faru ĉion, kion Mi ordonis al vi:","Kaj jen Mi donis al li kiel helpanton Oholiabon, filon de Aĥisamaĥ, el la tribo de Dan; kaj en la koron de ĉiu kompetentulo Mi enmetis saĝon, por ke ili faru ĉion, kion Mi ordonis al vi:"],[31,7,"la tabernaklon de kunveno kaj la keston de atesto kaj la fermoplaton sur ĝi kaj ĉiujn apartenaĵojn de la tabernaklo,","la tabernaklon de kunveno kaj la keston de atesto kaj la fermoplaton sur ĝi kaj ĉiujn apartenaĵojn de la tabernaklo,"],[31,8,"kaj la tablon kaj ĝiajn apartenaĵojn kaj la puran kandelabron kaj ĉiujn ĝiajn apartenaĵojn kaj la altaron de incensado,","kaj la tablon kaj ĝiajn apartenaĵojn kaj la puran kandelabron kaj ĉiujn ĝiajn apartenaĵojn kaj la altaron de incensado,"],[31,9,"kaj la altaron de bruloferoj kaj ĉiujn ĝiajn apartenaĵojn kaj la lavujon kaj ĝian piedestalon,","kaj la altaron de bruloferoj kaj ĉiujn ĝiajn apartenaĵojn kaj la lavujon kaj ĝian piedestalon,"],[31,10,"kaj la oficajn vestojn kaj la sanktajn vestojn por la pastro Aaron kaj la pastrajn vestojn de liaj filoj,","kaj la oficajn vestojn kaj la sanktajn vestojn por la pastro Aaron kaj la pastrajn vestojn de liaj filoj,"],[31,11,"kaj la sanktan oleon kaj la aroman incensaĵon por la sanktejo; ĉion konforme al tio, kiel Mi ordonis al vi, ili faros.","kaj la sanktan oleon kaj la aroman incensaĵon por la sanktejo; ĉion konforme al tio, kiel Mi ordonis al vi, ili faros."],[31,12,"Kaj la Eternulo ekparolis al Moseo, dirante:","Kaj la Eternulo ekparolis al Moseo, dirante:"],[31,13,"Diru al la Izraelidoj jene: Nepre observu Miajn sabatojn; ĉar tio estas signo inter Mi kaj vi en viaj generacioj, por ke vi sciu, ke Mi estas la Eternulo, kiu vin sanktigas.","Diru al la Izraelidoj jene: Nepre observu Miajn sabatojn; ĉar tio estas signo inter Mi kaj vi en viaj generacioj, por ke vi sciu, ke Mi estas la Eternulo, kiu vin sanktigas."],[31,14,"Kaj observu la sabaton, ĉar ĝi estas sankta por vi; kiu ĝin malsanktigos, tiu mortu; ĉar se iu faros en ĝi laboron, tiu animo ekstermiĝu el la mezo de sia popolo.","Kaj observu la sabaton, ĉar ĝi estas sankta por vi; kiu ĝin malsanktigos, tiu mortu; ĉar se iu faros en ĝi laboron, tiu animo ekstermiĝu el la mezo de sia popolo."],[31,15,"Dum ses tagoj oni faru laboron, sed la sepan tagon estas sabato de ripozo, sankta por la Eternulo; ĉiu, kiu faros laboron en la tago sabata, estu mortigita.","Dum ses tagoj oni faru laboron, sed la sepan tagon estas sabato de ripozo, sankta por la Eternulo; ĉiu, kiu faros laboron en la tago sabata, estu mortigita."],[31,16,"Kaj la Izraelidoj observu la sabaton, por fari la sabaton en siaj generacioj eterna interligo.","Kaj la Izraelidoj observu la sabaton, por fari la sabaton en siaj generacioj eterna interligo."],[31,17,"Inter Mi kaj la Izraelidoj ĝi estu signo por ĉiam; ĉar dum ses tagoj la Eternulo faris la ĉielon kaj la teron, sed en la sepa tago Li ĉesis kaj ripozis.","Inter Mi kaj la Izraelidoj ĝi estu signo por ĉiam; ĉar dum ses tagoj la Eternulo faris la ĉielon kaj la teron, sed en la sepa tago Li ĉesis kaj ripozis."],[31,18,"Kaj, fininte paroli al li sur la monto Sinaj, la Eternulo donis al Moseo du tabelojn de atesto, tabelojn ŝtonajn, skribitajn per la fingro de Dio.","Kaj, fininte paroli al li sur la monto Sinaj, la Eternulo donis al Moseo du tabelojn de atesto, tabelojn ŝtonajn, skribitajn per la fingro de Dio."],[32,1,"Kiam la popolo vidis, ke Moseo longe ne malsuprenvenas de la monto, la popolo kolektiĝis antaŭ Aaron, kaj diris al li: Leviĝu, faru al ni diojn, kiuj irus antaŭ ni; ĉar pri tiu Moseo, la viro, kiu elkondukis nin el la lando Egipta, ni ne scias, kio fariĝis kun li.","Kiam la popolo vidis, ke Moseo longe ne malsuprenvenas de la monto, la popolo kolektiĝis antaŭ Aaron, kaj diris al li: Leviĝu, faru al ni diojn, kiuj irus antaŭ ni; ĉar pri tiu Moseo, la viro, kiu elkondukis nin el la lando Egipta, ni ne scias, kio fariĝis kun li."],[32,2,"Tiam diris al ili Aaron: Elprenu la orajn orelringojn, kiuj estas en la oreloj de viaj edzinoj, de viaj filoj, kaj de viaj filinoj, kaj alportu al mi.","Tiam diris al ili Aaron: Elprenu la orajn orelringojn, kiuj estas en la oreloj de viaj edzinoj, de viaj filoj, kaj de viaj filinoj, kaj alportu al mi."],[32,3,"Kaj la tuta popolo elprenis la orajn orelringojn, kiuj estis en iliaj oreloj, kaj alportis al Aaron.","Kaj la tuta popolo elprenis la orajn orelringojn, kiuj estis en iliaj oreloj, kaj alportis al Aaron."],[32,4,"Kaj li prenis tion el iliaj manoj kaj formis ĝin per ĉizilo kaj faris el ĝi fanditan bovidon. Kaj ili diris: Jen estas viaj dioj, ho Izrael, kiuj elirigis vin el la lando Egipta.","Kaj li prenis tion el iliaj manoj kaj formis ĝin per ĉizilo kaj faris el ĝi fanditan bovidon. Kaj ili diris: Jen estas viaj dioj, ho Izrael, kiuj elirigis vin el la lando Egipta."],[32,5,"Kiam Aaron tion vidis, li konstruis altaron antaŭ ĝi; kaj Aaron proklamis kaj diris: Morgaŭ estos festo de la Eternulo.","Kiam Aaron tion vidis, li konstruis altaron antaŭ ĝi; kaj Aaron proklamis kaj diris: Morgaŭ estos festo de la Eternulo."],[32,6,"Kaj ili leviĝis frue la sekvantan tagon kaj oferis bruloferojn kaj alportis pacoferojn; kaj la popolo sidiĝis, por manĝi kaj trinki, kaj ili leviĝis, por ludi.","Kaj ili leviĝis frue la sekvantan tagon kaj oferis bruloferojn kaj alportis pacoferojn; kaj la popolo sidiĝis, por manĝi kaj trinki, kaj ili leviĝis, por ludi."],[32,7,"Tiam la Eternulo diris al Moseo: Iru, iru malsupren; ĉar malvirtiĝis via popolo, kiun vi elkondukis el la lando Egipta.","Tiam la Eternulo diris al Moseo: Iru, iru malsupren; ĉar malvirtiĝis via popolo, kiun vi elkondukis el la lando Egipta."],[32,8,"Rapide ili forflankiĝis de la vojo, kiun Mi ordonis al ili; ili faris al si fanditan bovidon kaj adorkliniĝis al ĝi kaj alportis al ĝi oferojn, kaj diris: Jen estas viaj dioj, ho Izrael, kiuj elirigis vin el la lando Egipta.","Rapide ili forflankiĝis de la vojo, kiun Mi ordonis al ili; ili faris al si fanditan bovidon kaj adorkliniĝis al ĝi kaj alportis al ĝi oferojn, kaj diris: Jen estas viaj dioj, ho Izrael, kiuj elirigis vin el la lando Egipta."],[32,9,"Kaj la Eternulo diris al Moseo: Mi vidas ĉi tiun popolon, ĝi estas popolo malmolnuka.","Kaj la Eternulo diris al Moseo: Mi vidas ĉi tiun popolon, ĝi estas popolo malmolnuka."],[32,10,"Lasu do Min, kaj ekflamos Mia kolero kontraŭ ilin, kaj Mi ilin ekstermos, kaj Mi faros vin granda popolo.","Lasu do Min, kaj ekflamos Mia kolero kontraŭ ilin, kaj Mi ilin ekstermos, kaj Mi faros vin granda popolo."],[32,11,"Sed Moseo ekpetegis la Eternulon, sian Dion, kaj diris: Por kio, ho Eternulo, Via kolero estas ekflamonta kontraŭ Vian popolon, kiun Vi elirigis el la lando Egipta per granda forto kaj per potenca mano?","Sed Moseo ekpetegis la Eternulon, sian Dion, kaj diris: Por kio, ho Eternulo, Via kolero estas ekflamonta kontraŭ Vian popolon, kiun Vi elirigis el la lando Egipta per granda forto kaj per potenca mano?"],[32,12,"Por kio la Egiptoj diru: Por malbono Li elirigis ilin, por mortigi ilin en la montoj kaj por ekstermi ilin de sur la tero? Forlasu Vian flaman koleron kaj fordecidu la malbonon kontraŭ Via popolo.","Por kio la Egiptoj diru: Por malbono Li elirigis ilin, por mortigi ilin en la montoj kaj por ekstermi ilin de sur la tero? Forlasu Vian flaman koleron kaj fordecidu la malbonon kontraŭ Via popolo."],[32,13,"Rememoru Abrahamon, Isaakon, kaj Izraelon, Viajn sklavojn, al kiuj Vi ĵuris per Vi, kaj al kiuj Vi diris: Mi multigos vian semon kiel la steloj de la ĉielo, kaj la tutan tiun landon, pri kiu Mi parolis, Mi donos al viaj idoj, kaj ili posedos ĝin eterne.","Rememoru Abrahamon, Isaakon, kaj Izraelon, Viajn sklavojn, al kiuj Vi ĵuris per Vi, kaj al kiuj Vi diris: Mi multigos vian semon kiel la steloj de la ĉielo, kaj la tutan tiun landon, pri kiu Mi parolis, Mi donos al viaj idoj, kaj ili posedos ĝin eterne."],[32,14,"Kaj la Eternulo fordecidis la malbonon, pri kiu Li diris, ke Li faros ĝin al Sia popolo.","Kaj la Eternulo fordecidis la malbonon, pri kiu Li diris, ke Li faros ĝin al Sia popolo."],[32,15,"Moseo sin returnis kaj malsupreniris de la monto, kaj la du tabeloj de atesto estis en liaj manoj, tabeloj, sur kiuj estis skribite ambaŭflanke; sur unu flanko kaj sur la alia estis skribite sur ili.","Moseo sin returnis kaj malsupreniris de la monto, kaj la du tabeloj de atesto estis en liaj manoj, tabeloj, sur kiuj estis skribite ambaŭflanke; sur unu flanko kaj sur la alia estis skribite sur ili."],[32,16,"Kaj la tabeloj estis faritaĵo de Dio, kaj la skribo estis skribo de Dio, gravurita sur la tabeloj.","Kaj la tabeloj estis faritaĵo de Dio, kaj la skribo estis skribo de Dio, gravurita sur la tabeloj."],[32,17,"Kaj Josuo aŭdis la bruon de la popolo ĝojkrianta, kaj li diris al Moseo: Bruo de batalo estas en la tendaro.","Kaj Josuo aŭdis la bruon de la popolo ĝojkrianta, kaj li diris al Moseo: Bruo de batalo estas en la tendaro."],[32,18,"Sed tiu diris: Tio ne estas kriado de venko, nek kriado de malvenko, sed bruon de kantantoj mi aŭdas.","Sed tiu diris: Tio ne estas kriado de venko, nek kriado de malvenko, sed bruon de kantantoj mi aŭdas."],[32,19,"Kiam li alproksimiĝis al la tendaro kaj ekvidis la bovidon kaj la dancadon, tiam ekflamis la kolero de Moseo, kaj li forĵetis el siaj manoj la tabelojn kaj disrompis ilin sub la monto.","Kiam li alproksimiĝis al la tendaro kaj ekvidis la bovidon kaj la dancadon, tiam ekflamis la kolero de Moseo, kaj li forĵetis el siaj manoj la tabelojn kaj disrompis ilin sub la monto."],[32,20,"Kaj li prenis la bovidon, kiun ili faris, kaj disbruligis ĝin per fajro kaj disfrakasis ĝis pulvoreco kaj disŝutis sur akvo kaj trinkigis ĝin al la Izraelidoj.","Kaj li prenis la bovidon, kiun ili faris, kaj disbruligis ĝin per fajro kaj disfrakasis ĝis pulvoreco kaj disŝutis sur akvo kaj trinkigis ĝin al la Izraelidoj."],[32,21,"Kaj Moseo diris al Aaron: Kion faris al vi ĉi tiu poplo, ke vi venigis sur ĝin grandan pekon?","Kaj Moseo diris al Aaron: Kion faris al vi ĉi tiu poplo, ke vi venigis sur ĝin grandan pekon?"],[32,22,"Kaj Aaron diris: Ne ekflamu la kolero de mia sinjoro; vi scias, ke la popolo havas inklinon al malbono;","Kaj Aaron diris: Ne ekflamu la kolero de mia sinjoro; vi scias, ke la popolo havas inklinon al malbono;"],[32,23,"ili diris al mi: Faru al ni diojn, kiuj irus antaŭ ni; ĉar pri tiu Moseo, la viro, kiu elkondukis nin el la lando Egipta, ni ne scias, kio fariĝis kun li.","ili diris al mi: Faru al ni diojn, kiuj irus antaŭ ni; ĉar pri tiu Moseo, la viro, kiu elkondukis nin el la lando Egipta, ni ne scias, kio fariĝis kun li."],[32,24,"Kaj mi diris al ili: Kiu havas oron, tiu deprenu ĝin; kaj ili donis al mi, kaj mi ĵetis ĝin en fajron, kaj eliris ĉi tiu bovido.","Kaj mi diris al ili: Kiu havas oron, tiu deprenu ĝin; kaj ili donis al mi, kaj mi ĵetis ĝin en fajron, kaj eliris ĉi tiu bovido."],[32,25,"Ĉar Moseo vidis, ke la popolo estas sendisciplina, ĉar Aaron sendisciplinigis ĝin ĝis honto antaŭ la malamikoj,","Ĉar Moseo vidis, ke la popolo estas sendisciplina, ĉar Aaron sendisciplinigis ĝin ĝis honto antaŭ la malamikoj,"],[32,26,"tial Moseo stariĝis ĉe la pordego de la tendaro, kaj diris: Kiu estas partiano de la Eternulo, tiu venu al mi. Kaj kolektiĝis al li ĉiuj idoj de Levi.","tial Moseo stariĝis ĉe la pordego de la tendaro, kaj diris: Kiu estas partiano de la Eternulo, tiu venu al mi. Kaj kolektiĝis al li ĉiuj idoj de Levi."],[32,27,"Kaj li diris al ili: Tiel diris la Eternulo, la Dio de Izrael: Metu ĉiu sian glavon sur sian femuron, trairu tien kaj reen de pordego ĝis pordego tra la tendaro, kaj ĉiu mortigu sian fraton, sian amikon, sian proksimulon.","Kaj li diris al ili: Tiel diris la Eternulo, la Dio de Izrael: Metu ĉiu sian glavon sur sian femuron, trairu tien kaj reen de pordego ĝis pordego tra la tendaro, kaj ĉiu mortigu sian fraton, sian amikon, sian proksimulon."],[32,28,"Kaj la idoj de Levi faris, kiel diris Moseo; kaj estis mortigitaj el la popolo en tiu tago ĉirkaŭ tri mil homoj.","Kaj la idoj de Levi faris, kiel diris Moseo; kaj estis mortigitaj el la popolo en tiu tago ĉirkaŭ tri mil homoj."],[32,29,"Kaj Moseo diris: Konsekru vin hodiaŭ al la Eternulo, ĉiu sur sia filo kaj sur sia frato, por ke estu donata al vi hodiaŭ beno.","Kaj Moseo diris: Konsekru vin hodiaŭ al la Eternulo, ĉiu sur sia filo kaj sur sia frato, por ke estu donata al vi hodiaŭ beno."],[32,30,"La sekvantan tagon Moseo diris al la popolo: Vi pekis per granda peko; nun mi supreniros al la Eternulo, eble mi akiros pardonon por via peko.","La sekvantan tagon Moseo diris al la popolo: Vi pekis per granda peko; nun mi supreniros al la Eternulo, eble mi akiros pardonon por via peko."],[32,31,"Kaj Moseo revenis al la Eternulo, kaj diris: Ho ve! tiu popolo pekis per granda peko kaj faris al si orajn diojn;","Kaj Moseo revenis al la Eternulo, kaj diris: Ho ve! tiu popolo pekis per granda peko kaj faris al si orajn diojn;"],[32,32,"nun volu pardoni ilian pekon; kaj se ne, tiam volu elstreki min el Via libro, kiun Vi skribis.","nun volu pardoni ilian pekon; kaj se ne, tiam volu elstreki min el Via libro, kiun Vi skribis."],[32,33,"Sed la Eternulo diris al Moseo; Kiu ajn pekis antaŭ Mi, tiun Mi elstrekos el Mia libro.","Sed la Eternulo diris al Moseo; Kiu ajn pekis antaŭ Mi, tiun Mi elstrekos el Mia libro."],[32,34,"Kaj nun iru, konduku la popolon tien, kien Mi diris al vi. Jen Mia anĝelo iros antaŭ vi; kaj en la tago de Mia rememorigado Mi rememorigos sur ili ilian pekon.","Kaj nun iru, konduku la popolon tien, kien Mi diris al vi. Jen Mia anĝelo iros antaŭ vi; kaj en la tago de Mia rememorigado Mi rememorigos sur ili ilian pekon."],[32,35,"Kaj la Eternulo frapis la popolon pro tio, ke ili faris la bovidon, kiun faris Aaron.","Kaj la Eternulo frapis la popolon pro tio, ke ili faris la bovidon, kiun faris Aaron."],[33,1,"Kaj la Eternulo diris al Moseo: Iru, eliru el ĉi tie, vi kaj la popolo, kiun vi elkondukis el la lando Egipta, al la lando, pri kiu Mi ĵuris al Abraham, al Isaak, kaj al Jakob, dirante: Al via idaro Mi ĝin donos.","Kaj la Eternulo diris al Moseo: Iru, eliru el ĉi tie, vi kaj la popolo, kiun vi elkondukis el la lando Egipta, al la lando, pri kiu Mi ĵuris al Abraham, al Isaak, kaj al Jakob, dirante: Al via idaro Mi ĝin donos."],[33,2,"Kaj Mi sendos antaŭ vi anĝelon, kaj Mi forpelos la Kanaanidojn, la Amoridojn kaj la Ĥetidojn kaj la Perizidojn, la Ĥividojn kaj la Jebusidojn.","Kaj Mi sendos antaŭ vi anĝelon, kaj Mi forpelos la Kanaanidojn, la Amoridojn kaj la Ĥetidojn kaj la Perizidojn, la Ĥividojn kaj la Jebusidojn."],[33,3,"Iru al lando, en kiu fluas lakto kaj mielo. Mi ne iros meze de vi; ĉar vi estas popolo malmolnuka, kaj Mi eble ekstermus vin dum la vojo.","Iru al lando, en kiu fluas lakto kaj mielo. Mi ne iros meze de vi; ĉar vi estas popolo malmolnuka, kaj Mi eble ekstermus vin dum la vojo."],[33,4,"Kaj la popolo aŭdis tiun malbonan sciigon, kaj ili ekfunebris, kaj neniu metis sur sin siajn ornamaĵojn.","Kaj la popolo aŭdis tiun malbonan sciigon, kaj ili ekfunebris, kaj neniu metis sur sin siajn ornamaĵojn."],[33,5,"Kaj la Eternulo diris al Moseo: Diru al la Izraelidoj: Vi estas popolo malmolnuka; se Mi nur unu momenton irus meze de vi, Mi vin ekstermus; nun demetu de vi viajn ornamaĵojn, kaj Mi rigardos, kion Mi faru kun vi.","Kaj la Eternulo diris al Moseo: Diru al la Izraelidoj: Vi estas popolo malmolnuka; se Mi nur unu momenton irus meze de vi, Mi vin ekstermus; nun demetu de vi viajn ornamaĵojn, kaj Mi rigardos, kion Mi faru kun vi."],[33,6,"Kaj la Izraelidoj demetis de si siajn ornamaĵojn antaŭ la monto Ĥoreb.","Kaj la Izraelidoj demetis de si siajn ornamaĵojn antaŭ la monto Ĥoreb."],[33,7,"Moseo prenis la tabernaklon, kaj starigis ĝin ekster la tendaro, malproksime de la tendaro, kaj nomis ĝin Tabernaklo de Kunveno; kaj ĉiu, kiu volis peti la Eternulon, devis eliri al la tabernaklo de kunveno, kiu estis ekstere de la tendaro.","Moseo prenis la tabernaklon, kaj starigis ĝin ekster la tendaro, malproksime de la tendaro, kaj nomis ĝin Tabernaklo de Kunveno; kaj ĉiu, kiu volis peti la Eternulon, devis eliri al la tabernaklo de kunveno, kiu estis ekstere de la tendaro."],[33,8,"Kaj kiam Moseo eliradis al la tabernaklo, la tuta popolo leviĝadis, kaj ĉiu stariĝadis ĉe la pordo de sia tendo kaj rigardadis post Moseo, ĝis li eniris en la tabernaklon.","Kaj kiam Moseo eliradis al la tabernaklo, la tuta popolo leviĝadis, kaj ĉiu stariĝadis ĉe la pordo de sia tendo kaj rigardadis post Moseo, ĝis li eniris en la tabernaklon."],[33,9,"Kaj kiam Moseo eniradis en la tabernaklon, malleviĝadis nuba kolono kaj stariĝadis ĉe la pordo de la tabernaklo kaj paroladis kun Moseo.","Kaj kiam Moseo eniradis en la tabernaklon, malleviĝadis nuba kolono kaj stariĝadis ĉe la pordo de la tabernaklo kaj paroladis kun Moseo."],[33,10,"Kaj la tuta popolo vidadis la nuban kolonon, kiu staris ĉe la pordo de la tabernaklo; kaj la tuta popolo leviĝadis kaj adorkliniĝadis ĉiu ĉe la pordo de sia tendo.","Kaj la tuta popolo vidadis la nuban kolonon, kiu staris ĉe la pordo de la tabernaklo; kaj la tuta popolo leviĝadis kaj adorkliniĝadis ĉiu ĉe la pordo de sia tendo."],[33,11,"Kaj la Eternulo paroladis kun Moseo vizaĝon kontraŭ vizaĝo, kiel parolas homo kun sia amiko. Kaj kiam li reiradis en la tendaron, tiam lia servanto Josuo, filo de Nun, junulo, ne foriĝadis el la tabernaklo.","Kaj la Eternulo paroladis kun Moseo vizaĝon kontraŭ vizaĝo, kiel parolas homo kun sia amiko. Kaj kiam li reiradis en la tendaron, tiam lia servanto Josuo, filo de Nun, junulo, ne foriĝadis el la tabernaklo."],[33,12,"Kaj Moseo diris al la Eternulo: Vidu, Vi diras al mi: Konduku ĉi tiun popolon; kaj Vi ne sciigis al mi, kiun Vi sendos kun mi, kvankam Vi diris: Mi konas vin laŭ via nomo, kaj vi akiris Mian favoron.","Kaj Moseo diris al la Eternulo: Vidu, Vi diras al mi: Konduku ĉi tiun popolon; kaj Vi ne sciigis al mi, kiun Vi sendos kun mi, kvankam Vi diris: Mi konas vin laŭ via nomo, kaj vi akiris Mian favoron."],[33,13,"Nun, se mi akiris Vian favoron, volu sciigi al mi Vian vojon, por ke mi konu Vin, por akiri Vian favoron; kaj vidu, ke ĉi tiu popolo estas Via popolo.","Nun, se mi akiris Vian favoron, volu sciigi al mi Vian vojon, por ke mi konu Vin, por akiri Vian favoron; kaj vidu, ke ĉi tiu popolo estas Via popolo."],[33,14,"Tiam Li diris: Mia vizaĝo iros antaŭe, kaj Mi donos al vi ripozon.","Tiam Li diris: Mia vizaĝo iros antaŭe, kaj Mi donos al vi ripozon."],[33,15,"Kaj li diris al Li: Se Via vizaĝo ne iros, tiam ne forkonduku nin de ĉi tie.","Kaj li diris al Li: Se Via vizaĝo ne iros, tiam ne forkonduku nin de ĉi tie."],[33,16,"Per kio do montriĝos, ke mi kaj Via popolo akiris Vian favoron? ĉu ne per tio, ke Vi irados kun ni? tiam mi kaj Via popolo distingiĝos de ĉiu popolo, kiu estas sur la tero.","Per kio do montriĝos, ke mi kaj Via popolo akiris Vian favoron? ĉu ne per tio, ke Vi irados kun ni? tiam mi kaj Via popolo distingiĝos de ĉiu popolo, kiu estas sur la tero."],[33,17,"Kaj la Eternulo diris al Moseo: Ankaŭ tion, kion vi diris, Mi faros; ĉar vi akiris Mian favoron kaj Mi konas vin laŭ via nomo.","Kaj la Eternulo diris al Moseo: Ankaŭ tion, kion vi diris, Mi faros; ĉar vi akiris Mian favoron kaj Mi konas vin laŭ via nomo."],[33,18,"Kaj li diris: Volu montri al mi Vian gloron.","Kaj li diris: Volu montri al mi Vian gloron."],[33,19,"Kaj Li diris: Mi preterpasigos antaŭ vi Mian tutan bonecon, kaj Mi alvokos la nomon de la Eternulo antaŭ vi; kaj Mi favorkoros tiun, kiun Mi favorkoros, kaj Mi kompatos tiun, kiun Mi kompatos.","Kaj Li diris: Mi preterpasigos antaŭ vi Mian tutan bonecon, kaj Mi alvokos la nomon de la Eternulo antaŭ vi; kaj Mi favorkoros tiun, kiun Mi favorkoros, kaj Mi kompatos tiun, kiun Mi kompatos."],[33,20,"Kaj Li diris: Vi ne povas vidi Mian vizaĝon, ĉar ne povas homo vidi Min kaj resti viva.","Kaj Li diris: Vi ne povas vidi Mian vizaĝon, ĉar ne povas homo vidi Min kaj resti viva."],[33,21,"Kaj la Eternulo diris: Jen estas loko ĉe Mi; stariĝu sur la roko.","Kaj la Eternulo diris: Jen estas loko ĉe Mi; stariĝu sur la roko."],[33,22,"Kaj kiam preteriros Mia gloro, Mi metos vin en fendon de la roko, kaj Mi ŝirmos vin per Mia mano, ĝis Mi pasos.","Kaj kiam preteriros Mia gloro, Mi metos vin en fendon de la roko, kaj Mi ŝirmos vin per Mia mano, ĝis Mi pasos."],[33,23,"Kaj kiam Mi formetos Mian manon, vi vidos Mian malantaŭan flankon, sed Mia vizaĝo ne estos videbla.","Kaj kiam Mi formetos Mian manon, vi vidos Mian malantaŭan flankon, sed Mia vizaĝo ne estos videbla."],[34,1,"Kaj la Eternulo diris al Moseo: Skulptu al vi du ŝtonajn tabelojn kiel la unuaj; kaj Mi skribos sur la tabeloj la vortojn, kiuj estis sur la unuaj tabeloj, kiujn vi rompis.","Kaj la Eternulo diris al Moseo: Skulptu al vi du ŝtonajn tabelojn kiel la unuaj; kaj Mi skribos sur la tabeloj la vortojn, kiuj estis sur la unuaj tabeloj, kiujn vi rompis."],[34,2,"Kaj estu preta por la mateno, kaj supreniru matene sur la monton Sinaj kaj stariĝu antaŭ Mi tie sur la pinto de la monto.","Kaj estu preta por la mateno, kaj supreniru matene sur la monton Sinaj kaj stariĝu antaŭ Mi tie sur la pinto de la monto."],[34,3,"Kaj neniu supreniru kun vi, kaj ankaŭ neniu montriĝu sur la tuta monto; eĉ ŝafo aŭ bovo ne paŝtiĝu antaŭ tiu monto.","Kaj neniu supreniru kun vi, kaj ankaŭ neniu montriĝu sur la tuta monto; eĉ ŝafo aŭ bovo ne paŝtiĝu antaŭ tiu monto."],[34,4,"Kaj li skulptis du ŝtonajn tabelojn kiel la unuaj; kaj Moseo leviĝis frue matene kaj supreniris sur la monton Sinaj, kiel ordonis al li la Eternulo, kaj li prenis en siajn manojn la du ŝtonajn tabelojn.","Kaj li skulptis du ŝtonajn tabelojn kiel la unuaj; kaj Moseo leviĝis frue matene kaj supreniris sur la monton Sinaj, kiel ordonis al li la Eternulo, kaj li prenis en siajn manojn la du ŝtonajn tabelojn."],[34,5,"Kaj la Eternulo malleviĝis en nubo, kaj Moseo stariĝis apud Li tie kaj alvokis la nomon de la Eternulo.","Kaj la Eternulo malleviĝis en nubo, kaj Moseo stariĝis apud Li tie kaj alvokis la nomon de la Eternulo."],[34,6,"Kaj la Eternulo preteriris antaŭ li, kaj li ekkriis: Eternulo, Eternulo, Dio indulgema kaj kompatema, multepacienca, favorkora, kaj verema;","Kaj la Eternulo preteriris antaŭ li, kaj li ekkriis: Eternulo, Eternulo, Dio indulgema kaj kompatema, multepacienca, favorkora, kaj verema;"],[34,7,"kiu konservas favorkorecon por miloj, pardonas kulpon kaj krimon kaj pekon, sed antaŭ kiu neniu estas senkulpa; kiu punas la kulpon de patroj sur filoj kaj nepoj, en la tria kaj kvara generacioj!","kiu konservas favorkorecon por miloj, pardonas kulpon kaj krimon kaj pekon, sed antaŭ kiu neniu estas senkulpa; kiu punas la kulpon de patroj sur filoj kaj nepoj, en la tria kaj kvara generacioj!"],[34,8,"Kaj rapide Moseo kliniĝis ĝis la tero kaj faris adoron.","Kaj rapide Moseo kliniĝis ĝis la tero kaj faris adoron."],[34,9,"Kaj li diris: Ho, se mi akiris Vian favoron, mia Sinjoro, tiam mia Sinjoro volu iri en nia mezo, ĉar tio estas popolo malmolnuka; kaj pardonu niajn kulpojn kaj niajn pekojn kaj faru nin Via posedaĵo.","Kaj li diris: Ho, se mi akiris Vian favoron, mia Sinjoro, tiam mia Sinjoro volu iri en nia mezo, ĉar tio estas popolo malmolnuka; kaj pardonu niajn kulpojn kaj niajn pekojn kaj faru nin Via posedaĵo."],[34,10,"Kaj Li diris: Jen Mi faros interligon; antaŭ via tuta popolo Mi faros miraklojn, kiuj neniam ekzistis sur la tuta tero nek ĉe iuj gentoj; kaj la tuta popolo, en kies mezo vi estas, vidos la faron de la Eternulo; ĉar terura estos tio, kion Mi faros por vi.","Kaj Li diris: Jen Mi faros interligon; antaŭ via tuta popolo Mi faros miraklojn, kiuj neniam ekzistis sur la tuta tero nek ĉe iuj gentoj; kaj la tuta popolo, en kies mezo vi estas, vidos la faron de la Eternulo; ĉar terura estos tio, kion Mi faros por vi."],[34,11,"Observu tion, kion Mi ordonas al vi hodiaŭ. Jen Mi forpelas antaŭ vi la Amoridojn kaj la Kanaanidojn kaj la Ĥetidojn kaj la Perizidojn kaj la Ĥividojn kaj la Jebusidojn.","Observu tion, kion Mi ordonas al vi hodiaŭ. Jen Mi forpelas antaŭ vi la Amoridojn kaj la Kanaanidojn kaj la Ĥetidojn kaj la Perizidojn kaj la Ĥividojn kaj la Jebusidojn."],[34,12,"Gardu vin, ke vi ne faru interligon kun la loĝantoj de la lando, en kiun vi venos, por ke tio ne fariĝu falilo inter vi;","Gardu vin, ke vi ne faru interligon kun la loĝantoj de la lando, en kiun vi venos, por ke tio ne fariĝu falilo inter vi;"],[34,13,"sed iliajn altarojn detruu kaj iliajn statuojn rompu kaj iliajn sanktajn stangojn dishaku.","sed iliajn altarojn detruu kaj iliajn statuojn rompu kaj iliajn sanktajn stangojn dishaku."],[34,14,"Ĉar vi ne devas adori alian dion; ĉar la Eternulo, koleremulo estas Lia nomo, estas Dio kolerema.","Ĉar vi ne devas adori alian dion; ĉar la Eternulo, koleremulo estas Lia nomo, estas Dio kolerema."],[34,15,"Ne faru interligon kun la loĝantoj de la lando; ĉar, malĉastante kun siaj dioj kaj alportante oferojn al siaj dioj, ili eble vokos vin kaj vi manĝos de iliaj oferoj,","Ne faru interligon kun la loĝantoj de la lando; ĉar, malĉastante kun siaj dioj kaj alportante oferojn al siaj dioj, ili eble vokos vin kaj vi manĝos de iliaj oferoj,"],[34,16,"kaj vi prenos iliajn filinojn por viaj filoj, kaj iliaj filinoj malĉastos por siaj dioj kaj malĉastigos viajn filojn por siaj dioj.","kaj vi prenos iliajn filinojn por viaj filoj, kaj iliaj filinoj malĉastos por siaj dioj kaj malĉastigos viajn filojn por siaj dioj."],[34,17,"Diojn fanditajn ne faru al vi.","Diojn fanditajn ne faru al vi."],[34,18,"La feston de macoj observu; dum sep tagoj manĝu macojn, kiel Mi ordonis al vi, en la difinita tempo de la monato Abib, ĉar en la monato Abib vi eliris el Egiptujo.","La feston de macoj observu; dum sep tagoj manĝu macojn, kiel Mi ordonis al vi, en la difinita tempo de la monato Abib, ĉar en la monato Abib vi eliris el Egiptujo."],[34,19,"Ĉio, kio malfermas unue la uteron, apartenas al mi; ĉiu virseksulo el viaj brutoj, kiu malfermas unue la uteron, bovo aŭ ŝafo.","Ĉio, kio malfermas unue la uteron, apartenas al mi; ĉiu virseksulo el viaj brutoj, kiu malfermas unue la uteron, bovo aŭ ŝafo."],[34,20,"Utermalferminton el azenoj elaĉetu per ŝafido: kaj se vi ne elaĉetos, tiam rompu al ĝi la kolon. La unuenaskiton el viaj filoj elaĉetu. Kaj oni ne montriĝu antaŭ Mi kun malplenaj manoj.","Utermalferminton el azenoj elaĉetu per ŝafido: kaj se vi ne elaĉetos, tiam rompu al ĝi la kolon. La unuenaskiton el viaj filoj elaĉetu. Kaj oni ne montriĝu antaŭ Mi kun malplenaj manoj."],[34,21,"Dum ses tagoj laboru, kaj en la sepa tago ripozu; en la tempo de la plugado kaj de la rikoltado ripozu.","Dum ses tagoj laboru, kaj en la sepa tago ripozu; en la tempo de la plugado kaj de la rikoltado ripozu."],[34,22,"Kaj feston de semajnoj faru al vi en la komenco de la rikoltado de tritiko, kaj feston de kolektado de fruktoj en la fino de la jaro.","Kaj feston de semajnoj faru al vi en la komenco de la rikoltado de tritiko, kaj feston de kolektado de fruktoj en la fino de la jaro."],[34,23,"Tri fojojn en la jaro ĉiuj viaj virseksuloj aperu antaŭ la Sinjoro, la Eternulo, Dio de Izrael.","Tri fojojn en la jaro ĉiuj viaj virseksuloj aperu antaŭ la Sinjoro, la Eternulo, Dio de Izrael."],[34,24,"Ĉar Mi forpelos gentojn antaŭ vi kaj vastigos viajn limojn, kaj neniu deziros havi vian landon, kiam vi iros, por montriĝi antaŭ la Eternulo, via Dio, tri fojojn en la jaro.","Ĉar Mi forpelos gentojn antaŭ vi kaj vastigos viajn limojn, kaj neniu deziros havi vian landon, kiam vi iros, por montriĝi antaŭ la Eternulo, via Dio, tri fojojn en la jaro."],[34,25,"Ne buĉverŝu sur fermentintaĵon la sangon de Mia ofero, kaj ne devas resti ĝis mateno la ofero de la festo de Pasko.","Ne buĉverŝu sur fermentintaĵon la sangon de Mia ofero, kaj ne devas resti ĝis mateno la ofero de la festo de Pasko."],[34,26,"La komencaĵon de la unuaj produktoj de via tero alportu en la domon de la Eternulo, via Dio. Ne kuiru kapridon en la lakto de ĝia patrino.","La komencaĵon de la unuaj produktoj de via tero alportu en la domon de la Eternulo, via Dio. Ne kuiru kapridon en la lakto de ĝia patrino."],[34,27,"Kaj la Eternulo diris al Moseo: Skribu al vi ĉi tiujn vortojn, ĉar laŭ ĉi tiuj vortoj Mi faris interligon kun vi kaj kun Izrael.","Kaj la Eternulo diris al Moseo: Skribu al vi ĉi tiujn vortojn, ĉar laŭ ĉi tiuj vortoj Mi faris interligon kun vi kaj kun Izrael."],[34,28,"Kaj li estis tie kun la Eternulo kvardek tagojn kaj kvardek noktojn; panon li ne manĝis kaj akvon li ne trinkis; kaj li skribis sur la tabeloj la vortojn de la interligo, la dek ordonojn.","Kaj li estis tie kun la Eternulo kvardek tagojn kaj kvardek noktojn; panon li ne manĝis kaj akvon li ne trinkis; kaj li skribis sur la tabeloj la vortojn de la interligo, la dek ordonojn."],[34,29,"Kiam Moseo estis malsupreniranta de la monto Sinaj kaj la du tabeloj de atesto estis en la manoj de Moseo dum lia malsuprenirado de la monto, Moseo ne sciis, ke la haŭto de lia vizaĝo lumradiis pro tio, ke li parolis kun Li.","Kiam Moseo estis malsupreniranta de la monto Sinaj kaj la du tabeloj de atesto estis en la manoj de Moseo dum lia malsuprenirado de la monto, Moseo ne sciis, ke la haŭto de lia vizaĝo lumradiis pro tio, ke li parolis kun Li."],[34,30,"Kaj Aaron kaj ĉiuj Izraelidoj ekvidis Moseon, kaj jen la haŭto de lia vizaĝo lumradias; kaj ili timis alproksimiĝi al li.","Kaj Aaron kaj ĉiuj Izraelidoj ekvidis Moseon, kaj jen la haŭto de lia vizaĝo lumradias; kaj ili timis alproksimiĝi al li."],[34,31,"Sed Moseo vokis ilin, kaj returniĝis al li Aaron kaj ĉiuj ĉefoj de la komunumo, kaj Moseo ekparolis al ili.","Sed Moseo vokis ilin, kaj returniĝis al li Aaron kaj ĉiuj ĉefoj de la komunumo, kaj Moseo ekparolis al ili."],[34,32,"Poste alproksimiĝis ĉiuj Izraelidoj; kaj li ordonis al ili ĉion, kion diris al li la Eternulo sur la monto Sinaj.","Poste alproksimiĝis ĉiuj Izraelidoj; kaj li ordonis al ili ĉion, kion diris al li la Eternulo sur la monto Sinaj."],[34,33,"Kiam Moseo ĉesis paroli al ili, li metis sur sian vizaĝon kovrotukon.","Kiam Moseo ĉesis paroli al ili, li metis sur sian vizaĝon kovrotukon."],[34,34,"Kiam Moseo venadis antaŭ la Eternulon, por paroli kun Li, li formetadis la kovrotukon ĝis sia eliro; kaj elirinte, li diradis al la Izraelidoj tion, kio estis ordonita al li.","Kiam Moseo venadis antaŭ la Eternulon, por paroli kun Li, li formetadis la kovrotukon ĝis sia eliro; kaj elirinte, li diradis al la Izraelidoj tion, kio estis ordonita al li."],[34,35,"Kaj la Izraelidoj vidis, ke la haŭto de la vizaĝo de Moseo lumradias; kaj tiam Moseo denove metis la kovrotukon sur sian vizaĝon, ĝis li eniris, por paroli kun Li.","Kaj la Izraelidoj vidis, ke la haŭto de la vizaĝo de Moseo lumradias; kaj tiam Moseo denove metis la kovrotukon sur sian vizaĝon, ĝis li eniris, por paroli kun Li."],[35,1,"Kaj Moseo kunvenigis la tutan komunumon de la Izraelidoj, kaj diris al ili: Jen kion la Eternulo ordonis al vi fari:","Kaj Moseo kunvenigis la tutan komunumon de la Izraelidoj, kaj diris al ili: Jen kion la Eternulo ordonis al vi fari:"],[35,2,"Dum ses tagoj faru laboron, sed la sepa tago estu por vi sankta, sabato de ripozo al la Eternulo; ĉiu, kiu faros en ĝi laboron, estu mortigita.","Dum ses tagoj faru laboron, sed la sepa tago estu por vi sankta, sabato de ripozo al la Eternulo; ĉiu, kiu faros en ĝi laboron, estu mortigita."],[35,3,"Ne bruligu fajron en ĉiuj viaj loĝejoj en la tago sabata.","Ne bruligu fajron en ĉiuj viaj loĝejoj en la tago sabata."],[35,4,"Kaj Moseo ekparolis al la tuta komunumo de la Izraelidoj, dirante: Jen kion ordonis la Eternulo:","Kaj Moseo ekparolis al la tuta komunumo de la Izraelidoj, dirante: Jen kion ordonis la Eternulo:"],[35,5,"Prenu inter vi oferdonon por la Eternulo: ĉiu memvole alportu la oferdonon por la Eternulo: oron kaj arĝenton kaj kupron,","Prenu inter vi oferdonon por la Eternulo: ĉiu memvole alportu la oferdonon por la Eternulo: oron kaj arĝenton kaj kupron,"],[35,6,"kaj bluan teksaĵon kaj purpuran kaj ruĝan, kaj bisinon kaj kapran lanon,","kaj bluan teksaĵon kaj purpuran kaj ruĝan, kaj bisinon kaj kapran lanon,"],[35,7,"kaj virŝafajn felojn ruĝe kolorigitajn, kaj antilopajn felojn, kaj akacian lignon,","kaj virŝafajn felojn ruĝe kolorigitajn, kaj antilopajn felojn, kaj akacian lignon,"],[35,8,"kaj oleon por lumigado, kaj aromaĵojn por la sankta oleo kaj por la bonodoraj incensoj,","kaj oleon por lumigado, kaj aromaĵojn por la sankta oleo kaj por la bonodoraj incensoj,"],[35,9,"kaj ŝtonojn oniksajn kaj ŝtonojn enkadrigeblajn por la efodo kaj por la surbrustaĵo.","kaj ŝtonojn oniksajn kaj ŝtonojn enkadrigeblajn por la efodo kaj por la surbrustaĵo."],[35,10,"Kaj ĉiu el vi, kiu estas kompetentulo, venu kaj faru ĉion, kion ordonis la Eternulo:","Kaj ĉiu el vi, kiu estas kompetentulo, venu kaj faru ĉion, kion ordonis la Eternulo:"],[35,11,"la tabernaklon kaj ĝian tendon kaj ĝian kovron, ĝiajn hoketojn kaj ĝiajn tabulojn, ĝiajn riglilojn, ĝiajn kolonojn kaj ĝiajn bazojn;","la tabernaklon kaj ĝian tendon kaj ĝian kovron, ĝiajn hoketojn kaj ĝiajn tabulojn, ĝiajn riglilojn, ĝiajn kolonojn kaj ĝiajn bazojn;"],[35,12,"la keston kaj ĝiajn stangojn, la fermoplaton kaj la kurtenon;","la keston kaj ĝiajn stangojn, la fermoplaton kaj la kurtenon;"],[35,13,"la tablon kaj ĝiajn stangojn kaj ĉiujn ĝiajn apartenaĵojn kaj la panojn de propono;","la tablon kaj ĝiajn stangojn kaj ĉiujn ĝiajn apartenaĵojn kaj la panojn de propono;"],[35,14,"kaj la kandelabron por lumigi kaj ĝiajn apartenaĵojn kaj ĝiajn lucernojn kaj la oleon por lumigi;","kaj la kandelabron por lumigi kaj ĝiajn apartenaĵojn kaj ĝiajn lucernojn kaj la oleon por lumigi;"],[35,15,"kaj la altaron de incensado kaj ĝiajn stangojn kaj la sanktan oleon kaj la bonodoran incenson kaj la pordan kovrotukon antaŭ la pordo de la tabernaklo;","kaj la altaron de incensado kaj ĝiajn stangojn kaj la sanktan oleon kaj la bonodoran incenson kaj la pordan kovrotukon antaŭ la pordo de la tabernaklo;"],[35,16,"la altaron de bruloferoj kaj ĝian kupran kradon, ĝiajn stangojn kaj ĉiujn ĝiajn apartenaĵojn, la lavujon kaj ĝian piedestalon;","la altaron de bruloferoj kaj ĝian kupran kradon, ĝiajn stangojn kaj ĉiujn ĝiajn apartenaĵojn, la lavujon kaj ĝian piedestalon;"],[35,17,"la kurtenojn de la korto, ĝiajn kolonojn kaj bazojn kaj la kovrotukon de la pordego de la korto;","la kurtenojn de la korto, ĝiajn kolonojn kaj bazojn kaj la kovrotukon de la pordego de la korto;"],[35,18,"la najlojn de la tabernaklo kaj la najlojn de la korto kaj iliajn ŝnurojn;","la najlojn de la tabernaklo kaj la najlojn de la korto kaj iliajn ŝnurojn;"],[35,19,"la oficajn vestojn por servado en la sanktejo, la sanktajn vestojn por la pastro Aaron kaj la pastrajn vestojn de liaj filoj.","la oficajn vestojn por servado en la sanktejo, la sanktajn vestojn por la pastro Aaron kaj la pastrajn vestojn de liaj filoj."],[35,20,"Kaj la tuta komunumo de la Izraelidoj eliris de antaŭ Moseo.","Kaj la tuta komunumo de la Izraelidoj eliris de antaŭ Moseo."],[35,21,"Kaj venis ĉiuj homoj, kiujn tiris la koro; kaj ĉiu, kiun inklinigis lia spirito, alportis la oferdonon por la Eternulo, por la aranĝo de la tabernaklo de kunveno kaj por ĝia tuta servado kaj por la sanktaj vestoj.","Kaj venis ĉiuj homoj, kiujn tiris la koro; kaj ĉiu, kiun inklinigis lia spirito, alportis la oferdonon por la Eternulo, por la aranĝo de la tabernaklo de kunveno kaj por ĝia tuta servado kaj por la sanktaj vestoj."],[35,22,"Kaj venis la viroj kaj la virinoj; ĉiuj, kiujn inklinigis la koro, alportis bukojn kaj orelringojn kaj ringojn kaj kolringojn, diversajn orajn objektojn; kaj ĉiu alportis oran oferdonon al la Eternulo.","Kaj venis la viroj kaj la virinoj; ĉiuj, kiujn inklinigis la koro, alportis bukojn kaj orelringojn kaj ringojn kaj kolringojn, diversajn orajn objektojn; kaj ĉiu alportis oran oferdonon al la Eternulo."],[35,23,"Kaj ĉiu, ĉe kiu troviĝis blua teksaĵo, aŭ purpura, aŭ ruĝa, aŭ bisino, aŭ kapra lano, aŭ ŝafaj feloj ruĝaj, aŭ antilopaj feloj, alportis.","Kaj ĉiu, ĉe kiu troviĝis blua teksaĵo, aŭ purpura, aŭ ruĝa, aŭ bisino, aŭ kapra lano, aŭ ŝafaj feloj ruĝaj, aŭ antilopaj feloj, alportis."],[35,24,"Ĉiu, kiu oferis arĝenton aŭ kupron, alportis la oferdonon por la Eternulo; kaj ĉiu, ĉe kiu troviĝis akacia ligno por ĉia bezono de la servado, alportis ĝin.","Ĉiu, kiu oferis arĝenton aŭ kupron, alportis la oferdonon por la Eternulo; kaj ĉiu, ĉe kiu troviĝis akacia ligno por ĉia bezono de la servado, alportis ĝin."],[35,25,"Kaj ĉiu virino, kiu havis ian kompetentecon, ŝpinis kaj alportis ŝpinitan lanon bluan kaj purpuran kaj ruĝan kaj bisinon.","Kaj ĉiu virino, kiu havis ian kompetentecon, ŝpinis kaj alportis ŝpinitan lanon bluan kaj purpuran kaj ruĝan kaj bisinon."],[35,26,"Kaj ĉiuj virinoj, kiuj havis deziron kaj kompetentecon, ŝpinis kapran lanon.","Kaj ĉiuj virinoj, kiuj havis deziron kaj kompetentecon, ŝpinis kapran lanon."],[35,27,"Kaj la princoj alportis ŝtonojn oniksajn kaj ŝtonojn enkadrigeblajn por la efodo kaj por la surbrustaĵo,","Kaj la princoj alportis ŝtonojn oniksajn kaj ŝtonojn enkadrigeblajn por la efodo kaj por la surbrustaĵo,"],[35,28,"kaj la aromaĵon kaj la oleon por lumigi kaj por la sankta oleo kaj por la bonodoraj incensoj.","kaj la aromaĵon kaj la oleon por lumigi kaj por la sankta oleo kaj por la bonodoraj incensoj."],[35,29,"Ĉiu viro kaj virino el la Izraelidoj, kiujn inklinigis ilia koro alporti por ĉia laboro, kiun la Eternulo per Moseo ordonis fari, alportis oferon al la Eternulo.","Ĉiu viro kaj virino el la Izraelidoj, kiujn inklinigis ilia koro alporti por ĉia laboro, kiun la Eternulo per Moseo ordonis fari, alportis oferon al la Eternulo."],[35,30,"Kaj Moseo diris al la Izraelidoj: Jen, la Eternulo vokis per la nomo Becalelon, filon de Uri, filo de Ĥur, el la tribo de Jehuda;","Kaj Moseo diris al la Izraelidoj: Jen, la Eternulo vokis per la nomo Becalelon, filon de Uri, filo de Ĥur, el la tribo de Jehuda;"],[35,31,"kaj Li plenigis lin per Dia spirito, per saĝo kaj prudento, kaj scio kaj per ĉia arto,","kaj Li plenigis lin per Dia spirito, per saĝo kaj prudento, kaj scio kaj per ĉia arto,"],[35,32,"por pripensi ideojn, por labori el oro kaj el arĝento kaj el kupro,","por pripensi ideojn, por labori el oro kaj el arĝento kaj el kupro,"],[35,33,"kaj por ĉizi ŝtonojn por enkadrigo, kaj por ĉizi lignon, por fari ĉian artistan laboron.","kaj por ĉizi ŝtonojn por enkadrigo, kaj por ĉizi lignon, por fari ĉian artistan laboron."],[35,34,"Kaj Li donis al li la kapablon instrui, al li kaj al Oholiab, filo de Aĥisamaĥ, el la tribo de Dan.","Kaj Li donis al li la kapablon instrui, al li kaj al Oholiab, filo de Aĥisamaĥ, el la tribo de Dan."],[35,35,"Li plenigis ilin per kompetenteco por farado de ĉia majstra laboro, por ĉia talenta brodado sur teksaĵo blua kaj purpura kaj ruĝa kaj sur bisino, por teksado de ĉia laboraĵo kaj pripensado de ideoj.","Li plenigis ilin per kompetenteco por farado de ĉia majstra laboro, por ĉia talenta brodado sur teksaĵo blua kaj purpura kaj ruĝa kaj sur bisino, por teksado de ĉia laboraĵo kaj pripensado de ideoj."],[36,1,"Kaj laboros Becalel kaj Oholiab kaj ĉiuj kompetentuloj, en kiujn la Eternulo enmetis saĝon kaj prudenton, por ke ili sciu fari ĉiun laboron por la servado en la sanktejo, laŭ ĉio, kion ordonis la Eternulo.","Kaj laboros Becalel kaj Oholiab kaj ĉiuj kompetentuloj, en kiujn la Eternulo enmetis saĝon kaj prudenton, por ke ili sciu fari ĉiun laboron por la servado en la sanktejo, laŭ ĉio, kion ordonis la Eternulo."],[36,2,"Kaj Moseo alvokis Becalelon kaj Oholiabon, kaj ĉiun kompetentulon, al kiu la Eternulo enmetis saĝon en la koron, ĉiun, kiun tiris lia koro entrepreni la laboron kaj fari ĝin.","Kaj Moseo alvokis Becalelon kaj Oholiabon, kaj ĉiun kompetentulon, al kiu la Eternulo enmetis saĝon en la koron, ĉiun, kiun tiris lia koro entrepreni la laboron kaj fari ĝin."],[36,3,"Kaj ili prenis de Moseo ĉiujn oferdonojn, kiujn alportis la Izraelidoj por la bezonoj de la servado en la sanktejo, por ellabori ilin. Kaj tiuj alportadis al li ankoraŭ plue oferdonojn ĉiumatene.","Kaj ili prenis de Moseo ĉiujn oferdonojn, kiujn alportis la Izraelidoj por la bezonoj de la servado en la sanktejo, por ellabori ilin. Kaj tiuj alportadis al li ankoraŭ plue oferdonojn ĉiumatene."],[36,4,"Kaj venis ĉiuj saĝuloj, kiuj estis farantaj la tutan laboron por la sanktejo, ĉiu venis de sia laboro, kiun li faris.","Kaj venis ĉiuj saĝuloj, kiuj estis farantaj la tutan laboron por la sanktejo, ĉiu venis de sia laboro, kiun li faris."],[36,5,"Kaj ili diris al Moseo jene: La popolo alportas pli multe, ol bezonas la laboroj, kiujn la Eternulo ordonis fari.","Kaj ili diris al Moseo jene: La popolo alportas pli multe, ol bezonas la laboroj, kiujn la Eternulo ordonis fari."],[36,6,"Tiam Moseo ordonis, kaj oni elkriis en la tendaro jene: Neniu viro kaj neniu virino faru plue laboraĵon, por oferdoni al la sanktejo. Kaj la popolo ĉesis alporti.","Tiam Moseo ordonis, kaj oni elkriis en la tendaro jene: Neniu viro kaj neniu virino faru plue laboraĵon, por oferdoni al la sanktejo. Kaj la popolo ĉesis alporti."],[36,7,"Kaj la alportitaĵo estis sufiĉa por la tuta farota laboro, kaj eĉ superflua.","Kaj la alportitaĵo estis sufiĉa por la tuta farota laboro, kaj eĉ superflua."],[36,8,"Kaj ĉiuj kompetentuloj inter tiuj, kiuj estis farantaj la laboron por la tabernaklo, faris dek tapiŝojn el tordita bisino kaj el blua, purpura, kaj ruĝa teksaĵo; kerubojn artiste laboritajn ili faris sur ili.","Kaj ĉiuj kompetentuloj inter tiuj, kiuj estis farantaj la laboron por la tabernaklo, faris dek tapiŝojn el tordita bisino kaj el blua, purpura, kaj ruĝa teksaĵo; kerubojn artiste laboritajn ili faris sur ili."],[36,9,"La longo de ĉiu tapiŝo estis dudek ok ulnoj, kaj la larĝo de ĉiu tapiŝo estis kvar ulnoj; unu mezuro estis por ĉiuj tapiŝoj.","La longo de ĉiu tapiŝo estis dudek ok ulnoj, kaj la larĝo de ĉiu tapiŝo estis kvar ulnoj; unu mezuro estis por ĉiuj tapiŝoj."],[36,10,"Kaj li kunigis kvin tapiŝojn unu kun la alia, kaj la kvin ceterajn ankaŭ unu kun la alia.","Kaj li kunigis kvin tapiŝojn unu kun la alia, kaj la kvin ceterajn ankaŭ unu kun la alia."],[36,11,"Kaj li faris maŝojn el blua teksaĵo sur la rando de unu tapiŝo, sur la rando de la kuniĝo; tiel same li faris sur la rando de la ekstrema tapiŝo, sur la dua rando de kuniĝo.","Kaj li faris maŝojn el blua teksaĵo sur la rando de unu tapiŝo, sur la rando de la kuniĝo; tiel same li faris sur la rando de la ekstrema tapiŝo, sur la dua rando de kuniĝo."],[36,12,"Kvindek maŝojn li faris sur unu tapiŝo, kaj kvindek maŝojn li faris sur la rando de tiu tapiŝo, sur kiu estis la dua flanko de la kuniĝo; la maŝoj estis reciproke aranĝitaj unu kontraŭ alia.","Kvindek maŝojn li faris sur unu tapiŝo, kaj kvindek maŝojn li faris sur la rando de tiu tapiŝo, sur kiu estis la dua flanko de la kuniĝo; la maŝoj estis reciproke aranĝitaj unu kontraŭ alia."],[36,13,"Kaj li faris kvindek orajn hoketojn, kaj li kunigis la tapiŝojn unu kun la alia per la hoketoj; kaj la tabernaklo fariĝis unu tutaĵo.","Kaj li faris kvindek orajn hoketojn, kaj li kunigis la tapiŝojn unu kun la alia per la hoketoj; kaj la tabernaklo fariĝis unu tutaĵo."],[36,14,"Kaj li faris tapiŝojn el kapra lano kiel kovron super la tabernaklo; dek unu tiajn tapiŝojn li faris.","Kaj li faris tapiŝojn el kapra lano kiel kovron super la tabernaklo; dek unu tiajn tapiŝojn li faris."],[36,15,"La longo de ĉiu tapiŝo estis tridek ulnoj, kaj kvar ulnoj estis la larĝo de ĉiu tapiŝo; unu mezuro estis por la dek unu tapiŝoj.","La longo de ĉiu tapiŝo estis tridek ulnoj, kaj kvar ulnoj estis la larĝo de ĉiu tapiŝo; unu mezuro estis por la dek unu tapiŝoj."],[36,16,"Kaj li kunigis kvin tapiŝojn aparte kaj la ceterajn ses tapiŝojn aparte.","Kaj li kunigis kvin tapiŝojn aparte kaj la ceterajn ses tapiŝojn aparte."],[36,17,"Kaj li faris kvindek maŝojn sur la rando de la ekstrema tapiŝo, sur la rando de la kuniĝo, kaj kvindek maŝojn li faris sur la rando de la dua kuniĝa tapiŝo.","Kaj li faris kvindek maŝojn sur la rando de la ekstrema tapiŝo, sur la rando de la kuniĝo, kaj kvindek maŝojn li faris sur la rando de la dua kuniĝa tapiŝo."],[36,18,"Kaj li faris kvindek kuprajn hoketojn, por kunigi la tendon, por ke ĝi estu unu tutaĵo.","Kaj li faris kvindek kuprajn hoketojn, por kunigi la tendon, por ke ĝi estu unu tutaĵo."],[36,19,"Kaj li faris kovron por la tendo el ruĝaj virŝafaj feloj kaj ankoraŭ kovron el antilopaj feloj supre.","Kaj li faris kovron por la tendo el ruĝaj virŝafaj feloj kaj ankoraŭ kovron el antilopaj feloj supre."],[36,20,"Kaj li faris la tabulojn por la tabernaklo, starantajn, el akacia ligno.","Kaj li faris la tabulojn por la tabernaklo, starantajn, el akacia ligno."],[36,21,"Dek ulnoj estis la longo de ĉiu tabulo, kaj unu ulno kaj duono la larĝo de ĉiu tabulo.","Dek ulnoj estis la longo de ĉiu tabulo, kaj unu ulno kaj duono la larĝo de ĉiu tabulo."],[36,22,"Ĉiu tabulo havis du pivotojn, alĝustigitajn unu al la alia; tiel li faris ĉe ĉiuj tabuloj de la tabernaklo.","Ĉiu tabulo havis du pivotojn, alĝustigitajn unu al la alia; tiel li faris ĉe ĉiuj tabuloj de la tabernaklo."],[36,23,"Kaj li faris la tabulojn por la tabernaklo; dudek tabulojn sur la flanko suda.","Kaj li faris la tabulojn por la tabernaklo; dudek tabulojn sur la flanko suda."],[36,24,"Kaj kvardek arĝentajn bazojn li faris sub la dudek tabuloj, du bazojn sub ĉiu tabulo, por ĝiaj du pivotoj.","Kaj kvardek arĝentajn bazojn li faris sub la dudek tabuloj, du bazojn sub ĉiu tabulo, por ĝiaj du pivotoj."],[36,25,"Kaj sur la dua flanko de la tabernaklo, sur la flanko norda, li faris dudek tabulojn,","Kaj sur la dua flanko de la tabernaklo, sur la flanko norda, li faris dudek tabulojn,"],[36,26,"kaj kvardek arĝentajn bazojn por ili, du bazojn sub ĉiu tabulo.","kaj kvardek arĝentajn bazojn por ili, du bazojn sub ĉiu tabulo."],[36,27,"Kaj sur la malantaŭa flanko de la tabernaklo, okcidente, li faris ses tabulojn.","Kaj sur la malantaŭa flanko de la tabernaklo, okcidente, li faris ses tabulojn."],[36,28,"Kaj du tabulojn li faris en la anguloj de la tabernaklo sur la malantaŭa flanko.","Kaj du tabulojn li faris en la anguloj de la tabernaklo sur la malantaŭa flanko."],[36,29,"Kaj ili estis kunigitaj malsupre kaj kunigitaj supre per unu ringo; tiel li faris kun ambaŭ en la du anguloj.","Kaj ili estis kunigitaj malsupre kaj kunigitaj supre per unu ringo; tiel li faris kun ambaŭ en la du anguloj."],[36,30,"Kaj estis ok tabuloj, kaj ĉe ili dek ses arĝentaj bazoj, po du bazoj sub ĉiu tabulo.","Kaj estis ok tabuloj, kaj ĉe ili dek ses arĝentaj bazoj, po du bazoj sub ĉiu tabulo."],[36,31,"Kaj li faris riglilojn el akacia ligno: kvin por la tabuloj de unu flanko de la tabernaklo,","Kaj li faris riglilojn el akacia ligno: kvin por la tabuloj de unu flanko de la tabernaklo,"],[36,32,"kaj kvin riglilojn por la tabuloj de la dua flanko de la tabernaklo, kaj kvin riglilojn por la tabuloj de la malantaŭa flanko de la tabernaklo, okcidente.","kaj kvin riglilojn por la tabuloj de la dua flanko de la tabernaklo, kaj kvin riglilojn por la tabuloj de la malantaŭa flanko de la tabernaklo, okcidente."],[36,33,"Kaj li faris mezan riglilon, kiu ŝoviĝis meze de la tabuloj de unu fino ĝis la alia.","Kaj li faris mezan riglilon, kiu ŝoviĝis meze de la tabuloj de unu fino ĝis la alia."],[36,34,"Kaj la tabulojn li tegis per oro, kaj iliajn ringojn, ingojn por la rigliloj, li faris el oro, kaj la riglilojn li tegis per oro.","Kaj la tabulojn li tegis per oro, kaj iliajn ringojn, ingojn por la rigliloj, li faris el oro, kaj la riglilojn li tegis per oro."],[36,35,"Kaj li faris la kurtenon el blua, purpura, kaj ruĝa teksaĵo, kaj el tordita bisino; per artista laboro li faris sur ĝi kerubojn.","Kaj li faris la kurtenon el blua, purpura, kaj ruĝa teksaĵo, kaj el tordita bisino; per artista laboro li faris sur ĝi kerubojn."],[36,36,"Kaj li faris por ĝi kvar kolonojn el akacia ligno, kaj li tegis ilin per oro, kaj iliaj hoketoj estis el oro; kaj li fandis por ili kvar arĝentajn bazojn.","Kaj li faris por ĝi kvar kolonojn el akacia ligno, kaj li tegis ilin per oro, kaj iliaj hoketoj estis el oro; kaj li fandis por ili kvar arĝentajn bazojn."],[36,37,"Kaj li faris kovrotukon por la pordo de la tabernaklo, el blua, purpura, kaj ruĝa teksaĵo, kaj el tordita bisino, kun brodaĵoj;","Kaj li faris kovrotukon por la pordo de la tabernaklo, el blua, purpura, kaj ruĝa teksaĵo, kaj el tordita bisino, kun brodaĵoj;"],[36,38,"kaj kvin kolonojn por ĝi kun iliaj hoketoj; kaj li tegis iliajn kapojn kaj ligaĵojn per oro; kaj por ili kvin kuprajn bazojn.","kaj kvin kolonojn por ĝi kun iliaj hoketoj; kaj li tegis iliajn kapojn kaj ligaĵojn per oro; kaj por ili kvin kuprajn bazojn."],[37,1,"Kaj Becalel faris la keston el akacia ligno; du ulnoj kaj duono estis ĝia longo, kaj unu ulno kaj duono ĝia larĝo, kaj unu ulno kaj duono ĝia alto.","Kaj Becalel faris la keston el akacia ligno; du ulnoj kaj duono estis ĝia longo, kaj unu ulno kaj duono ĝia larĝo, kaj unu ulno kaj duono ĝia alto."],[37,2,"Kaj li tegis ĝin per pura oro interne kaj ekstere, kaj li faris al ĝi oran kronon ĉirkaŭe.","Kaj li tegis ĝin per pura oro interne kaj ekstere, kaj li faris al ĝi oran kronon ĉirkaŭe."],[37,3,"Kaj li fandis por ĝi kvar orajn ringojn sur ĝiaj kvar anguloj: du ringojn sur unu ĝia flanko kaj du ringojn sur ĝia alia flanko.","Kaj li fandis por ĝi kvar orajn ringojn sur ĝiaj kvar anguloj: du ringojn sur unu ĝia flanko kaj du ringojn sur ĝia alia flanko."],[37,4,"Kaj li faris stangojn el akacia ligno kaj tegis ilin per oro.","Kaj li faris stangojn el akacia ligno kaj tegis ilin per oro."],[37,5,"Kaj li metis la stangojn en la ringojn sur la flankoj de la kesto, por porti la keston.","Kaj li metis la stangojn en la ringojn sur la flankoj de la kesto, por porti la keston."],[37,6,"Kaj li faris fermoplaton el pura oro; du ulnoj kaj duono estis ĝia longo, kaj unu ulno kaj duono ĝia larĝo.","Kaj li faris fermoplaton el pura oro; du ulnoj kaj duono estis ĝia longo, kaj unu ulno kaj duono ĝia larĝo."],[37,7,"Kaj li faris du kerubojn el oro; per forĝa laboro li faris ilin, sur la du randoj de la fermoplato:","Kaj li faris du kerubojn el oro; per forĝa laboro li faris ilin, sur la du randoj de la fermoplato:"],[37,8,"unu kerubon ĉe unu flanko kaj la duan kerubon ĉe la dua flanko; elstarantaj el la fermoplato li faris la kerubojn, sur ĝiaj du flankoj.","unu kerubon ĉe unu flanko kaj la duan kerubon ĉe la dua flanko; elstarantaj el la fermoplato li faris la kerubojn, sur ĝiaj du flankoj."],[37,9,"Kaj la keruboj estis etendantaj siajn flugilojn supren, kovrante per siaj flugiloj la fermoplaton, kaj iliaj vizaĝoj estis unu kontraŭ la alia; al la fermoplato estis turnitaj la vizaĝoj de la keruboj.","Kaj la keruboj estis etendantaj siajn flugilojn supren, kovrante per siaj flugiloj la fermoplaton, kaj iliaj vizaĝoj estis unu kontraŭ la alia; al la fermoplato estis turnitaj la vizaĝoj de la keruboj."],[37,10,"Kaj li faris la tablon el akacia ligno; du ulnoj estis ĝia longo, kaj unu ulno ĝia larĝo, kaj unu ulno kaj duono ĝia alto.","Kaj li faris la tablon el akacia ligno; du ulnoj estis ĝia longo, kaj unu ulno ĝia larĝo, kaj unu ulno kaj duono ĝia alto."],[37,11,"Kaj li tegis ĝin per pura oro, kaj li faris al ĝi oran kronon ĉirkaŭe.","Kaj li tegis ĝin per pura oro, kaj li faris al ĝi oran kronon ĉirkaŭe."],[37,12,"Kaj li faris ĉirkaŭ ĝi manlarĝan listelon, kaj li faris oran kronon ĉirkaŭ la listelo.","Kaj li faris ĉirkaŭ ĝi manlarĝan listelon, kaj li faris oran kronon ĉirkaŭ la listelo."],[37,13,"Kaj li fandis por ĝi kvar orajn ringojn, kaj li alfortikigis la ringojn sur la kvar anguloj, ĉe ĝiaj kvar piedoj.","Kaj li fandis por ĝi kvar orajn ringojn, kaj li alfortikigis la ringojn sur la kvar anguloj, ĉe ĝiaj kvar piedoj."],[37,14,"Apud la listelo estis la ringoj, kiel ingoj por la stangoj, por porti la tablon.","Apud la listelo estis la ringoj, kiel ingoj por la stangoj, por porti la tablon."],[37,15,"Kaj li faris la stangojn el akacia ligno, kaj li tegis ilin per oro, por porti la tablon.","Kaj li faris la stangojn el akacia ligno, kaj li tegis ilin per oro, por porti la tablon."],[37,16,"Kaj ankaŭ la vazojn por la tablo, ĝiajn pladojn kaj ĝiajn kulerojn, kaj ĝiajn kruĉojn kaj la kalikojn, per kiuj oni verŝas, li faris el pura oro.","Kaj ankaŭ la vazojn por la tablo, ĝiajn pladojn kaj ĝiajn kulerojn, kaj ĝiajn kruĉojn kaj la kalikojn, per kiuj oni verŝas, li faris el pura oro."],[37,17,"Kaj li faris la kandelabron el pura oro, per forĝa laboro li faris la kandelabron; ĝia trunko kaj ĝiaj branĉoj, ĝiaj kalikoj, ĝiaj kapetoj, kaj ĝiaj floroj elstaris el ĝi.","Kaj li faris la kandelabron el pura oro, per forĝa laboro li faris la kandelabron; ĝia trunko kaj ĝiaj branĉoj, ĝiaj kalikoj, ĝiaj kapetoj, kaj ĝiaj floroj elstaris el ĝi."],[37,18,"Kaj ses branĉoj elstaris el ĝiaj flankoj: tri branĉoj de la kandelabro el unu flanko, kaj tri branĉoj de la kandelabro el la dua flanko;","Kaj ses branĉoj elstaris el ĝiaj flankoj: tri branĉoj de la kandelabro el unu flanko, kaj tri branĉoj de la kandelabro el la dua flanko;"],[37,19,"tri migdalformaj kalikoj, kapeto, kaj floro estis sur unu branĉo, kaj tri migdalformaj kalikoj, kapeto, kaj floro sur la dua branĉo; tiel estis sur la ses branĉoj, kiuj elstaris el la kandelabro.","tri migdalformaj kalikoj, kapeto, kaj floro estis sur unu branĉo, kaj tri migdalformaj kalikoj, kapeto, kaj floro sur la dua branĉo; tiel estis sur la ses branĉoj, kiuj elstaris el la kandelabro."],[37,20,"Kaj sur la kandelabro estis kvar migdalformaj kalikoj kun siaj kapetoj kaj floroj.","Kaj sur la kandelabro estis kvar migdalformaj kalikoj kun siaj kapetoj kaj floroj."],[37,21,"Kaj kapeto estis sub unu paro da branĉoj, kaj kapeto sub la dua paro da branĉoj, kaj kapeto sub la tria paro da branĉoj; tiel estis ĉe la ses branĉoj, kiuj elstaris el ĝi.","Kaj kapeto estis sub unu paro da branĉoj, kaj kapeto sub la dua paro da branĉoj, kaj kapeto sub la tria paro da branĉoj; tiel estis ĉe la ses branĉoj, kiuj elstaris el ĝi."],[37,22,"La kapetoj kaj branĉoj elstaris el ĝi; ĉio estis unu forĝita tutaĵo el pura oro.","La kapetoj kaj branĉoj elstaris el ĝi; ĉio estis unu forĝita tutaĵo el pura oro."],[37,23,"Kaj li faris ĝiajn sep lucernojn kaj ĝiajn prenilojn kaj cindrujojn el pura oro.","Kaj li faris ĝiajn sep lucernojn kaj ĝiajn prenilojn kaj cindrujojn el pura oro."],[37,24,"El kikaro da pura oro li faris ĝin kaj ĉiujn ĝiajn apartenaĵojn.","El kikaro da pura oro li faris ĝin kaj ĉiujn ĝiajn apartenaĵojn."],[37,25,"Kaj li faris la altaron por la incensado el akacia ligno; unu ulno estis ĝia longo, kaj unu ulno ĝia larĝo; kvarangula ĝi estis; du ulnoj estis ĝia alto; el ĝi elstaris ĝiaj kornoj.","Kaj li faris la altaron por la incensado el akacia ligno; unu ulno estis ĝia longo, kaj unu ulno ĝia larĝo; kvarangula ĝi estis; du ulnoj estis ĝia alto; el ĝi elstaris ĝiaj kornoj."],[37,26,"Kaj li tegis ĝin per pura oro, ĝian supran platon kaj ĝiajn muretojn ĉirkaŭe kaj ĝiajn kornojn; kaj li faris al ĝi oran kronon ĉirkaŭe.","Kaj li tegis ĝin per pura oro, ĝian supran platon kaj ĝiajn muretojn ĉirkaŭe kaj ĝiajn kornojn; kaj li faris al ĝi oran kronon ĉirkaŭe."],[37,27,"Kaj du orajn ringojn li faris al ĝi sub ĝia krono, sur ĝiaj du flankoj, kiel ingojn por stangoj, per kiuj oni portu ĝin.","Kaj du orajn ringojn li faris al ĝi sub ĝia krono, sur ĝiaj du flankoj, kiel ingojn por stangoj, per kiuj oni portu ĝin."],[37,28,"Kaj li faris la stangojn el akacia ligno kaj tegis ilin per oro.","Kaj li faris la stangojn el akacia ligno kaj tegis ilin per oro."],[37,29,"Kaj li faris la oleon por la sanktoleado kaj la puran bonodoran incenson laŭ la arto de ŝmiraĵisto.","Kaj li faris la oleon por la sanktoleado kaj la puran bonodoran incenson laŭ la arto de ŝmiraĵisto."],[38,1,"Kaj li faris la altaron por la bruloferoj el akacia ligno; kvin ulnoj estis ĝia longo, kaj kvin ulnoj ĝia larĝo; kvarangula ĝi estis; kaj tri ulnoj estis ĝia alto.","Kaj li faris la altaron por la bruloferoj el akacia ligno; kvin ulnoj estis ĝia longo, kaj kvin ulnoj ĝia larĝo; kvarangula ĝi estis; kaj tri ulnoj estis ĝia alto."],[38,2,"Kaj li faris ĝiajn kornojn sur ĝiaj kvar anguloj; el ĝi elstaris ĝiaj kornoj; kaj li tegis ĝin per kupro.","Kaj li faris ĝiajn kornojn sur ĝiaj kvar anguloj; el ĝi elstaris ĝiaj kornoj; kaj li tegis ĝin per kupro."],[38,3,"Kaj li faris ĉiujn vazojn de la altaro; la potojn, la ŝovelilojn, la kalikojn, la forkojn, la karbujojn; ĉiujn ĝiajn vazojn li faris el kupro.","Kaj li faris ĉiujn vazojn de la altaro; la potojn, la ŝovelilojn, la kalikojn, la forkojn, la karbujojn; ĉiujn ĝiajn vazojn li faris el kupro."],[38,4,"Kaj li faris por la altaro kradon en formo de kupra reto, sub ĝia kornico, malsupre, ĝis la mezo.","Kaj li faris por la altaro kradon en formo de kupra reto, sub ĝia kornico, malsupre, ĝis la mezo."],[38,5,"Kaj li fandis kvar ringojn en la kvar anguloj de la kupra krado, ke ili estu ingoj por la stangoj.","Kaj li fandis kvar ringojn en la kvar anguloj de la kupra krado, ke ili estu ingoj por la stangoj."],[38,6,"Kaj li faris la stangojn el akacia ligno kaj tegis ilin per kupro.","Kaj li faris la stangojn el akacia ligno kaj tegis ilin per kupro."],[38,7,"Kaj li metis la stangojn en la ringojn sur la flankoj de la altaro, por ke oni povu porti ĝin per ili; li faris ĝin interne malplena, el tabuloj.","Kaj li metis la stangojn en la ringojn sur la flankoj de la altaro, por ke oni povu porti ĝin per ili; li faris ĝin interne malplena, el tabuloj."],[38,8,"Kaj li faris la lavujon el kupro kaj ĝian piedestalon el kupro, el la speguloj de la virinoj, kiuj kolektiĝis amase antaŭ la pordo de la tabernaklo de kunveno.","Kaj li faris la lavujon el kupro kaj ĝian piedestalon el kupro, el la speguloj de la virinoj, kiuj kolektiĝis amase antaŭ la pordo de la tabernaklo de kunveno."],[38,9,"Kaj li faris la korton: sur la flanko suda estis la kurtenoj de la korto el tordita bisino, cent ulnoj,","Kaj li faris la korton: sur la flanko suda estis la kurtenoj de la korto el tordita bisino, cent ulnoj,"],[38,10,"kaj al ili dudek kolonoj kun dudek kupraj bazoj; la hokoj de la kolonoj kaj iliaj ligaĵoj estis el arĝento.","kaj al ili dudek kolonoj kun dudek kupraj bazoj; la hokoj de la kolonoj kaj iliaj ligaĵoj estis el arĝento."],[38,11,"Kaj sur la norda flanko ankaŭ cent ulnoj, kaj al ili dudek kolonoj kaj dudek kupraj bazoj; la hokoj de la kolonoj kaj iliaj ligaĵoj estis el arĝento.","Kaj sur la norda flanko ankaŭ cent ulnoj, kaj al ili dudek kolonoj kaj dudek kupraj bazoj; la hokoj de la kolonoj kaj iliaj ligaĵoj estis el arĝento."],[38,12,"Kaj sur la okcidenta flanko estis kurtenoj de kvindek ulnoj, kaj al ili dek kolonoj kun dek bazoj; la hokoj de la kolonoj kaj iliaj ligaĵoj estis el arĝento.","Kaj sur la okcidenta flanko estis kurtenoj de kvindek ulnoj, kaj al ili dek kolonoj kun dek bazoj; la hokoj de la kolonoj kaj iliaj ligaĵoj estis el arĝento."],[38,13,"Kaj sur la orienta flanko kvindek ulnoj.","Kaj sur la orienta flanko kvindek ulnoj."],[38,14,"Kurtenoj de dek kvin ulnoj sur unu latero, kaj al tio tri kolonoj kun tri bazoj.","Kurtenoj de dek kvin ulnoj sur unu latero, kaj al tio tri kolonoj kun tri bazoj."],[38,15,"Kaj sur la dua latero, sur ambaŭ flankoj de la pordego de la korto estis kurtenoj po dek kvin ulnoj, kaj al ili po tri kolonoj kun tri bazoj.","Kaj sur la dua latero, sur ambaŭ flankoj de la pordego de la korto estis kurtenoj po dek kvin ulnoj, kaj al ili po tri kolonoj kun tri bazoj."],[38,16,"Ĉiuj kurtenoj de la korto ĉirkaŭe estis el tordita bisino.","Ĉiuj kurtenoj de la korto ĉirkaŭe estis el tordita bisino."],[38,17,"Kaj la bazoj de la kolonoj estis el kupro, la hokoj de la kolonoj kaj iliaj ligaĵoj el arĝento, kaj iliaj kapoj estis tegitaj per arĝento, kaj ĉiuj kolonoj de la korto estis kunigitaj per arĝentaj ligaĵoj.","Kaj la bazoj de la kolonoj estis el kupro, la hokoj de la kolonoj kaj iliaj ligaĵoj el arĝento, kaj iliaj kapoj estis tegitaj per arĝento, kaj ĉiuj kolonoj de la korto estis kunigitaj per arĝentaj ligaĵoj."],[38,18,"Kaj la kovrotuko de la pordego de la korto estis brodita laboraĵo el blua, purpura, kaj ruĝa teksaĵo, kaj el tordita bisino; kaj dudek ulnoj estis ĝia longo, kaj kvin ulnoj ĝia larĝo, laŭ la mezuro de la kurtenoj de la korto.","Kaj la kovrotuko de la pordego de la korto estis brodita laboraĵo el blua, purpura, kaj ruĝa teksaĵo, kaj el tordita bisino; kaj dudek ulnoj estis ĝia longo, kaj kvin ulnoj ĝia larĝo, laŭ la mezuro de la kurtenoj de la korto."],[38,19,"Kaj al ĝi apartenis kvar kolonoj kun kvar kupraj bazoj; iliaj hokoj estis el arĝento, iliaj kapoj estis tegitaj per arĝento, kaj iliaj ligaĵoj estis el arĝento.","Kaj al ĝi apartenis kvar kolonoj kun kvar kupraj bazoj; iliaj hokoj estis el arĝento, iliaj kapoj estis tegitaj per arĝento, kaj iliaj ligaĵoj estis el arĝento."],[38,20,"Kaj ĉiuj najloj en la tabernaklo kaj en la korto ĉirkaŭe estis el kupro.","Kaj ĉiuj najloj en la tabernaklo kaj en la korto ĉirkaŭe estis el kupro."],[38,21,"Jen estas la kalkulo pri la tabernaklo, la tabernaklo de atesto, kiu estis kalkulita laŭ la ordono de Moseo, por la servo de la Levidoj, sub la kontrolo de Itamar, filo de la pastro Aaron.","Jen estas la kalkulo pri la tabernaklo, la tabernaklo de atesto, kiu estis kalkulita laŭ la ordono de Moseo, por la servo de la Levidoj, sub la kontrolo de Itamar, filo de la pastro Aaron."],[38,22,"Kaj Becalel, filo de Uri, filo de Ĥur, el la tribo de Jehuda, faris ĉion, kion ordonis la Eternulo al Moseo;","Kaj Becalel, filo de Uri, filo de Ĥur, el la tribo de Jehuda, faris ĉion, kion ordonis la Eternulo al Moseo;"],[38,23,"kaj kun li Oholiab, filo de Aĥisamaĥ, el la tribo de Dan, artista skulptisto, teksisto, kaj brodisto sur blua, purpura, kaj ruĝa teksaĵo, kaj sur bisino.","kaj kun li Oholiab, filo de Aĥisamaĥ, el la tribo de Dan, artista skulptisto, teksisto, kaj brodisto sur blua, purpura, kaj ruĝa teksaĵo, kaj sur bisino."],[38,24,"La tuta oro, kiu estis uzita por ĉiuj laboroj de la sanktejo, la oro, kiu estis alportita kiel oferdonoj, prezentis la kvanton de dudek naŭ kikaroj kaj sepcent tridek sikloj laŭ la mezuro de la sankta siklo.","La tuta oro, kiu estis uzita por ĉiuj laboroj de la sanktejo, la oro, kiu estis alportita kiel oferdonoj, prezentis la kvanton de dudek naŭ kikaroj kaj sepcent tridek sikloj laŭ la mezuro de la sankta siklo."],[38,25,"Kaj la arĝento, akirita per la kalkulado de la komunumo, prezentis la kvanton de cent kikaroj kaj mil sepcent sepdek kvin sikloj laŭ la sankta siklo:","Kaj la arĝento, akirita per la kalkulado de la komunumo, prezentis la kvanton de cent kikaroj kaj mil sepcent sepdek kvin sikloj laŭ la sankta siklo:"],[38,26,"po unu bek’o, tio estas po duono de siklo laŭ la sankta siklo, por ĉiu kapo, de ĉiuj, kiuj trapasis la kalkulon, kiuj havis la aĝon de dudek jaroj kaj pli, de sescent tri mil kvincent kvindek homoj.","po unu bek’o, tio estas po duono de siklo laŭ la sankta siklo, por ĉiu kapo, de ĉiuj, kiuj trapasis la kalkulon, kiuj havis la aĝon de dudek jaroj kaj pli, de sescent tri mil kvincent kvindek homoj."],[38,27,"Cent kikaroj da arĝento estis uzitaj por elfandi la bazojn de la sanktejo kaj la bazojn de la kurteno; cent bazoj el cent kikaroj, po unu kikaro por bazo.","Cent kikaroj da arĝento estis uzitaj por elfandi la bazojn de la sanktejo kaj la bazojn de la kurteno; cent bazoj el cent kikaroj, po unu kikaro por bazo."],[38,28,"Kaj el mil sepcent sepdek kvin sikloj estis faritaj hokoj por la kolonoj kaj estis tegitaj iliaj kapoj kaj estis faritaj ligaĵoj inter ili.","Kaj el mil sepcent sepdek kvin sikloj estis faritaj hokoj por la kolonoj kaj estis tegitaj iliaj kapoj kaj estis faritaj ligaĵoj inter ili."],[38,29,"Kaj da oferdonita kupro estis sepdek kikaroj kaj du mil kvarcent sikloj.","Kaj da oferdonita kupro estis sepdek kikaroj kaj du mil kvarcent sikloj."],[38,30,"Kaj li faris el ĝi la bazojn por la pordo de la tabernaklo de kunveno kaj la kupran altaron kaj la kupran kradon por ĝi kaj ĉiujn apartenaĵojn de la altaro,","Kaj li faris el ĝi la bazojn por la pordo de la tabernaklo de kunveno kaj la kupran altaron kaj la kupran kradon por ĝi kaj ĉiujn apartenaĵojn de la altaro,"],[38,31,"kaj la bazojn de la korto ĉirkaŭe kaj la bazojn de la pordego de la korto kaj ĉiujn najlojn de la tabernaklo kaj ĉiujn najlojn de la korto ĉirkaŭe.","kaj la bazojn de la korto ĉirkaŭe kaj la bazojn de la pordego de la korto kaj ĉiujn najlojn de la tabernaklo kaj ĉiujn najlojn de la korto ĉirkaŭe."],[39,1,"Kaj el la blua, purpura, kaj ruĝa teksaĵo ili faris la oficajn vestojn por la servado en la sanktejo; kaj ili faris la sanktajn vestojn por Aaron, kiel la Eternulo ordonis al Moseo.","Kaj el la blua, purpura, kaj ruĝa teksaĵo ili faris la oficajn vestojn por la servado en la sanktejo; kaj ili faris la sanktajn vestojn por Aaron, kiel la Eternulo ordonis al Moseo."],[39,2,"Kaj ili faris la efodon el oro, el blua, purpura, kaj ruĝa teksaĵo, kaj el tordita bisino.","Kaj ili faris la efodon el oro, el blua, purpura, kaj ruĝa teksaĵo, kaj el tordita bisino."],[39,3,"Kaj ili batetendis foliojn da oro kaj tranĉis ilin en formo de fadenoj, por enteksi internen de la blua, purpura, kaj ruĝa teksaĵo kaj de la bisino per artista laboro.","Kaj ili batetendis foliojn da oro kaj tranĉis ilin en formo de fadenoj, por enteksi internen de la blua, purpura, kaj ruĝa teksaĵo kaj de la bisino per artista laboro."],[39,4,"Surŝultraĵojn kunigantajn ili faris al ĝi; sur siaj du finoj ĝi estis ligita.","Surŝultraĵojn kunigantajn ili faris al ĝi; sur siaj du finoj ĝi estis ligita."],[39,5,"Kaj la ĉirkaŭliganta zono sur ĝi estis kontinuaĵo de ĝi, la sama laboraĵo, el oro, el blua, purpura, kaj ruĝa teksaĵo, kaj el tordita bisino; kiel la Eternulo ordonis al Moseo.","Kaj la ĉirkaŭliganta zono sur ĝi estis kontinuaĵo de ĝi, la sama laboraĵo, el oro, el blua, purpura, kaj ruĝa teksaĵo, kaj el tordita bisino; kiel la Eternulo ordonis al Moseo."],[39,6,"Kaj ili faris la oniksajn ŝtonojn, ĉirkaŭe enkadrigitajn per oro, gravuritajn per sigelila gravurado laŭ la nomoj de la filoj de Izrael.","Kaj ili faris la oniksajn ŝtonojn, ĉirkaŭe enkadrigitajn per oro, gravuritajn per sigelila gravurado laŭ la nomoj de la filoj de Izrael."],[39,7,"Kaj li metis ilin sur la surŝultraĵojn de la efodo, kiel ŝtonojn de memoro pri la filoj de Izrael; kiel la Eternulo ordonis al Moseo.","Kaj li metis ilin sur la surŝultraĵojn de la efodo, kiel ŝtonojn de memoro pri la filoj de Izrael; kiel la Eternulo ordonis al Moseo."],[39,8,"Kaj ili faris la surbrustaĵon per artista laboro, simile al la laboro de la efodo, el oro, el blua, purpura, kaj ruĝa teksaĵo, kaj el tordita bisino.","Kaj ili faris la surbrustaĵon per artista laboro, simile al la laboro de la efodo, el oro, el blua, purpura, kaj ruĝa teksaĵo, kaj el tordita bisino."],[39,9,"Ĝi estis kvarangula; ili faris la surbrustaĵon duobla; manstreĉo estis ĝia longo, kaj manstreĉo ĝia larĝo; ĝi estis duobla.","Ĝi estis kvarangula; ili faris la surbrustaĵon duobla; manstreĉo estis ĝia longo, kaj manstreĉo ĝia larĝo; ĝi estis duobla."],[39,10,"Kaj ili enmetis en ĝin kvar vicojn da ŝtonoj. La unua vico estis: rubeno, topazo, kaj smeraldo;","Kaj ili enmetis en ĝin kvar vicojn da ŝtonoj. La unua vico estis: rubeno, topazo, kaj smeraldo;"],[39,11,"kaj la dua vico: hiacinto, safiro, kaj jaspiso;","kaj la dua vico: hiacinto, safiro, kaj jaspiso;"],[39,12,"kaj la tria vico: ligurio, agato, kaj ametisto;","kaj la tria vico: ligurio, agato, kaj ametisto;"],[39,13,"kaj la kvara vico: krizolito, onikso, kaj berilo. Ĉiuj vicoj estis en oraj kadretoj.","kaj la kvara vico: krizolito, onikso, kaj berilo. Ĉiuj vicoj estis en oraj kadretoj."],[39,14,"Kaj la ŝtonoj estis laŭ la nomoj de la filoj de Izrael; dek du, laŭ iliaj nomoj, gravuritaj sigelile, ĉiu kun sia nomo, por la dek du triboj.","Kaj la ŝtonoj estis laŭ la nomoj de la filoj de Izrael; dek du, laŭ iliaj nomoj, gravuritaj sigelile, ĉiu kun sia nomo, por la dek du triboj."],[39,15,"Kaj ili faris al la surbrustaĵo plektitajn ĉenetojn, kuniĝantajn per siaj finoj, el pura oro.","Kaj ili faris al la surbrustaĵo plektitajn ĉenetojn, kuniĝantajn per siaj finoj, el pura oro."],[39,16,"Kaj ili faris du orajn kadretojn kaj du orajn ringojn, kaj alfortikigis la du ringojn al la du finoj de la surbrustaĵo.","Kaj ili faris du orajn kadretojn kaj du orajn ringojn, kaj alfortikigis la du ringojn al la du finoj de la surbrustaĵo."],[39,17,"Kaj ili metis la du orajn plektitajn ĉenetojn en la du ringojn ĉe la finoj de la surbrustaĵo.","Kaj ili metis la du orajn plektitajn ĉenetojn en la du ringojn ĉe la finoj de la surbrustaĵo."],[39,18,"Kaj la du finojn de la du plektitaj ĉenetoj ili alfortikigis al la du kadretoj, kaj alfortikigis ilin al la surŝultraĵoj de la efodo sur la antaŭa flanko.","Kaj la du finojn de la du plektitaj ĉenetoj ili alfortikigis al la du kadretoj, kaj alfortikigis ilin al la surŝultraĵoj de la efodo sur la antaŭa flanko."],[39,19,"Kaj ili faris du orajn ringojn, kaj alfortikigis ilin al la du aliaj finoj de la surbrustaĵo, sur ĝia rando interna, direktita al la efodo.","Kaj ili faris du orajn ringojn, kaj alfortikigis ilin al la du aliaj finoj de la surbrustaĵo, sur ĝia rando interna, direktita al la efodo."],[39,20,"Kaj ili faris du orajn ringojn, kaj alfortikigis ilin al la du surŝultraĵoj de la efodo malsupre, sur la antaŭa flanko, ĉe ĝia kuniĝo, super la zono de la efodo.","Kaj ili faris du orajn ringojn, kaj alfortikigis ilin al la du surŝultraĵoj de la efodo malsupre, sur la antaŭa flanko, ĉe ĝia kuniĝo, super la zono de la efodo."],[39,21,"Kaj ili alligis la surbrustaĵon per ĝiaj ringoj al la ringoj de la efodo per laĉo el blua ŝtofo, por ke ĝi estu super la zono de la efodo kaj por ke la surbrustaĵo ne forŝoviĝu de sur la efodo; kiel la Eternulo ordonis al Moseo.","Kaj ili alligis la surbrustaĵon per ĝiaj ringoj al la ringoj de la efodo per laĉo el blua ŝtofo, por ke ĝi estu super la zono de la efodo kaj por ke la surbrustaĵo ne forŝoviĝu de sur la efodo; kiel la Eternulo ordonis al Moseo."],[39,22,"Kaj li faris la tunikon por la efodo, teksitan, tutan el blua teksaĵo.","Kaj li faris la tunikon por la efodo, teksitan, tutan el blua teksaĵo."],[39,23,"Kaj la aperturo de la tuniko estis en la mezo, kiel aperturo de ŝildo; borderon havis la aperturo ĉirkaŭe, por ke ĝi ne disŝiriĝu.","Kaj la aperturo de la tuniko estis en la mezo, kiel aperturo de ŝildo; borderon havis la aperturo ĉirkaŭe, por ke ĝi ne disŝiriĝu."],[39,24,"Kaj ili faris sur la malsupra rando de la tuniko granatojn el blua, purpura, kaj ruĝa ŝtofo, tordita.","Kaj ili faris sur la malsupra rando de la tuniko granatojn el blua, purpura, kaj ruĝa ŝtofo, tordita."],[39,25,"Kaj ili faris tintilojn el pura oro, kaj metis la tintilojn mezen de la granatoj sur la malsupra rando de la tuniko, ĉirkaŭe inter la granatoj;","Kaj ili faris tintilojn el pura oro, kaj metis la tintilojn mezen de la granatoj sur la malsupra rando de la tuniko, ĉirkaŭe inter la granatoj;"],[39,26,"tintilon kaj granaton, tintilon kaj granaton sur la malsupra rando de la tuniko, ĉirkaŭe, por la servado; kiel la Eternulo ordonis al Moseo.","tintilon kaj granaton, tintilon kaj granaton sur la malsupra rando de la tuniko, ĉirkaŭe, por la servado; kiel la Eternulo ordonis al Moseo."],[39,27,"Kaj ili faris la ĥitonon el bisino, teksitan, por Aaron kaj liaj filoj,","Kaj ili faris la ĥitonon el bisino, teksitan, por Aaron kaj liaj filoj,"],[39,28,"kaj la cidaron el bisino, kaj la ornamajn mitrojn el bisino, kaj la linajn pantalonojn el tordita bisino,","kaj la cidaron el bisino, kaj la ornamajn mitrojn el bisino, kaj la linajn pantalonojn el tordita bisino,"],[39,29,"kaj la zonon el tordita bisino kaj el blua, purpura, kaj ruĝa teksaĵo, broditan; kiel la Eternulo ordonis al Moseo.","kaj la zonon el tordita bisino kaj el blua, purpura, kaj ruĝa teksaĵo, broditan; kiel la Eternulo ordonis al Moseo."],[39,30,"Kaj ili faris la tabuleton, la sanktan kronon, el pura oro, kaj ili skribis sur ĝi skribon gravuritan: SANKTA AL LA ETERNULO .","Kaj ili faris la tabuleton, la sanktan kronon, el pura oro, kaj ili skribis sur ĝi skribon gravuritan: SANKTA AL LA ETERNULO ."],[39,31,"Kaj ili alfortikigis al ĝi laĉon el blua ŝtofo, por alfortikigi al la cidaro supre; kiel la Eternulo ordonis al Moseo.","Kaj ili alfortikigis al ĝi laĉon el blua ŝtofo, por alfortikigi al la cidaro supre; kiel la Eternulo ordonis al Moseo."],[39,32,"Tiel finiĝis la tuta laboro por la konstruaĵo de la tabernaklo de kunveno. Kaj la Izraelidoj faris konforme al ĉio, kion la Eternulo ordonis al Moseo; tiel ili faris.","Tiel finiĝis la tuta laboro por la konstruaĵo de la tabernaklo de kunveno. Kaj la Izraelidoj faris konforme al ĉio, kion la Eternulo ordonis al Moseo; tiel ili faris."],[39,33,"Kaj ili alportis la konstruaĵon al Moseo, la tabernaklon kaj ĉiujn ĝiajn apartenaĵojn: hokojn, tabulojn, riglilojn, kolonojn, kaj bazojn;","Kaj ili alportis la konstruaĵon al Moseo, la tabernaklon kaj ĉiujn ĝiajn apartenaĵojn: hokojn, tabulojn, riglilojn, kolonojn, kaj bazojn;"],[39,34,"kaj la kovron el ruĝaj virŝafaj feloj kaj la kovron el antilopaj feloj kaj la kurtenon;","kaj la kovron el ruĝaj virŝafaj feloj kaj la kovron el antilopaj feloj kaj la kurtenon;"],[39,35,"la keston de atesto kaj ĝiajn stangojn kaj la fermoplaton;","la keston de atesto kaj ĝiajn stangojn kaj la fermoplaton;"],[39,36,"la tablon, ĉiujn ĝiajn apartenaĵojn, kaj la panon de propono;","la tablon, ĉiujn ĝiajn apartenaĵojn, kaj la panon de propono;"],[39,37,"la puran kandelabron, ĝiajn lucernojn, la lucernojn vice starantajn, ĉiujn ĝiajn apartenaĵojn, kaj la oleon por lumigado;","la puran kandelabron, ĝiajn lucernojn, la lucernojn vice starantajn, ĉiujn ĝiajn apartenaĵojn, kaj la oleon por lumigado;"],[39,38,"kaj la oran altaron kaj la sanktan oleon kaj la bonodoran incenson kaj la kovrotukon por la pordo de la tabernaklo;","kaj la oran altaron kaj la sanktan oleon kaj la bonodoran incenson kaj la kovrotukon por la pordo de la tabernaklo;"],[39,39,"la kupran altaron kaj la kupran kradon por ĝi, ĝiajn stangojn kaj ĉiujn ĝiajn apartenaĵojn, la lavujon kaj ĝian piedestalon;","la kupran altaron kaj la kupran kradon por ĝi, ĝiajn stangojn kaj ĉiujn ĝiajn apartenaĵojn, la lavujon kaj ĝian piedestalon;"],[39,40,"la kurtenojn de la korto, ĝiajn kolonojn kaj bazojn, la kovrotukon por la pordego de la korto, ĝiajn ŝnurojn kaj najlojn, kaj ĉion, kio apartenas al la servado en la konstruaĵo de la tabernaklo de kunveno;","la kurtenojn de la korto, ĝiajn kolonojn kaj bazojn, la kovrotukon por la pordego de la korto, ĝiajn ŝnurojn kaj najlojn, kaj ĉion, kio apartenas al la servado en la konstruaĵo de la tabernaklo de kunveno;"],[39,41,"la oficajn vestojn por la servado en la sanktejo, la sanktajn vestojn por la pastro Aaron kaj la pastrajn vestojn por liaj filoj.","la oficajn vestojn por la servado en la sanktejo, la sanktajn vestojn por la pastro Aaron kaj la pastrajn vestojn por liaj filoj."],[39,42,"Konforme al ĉio, kion la Eternulo ordonis al Moseo, tiel la Izraelidoj faris la tutan laboron.","Konforme al ĉio, kion la Eternulo ordonis al Moseo, tiel la Izraelidoj faris la tutan laboron."],[39,43,"Kaj Moseo vidis la tutan laboron, li vidis, ke ili faris ĝin tute tiel, kiel la Eternulo ordonis; kaj Moseo benis ilin.","Kaj Moseo vidis la tutan laboron, li vidis, ke ili faris ĝin tute tiel, kiel la Eternulo ordonis; kaj Moseo benis ilin."],[40,1,"Kaj la Eternulo ekparolis al Moseo, dirante:","Kaj la Eternulo ekparolis al Moseo, dirante:"],[40,2,"En la unua monato, en la unua tago de la monato starigu la konstruaĵon de la tabernaklo de kunveno.","En la unua monato, en la unua tago de la monato starigu la konstruaĵon de la tabernaklo de kunveno."],[40,3,"Kaj metu tien la keston de atesto kaj ŝirmu la keston per la kurteno.","Kaj metu tien la keston de atesto kaj ŝirmu la keston per la kurteno."],[40,4,"Kaj enportu la tablon kaj aranĝu sur ĝi ĝian aranĝotaĵon, kaj enportu la kandelabron kaj ekbruligu ĝiajn lucernojn.","Kaj enportu la tablon kaj aranĝu sur ĝi ĝian aranĝotaĵon, kaj enportu la kandelabron kaj ekbruligu ĝiajn lucernojn."],[40,5,"Kaj starigu la oran altaron por la incensado antaŭ la kesto de atesto, kaj pendigu la kovrotukon ĉe la eniro de la tabernaklo.","Kaj starigu la oran altaron por la incensado antaŭ la kesto de atesto, kaj pendigu la kovrotukon ĉe la eniro de la tabernaklo."],[40,6,"Kaj starigu la altaron de bruloferoj antaŭ la eniro en la konstruaĵon de la tabernaklo de kunveno.","Kaj starigu la altaron de bruloferoj antaŭ la eniro en la konstruaĵon de la tabernaklo de kunveno."],[40,7,"Kaj starigu la lavujon inter la tabernaklo de kunveno kaj la altaro kaj enverŝu en ĝin akvon.","Kaj starigu la lavujon inter la tabernaklo de kunveno kaj la altaro kaj enverŝu en ĝin akvon."],[40,8,"Kaj aranĝu la korton ĉirkaŭe, kaj pendigu la kovrotukon ĉe la pordego de la korto.","Kaj aranĝu la korton ĉirkaŭe, kaj pendigu la kovrotukon ĉe la pordego de la korto."],[40,9,"Kaj prenu la sanktan oleon, kaj sanktoleu la loĝejon, kaj ĉion, kio estas en ĝi, kaj sanktigu ĝin kun ĉiuj ĝiaj apartenaĵoj, por ke ĝi estu sankta.","Kaj prenu la sanktan oleon, kaj sanktoleu la loĝejon, kaj ĉion, kio estas en ĝi, kaj sanktigu ĝin kun ĉiuj ĝiaj apartenaĵoj, por ke ĝi estu sankta."],[40,10,"Kaj sanktoleu la altaron de bruloferoj kun ĉiuj ĝiaj apartenaĵoj, kaj sanktigu la altaron, ke la altaro estu tre sankta.","Kaj sanktoleu la altaron de bruloferoj kun ĉiuj ĝiaj apartenaĵoj, kaj sanktigu la altaron, ke la altaro estu tre sankta."],[40,11,"Kaj sanktoleu la lavujon kaj ĝian piedestalon, kaj sanktigu ĝin.","Kaj sanktoleu la lavujon kaj ĝian piedestalon, kaj sanktigu ĝin."],[40,12,"Kaj alkonduku Aaronon kaj liajn filojn al la eniro de la tabernaklo de kunveno, kaj lavu ilin per akvo.","Kaj alkonduku Aaronon kaj liajn filojn al la eniro de la tabernaklo de kunveno, kaj lavu ilin per akvo."],[40,13,"Kaj vestu Aaronon per la sanktaj vestoj kaj sanktoleu lin kaj sanktigu lin, ke li estu Mia pastro.","Kaj vestu Aaronon per la sanktaj vestoj kaj sanktoleu lin kaj sanktigu lin, ke li estu Mia pastro."],[40,14,"Kaj liajn filojn alkonduku, kaj vestu ilin per ĥitonoj.","Kaj liajn filojn alkonduku, kaj vestu ilin per ĥitonoj."],[40,15,"Kaj sanktoleu ilin, kiel vi sanktoleis ilian patron, ke ili estu Miaj pastroj; kaj ilia sanktoleiteco estu por ili por eterna pastreco en iliaj generacioj.","Kaj sanktoleu ilin, kiel vi sanktoleis ilian patron, ke ili estu Miaj pastroj; kaj ilia sanktoleiteco estu por ili por eterna pastreco en iliaj generacioj."],[40,16,"Kaj Moseo faris konforme al ĉio, kion la Eternulo al li ordonis; tiel li faris.","Kaj Moseo faris konforme al ĉio, kion la Eternulo al li ordonis; tiel li faris."],[40,17,"En la unua monato de la dua jaro, en la unua tago de la monato estis starigita la tabernaklo.","En la unua monato de la dua jaro, en la unua tago de la monato estis starigita la tabernaklo."],[40,18,"Kaj Moseo starigis la tabernaklon kaj metis ĝiajn bazojn kaj starigis ĝiajn tabulojn kaj aranĝis ĝiajn riglilojn kaj starigis ĝiajn kolonojn.","Kaj Moseo starigis la tabernaklon kaj metis ĝiajn bazojn kaj starigis ĝiajn tabulojn kaj aranĝis ĝiajn riglilojn kaj starigis ĝiajn kolonojn."],[40,19,"Kaj li etendis tendon super la tabernaklo kaj metis la kovron de la tendo sur ĝin supre, kiel la Eternulo ordonis al Moseo.","Kaj li etendis tendon super la tabernaklo kaj metis la kovron de la tendo sur ĝin supre, kiel la Eternulo ordonis al Moseo."],[40,20,"Kaj li prenis kaj metis la ateston en la keston, kaj almetis la stangojn al la kesto kaj surmetis la fermoplaton sur la keston supre.","Kaj li prenis kaj metis la ateston en la keston, kaj almetis la stangojn al la kesto kaj surmetis la fermoplaton sur la keston supre."],[40,21,"Kaj li envenigis la keston en la tabernaklon, kaj pendigis la kurtenon kaj ŝirmis la keston de atesto, kiel la Eternulo ordonis al Moseo.","Kaj li envenigis la keston en la tabernaklon, kaj pendigis la kurtenon kaj ŝirmis la keston de atesto, kiel la Eternulo ordonis al Moseo."],[40,22,"Kaj li starigis la tablon en la tabernaklo de kunveno, en la norda parto de la tabernaklo, ekster la kurteno.","Kaj li starigis la tablon en la tabernaklo de kunveno, en la norda parto de la tabernaklo, ekster la kurteno."],[40,23,"Kaj li aranĝis sur ĝi vicon da panoj antaŭ la Eternulo, kiel la Eternulo ordonis al Moseo.","Kaj li aranĝis sur ĝi vicon da panoj antaŭ la Eternulo, kiel la Eternulo ordonis al Moseo."],[40,24,"Kaj li starigis la kandelabron en la tabernaklo de kunveno kontraŭ la tablo, en la suda parto de la tabernaklo.","Kaj li starigis la kandelabron en la tabernaklo de kunveno kontraŭ la tablo, en la suda parto de la tabernaklo."],[40,25,"Kaj li ekbruligis la lucernojn antaŭ la Eternulo, kiel la Eternulo ordonis al Moseo.","Kaj li ekbruligis la lucernojn antaŭ la Eternulo, kiel la Eternulo ordonis al Moseo."],[40,26,"Kaj li starigis la oran altaron en la tabernaklo de kunveno antaŭ la kurteno.","Kaj li starigis la oran altaron en la tabernaklo de kunveno antaŭ la kurteno."],[40,27,"Kaj li bruligis sur ĝi bonodoran incenson, kiel la Eternulo ordonis al Moseo.","Kaj li bruligis sur ĝi bonodoran incenson, kiel la Eternulo ordonis al Moseo."],[40,28,"Kaj li pendigis la kovrotukon ĉe la pordo de la tabernaklo.","Kaj li pendigis la kovrotukon ĉe la pordo de la tabernaklo."],[40,29,"Kaj la altaron de bruloferoj li starigis ĉe la eniro de la tabernaklo de kunveno, kaj li alportis sur ĝi la bruloferon kaj la farunoferon, kiel la Eternulo ordonis al Moseo.","Kaj la altaron de bruloferoj li starigis ĉe la eniro de la tabernaklo de kunveno, kaj li alportis sur ĝi la bruloferon kaj la farunoferon, kiel la Eternulo ordonis al Moseo."],[40,30,"Kaj li starigis la lavujon inter la tabernaklo de kunveno kaj la altaro, kaj enverŝis tien akvon por sin lavi.","Kaj li starigis la lavujon inter la tabernaklo de kunveno kaj la altaro, kaj enverŝis tien akvon por sin lavi."],[40,31,"Kaj lavis per ĝi Moseo kaj Aaron kaj liaj filoj siajn manojn kaj siajn piedojn;","Kaj lavis per ĝi Moseo kaj Aaron kaj liaj filoj siajn manojn kaj siajn piedojn;"],[40,32,"kiam ili eniradis en la tabernaklon de kunveno kaj aliradis al la altaro, ili lavadis sin; kiel la Eternulo ordonis al Moseo.","kiam ili eniradis en la tabernaklon de kunveno kaj aliradis al la altaro, ili lavadis sin; kiel la Eternulo ordonis al Moseo."],[40,33,"Kaj li aranĝis la korton ĉirkaŭe de la tabernaklo kaj de la altaro, kaj li pendigis la kovrotukon ĉe la pordego de la korto. Tiamaniere Moseo finis la laboron.","Kaj li aranĝis la korton ĉirkaŭe de la tabernaklo kaj de la altaro, kaj li pendigis la kovrotukon ĉe la pordego de la korto. Tiamaniere Moseo finis la laboron."],[40,34,"Kaj nubo kovris la tabernaklon de kunveno, kaj la majesto de la Eternulo plenigis la tabernaklon.","Kaj nubo kovris la tabernaklon de kunveno, kaj la majesto de la Eternulo plenigis la tabernaklon."],[40,35,"Kaj Moseo ne povis eniri en la tabernaklon de kunveno, ĉar kuŝis sur ĝi la nubo kaj la majesto de la Eternulo plenigis la tabernaklon.","Kaj Moseo ne povis eniri en la tabernaklon de kunveno, ĉar kuŝis sur ĝi la nubo kaj la majesto de la Eternulo plenigis la tabernaklon."],[40,36,"Kaj kiam la nubo leviĝadis de sur la tabernaklo, la Izraelidoj ekmarŝadis, por fari ĉiujn siajn marŝojn.","Kaj kiam la nubo leviĝadis de sur la tabernaklo, la Izraelidoj ekmarŝadis, por fari ĉiujn siajn marŝojn."],[40,37,"Sed se la nubo ne leviĝis, ili ne ekmarŝis ĝis la tago de ĝia leviĝo.","Sed se la nubo ne leviĝis, ili ne ekmarŝis ĝis la tago de ĝia leviĝo."],[40,38,"Ĉar nubo de la Eternulo estis super la tabernaklo dum la tago, kaj fajro estis dum la nokto super ĝi, antaŭ la okuloj de ĉiuj Izraelidoj en ĉiuj iliaj marŝoj.","Ĉar nubo de la Eternulo estis super la tabernaklo dum la tago, kaj fajro estis dum la nokto super ĝi, antaŭ la okuloj de ĉiuj Izraelidoj en ĉiuj iliaj marŝoj."]]}};